INSERT INTO "notes"."NoteVersion" ("id", "noteId", "number", "kind", "title", "cards", "createdById", "createdAt")
SELECT '4534f0a4-efeb-7e59-a7b0-774f20ef6257', '74d8e5c6-f2a4-76ea-800e-5ac442065474', 1, 'PUBLISHED', 'Elliptic Curves (ECC)', '[{"id":"f6601ce4-831c-7d32-8886-eed64827b6f3","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Coordinate geometry, point arithmetic equations, and curve standards (secp256k1 & Curve25519)."}]}]}},"revision":1},{"id":"5296772d-03bb-7088-a599-203498132c84","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"1. Elliptic Curve Coordinates & Point Arithmetic"}]},"revision":1},{"id":"d879a464-1976-7d21-b16f-6591fd93e383","type":"callout","position":"a2","content":{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Elliptic curve cryptography utilizes curves defined by the algebraic equation:"}]},{"type":"paragraph","content":[{"type":"text","text":"y² = x³ + ax + b","marks":[{"type":"code"}]}]},{"type":"paragraph","content":[{"type":"text","text":"The coordinates of points on the curve form a group under a defined addition operation:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Point Addition (P + Q):","marks":[{"type":"bold"}]},{"type":"text","text":" Draw a line through points P and Q. The line will intersect the curve at a third point, R. Reflect R across the x-axis to find the sum point: "},{"type":"text","text":"P + Q = -R","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Point Doubling (2P):","marks":[{"type":"bold"}]},{"type":"text","text":" Draw a tangent line to the curve at point P. The line will intersect the curve at another point. Reflect this point across the x-axis to find "},{"type":"text","text":"2P","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}]}]}},"revision":1},{"id":"0986f7d9-ecdc-7611-985f-05f3ff3b0ba8","type":"heading","position":"a3","content":{"level":1,"content":[{"type":"text","text":"2. The Discrete Logarithm Problem on Curves (ECDLP)"}]},"revision":1},{"id":"28e177bc-62c6-7eed-9396-12bafd537803","type":"text","position":"a4","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Given a starting point "},{"type":"text","text":"P","marks":[{"type":"code"}]},{"type":"text","text":" (generator) and a scalar multiplier "},{"type":"text","text":"k","marks":[{"type":"code"}]},{"type":"text","text":" (private key), we compute the public key point "},{"type":"text","text":"Q = k * P","marks":[{"type":"code"}]},{"type":"text","text":" by repeatedly doubling and adding. "},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":" The security of ECC relies on the difficulty of finding the scalar "},{"type":"text","text":"k","marks":[{"type":"code"}]},{"type":"text","text":" given only points "},{"type":"text","text":"P","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"Q","marks":[{"type":"code"}]},{"type":"text","text":". This is the "},{"type":"text","text":"Elliptic Curve Discrete Logarithm Problem (ECDLP)","marks":[{"type":"bold"}]},{"type":"text","text":", for which there are no known sub-exponential time solving algorithms."}]}]}},"revision":1},{"id":"3fdadf6f-a1d0-745a-8837-18731dbb8edd","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"3. Industry Standard Curves"}]},"revision":1},{"id":"c8d0cb61-2f62-7165-a12f-125aa14ad5b7","type":"callout","position":"a6","content":{"variant":"note","title":"secp256k1","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A Koblitz curve defined by "},{"type":"text","text":"y² = x³ + 7 mod p","marks":[{"type":"code"}]},{"type":"text","text":". Used in Bitcoin, Ethereum, and other cryptocurrencies due to its efficient point addition properties."}]}]}},"revision":1},{"id":"23cdf1ca-af95-772e-8eba-204f78fcbeb7","type":"callout","position":"a7","content":{"variant":"note","title":"Curve25519","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A Montgomery curve optimized for fast ECDH key exchanges. Designed by Daniel J. Bernstein, it is highly resistant to timing attacks and is the standard curve for SSH, TLS 1.3, Signal, and WireGuard."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
