  SELECT 1 FROM "notes"."Note" n
  WHERE n.id = '74d8e5c6-f2a4-76ea-800e-5ac442065474' AND n.visibility = 'PUBLIC' AND n."publishedVersionId" = '4534f0a4-efeb-7e59-a7b0-774f20ef6257' AND n."deletedAt" IS NULL
)
