INSERT INTO "notes"."NoteVersion" ("id", "noteId", "number", "kind", "title", "cards", "createdById", "createdAt")
SELECT 'ede32faf-4522-7ac5-b332-002372f8f328', 'e292c725-3262-7398-8cec-c48621676dc5', 1, 'PUBLISHED', 'Password Security', '[{"id":"03c21b99-6fd5-713c-9411-1e9c4ad8ba6d","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Protecting password databases: salts (preventing rainbow tables), peppers, and key stretching ciphers."}]}]}},"revision":1},{"id":"127c7e78-d192-7c97-a4ee-45bd366af842","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"1. Why Simple Hashes Fail for Passwords"}]},"revision":1},{"id":"eaf72cc6-5c3b-7d16-a498-e06fadde25ba","type":"callout","position":"a2","content":{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Hash functions like MD5 or SHA-256 are designed to be fast, which makes them insecure for password storage. An attacker with a stolen database can use GPUs to test millions of passwords per second. "},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":" Furthermore, without unique salting, users with identical passwords will have identical hashes, allowing attackers to crack multiple accounts simultaneously using "},{"type":"text","text":"Rainbow Tables","marks":[{"type":"bold"}]},{"type":"text","text":" (pre-computed lists of common passwords and their hashes)."}]}]}},"revision":1},{"id":"9e153aaf-07c1-7e61-8218-9136eb4f9ad3","type":"heading","position":"a3","content":{"level":1,"content":[{"type":"text","text":"2. Salt vs. Pepper"}]},"revision":1},{"id":"36c1da18-8f74-7da1-b6d7-eb48348e15cb","type":"callout","position":"a4","content":{"variant":"tip","title":"Cryptographic Salt","doc":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A unique, cryptographically random string generated for each user."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Appended to the password before hashing and stored in plaintext in the database alongside the hash."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Purpose:","marks":[{"type":"bold"}]},{"type":"text","text":" Ensures identical passwords yield different hashes, preventing rainbow table attacks."}]}]}]}]}},"revision":1},{"id":"2ea0ae1b-d514-783e-abd5-d8113c458787","type":"callout","position":"a5","content":{"variant":"danger","title":"Cryptographic Pepper","doc":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A secret key appended to all passwords before hashing."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Stored separately from the database (e.g. in environment variables or an HSM)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Purpose:","marks":[{"type":"bold"}]},{"type":"text","text":" Prevents attackers from cracking passwords even if they steal the database, as they still lack the pepper."}]}]}]}]}},"revision":1},{"id":"bc5993d1-e297-7249-a1ee-d71258ef5bed","type":"heading","position":"a6","content":{"level":1,"content":[{"type":"text","text":"3. Key Stretching Algorithms"}]},"revision":1},{"id":"fea05c2a-241a-761b-a941-44bfd84b09fd","type":"text","position":"a7","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Using slow, memory-hard algorithms to resist brute-force attacks."}]}]}},"revision":1},{"id":"2ad2ca6c-bb1b-73bb-95f4-0cae77da415e","type":"callout","position":"a8","content":{"variant":"note","title":"bcrypt","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Based on the Blowfish cipher. Uses a configurable cost parameter to increase the number of hashing rounds, slowing down brute-force attempts."}]}]}},"revision":1},{"id":"607ba0d3-cd8a-7edc-8972-5e96e1e8eb98","type":"callout","position":"a9","content":{"variant":"note","title":"scrypt","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Designed to require a large amount of memory, making it highly resistant to parallel attacks using custom hardware (ASICs/GPUs)."}]}]}},"revision":1},{"id":"79541ad0-f8d4-76da-8a91-00c8d5c2b48b","type":"callout","position":"aA","content":{"variant":"note","title":"Argon2id","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The winner of the Password Hashing Competition (2015). Provides configurable memory, time, and parallelization parameters. Highly secure."}]}]}},"revision":1},{"id":"bc4007a9-91bb-7713-b16c-22450fcec124","type":"heading","position":"aB","content":{"level":1,"content":[{"type":"text","text":"4. Code Implementation: Hashing with bcrypt"}]},"revision":1},{"id":"d8618f5a-34ec-75d9-8d61-fa0834d25825","type":"text","position":"aC","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A standard implementation using Node.js to hash and verify passwords securely."}]}]}},"revision":1},{"id":"ae5f8cf5-b674-7e81-9b7a-f174af5ced43","type":"code","position":"aD","content":{"language":"javascript","code":"const bcrypt = require(''bcrypt'');\n\n// Hash a password\nasync function hashPassword(password) {\n  const saltRounds = 12; // Cost factor (2^12 rounds)\n  const hash = await bcrypt.hash(password, saltRounds);\n  return hash;\n}\n\n// Verify a password match\nasync function verifyPassword(password, storedHash) {\n  const match = await bcrypt.compare(password, storedHash);\n  return match;\n}","filename":"JavaScript"},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
