  ('9e153aaf-07c1-7e61-8218-9136eb4f9ad3', 'a3', 'heading', '{"level":1,"content":[{"type":"text","text":"2. Salt vs. Pepper"}]}'),
  ('36c1da18-8f74-7da1-b6d7-eb48348e15cb', 'a4', 'callout', '{"variant":"tip","title":"Cryptographic Salt","doc":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A unique, cryptographically random string generated for each user."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Appended to the password before hashing and stored in plaintext in the database alongside the hash."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Purpose:","marks":[{"type":"bold"}]},{"type":"text","text":" Ensures identical passwords yield different hashes, preventing rainbow table attacks."}]}]}]}]}}'),
  ('2ea0ae1b-d514-783e-abd5-d8113c458787', 'a5', 'callout', '{"variant":"danger","title":"Cryptographic Pepper","doc":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A secret key appended to all passwords before hashing."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Stored separately from the database (e.g. in environment variables or an HSM)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Purpose:","marks":[{"type":"bold"}]},{"type":"text","text":" Prevents attackers from cracking passwords even if they steal the database, as they still lack the pepper."}]}]}]}]}}'),
  ('bc5993d1-e297-7249-a1ee-d71258ef5bed', 'a6', 'heading', '{"level":1,"content":[{"type":"text","text":"3. Key Stretching Algorithms"}]}'),
  ('fea05c2a-241a-761b-a941-44bfd84b09fd', 'a7', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Using slow, memory-hard algorithms to resist brute-force attacks."}]}]}}'),
