INSERT INTO "notes"."NoteVersion" ("id", "noteId", "number", "kind", "title", "cards", "createdById", "createdAt")
SELECT 'fb276a51-eb5b-7b1e-b8f3-65cad13e8d61', '2ec29b04-96db-7f24-980e-e9b63056252b', 1, 'PUBLISHED', 'Modern Applications', '[{"id":"00c6b8e3-3987-77fc-841d-4852a9e754d8","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Real-world cryptographic implementations: Signal''s Double Ratchet, PGP, WireGuard, and Zero-Knowledge Proofs."}]}]}},"revision":1},{"id":"978be28e-6a20-7647-81ad-9e0cf7bf1239","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"1. Signal Protocol: Double Ratchet & X3DH"}]},"revision":1},{"id":"2519a0a7-4727-74e9-a6db-f1903286c696","type":"callout","position":"a2","content":{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The Signal Protocol is the industry standard for E2EE messaging."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"X3DH (Extended Triple Diffie-Hellman):","marks":[{"type":"bold"}]},{"type":"text","text":" Establishes a shared secret session key between two parties, even if one is offline, using pre-published public keys."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Double Ratchet:","marks":[{"type":"bold"}]},{"type":"text","text":" Updates session keys dynamically for every message exchanged using a combination of KDF chains and ephemeral ECDH exchanges. This guarantees "},{"type":"text","text":"Forward Secrecy","marks":[{"type":"bold"}]},{"type":"text","text":" and "},{"type":"text","text":"Break-in Recovery","marks":[{"type":"bold"}]},{"type":"text","text":" (compromising one key does not expose past or future messages)."}]}]}]}]}},"revision":1},{"id":"cd7928f3-464b-7abe-a90b-9b31827dc38b","type":"heading","position":"a3","content":{"level":1,"content":[{"type":"text","text":"2. PGP (Pretty Good Privacy)"}]},"revision":1},{"id":"ca5816f0-3deb-7951-a579-7778b9443be6","type":"text","position":"a4","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"PGP encrypts emails and files using a hybrid model: "},{"type":"hardBreak"},{"type":"text","text":"1. Plaintext is encrypted with a fast, random symmetric key (e.g. AES). "},{"type":"hardBreak"},{"type":"text","text":"2. The symmetric key is encrypted using the recipient''s public key (RSA) and appended to the message. "},{"type":"hardBreak"},{"type":"text","text":"3. Recipient uses their private key to decrypt the symmetric key, then decrypts the message payload."}]}]}},"revision":1},{"id":"1295378f-83f2-719c-a181-cccc1974eeff","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"3. WireGuard VPN"}]},"revision":1},{"id":"b765c676-e96c-7ca3-b2ea-f25458d3ada1","type":"text","position":"a6","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A modern VPN protocol that uses "},{"type":"text","text":"Cryptographic Key Routing","marks":[{"type":"bold"}]},{"type":"text","text":". It binds tunnel IP addresses to peer public keys, using Curve25519 (ECDH), ChaCha20-Poly1305 (encryption), and BLAKE2s (hashing) to provide faster, simpler connections than IPsec or OpenVPN."}]}]}},"revision":1},{"id":"a6565eac-fd80-7d7e-a21e-ceef318a6735","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"4. Zero-Knowledge Proofs (ZKP)"}]},"revision":1},{"id":"d10bb10c-b3cc-78a1-a49d-7da616e8c90c","type":"text","position":"a8","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"ZKP is a cryptographic method that allows one party (the prover) to prove to another party (the verifier) that they know a secret value without revealing any information about the secret itself (e.g., proving identity without revealing the password)."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
WHERE EXISTS (SELECT 1 FROM "notes"."Note" n WHERE n.id = '2ec29b04-96db-7f24-980e-e9b63056252b' AND n."ownerId" = '019a118c-f480-7000-8000-000000000001' AND n."publishedVersionId" IS NULL AND n.visibility = 'PRIVATE' AND n."deletedAt" IS NULL AND n."draftUpdatedAt" = TIMESTAMPTZ '2026-10-07 03:23:53+00')
