SELECT '9d4f8094-34f4-74e8-99e0-2a48d0832e59', '864cefa7-1942-7af4-aeae-46b428892ef5', 1, 'PUBLISHED', 'Certificates & PKI', '[{"id":"2be19593-74fc-7f5b-8a55-9ff27e9f2a79","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Managing trust, X.509 certificate formats, certificate chains, and revocation validation."}]}]}},"revision":1},{"id":"28ced5ee-ec91-7e89-9706-bacac65f997e","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"1. X.509 Certificate Fields"}]},"revision":1},{"id":"670eb74c-714a-759b-9325-ae4ec1963236","type":"callout","position":"a2","content":{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A digital certificate is a cryptographically signed document that binds a public key to an entity''s identity (e.g. a domain name). Standardized under the "},{"type":"text","text":"X.509","marks":[{"type":"bold"}]},{"type":"text","text":" format, it contains:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Subject:","marks":[{"type":"bold"}]},{"type":"text","text":" The entity owning the public key (e.g., Common Name: "},{"type":"text","text":"c-note.io","marks":[{"type":"code"}]},{"type":"text","text":")."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Issuer:","marks":[{"type":"bold"}]},{"type":"text","text":" The Certificate Authority (CA) that validated the entity and signed the certificate."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Public Key:","marks":[{"type":"bold"}]},{"type":"text","text":" The entity''s public key (RSA or ECC coordinates)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Signature Algorithm:","marks":[{"type":"bold"}]},{"type":"text","text":" The algorithm used to sign the certificate (e.g. "},{"type":"text","text":"sha256WithRSAEncryption","marks":[{"type":"code"}]},{"type":"text","text":")."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Validity Period:","marks":[{"type":"bold"}]},{"type":"text","text":" The start and end dates for the certificate."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"CA Signature:","marks":[{"type":"bold"}]},{"type":"text","text":" The cryptographic signature of the Issuer CA, generated using the CA''s private key."}]}]}]}]}},"revision":1},{"id":"1f9d17a7-649d-7519-a112-5c2014b0b796","type":"heading","position":"a3","content":{"level":1,"content":[{"type":"text","text":"2. The Certificate Chain of Trust"}]},"revision":1},{"id":"09e33be2-92e1-7ed8-9bc4-0fda6b71806c","type":"text","position":"a4","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How browsers trust certificates by tracing them back to built-in Root CAs."}]}]}},"revision":1},{"id":"4726a622-ce8c-74f1-a5e3-244428f9fc31","type":"code","position":"a5","content":{"language":"","code":"+------------------------+\n|   Root CA Certificate  | -> Built into browser/OS trust store. Self-signed.\n+------------------------+\n           | Signs\n+------------------------+\n| Intermediate CA Cert   | -> Signed by Root. Used to sign leaf certs to protect root.\n+------------------------+\n           | Signs\n+------------------------+\n|   Leaf Certificate     | -> Installed on the web server (e.g., c-note.io).\n+------------------------+"},"revision":1},{"id":"b87f78fe-9bfb-7112-be7a-52cedfdeb31d","type":"heading","position":"a6","content":{"level":1,"content":[{"type":"text","text":"3. Certificate Revocation: CRL vs. OCSP"}]},"revision":1},{"id":"fa24f68d-d03c-7d01-a5d7-34d743a12f5f","type":"callout","position":"a7","content":{"variant":"tip","title":"CRL (Certificate Revocation List)","doc":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The CA publishes a signed list of revoked certificate serial numbers."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Clients download the entire list periodically to verify certificate status."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Drawbacks:","marks":[{"type":"bold"}]},{"type":"text","text":" High bandwidth usage, latency, and lists can become stale."}]}]}]}]}},"revision":1},{"id":"80c29fc6-5b05-7bf5-b7a5-5180c8e2f705","type":"callout","position":"a8","content":{"variant":"danger","title":"OCSP (Online Certificate Status Protocol)","doc":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Clients query the CA''s server directly to verify a certificate''s status."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"OCSP Stapling:","marks":[{"type":"bold"}]},{"type":"text","text":" The web server queries the CA''s status periodically, signs the response, and sends (\"staples\") it to the client during the TLS handshake, reducing latency and protecting privacy."}]}]}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
