  SELECT 1 FROM "notes"."Note" n
  WHERE n.id = '864cefa7-1942-7af4-aeae-46b428892ef5' AND n.visibility = 'PUBLIC' AND n."publishedVersionId" = '9d4f8094-34f4-74e8-99e0-2a48d0832e59' AND n."deletedAt" IS NULL
)
