INSERT INTO "notes"."NoteSearchDocument" ("noteId", "versionId", "title", "topics", "body", "document", "updatedAt")
SELECT '647211bb-d75f-7152-98c6-3d239e5b149b', 'a7d55ded-7d40-7333-9622-43cb7516edb8', 'System Diagrams', 'System Diagrams', 'Text diagrams detailing secure handshakes and persistent message flows.
1. Key Exchange Handshake (ECDH)
User A (Private a, Pub A=aG)                     User B (Private b, Pub B=bG)
      |                                                |
      |------------ [1. Upload PubKey A] ------------->| (Server Store)
      |                                                |
      |<----------- [2. Download PubKey B] ------------| (Server Retrieval)
      |                                                |
      |-- Derives shared secret S = a * Pub B (abG) ---|
      |-- Runs through HKDF -> Symmetric Session Key --|
2. Message Flow Routing Lifecycle
+---------+         +---------+         +-----------+         +--------+
| ClientA |         | Backend |         |  Database |         |ClientB |
+---------+         +---------+         +-----------+         +--------+
     |                   |                    |                    |
     |--[AES Encrypt]    |                    |                    |
     |                   |                    |                    |
     |--- websocket ---->|                    |                    |
     |    {ct, iv, tag}  |                    |                    |
     |                   |-- db.insert ------>|                    |
     |                   |   {ct, iv, tag}    |                    |
     |                   |                    |                    |
     |                   |----------- websocket -------------->|
     |                   |            {ct, iv, tag}            |
     |                   |                                     |
     |                   |                                [AES Decrypt]
     |                   |<---------- ack delivery ------------|
     |<-- ack delivery --|                                     |',
  setweight(to_tsvector('english', 'System Diagrams'), 'A')
    || setweight(to_tsvector('english', 'System Diagrams'), 'B')
    || setweight(to_tsvector('english', 'Text diagrams detailing secure handshakes and persistent message flows.
1. Key Exchange Handshake (ECDH)
User A (Private a, Pub A=aG)                     User B (Private b, Pub B=bG)
      |                                                |
      |------------ [1. Upload PubKey A] ------------->| (Server Store)
      |                                                |
      |<----------- [2. Download PubKey B] ------------| (Server Retrieval)
      |                                                |
      |-- Derives shared secret S = a * Pub B (abG) ---|
      |-- Runs through HKDF -> Symmetric Session Key --|
2. Message Flow Routing Lifecycle
+---------+         +---------+         +-----------+         +--------+
| ClientA |         | Backend |         |  Database |         |ClientB |
+---------+         +---------+         +-----------+         +--------+
     |                   |                    |                    |
     |--[AES Encrypt]    |                    |                    |
     |                   |                    |                    |
     |--- websocket ---->|                    |                    |
     |    {ct, iv, tag}  |                    |                    |
     |                   |-- db.insert ------>|                    |
     |                   |   {ct, iv, tag}    |                    |
     |                   |                    |                    |
     |                   |----------- websocket -------------->|
     |                   |            {ct, iv, tag}            |
     |                   |                                     |
     |                   |                                [AES Decrypt]
     |                   |<---------- ack delivery ------------|
     |<-- ack delivery --|                                     |'), 'C'),
  TIMESTAMPTZ '2026-10-07 03:23:53+00'
WHERE EXISTS (
  SELECT 1 FROM "notes"."Note" n
  WHERE n.id = '647211bb-d75f-7152-98c6-3d239e5b149b' AND n.visibility = 'PUBLIC' AND n."publishedVersionId" = 'a7d55ded-7d40-7333-9622-43cb7516edb8' AND n."deletedAt" IS NULL
)
ON CONFLICT DO NOTHING;

