INSERT INTO "notes"."NoteVersion" ("id", "noteId", "number", "kind", "title", "cards", "createdById", "createdAt")
SELECT 'e66df435-bb43-76a5-89d4-5e35a0c62198', 'ae8da301-e12f-7b23-91e2-67ce7e137185', 1, 'PUBLISHED', 'System Overview', '[{"id":"2defdc69-4187-7d91-9e39-1eb774795aff","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Production-grade End-to-End Encrypted (E2EE) messaging architectures, trust boundaries, and communication strategies."}]}]}},"revision":1},{"id":"9d986f5f-3d38-7b52-8bdb-c6285f3c30c3","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"E2EE Model Philosophy"}]},"revision":1},{"id":"fa66511a-d6e1-7697-bf06-73af7ca55ccd","type":"callout","position":"a2","content":{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"An "},{"type":"text","text":"End-to-End Encrypted (E2EE)","marks":[{"type":"bold"}]},{"type":"text","text":" message system ensures that payloads are encrypted on the sender''s device and can only be decrypted on the recipient''s device. The intermediate server handles routing and message persistence in a "},{"type":"text","text":"zero-knowledge","marks":[{"type":"bold"}]},{"type":"text","text":" manner — the backend never sees plaintext messages or keys."}]}]}},"revision":1},{"id":"514ff445-4dc4-70b7-84cc-fa67a3f48977","type":"heading","position":"a3","content":{"level":1,"content":[{"type":"text","text":"Core Architectural Pillars"}]},"revision":1},{"id":"9cc62edb-116a-7c69-ba75-a09dd1918cdb","type":"callout","position":"a4","content":{"variant":"note","title":"Key Exchange Model","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Diffie-Hellman Key Exchange (ECDH):","marks":[{"type":"bold"}]},{"type":"text","text":" Ephemeral or double-ratchet models are used to establish unique session keys between participants. Public keys are registered on the database, allowing offline negotiation."}]}]}},"revision":1},{"id":"eda1aac8-a3a1-7b80-ae4e-b4d8caad3051","type":"callout","position":"a5","content":{"variant":"note","title":"Message Encryption","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Authenticated Symmetric Encryption (AES-GCM):","marks":[{"type":"bold"}]},{"type":"text","text":" Message payloads are encrypted using a derived 256-bit symmetric session key with random 96-bit Initialization Vectors (IVs) and authentication tags to guarantee integrity."}]}]}},"revision":1},{"id":"f9ec2484-fc17-7b6c-830e-6d8d953adcaa","type":"callout","position":"a6","content":{"variant":"note","title":"Transport Channel","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Real-Time WebSockets (Socket.IO):","marks":[{"type":"bold"}]},{"type":"text","text":" Delivers low-latency message relaying between connected clients. Authentication occurs during the socket handshake using cryptographically signed tokens (JWTs)."}]}]}},"revision":1},{"id":"f21a7456-51aa-7f2d-b794-8f3851353b02","type":"callout","position":"a7","content":{"variant":"note","title":"Storage Strategy","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Encrypted persistence:","marks":[{"type":"bold"}]},{"type":"text","text":" The server stores the payload''s "},{"type":"text","text":"ciphertext","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"iv","marks":[{"type":"code"}]},{"type":"text","text":", and "},{"type":"text","text":"auth_tag","marks":[{"type":"code"}]},{"type":"text","text":". Routing metadata (timestamps, sender/receiver IDs) is plaintext, but payloads are locked."}]}]}},"revision":1},{"id":"7f749381-7f2e-7243-8dee-44265ab8045f","type":"heading","position":"a8","content":{"level":1,"content":[{"type":"text","text":"Trust Boundaries & Attack Surface"}]},"revision":1},{"id":"5d297f36-686b-7386-85d2-59ae84ac9ebf","type":"callout","position":"a9","content":{"variant":"tip","title":"Client-Side Secure Boundary","doc":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Private keys are generated locally and never transmitted to the network."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Private keys are decrypted in memory only using a key derived from password hashing (PBKDF2/Argon2)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Compromise of the database or transport channel does not expose message contents."}]}]}]}]}},"revision":1},{"id":"71879b09-ee3e-7bf2-a43a-1905bf4085d8","type":"callout","position":"aA","content":{"variant":"danger","title":"Remaining Attack Surface","doc":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Metadata Leakage:","marks":[{"type":"bold"}]},{"type":"text","text":" Server knows who is communicating, when, and how frequently."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"XSS / Local Exploits:","marks":[{"type":"bold"}]},{"type":"text","text":" If keys are stored in localStorage, a cross-site scripting attack can leak them."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"MITM Key Substitution:","marks":[{"type":"bold"}]},{"type":"text","text":" A malicious server could return its own public keys instead of the receiver''s."}]}]}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
WHERE EXISTS (SELECT 1 FROM "notes"."Note" n WHERE n.id = 'ae8da301-e12f-7b23-91e2-67ce7e137185' AND n."ownerId" = '019a118c-f480-7000-8000-000000000001' AND n."publishedVersionId" IS NULL AND n.visibility = 'PRIVATE' AND n."deletedAt" IS NULL AND n."draftUpdatedAt" = TIMESTAMPTZ '2026-10-07 03:23:53+00')
