SELECT '82e04b32-a679-7c54-b4cc-56476727357e', '0116325f-5fbd-7463-936a-9e9e5356908e', 1, 'PUBLISHED', 'Threat Model', '[{"id":"51a047d4-6a14-7228-94c6-1235ac5adca4","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Evaluating the architecture against standard cybersecurity attack vectors and exploits."}]}]}},"revision":1},{"id":"35e8a608-6fa4-7003-b702-b0c34e74f759","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Attack Vector Analysis"}]},"revision":1},{"id":"ab99bd26-e519-7ff4-8353-96a8c39112e6","type":"callout","position":"a2","content":{"variant":"note","title":"Man-in-the-Middle (MITM)","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Threat:","marks":[{"type":"bold"}]},{"type":"text","text":" The server acts as a proxy, returning a fake public key to User A so it can decrypt messages."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"Mitigation:","marks":[{"type":"bold"}]},{"type":"text","text":" Visual safety numbers (computed from hashes of public keys) are compared out-of-band by users, or public keys are signed by a Certificate Authority."}]}]}},"revision":1},{"id":"a36c98d9-c760-7fc5-bada-3c6d5f284850","type":"callout","position":"a3","content":{"variant":"note","title":"Compromised Server Database","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Threat:","marks":[{"type":"bold"}]},{"type":"text","text":" An attacker steals all records from the messages table."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"Mitigation:","marks":[{"type":"bold"}]},{"type":"text","text":" Payloads are stored as ciphertext. Only metadata (sender ID, time) is exposed. Message content remains secure."}]}]}},"revision":1},{"id":"e9f4d122-f1ff-7815-8a77-93871082e088","type":"callout","position":"a4","content":{"variant":"note","title":"Replay Attacks","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Threat:","marks":[{"type":"bold"}]},{"type":"text","text":" An attacker intercepts an encrypted message packet and forwards it to the recipient repeatedly."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"Mitigation:","marks":[{"type":"bold"}]},{"type":"text","text":" The encrypted packet contains a sequence counter and timestamp. Recipient rejects duplicated or expired sequences."}]}]}},"revision":1},{"id":"315f6601-52bf-7081-897d-4b481b60a496","type":"callout","position":"a5","content":{"variant":"note","title":"XSS Key Leakage","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Threat:","marks":[{"type":"bold"}]},{"type":"text","text":" A cross-site scripting script accesses local IndexedDB variables and exfiltrates private keys."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"Mitigation:","marks":[{"type":"bold"}]},{"type":"text","text":" Keys are kept in-memory (volatile storage) or loaded only within a sandbox Web Worker that restricts DOM access."}]}]}},"revision":1},{"id":"4dff47d5-da00-72ea-ba65-cb903dce155f","type":"heading","position":"a6","content":{"level":1,"content":[{"type":"text","text":"Forward Secrecy Definition"}]},"revision":1},{"id":"0a61ea0b-e5dd-7be0-8d47-ddc29e61b658","type":"callout","position":"a7","content":{"variant":"note","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Forward Secrecy:","marks":[{"type":"bold"}]},{"type":"text","text":" If an attacker compromises the private keys of User A or User B today, they must not be able to decrypt past conversations. This is achieved by generating "},{"type":"text","text":"ephemeral keys","marks":[{"type":"bold"}]},{"type":"text","text":" that are destroyed after a session is closed."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
WHERE EXISTS (SELECT 1 FROM "notes"."Note" n WHERE n.id = '0116325f-5fbd-7463-936a-9e9e5356908e' AND n."ownerId" = '019a118c-f480-7000-8000-000000000001' AND n."publishedVersionId" IS NULL AND n.visibility = 'PRIVATE' AND n."deletedAt" IS NULL AND n."draftUpdatedAt" = TIMESTAMPTZ '2026-10-07 03:23:53+00')
