INSERT INTO "notes"."NoteVersion" ("id", "noteId", "number", "kind", "title", "cards", "createdById", "createdAt")
SELECT '7c28c965-a28e-729a-b06a-5827e3ca57f0', '42914687-4ee5-7011-8cd2-56ebba8f168d', 1, 'PUBLISHED', 'API Design', '[{"id":"7b7e479b-184a-7e24-b189-f00073f2ebb3","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Principles and patterns for designing robust, scalable, and developer-friendly application programming interfaces."}]}]}},"revision":1},{"id":"ada12c3c-1ac6-7764-8c15-7330b8599902","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"REST vs GraphQL vs gRPC"}]},"revision":1},{"id":"0ad19081-a191-7c94-955b-fe819bc16552","type":"callout","position":"a2","content":{"variant":"note","title":"REST","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Resource-based, HTTP verbs, stateless, JSON. Universal client support. Over-fetching/under-fetching is the main pain. Use for public APIs."}]}]}},"revision":1},{"id":"a9f457f3-37a0-78b4-93bc-df60f2afdc5d","type":"callout","position":"a3","content":{"variant":"note","title":"GraphQL","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Client specifies exact data needed. Single endpoint. No over/under-fetching. Complex queries can be expensive server-side. Great for mobile clients."}]}]}},"revision":1},{"id":"454f6709-e351-7a41-a869-b0619e8751c6","type":"callout","position":"a4","content":{"variant":"note","title":"gRPC","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Binary protocol (Protocol Buffers). 5–10× faster than REST. Strongly typed. Bi-directional streaming. Used for internal microservice communication."}]}]}},"revision":1},{"id":"04442074-704a-7bb1-a942-fd947c2e83fa","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"Rate Limiting"}]},"revision":1},{"id":"03938fa1-4208-72c5-8de4-7edecc0236e8","type":"callout","position":"a6","content":{"variant":"note","title":"Rate Limiting Algorithms","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Token Bucket:","marks":[{"type":"bold"}]},{"type":"text","text":" Tokens added at fixed rate; each request consumes a token. Allows bursts."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"Leaky Bucket:","marks":[{"type":"bold"}]},{"type":"text","text":" Requests processed at fixed rate regardless of input. Smooths bursts."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"Fixed Window Counter:","marks":[{"type":"bold"}]},{"type":"text","text":" Count requests per time window. Simple but vulnerable to boundary attacks."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"Sliding Window Log:","marks":[{"type":"bold"}]},{"type":"text","text":" Track timestamps of each request. Precise but memory-intensive."}]}]}},"revision":1},{"id":"5461905c-15ad-7b6e-8b3c-abcbb0dd60a9","type":"callout","position":"a7","content":{"variant":"note","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Idempotency:","marks":[{"type":"bold"}]},{"type":"text","text":" Design mutating API endpoints to be idempotent — calling them multiple times produces the same result. Use idempotency keys (unique request IDs) to deduplicate retried requests. Critical for payment APIs."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
WHERE EXISTS (SELECT 1 FROM "notes"."Note" n WHERE n.id = '42914687-4ee5-7011-8cd2-56ebba8f168d' AND n."ownerId" = '019a118c-f480-7000-8000-000000000001' AND n."publishedVersionId" IS NULL AND n.visibility = 'PRIVATE' AND n."deletedAt" IS NULL AND n."draftUpdatedAt" = TIMESTAMPTZ '2026-10-07 03:23:53+00')
ON CONFLICT DO NOTHING;

