SELECT '1a81a280-03a0-7993-b23a-ff14b7eb8bde', 'e6830624-6920-71a6-9b67-d5f89d9366b8', 1, 'PUBLISHED', 'Caching Deep-Dive', '[{"id":"290d6c66-852e-7380-8b49-c40396ce368c","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Comprehensive master guide to caching strategies, Redis eviction policies, consistent hashing, cache stampede mitigations, and distributed Redis cluster topology."}]}]}},"revision":1},{"id":"d0b8040a-68c3-776b-8ee4-19c09d480f09","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Cache Strategies & Design Patterns"}]},"revision":1},{"id":"2a293c20-fde3-78e1-9d55-4423719b76f3","type":"callout","position":"a2","content":{"variant":"note","title":"Cache-Aside (Lazy Loading)","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"App checks cache first. On miss, app fetches from DB, populates cache, and returns data. "},{"type":"text","text":"Resilient to cache outages","marks":[{"type":"bold"}]},{"type":"text","text":", but cache misses incur 3 network round-trips."}]}]}},"revision":1},{"id":"1e2fd085-65f0-79b1-a2f5-e5215918a977","type":"callout","position":"a3","content":{"variant":"note","title":"Read-Through","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"App interacts only with Cache abstraction layer. On cache miss, the Cache library automatically fetches from DB, populates itself, and returns data to App."}]}]}},"revision":1},{"id":"2162763f-3fad-7f38-9800-a621642d4794","type":"callout","position":"a4","content":{"variant":"note","title":"Write-Through","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"App writes to Cache. Cache synchronously updates DB before returning success. Guarantees cache consistency, but increases write latency."}]}]}},"revision":1},{"id":"d6145936-31ba-79e9-b11e-0f7d1b38f453","type":"callout","position":"a5","content":{"variant":"note","title":"Write-Behind (Write-Back)","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"App writes to Cache immediately. Cache asynchronously batches and flushes writes to DB in background. Ultra-low write latency, but "},{"type":"text","text":"risk of data loss","marks":[{"type":"bold"}]},{"type":"text","text":" if cache node crashes before DB sync."}]}]}},"revision":1},{"id":"063df1b0-2395-7207-aec9-79425d4c4e11","type":"heading","position":"a6","content":{"level":1,"content":[{"type":"text","text":"Redis Eviction Policies"}]},"revision":1},{"id":"ffe64f7c-9c96-7e31-8709-d5fde095c48b","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"Redis "},{"type":"text","text":"maxmemory-policy","marks":[{"type":"code"}]},{"type":"text","text":" Settings"}]},"revision":1},{"id":"121e66ee-2583-7c08-a7c1-c70427356423","type":"table","position":"a8","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Policy"}],[{"type":"text","text":"Scope"}],[{"type":"text","text":"Behavior"}]],[[{"type":"text","text":"noeviction","marks":[{"type":"code"}]}],[{"type":"text","text":"All Keys"}],[{"type":"text","text":"Returns error on writes when memory limit reached. Best for critical caches."}]],[[{"type":"text","text":"allkeys-lru","marks":[{"type":"code"}]}],[{"type":"text","text":"All Keys"}],[{"type":"text","text":"Evicts Least Recently Used keys across entire dataset. (Most popular choice)."}]],[[{"type":"text","text":"volatile-lru","marks":[{"type":"code"}]}],[{"type":"text","text":"Keys with TTL"}],[{"type":"text","text":"Evicts Least Recently Used keys among keys configured with expiration TTL."}]],[[{"type":"text","text":"allkeys-lfu","marks":[{"type":"code"}]}],[{"type":"text","text":"All Keys"}],[{"type":"text","text":"Evicts Least Frequently Used keys using logarithmic access counters."}]],[[{"type":"text","text":"volatile-ttl","marks":[{"type":"code"}]}],[{"type":"text","text":"Keys with TTL"}],[{"type":"text","text":"Evicts keys with the shortest remaining Time-To-Live."}]]]},"revision":1},{"id":"95731e8c-5790-7c9d-9936-ba3877343ad6","type":"heading","position":"a9","content":{"level":1,"content":[{"type":"text","text":"Cache Stampede & Hot Key Mitigation"}]},"revision":1},{"id":"c09fd6a1-307a-7154-8db7-9024e0125a75","type":"callout","position":"aA","content":{"variant":"note","title":"Cache Stampede (Thundering Herd)","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Occurs when a popular cached key expires, causing thousands of concurrent requests to hit the DB simultaneously."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":" • "},{"type":"text","text":"Mutex / Distributed Locking:","marks":[{"type":"bold"}]},{"type":"text","text":" First thread acquires lock, populates cache; remaining threads wait."},{"type":"hardBreak"},{"type":"text","text":" • "},{"type":"text","text":"Probabilistic Early Expiration (XFetch Algorithm):","marks":[{"type":"bold"}]},{"type":"text","text":" Recomputes key early if "},{"type":"text","text":"currentTime - (beta * delta * ln(rnd)) > TTL","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"0577ee49-4f2a-7060-890a-e1eb4f904f4d","type":"callout","position":"aB","content":{"variant":"note","title":"Hot Key Bottleneck","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Single key receives millions of requests/sec overloading a single cache node."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":" • "},{"type":"text","text":"L1 Local Memory Cache:","marks":[{"type":"bold"}]},{"type":"text","text":" In-process cache (Guava/Caffeine) on application servers."},{"type":"hardBreak"},{"type":"text","text":" • "},{"type":"text","text":"Key Sharding / Random Suffix:","marks":[{"type":"bold"}]},{"type":"text","text":" Replicate key as "},{"type":"text","text":"item_key_1","marks":[{"type":"code"}]},{"type":"text","text":"..."},{"type":"text","text":"item_key_N","marks":[{"type":"code"}]},{"type":"text","text":" across nodes."}]}]}},"revision":1},{"id":"d6addeec-539f-7b1f-bff6-96e7c4ded428","type":"heading","position":"aC","content":{"level":1,"content":[{"type":"text","text":"Redis Cluster vs Redis Sentinel"}]},"revision":1},{"id":"7e04e33f-1cbf-7053-a59e-bd6aa6d4cff4","type":"callout","position":"aD","content":{"variant":"note","title":"Redis Sentinel","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"High availability solution for single-master topologies. Sentinels monitor primary, trigger automated failover to replica if primary dies, and notify app clients."}]}]}},"revision":1},{"id":"fead8c15-5447-7d7b-b30c-51179c7d5f9f","type":"callout","position":"aE","content":{"variant":"note","title":"Redis Cluster","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Distributed horizontal scaling solution. Divides key space into "},{"type":"text","text":"16,384 Hash Slots","marks":[{"type":"bold"}]},{"type":"text","text":" assigned across master nodes using CRC16: "},{"type":"text","text":"slot = CRC16(key) mod 16384","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
WHERE EXISTS (SELECT 1 FROM "notes"."Note" n WHERE n.id = 'e6830624-6920-71a6-9b67-d5f89d9366b8' AND n."ownerId" = '019a118c-f480-7000-8000-000000000001' AND n."publishedVersionId" IS NULL AND n.visibility = 'PRIVATE' AND n."deletedAt" IS NULL AND n."draftUpdatedAt" = TIMESTAMPTZ '2026-10-07 03:23:53+00')
