SELECT '1ea11085-5db8-7f43-a61c-9bde45882727', 'bc360275-95d1-724c-93db-48b16122351e', 1, 'PUBLISHED', 'DB Internals', '[{"id":"17e52a2b-d2eb-71eb-acc8-716431322084","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Under the hood mechanics of Multi-Version Concurrency Control, transaction isolation anomalies, 2PL, index types, deadlock detection, and cost-based query optimization."}]}]}},"revision":1},{"id":"71309f1c-93a0-7f2e-8209-65d3135bd572","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"MVCC (Multi-Version Concurrency Control)"}]},"revision":1},{"id":"37e17a7c-0653-7350-80c3-b9e7cc8a3bea","type":"callout","position":"a2","content":{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"MVCC Mechanics:","marks":[{"type":"bold"}]},{"type":"text","text":" Allows concurrent readers and writers without blocking each other (\"Readers don''t block Writers, Writers don''t block Readers\")."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":" • "},{"type":"text","text":"Tuple Header Fields:","marks":[{"type":"bold"}]},{"type":"text","text":" Each row stores metadata fields: "},{"type":"text","text":"xmin","marks":[{"type":"code"}]},{"type":"text","text":" (Transaction ID that created the tuple) and "},{"type":"text","text":"xmax","marks":[{"type":"code"}]},{"type":"text","text":" (Transaction ID that deleted/overwrote the tuple)."},{"type":"hardBreak"},{"type":"text","text":" • "},{"type":"text","text":"Read Views:","marks":[{"type":"bold"}]},{"type":"text","text":" When a transaction begins, it takes a snapshot view of active transactions. A tuple is visible only if "},{"type":"text","text":"xmin","marks":[{"type":"code"}]},{"type":"text","text":" is committed and "},{"type":"text","text":"xmax","marks":[{"type":"code"}]},{"type":"text","text":" is uncommitted or "},{"type":"text","text":"> current_tx","marks":[{"type":"code"}]},{"type":"text","text":"."},{"type":"hardBreak"},{"type":"text","text":" • "},{"type":"text","text":"Undo Logs & Vacuuming:","marks":[{"type":"bold"}]},{"type":"text","text":" Old tuple versions are retained in Undo Logs / Dead pages and asynchronously garbage collected by background Vacuum processes."}]}]}},"revision":1},{"id":"70ef8712-3a3a-7852-8c10-c5b56106f3bc","type":"heading","position":"a3","content":{"level":1,"content":[{"type":"text","text":"Isolation Levels & Anomalies Matrix"}]},"revision":1},{"id":"5422e728-5917-70d6-9066-d54dd5b5f8b3","type":"heading","position":"a4","content":{"level":1,"content":[{"type":"text","text":"ANSI SQL & Snapshot Isolation Anomalies"}]},"revision":1},{"id":"ee6988ad-1f1a-7eea-90d5-2edf66e73472","type":"table","position":"a5","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Isolation Level"}],[{"type":"text","text":"Dirty Read"}],[{"type":"text","text":"Non-Repeatable Read"}],[{"type":"text","text":"Phantom Read"}],[{"type":"text","text":"Write Skew"}]],[[{"type":"text","text":"Read Uncommitted","marks":[{"type":"bold"}]}],[{"type":"text","text":"Allowed"}],[{"type":"text","text":"Allowed"}],[{"type":"text","text":"Allowed"}],[{"type":"text","text":"Allowed"}]],[[{"type":"text","text":"Read Committed","marks":[{"type":"bold"}]}],[{"type":"text","text":"Prevented"}],[{"type":"text","text":"Allowed"}],[{"type":"text","text":"Allowed"}],[{"type":"text","text":"Allowed"}]],[[{"type":"text","text":"Repeatable Read","marks":[{"type":"bold"}]}],[{"type":"text","text":"Prevented"}],[{"type":"text","text":"Prevented"}],[{"type":"text","text":"Allowed (SQL Standard)"}],[{"type":"text","text":"Allowed"}]],[[{"type":"text","text":"Snapshot Isolation","marks":[{"type":"bold"}]}],[{"type":"text","text":"Prevented"}],[{"type":"text","text":"Prevented"}],[{"type":"text","text":"Prevented"}],[{"type":"text","text":"Allowed"}]],[[{"type":"text","text":"Serializable (SSI)","marks":[{"type":"bold"}]}],[{"type":"text","text":"Prevented"}],[{"type":"text","text":"Prevented"}],[{"type":"text","text":"Prevented"}],[{"type":"text","text":"Prevented"}]]]},"revision":1},{"id":"805b0eab-276c-747a-adb0-064520946770","type":"heading","position":"a6","content":{"level":1,"content":[{"type":"text","text":"Locking & Concurrency Control"}]},"revision":1},{"id":"91f6e26d-7293-74d0-afe1-7976532f6a75","type":"callout","position":"a7","content":{"variant":"note","title":"Lock Types & Intent Locks","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"• "},{"type":"text","text":"Shared (S):","marks":[{"type":"bold"}]},{"type":"text","text":" Read lock. Multiple transactions can hold S locks."},{"type":"hardBreak"},{"type":"text","text":" • "},{"type":"text","text":"Exclusive (X):","marks":[{"type":"bold"}]},{"type":"text","text":" Write lock. Only one transaction can hold X lock."},{"type":"hardBreak"},{"type":"text","text":" • "},{"type":"text","text":"Intent Locks (IS, IX, SIX):","marks":[{"type":"bold"}]},{"type":"text","text":" Placed at table level before acquiring row locks to prevent coarse-grained lock conflicts without scanning rows."}]}]}},"revision":1},{"id":"e5e1c4f2-849d-7212-a943-6a602228e14c","type":"callout","position":"a8","content":{"variant":"note","title":"Two-Phase Locking (2PL)","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"• "},{"type":"text","text":"Growing Phase:","marks":[{"type":"bold"}]},{"type":"text","text":" Transaction acquires locks, cannot release any."},{"type":"hardBreak"},{"type":"text","text":" • "},{"type":"text","text":"Shrinking Phase:","marks":[{"type":"bold"}]},{"type":"text","text":" Transaction releases locks, cannot acquire new ones."},{"type":"hardBreak"},{"type":"text","text":" • "},{"type":"text","text":"Strict 2PL:","marks":[{"type":"bold"}]},{"type":"text","text":" All exclusive locks held until transaction commits/aborts (prevents cascading rollbacks)."}]}]}},"revision":1},{"id":"2c07434d-b73f-7cd0-865a-f089e70fc014","type":"heading","position":"a9","content":{"level":1,"content":[{"type":"text","text":"Deadlock Detection & Prevention"}]},"revision":1},{"id":"204cd756-37ae-7d8f-989c-ddc6906d290b","type":"callout","position":"aA","content":{"variant":"note","title":"Wait-For Graph (WFG)","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Background thread periodically builds directed graph of transactions waiting for locks. A cycle indicates a deadlock. System selects a "},{"type":"text","text":"victim transaction","marks":[{"type":"bold"}]},{"type":"text","text":" and aborts it to break the cycle."}]}]}},"revision":1},{"id":"df1ebe79-69e1-7e45-9910-842dcf9a4d6c","type":"callout","position":"aB","content":{"variant":"note","title":"Wait-Die vs Wound-Wait","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"• "},{"type":"text","text":"Wait-Die (Non-preemptive):","marks":[{"type":"bold"}]},{"type":"text","text":" Older Tx waits for younger Tx; Younger Tx dies if requesting older lock."},{"type":"hardBreak"},{"type":"text","text":" • "},{"type":"text","text":"Wound-Wait (Preemptive):","marks":[{"type":"bold"}]},{"type":"text","text":" Older Tx preempts (\"wounds\") younger Tx; Younger Tx waits for older Tx."}]}]}},"revision":1},{"id":"0d027f58-931a-79bd-bb2e-ad1b31ab7a34","type":"heading","position":"aC","content":{"level":1,"content":[{"type":"text","text":"Cost-Based Query Optimizer (CBO)"}]},"revision":1},{"id":"bb8ab53c-f291-7d83-bb97-c23aa7d513a5","type":"callout","position":"aD","content":{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"CBO Execution Workflow:","marks":[{"type":"bold"}]},{"type":"text","text":" SQL Query → Parser (Abstract Syntax Tree) → Query Rewriter → Optimizer (Estimates I/O + CPU costs using column histograms/statistics) → Physical Execution Plan (Nested Loop Join vs Hash Join vs Merge Join)."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
