INSERT INTO "notes"."NoteVersion" ("id", "noteId", "number", "kind", "title", "cards", "createdById", "createdAt")
SELECT '9baaf480-10cb-74d7-ae9a-7da1fc02dd87', '201449b2-2f5f-78a4-a34e-10f47d3f5cbd', 1, 'PUBLISHED', 'Distributed Systems', '[{"id":"ef6b08f4-3726-716b-ac7a-2ee2f4fc1352","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Fundamental protocols, consensus mechanics, failure detection algorithms, and coordination engines powering global scale systems."}]}]}},"revision":1},{"id":"51c8ec4d-a1d3-7505-9e7b-519e58deb9a4","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Leader Election & Consensus Protocols"}]},"revision":1},{"id":"77058d10-931c-7828-abc4-930414ba6774","type":"callout","position":"a2","content":{"variant":"note","title":"Raft Consensus Protocol","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Decomposes consensus into Leader Election, Log Replication, and Safety. Nodes operate in 3 states: "},{"type":"text","text":"Follower","marks":[{"type":"bold"}]},{"type":"text","text":", "},{"type":"text","text":"Candidate","marks":[{"type":"bold"}]},{"type":"text","text":", or "},{"type":"text","text":"Leader","marks":[{"type":"bold"}]},{"type":"text","text":"."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":" • "},{"type":"text","text":"Election Mechanics:","marks":[{"type":"bold"}]},{"type":"text","text":" Randomized election timeouts (150–300ms) prevent split votes. Followers convert to Candidate if no heartbeat received."},{"type":"hardBreak"},{"type":"text","text":" • "},{"type":"text","text":"Log Replication:","marks":[{"type":"bold"}]},{"type":"text","text":" Leader receives client commands, writes to log, and broadcasts "},{"type":"text","text":"AppendEntries","marks":[{"type":"code"}]},{"type":"text","text":" RPCs. Uncommitted entries become committed when replicated to a Quorum majority: "},{"type":"text","text":"Quorum = ⌊N/2⌋ + 1","marks":[{"type":"code"}]},{"type":"text","text":"."},{"type":"hardBreak"},{"type":"text","text":" • "},{"type":"text","text":"Leader Completeness:","marks":[{"type":"bold"}]},{"type":"text","text":" A candidate must contain all committed entries to win an election (Term numbers enforced)."}]}]}},"revision":1},{"id":"65665f7f-c50d-78b7-8381-0401da5f8a1d","type":"callout","position":"a3","content":{"variant":"note","title":"Paxos Protocol (Overview)","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The foundational consensus protocol for asynchronous networks with crash-stop failures."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":" • "},{"type":"text","text":"Roles:","marks":[{"type":"bold"}]},{"type":"text","text":" Proposers (propose values), Acceptors (vote on values), Learners (learn agreed value)."},{"type":"hardBreak"},{"type":"text","text":" • "},{"type":"text","text":"Phase 1a (Prepare):","marks":[{"type":"bold"}]},{"type":"text","text":" Proposer sends "},{"type":"text","text":"Prepare(n)","marks":[{"type":"code"}]},{"type":"text","text":" with proposal number "},{"type":"text","text":"n","marks":[{"type":"italic"}]},{"type":"text","text":"."},{"type":"hardBreak"},{"type":"text","text":" • "},{"type":"text","text":"Phase 1b (Promise):","marks":[{"type":"bold"}]},{"type":"text","text":" Acceptors respond with "},{"type":"text","text":"Promise","marks":[{"type":"code"}]},{"type":"text","text":" not to accept proposals "},{"type":"text","text":"< n","marks":[{"type":"code"}]},{"type":"text","text":", returning highest proposal accepted."},{"type":"hardBreak"},{"type":"text","text":" • "},{"type":"text","text":"Phase 2a (Accept):","marks":[{"type":"bold"}]},{"type":"text","text":" If Proposer receives majority promises, sends "},{"type":"text","text":"Accept(n, v)","marks":[{"type":"code"}]},{"type":"text","text":"."},{"type":"hardBreak"},{"type":"text","text":" • "},{"type":"text","text":"Phase 2b (Accepted):","marks":[{"type":"bold"}]},{"type":"text","text":" Acceptors accept value if "},{"type":"text","text":"n","marks":[{"type":"italic"}]},{"type":"text","text":" is still highest seen."},{"type":"hardBreak"},{"type":"text","text":" • "},{"type":"text","text":"Multi-Paxos:","marks":[{"type":"bold"}]},{"type":"text","text":" Stabilizes a single leader across proposal streams to eliminate Phase 1 round-trips for high throughput."}]}]}},"revision":1},{"id":"bb7978b6-a92f-7105-9007-1e053f791002","type":"heading","position":"a4","content":{"level":1,"content":[{"type":"text","text":"Gossip Protocol & P2P Membership"}]},"revision":1},{"id":"290d63bb-26a2-7029-a5d8-103b8e5012c1","type":"callout","position":"a5","content":{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Gossip Protocol:","marks":[{"type":"bold"}]},{"type":"text","text":" A decentralized peer-to-peer communication protocol inspired by epidemic spreading. Every node periodically selects random peers and exchanges cluster state. Offers "},{"type":"text","text":"O(log N)","marks":[{"type":"code"}]},{"type":"text","text":" convergence time, extreme fault tolerance, and zero single point of failure."}]}]}},"revision":1},{"id":"18612fc1-3161-75b7-933e-63012a4c66ac","type":"callout","position":"a6","content":{"variant":"note","title":"SWIM Protocol","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Structured Weakness-Detection & Infection-Style Process Group Membership:","marks":[{"type":"bold"}]},{"type":"text","text":" Separates failure detection from membership updates. Node A pings Node B. If no ACK, Node A requests "},{"type":"text","text":"k","marks":[{"type":"italic"}]},{"type":"text","text":" indirect peers to ping Node B. Prevents false failure detections caused by transient network congestion."}]}]}},"revision":1},{"id":"8791039e-369c-7848-865b-cf531c79c830","type":"callout","position":"a7","content":{"variant":"note","title":"Anti-Entropy & Dissemination","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"• "},{"type":"text","text":"Rumor-Mongering:","marks":[{"type":"bold"}]},{"type":"text","text":" Fast infection mode for immediate state changes."},{"type":"hardBreak"},{"type":"text","text":"• "},{"type":"text","text":"Anti-Entropy:","marks":[{"type":"bold"}]},{"type":"text","text":" Periodic full background comparison (using Merkle Trees) to guarantee eventual consistency across cluster nodes."}]}]}},"revision":1},{"id":"05a6c006-2046-7bf9-9b2a-dba08e5221bf","type":"heading","position":"a8","content":{"level":1,"content":[{"type":"text","text":"Heartbeats & Failure Detectors"}]},"revision":1},{"id":"0ae5fe40-4502-7ab8-b90b-3d867f593037","type":"callout","position":"a9","content":{"variant":"note","title":"Lease Timeouts","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Fixed time window heartbeats. Simple but prone to false positives under high garbage collection (GC) pauses or temporary network spikes."}]}]}},"revision":1},{"id":"d3ac39d7-89b3-749b-a851-abc31868a10a","type":"callout","position":"aA","content":{"variant":"note","title":"Phi Accrual Failure Detector","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Calculates a continuous suspicion level "},{"type":"text","text":"Φ","marks":[{"type":"code"}]},{"type":"text","text":" using historical inter-arrival time distributions:"},{"type":"hardBreak"},{"type":"text","text":" "},{"type":"text","text":"Φ = -log10(P_later(t - t_last))","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":" Adapts dynamically to fluctuating network latency, enabling configurable sensitivity thresholds without fixed timeouts (used in Cassandra and Akka)."}]}]}},"revision":1},{"id":"04479b78-af60-7a1f-adc7-acff28fc9e35","type":"heading","position":"aB","content":{"level":1,"content":[{"type":"text","text":"Service Discovery Architecture"}]},"revision":1},{"id":"4bb4928a-5d60-7268-a586-05d92587a316","type":"callout","position":"aC","content":{"variant":"note","title":"Client-Side Discovery","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Client queries Service Registry (e.g., Eureka), obtains healthy instance IP endpoints, and executes local load balancing algorithm (e.g., Round Robin, Least Connections). High speed, no proxy bottleneck."}]}]}},"revision":1},{"id":"413f75b7-4b91-7740-8b94-efb4018e0f07","type":"callout","position":"aD","content":{"variant":"note","title":"Server-Side Discovery","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Client issues request directly to a Load Balancer (e.g., AWS ALB, NGINX). Load Balancer queries Service Registry and routes request to healthy target nodes. Hides infrastructure complexity from clients."}]}]}},"revision":1},{"id":"19258c5e-2c90-75a7-926e-3933bf3e75c6","type":"heading","position":"aE","content":{"level":1,"content":[{"type":"text","text":"Coordination Tools Comparison"}]},"revision":1},{"id":"b1d13355-a781-7c36-859a-9a48dfe12006","type":"heading","position":"aF","content":{"level":1,"content":[{"type":"text","text":"Distributed Coordination Engines"}]},"revision":1},{"id":"e2d44de3-6c0c-708a-9888-faf7dcf4e104","type":"table","position":"aG","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Engine"}],[{"type":"text","text":"Consensus"}],[{"type":"text","text":"Data Model"}],[{"type":"text","text":"Key Features"}],[{"type":"text","text":"Primary Use Case"}]],[[{"type":"text","text":"ZooKeeper","marks":[{"type":"bold"}]}],[{"type":"text","text":"Zab"}],[{"type":"text","text":"Hierarchical ZNodes (Tree)"}],[{"type":"text","text":"Watcher events, Ephemeral nodes, Sequential IDs"}],[{"type":"text","text":"Kafka metadata (legacy), Hadoop, Solr"}]],[[{"type":"text","text":"etcd","marks":[{"type":"bold"}]}],[{"type":"text","text":"Raft"}],[{"type":"text","text":"Flat KV (B+ Tree with MVCC)"}],[{"type":"text","text":"gRPC API, Lease grants, Watch streams, Distributed locks"}],[{"type":"text","text":"Kubernetes Control Plane state storage"}]],[[{"type":"text","text":"Consul","marks":[{"type":"bold"}]}],[{"type":"text","text":"Raft + Serf Gossip"}],[{"type":"text","text":"KV Store + Service Registry"}],[{"type":"text","text":"Native Service Mesh (Envoy sidecars), DNS interface, Health checks"}],[{"type":"text","text":"Microservice discovery & Config management"}]]]},"revision":1},{"id":"7c638037-a046-7202-86ec-74173c57f17b","type":"callout","position":"aH","content":{"variant":"note","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Key Interview Takeaway:","marks":[{"type":"bold"}]},{"type":"text","text":" In system design interviews, never state \"we use ZooKeeper\" without specifying why. ZooKeeper/etcd are designed for "},{"type":"text","text":"strong consistency and small metadata volumes","marks":[{"type":"bold"}]},{"type":"text","text":". Never use them as primary data stores for high-throughput user traffic."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
