  WHERE n.id = '5e7b257e-10b3-7d90-a0d5-f557973e4a07' AND n.visibility = 'PUBLIC' AND n."publishedVersionId" = '48aa367e-d5d4-733d-97bb-bc075bda09c5' AND n."deletedAt" IS NULL
)
