  SELECT 1 FROM "notes"."Note" n
  WHERE n.id = 'f8780c20-a005-7d32-bd42-f6fd75f32e3e' AND n.visibility = 'PUBLIC' AND n."publishedVersionId" = '3a30c49b-1f28-7cf1-96e7-470555fbf375' AND n."deletedAt" IS NULL
)
ON CONFLICT DO NOTHING;

