SELECT '593b5735-1cfe-71ba-a2b4-4f8132129346', '197d0ff2-9718-73bd-a45a-8967f2adae4f', 1, 'PUBLISHED', 'Interview Tips', '[{"id":"c5f99f62-c823-7051-9095-1ce1ff52c393","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A structured approach to system design interviews. The difference between senior and staff-level candidates is almost entirely in how they structure their thinking."}]}]}},"revision":1},{"id":"d56198cf-a170-70c2-a0b4-8bf069028832","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"The 5-Step Framework"}]},"revision":1},{"id":"c68761b4-1be5-7445-ae87-0da2a2a8ff75","type":"callout","position":"a2","content":{"variant":"note","title":"1. Clarify Requirements (5 min)","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Don''t assume. Ask: Who are the users? What''s the scale? Read vs write heavy? Any specific constraints? Latency requirements? Global or regional? Active users vs registered?"}]}]}},"revision":1},{"id":"7a3453ec-d821-72be-b7f2-9b00ab5f3f74","type":"callout","position":"a3","content":{"variant":"note","title":"2. Estimate Scale (3 min)","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"QPS, storage, bandwidth. This drives your architectural choices. A system serving 1K users vs 1B users is completely different. Do this out loud — show your math."}]}]}},"revision":1},{"id":"a4e87be1-91bb-7afd-b293-cd6205fc1487","type":"callout","position":"a4","content":{"variant":"note","title":"3. High-Level Design (10 min)","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Draw the major components: clients, load balancers, API servers, databases, caches, queues, CDN. Don''t go deep yet — get the full picture down first."}]}]}},"revision":1},{"id":"34fd3974-9a4e-7036-bf2f-f5ddcb29c3dc","type":"callout","position":"a5","content":{"variant":"note","title":"4. Deep Dive (15 min)","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The interviewer will guide you to the interesting part. Common deep dives: database schema, feed generation algorithm, consistency model, handling failures."}]}]}},"revision":1},{"id":"aff787b5-d354-7d0b-a209-3280d3b178c4","type":"callout","position":"a6","content":{"variant":"note","title":"5. Trade-offs (5 min)","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Every decision has a cost. Acknowledge them: \"We chose Cassandra for writes but this makes JOINs impossible.\" Senior engineers always discuss what they gave up."}]}]}},"revision":1},{"id":"3696ea06-cb1e-7af2-b8e2-e79af6780059","type":"callout","position":"a7","content":{"variant":"note","title":"Wrap Up","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Discuss bottlenecks, monitoring strategy, how the system evolves with 10× more traffic, any open issues you''d address with more time."}]}]}},"revision":1},{"id":"6f3cdb20-3aa3-7672-bd73-9300f00757b5","type":"heading","position":"a8","content":{"level":1,"content":[{"type":"text","text":"Do''s and Don''ts"}]},"revision":1},{"id":"522f5dcc-ead7-7b75-8335-b0b1b293dd62","type":"callout","position":"a9","content":{"variant":"note","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Think out loud.","marks":[{"type":"bold"}]},{"type":"text","text":" Interviewers want to see your thought process, not just the answer. A great wrong answer with good reasoning beats a lucky right answer with no explanation."}]},{"type":"paragraph","content":[{"type":"text","text":"Drive the conversation.","marks":[{"type":"bold"}]},{"type":"text","text":" Don''t wait to be asked. Lead with: \"I''m going to start with requirements, then estimate scale, then sketch the HLD. Does that sound good?\""}]},{"type":"paragraph","content":[{"type":"text","text":"Don''t jump to solutions.","marks":[{"type":"bold"}]},{"type":"text","text":" Designing before clarifying requirements is the #1 interview mistake. You''ll solve the wrong problem and waste everyone''s time."}]},{"type":"paragraph","content":[{"type":"text","text":"Don''t say \"use Kafka\" without reasoning.","marks":[{"type":"bold"}]},{"type":"text","text":" Every technology choice needs a why. \"Kafka because it handles high throughput and message replay\" beats \"Kafka\" alone."}]},{"type":"paragraph","content":[{"type":"text","text":"Acknowledge trade-offs explicitly.","marks":[{"type":"bold"}]},{"type":"text","text":" \"We could use PostgreSQL here for strong consistency, but at 1M writes/sec we''d need heavy sharding. Cassandra trades consistency for write throughput — that''s acceptable here because...\""}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
