INSERT INTO "notes"."NoteVersion" ("id", "noteId", "number", "kind", "title", "cards", "createdById", "createdAt")
SELECT '81a91198-7aa2-7b44-8239-f0fc01ff36be', 'e1b747f1-563d-7700-abcb-976d8763bdcd', 1, 'PUBLISHED', 'Load Balancing', '[{"id":"3e50f4ee-052c-7c84-86eb-80eae722318e","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Distributes incoming traffic across multiple servers to maximize throughput, minimize latency, and ensure no single server is overwhelmed."}]}]}},"revision":1},{"id":"72b299f2-6675-797f-bb89-8e205b586cf3","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Definition"}]},"revision":1},{"id":"d202ec17-778b-736c-aaf9-0549df725f62","type":"callout","position":"a2","content":{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Load Balancing","marks":[{"type":"bold"}]},{"type":"text","text":" is the process of distributing network or application traffic across a cluster of servers. It improves responsiveness and increases availability of applications."}]}]}},"revision":1},{"id":"8be1fddc-6cd8-70ba-a645-8e5b5156f2f8","type":"heading","position":"a3","content":{"level":1,"content":[{"type":"text","text":"Algorithms"}]},"revision":1},{"id":"fe218d53-d53b-7a35-9db5-2b2a87fefac3","type":"callout","position":"a4","content":{"variant":"note","title":"Round Robin","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Requests distributed sequentially. Simple, works well when servers have equal capacity and requests are similar in weight."}]}]}},"revision":1},{"id":"ecfaff22-0a5a-76f9-bf20-57a2f60f78f0","type":"callout","position":"a5","content":{"variant":"note","title":"Weighted Round Robin","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Servers with higher capacity get more requests. Useful when servers have different hardware specs."}]}]}},"revision":1},{"id":"2ae51c21-f5a9-745d-ace1-288c2fbe88f3","type":"callout","position":"a6","content":{"variant":"note","title":"Least Connections","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"New requests go to the server with fewest active connections. Best for variable-length requests."}]}]}},"revision":1},{"id":"8201a305-4fee-7d3a-a23d-877ee971a5e8","type":"callout","position":"a7","content":{"variant":"note","title":"IP Hash","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Client''s IP is hashed to always route to the same server. Good for session stickiness without session storage."}]}]}},"revision":1},{"id":"8eb4acb1-c430-796d-bdf4-a9388be4f25a","type":"heading","position":"a8","content":{"level":1,"content":[{"type":"text","text":"L4 vs L7 Load Balancing"}]},"revision":1},{"id":"186245bd-cb00-7e4f-92fa-cacd4146d27a","type":"callout","position":"a9","content":{"variant":"note","title":"L4 (Transport Layer)","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Routes based on IP and TCP/UDP port. Fast but no content inspection. Can''t route based on URL path or HTTP headers."}]}]}},"revision":1},{"id":"b213adb6-728a-7e73-8fb4-8d4e5c331bbc","type":"callout","position":"aA","content":{"variant":"note","title":"L7 (Application Layer)","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Routes based on HTTP headers, URL, cookies, content. Slower but powerful — route /api/* to API servers, /static/* to CDN."}]}]}},"revision":1},{"id":"352947b6-673c-7363-ac8e-7c36f08670f8","type":"callout","position":"aB","content":{"variant":"note","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Health Checks:","marks":[{"type":"bold"}]},{"type":"text","text":" Load balancers continuously ping backend servers. If a server fails to respond, it''s removed from the rotation automatically — this is how zero-downtime failover works."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
WHERE EXISTS (SELECT 1 FROM "notes"."Note" n WHERE n.id = 'e1b747f1-563d-7700-abcb-976d8763bdcd' AND n."ownerId" = '019a118c-f480-7000-8000-000000000001' AND n."publishedVersionId" IS NULL AND n.visibility = 'PRIVATE' AND n."deletedAt" IS NULL AND n."draftUpdatedAt" = TIMESTAMPTZ '2026-10-07 03:23:53+00')
