  ('ecfaff22-0a5a-76f9-bf20-57a2f60f78f0', 'a5', 'callout', '{"variant":"note","title":"Weighted Round Robin","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Servers with higher capacity get more requests. Useful when servers have different hardware specs."}]}]}}'),
