INSERT INTO "notes"."NoteVersion" ("id", "noteId", "number", "kind", "title", "cards", "createdById", "createdAt")
SELECT '7f810e26-c696-73f5-9df2-4ab7a7c81230', 'ab74626e-d324-79c7-a2f0-d4c1f38f7abd', 1, 'PUBLISHED', 'Microservices', '[{"id":"7ba6899b-7dda-7a57-a20c-0a47ac0b9e7b","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Architectural style where a large application is built as a suite of small, independently deployable services."}]}]}},"revision":1},{"id":"0b36b5cb-eb01-7f50-aeb2-7a0cdd300376","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Definition"}]},"revision":1},{"id":"9c330a4a-8251-7a33-86d0-367830b26e5d","type":"callout","position":"a2","content":{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"In "},{"type":"text","text":"microservices","marks":[{"type":"bold"}]},{"type":"text","text":", each service owns a specific business capability, has its own database, and communicates via well-defined APIs (REST, gRPC, events). Services are independently deployable, scalable, and replaceable."}]}]}},"revision":1},{"id":"c2886235-537d-70a2-9fba-06576c0734e9","type":"callout","position":"a3","content":{"variant":"tip","title":"Advantages","doc":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Independent deployment and scaling"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Technology diversity per service"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Fault isolation"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Easier to understand small codebases"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Parallel development by multiple teams"}]}]}]}]}},"revision":1},{"id":"f22f6c2e-04fc-78e2-a135-649bd357413c","type":"callout","position":"a4","content":{"variant":"danger","title":"Trade-offs","doc":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Network latency between services"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Distributed system complexity"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Data consistency challenges"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Operational overhead (many services)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Hard to trace requests across services"}]}]}]}]}},"revision":1},{"id":"aa7ca80f-a8c0-7852-aafb-db9562910426","type":"callout","position":"a5","content":{"variant":"note","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"vs Monolith:","marks":[{"type":"bold"}]},{"type":"text","text":" Start with a monolith. Extract microservices when a specific component has different scaling requirements or team boundaries emerge. Don''t start with microservices on day one — the overhead kills small teams."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
WHERE EXISTS (SELECT 1 FROM "notes"."Note" n WHERE n.id = 'ab74626e-d324-79c7-a2f0-d4c1f38f7abd' AND n."ownerId" = '019a118c-f480-7000-8000-000000000001' AND n."publishedVersionId" IS NULL AND n.visibility = 'PRIVATE' AND n."deletedAt" IS NULL AND n."draftUpdatedAt" = TIMESTAMPTZ '2026-10-07 03:23:53+00')
