  SELECT 1 FROM "notes"."Note" n
  WHERE n.id = '2f9e7843-aec9-713c-8644-511e72704dff' AND n.visibility = 'PUBLIC' AND n."publishedVersionId" = 'ec23c682-1d76-72e9-846a-676f31f2b34e' AND n."deletedAt" IS NULL
)
ON CONFLICT DO NOTHING;

