INSERT INTO "notes"."NoteVersion" ("id", "noteId", "number", "kind", "title", "cards", "createdById", "createdAt")
SELECT 'e63e69d2-7635-74a2-b1b3-e8c3fbdb7655', 'd7ed0258-0710-73ad-b9c1-376992d2842b', 1, 'PUBLISHED', 'DB Sharding', '[{"id":"78b9fed2-63c4-7d93-b543-f0c58ebcb497","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Horizontally partitioning a database into smaller, independent pieces (shards) each stored on a separate server."}]}]}},"revision":1},{"id":"c78cf8a4-7723-79bc-9120-26996497fa2a","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Definition"}]},"revision":1},{"id":"935a5f7e-170f-7526-ad15-a1f7d8358567","type":"callout","position":"a2","content":{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Sharding","marks":[{"type":"bold"}]},{"type":"text","text":" splits a large database into smaller shards, each responsible for a subset of data. Each shard is an independent database that can be queried independently. Enables horizontal scaling of databases beyond what any single machine can handle."}]}]}},"revision":1},{"id":"be43a34d-703a-7422-b9eb-2d7558388bc6","type":"heading","position":"a3","content":{"level":1,"content":[{"type":"text","text":"Sharding Strategies"}]},"revision":1},{"id":"0c93aef6-531b-740e-880b-b91216b972f4","type":"callout","position":"a4","content":{"variant":"note","title":"Hash-Based Sharding","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Hash the shard key (e.g., user_id % N). Even distribution but makes range queries hard and resharding painful."}]}]}},"revision":1},{"id":"33fab1da-6cc9-7b1e-9717-bca2883db527","type":"callout","position":"a5","content":{"variant":"note","title":"Range-Based Sharding","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Shard by key ranges (A-M, N-Z). Easy range queries but can create hotspots if data isn''t uniformly distributed."}]}]}},"revision":1},{"id":"84e17fad-735e-7789-95ff-af3ad10e4700","type":"callout","position":"a6","content":{"variant":"note","title":"Geographic Sharding","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Shard by user region. Keeps data close to users, helps with data residency regulations."}]}]}},"revision":1},{"id":"76710bfd-d96b-7d11-8151-9cb13ecececc","type":"callout","position":"a7","content":{"variant":"note","title":"Directory-Based Sharding","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A lookup table maps keys to shards. Flexible but the lookup table becomes a bottleneck and SPOF."}]}]}},"revision":1},{"id":"634fb248-a9ad-7a3a-b829-f2fe7d3e65ca","type":"callout","position":"a8","content":{"variant":"warning","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"⚠️ "},{"type":"text","text":"Hotspot Problem:","marks":[{"type":"bold"}]},{"type":"text","text":" If one shard gets disproportionate traffic (celebrity user, trending content), it becomes overloaded. Mitigate with consistent hashing, virtual nodes, or application-level load awareness."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
WHERE EXISTS (SELECT 1 FROM "notes"."Note" n WHERE n.id = 'd7ed0258-0710-73ad-b9c1-376992d2842b' AND n."ownerId" = '019a118c-f480-7000-8000-000000000001' AND n."publishedVersionId" IS NULL AND n.visibility = 'PRIVATE' AND n."deletedAt" IS NULL AND n."draftUpdatedAt" = TIMESTAMPTZ '2026-10-07 03:23:53+00')
