INSERT INTO "notes"."NoteSearchDocument" ("noteId", "versionId", "title", "topics", "body", "document", "updatedAt")
SELECT 'd024b91d-79d6-7cf8-8fda-8f8f7abf8fb4', '494d816f-410a-7fc2-94df-545ffc0357a9', 'Uber Platform', 'Uber Platform', 'Real-time geospatial matching platform powering 100M+ rides. Key challenges: geospatial indexing, location ping ingestion, rider-driver matching, surge pricing.
Requirements
Functional
Drivers update location (every 4s) · Riders request ride · Match nearby drivers · Real-time location tracking · Surge pricing based on demand
Non-Functional
1M active drivers sending pings = 250k write QPS · Low matching latency (<2s) · High availability · Zero lost location pings during active trip
Geospatial Indexing: H3 / Quadtree
Uber uses Uber H3 (Hexagonal hierarchical spatial index). Hexagons are ideal for spatial analysis because all neighbor centroids are equidistant, eliminating edge distortion compared to rectangular grids.
System Architecture Flow
Driver App (WebSockets) → Location Ingestion Service → Kafka → Redis (H3 Spatial Index)
Rider Request → Dispatch Service → Geospatial Matcher → Driver Notification',
  setweight(to_tsvector('english', 'Uber Platform'), 'A')
    || setweight(to_tsvector('english', 'Uber Platform'), 'B')
    || setweight(to_tsvector('english', 'Real-time geospatial matching platform powering 100M+ rides. Key challenges: geospatial indexing, location ping ingestion, rider-driver matching, surge pricing.
Requirements
Functional
Drivers update location (every 4s) · Riders request ride · Match nearby drivers · Real-time location tracking · Surge pricing based on demand
Non-Functional
1M active drivers sending pings = 250k write QPS · Low matching latency (<2s) · High availability · Zero lost location pings during active trip
Geospatial Indexing: H3 / Quadtree
Uber uses Uber H3 (Hexagonal hierarchical spatial index). Hexagons are ideal for spatial analysis because all neighbor centroids are equidistant, eliminating edge distortion compared to rectangular grids.
System Architecture Flow
Driver App (WebSockets) → Location Ingestion Service → Kafka → Redis (H3 Spatial Index)
Rider Request → Dispatch Service → Geospatial Matcher → Driver Notification'), 'C'),
  TIMESTAMPTZ '2026-10-07 03:23:53+00'
WHERE EXISTS (
  SELECT 1 FROM "notes"."Note" n
  WHERE n.id = 'd024b91d-79d6-7cf8-8fda-8f8f7abf8fb4' AND n.visibility = 'PUBLIC' AND n."publishedVersionId" = '494d816f-410a-7fc2-94df-545ffc0357a9' AND n."deletedAt" IS NULL
)
ON CONFLICT DO NOTHING;

