  SELECT 1 FROM "notes"."Note" n
  WHERE n.id = '60417b46-2be6-7382-97c8-bfea29ada62a' AND n.visibility = 'PUBLIC' AND n."publishedVersionId" = '627ea6c7-c125-7c06-88b1-243346736475' AND n."deletedAt" IS NULL
)
ON CONFLICT DO NOTHING;

