SELECT 'e9e0339e-d23e-7751-ae43-aeac3afae8e2', '129d6d4c-abd4-797b-a6dd-43d4b7034f39', 1, 'PUBLISHED', 'Branching & Checkout', '[{"id":"94b3aca5-8021-7718-8dd4-16b8e4c20747","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Creating parallel lines of development to build features in isolation."}]}]}},"revision":1},{"id":"7350633e-9f04-7550-9b09-e5a5a4a4c666","type":"callout","position":"a1","content":{"variant":"info","title":"Branch","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A "},{"type":"text","text":"Branch","marks":[{"type":"bold"}]},{"type":"text","text":" in Git is a lightweight, moveable pointer to a specific commit. By default, projects start with a default branch (typically "},{"type":"text","text":"main","marks":[{"type":"code"}]},{"type":"text","text":"). Creating a new branch creates a separate pathway of history so you can build features or fix bugs without affecting the stable production code."}]}]}},"revision":1},{"id":"b4dd0c12-3df4-7fbb-9c0f-d75efe9542f7","type":"heading","position":"a2","content":{"level":1,"content":[{"type":"text","text":"Branching Flow Chart"}]},"revision":1},{"id":"f7528db4-4078-75a2-8a43-cf29e6c15bdc","type":"text","position":"a3","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Commit 1 → Commit 2 (main) → Commit 3 (main)"}]},{"type":"paragraph","content":[{"type":"text","text":"Commit 2 (main) ↳ checkout new branch → Feature Commit A → Feature Commit B"}]}]}},"revision":1},{"id":"e1cd92eb-b825-7453-8eb3-2d2dd8d437df","type":"heading","position":"a4","content":{"level":1,"content":[{"type":"text","text":"Branching Commands"}]},"revision":1},{"id":"8156386c-cf30-7904-a79e-2a9794bfadbf","type":"table","position":"a5","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Command"}],[{"type":"text","text":"Purpose"}],[{"type":"text","text":"Description"}]],[[{"type":"text","text":"git branch","marks":[{"type":"bold"}]}],[{"type":"text","text":"List Branches"}],[{"type":"text","text":"Lists all local branches in the repository."}]],[[{"type":"text","text":"git checkout [branch]","marks":[{"type":"bold"}]}],[{"type":"text","text":"Navigate Branch"}],[{"type":"text","text":"Switches the working directory to the target branch."}]],[[{"type":"text","text":"git checkout -b [new-branch]","marks":[{"type":"bold"}]}],[{"type":"text","text":"Create & Navigate"}],[{"type":"text","text":"Creates a new branch and switches to it in one step."}]],[[{"type":"text","text":"git branch -d [branch]","marks":[{"type":"bold"}]}],[{"type":"text","text":"Delete Branch"}],[{"type":"text","text":"Deletes a branch (requires that changes are merged)."}]]]},"revision":1},{"id":"474fa242-5908-7d98-95d0-9405772c8230","type":"callout","position":"a6","content":{"variant":"tip","title":"Interview tip","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"On modern versions of Git, the checkout command can be replaced with "},{"type":"text","text":"git switch","marks":[{"type":"code"}]},{"type":"text","text":" (e.g. "},{"type":"text","text":"git switch -c new-branch","marks":[{"type":"code"}]},{"type":"text","text":" to create and switch), separating branch navigation from file restoration."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
