  SELECT 1 FROM "notes"."Note" n
  WHERE n.id = '941a9990-368f-7bb7-b5df-2d5746dfbcf8' AND n.visibility = 'PUBLIC' AND n."publishedVersionId" = '9c1eb8d7-17b2-706f-a26c-e0fe496aa0c3' AND n."deletedAt" IS NULL
)
