SELECT '3822f6a0-aa63-7f56-9d64-7e85191a2626', 'dabd9d03-bcfc-7e3d-a7ca-b41b01114a26', 1, 'PUBLISHED', 'Merging & PRs', '[{"id":"8afed68b-170f-7049-a545-2c24fa071b9a","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Integrating isolated branches and requesting code reviews on GitHub."}]}]}},"revision":1},{"id":"c1b59182-befe-7f53-95e7-eccc5e58202a","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Comparing Changes"}]},"revision":1},{"id":"4749467e-dba5-7925-b96b-56c04a946da7","type":"text","position":"a2","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"To view the difference in code content between two branches, commits, or staging areas before merging, use:"}]}]}},"revision":1},{"id":"9dd34df3-3dc0-7a9e-84c6-df9ac2ea7402","type":"code","position":"a3","content":{"language":"bash","code":"git diff feature-branch main","filename":"Shell"},"revision":1},{"id":"ba780b3e-77d2-76f2-aafd-6ca053ab5f1e","type":"heading","position":"a4","content":{"level":1,"content":[{"type":"text","text":"Merging Locally"}]},"revision":1},{"id":"b6c8da78-9995-79eb-9180-3d36a011100b","type":"text","position":"a5","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"To integrate changes from a feature branch into your active branch (e.g., merging "},{"type":"text","text":"feature-login","marks":[{"type":"code"}]},{"type":"text","text":" into "},{"type":"text","text":"main","marks":[{"type":"code"}]},{"type":"text","text":"), run:"}]}]}},"revision":1},{"id":"18ebd372-9836-7045-a716-a12a50aa16e4","type":"code","position":"a6","content":{"language":"bash","code":"# 1. Switch to the recipient branch (main)\ngit checkout main\n\n# 2. Merge changes from the target branch\ngit merge feature-login","filename":"Shell"},"revision":1},{"id":"ecd4ecf9-f0db-76f8-b321-fe5bf729e317","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"Pull Requests (PRs)"}]},"revision":1},{"id":"de00b06f-e436-72d8-b151-f2eb60a55fa0","type":"callout","position":"a8","content":{"variant":"info","title":"Pull Request","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A "},{"type":"text","text":"Pull Request (PR)","marks":[{"type":"bold"}]},{"type":"text","text":" is a collaboration feature on GitHub that notifies team members that you''ve pushed changes to a branch and would like them to review, comment on, and merge those changes into the main repository."}]}]}},"revision":1},{"id":"3203a9b4-4358-7fcc-90fc-0269d88295aa","type":"heading","position":"a9","content":{"level":1,"content":[{"type":"text","text":"Fast-Forward vs Three-Way Merge"}]},"revision":1},{"id":"bf6e5409-2742-7dba-8d04-dcbae88a486c","type":"callout","position":"aA","content":{"variant":"info","title":"Fast-Forward Merge","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"If the recipient branch hasn''t diverged (no new commits were made to "},{"type":"text","text":"main","marks":[{"type":"code"}]},{"type":"text","text":" while you worked on the feature), Git simply moves the branch pointer forward. No merge commit is created."}]}]}},"revision":1},{"id":"dc889369-f90a-763e-b5aa-1a4463d2a518","type":"callout","position":"aB","content":{"variant":"info","title":"Three-Way Merge (3-Way)","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"If both branches have diverged (new commits were made on both branches), Git performs a three-way merge using a common ancestor and creates a new, dedicated "},{"type":"text","text":"merge commit","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
