  WHERE n.id = 'cbe712b8-caf8-79af-aff0-992710e5c272' AND n.visibility = 'PUBLIC' AND n."publishedVersionId" = '4e541ec2-5471-7c26-8eec-1674e68516ae' AND n."deletedAt" IS NULL
)
ON CONFLICT DO NOTHING;

