  SELECT 1 FROM "notes"."Note" n
  WHERE n.id = '109b2388-b2f0-7e95-9522-cefa4599a013' AND n.visibility = 'PUBLIC' AND n."publishedVersionId" = 'b3c02116-9ee9-7a45-876c-dfde5030f4c8' AND n."deletedAt" IS NULL
)
