INSERT INTO "notes"."NoteSearchDocument" ("noteId", "versionId", "title", "topics", "body", "document", "updatedAt")
SELECT '737cb4b2-31b8-7ecb-8eda-81ffe65c1025', 'fe4b7ac0-eded-7e17-8964-d09c5213b5ed', 'Caching', 'Caching', 'The fastest API call is the one you don''t make. HTTP has built-in caching primitives — use them.
Caching layers
Client cache → CDN / Edge → Reverse proxy → App cache (Redis) → Database
HTTP caching headers
// Public — CDN + browser can cache
Cache-Control: public, max-age=3600

// Private — only browser caches
Cache-Control: private, max-age=300

// Never cache (auth endpoints, mutations)
Cache-Control: no-store

// stale-while-revalidate: serve stale, refresh in background
Cache-Control: public, max-age=60, stale-while-revalidate=600
// Server response:
ETag: "v2-abc123"

// Client''s next request:
If-None-Match: "v2-abc123"

// Unchanged → 304 Not Modified (no body = saves bandwidth)
// Changed → 200 OK + new ETag + new body
// Different languages = different cache entries
Vary: Accept-Language

// NEVER do this — disables CDN caching effectively
Vary: Authorization
What to cache vs not
Safe to cache
Public product listings · Static reference data · Product images · Public profiles
Never cache
Auth tokens · Payment endpoints · POST/PUT/PATCH/DELETE · OTP codes · Real-time prices',
  setweight(to_tsvector('english', 'Caching'), 'A')
    || setweight(to_tsvector('english', 'Caching'), 'B')
    || setweight(to_tsvector('english', 'The fastest API call is the one you don''t make. HTTP has built-in caching primitives — use them.
Caching layers
Client cache → CDN / Edge → Reverse proxy → App cache (Redis) → Database
HTTP caching headers
// Public — CDN + browser can cache
Cache-Control: public, max-age=3600

// Private — only browser caches
Cache-Control: private, max-age=300

// Never cache (auth endpoints, mutations)
Cache-Control: no-store

// stale-while-revalidate: serve stale, refresh in background
Cache-Control: public, max-age=60, stale-while-revalidate=600
// Server response:
ETag: "v2-abc123"

// Client''s next request:
If-None-Match: "v2-abc123"

// Unchanged → 304 Not Modified (no body = saves bandwidth)
// Changed → 200 OK + new ETag + new body
// Different languages = different cache entries
Vary: Accept-Language

// NEVER do this — disables CDN caching effectively
Vary: Authorization
What to cache vs not
Safe to cache
Public product listings · Static reference data · Product images · Public profiles
Never cache
Auth tokens · Payment endpoints · POST/PUT/PATCH/DELETE · OTP codes · Real-time prices'), 'C'),
  TIMESTAMPTZ '2026-10-07 03:23:53+00'
WHERE EXISTS (
  SELECT 1 FROM "notes"."Note" n
  WHERE n.id = '737cb4b2-31b8-7ecb-8eda-81ffe65c1025' AND n.visibility = 'PUBLIC' AND n."publishedVersionId" = 'fe4b7ac0-eded-7e17-8964-d09c5213b5ed' AND n."deletedAt" IS NULL
)
ON CONFLICT DO NOTHING;

