SELECT '1bb70392-8574-7a3d-8732-9acf80f241e5', '57610891-3d82-7d71-80f5-85d302ecd11a', 1, 'PUBLISHED', 'GraphQL', '[{"id":"fa71f5c5-acaf-75a9-8dc5-f3465c8ed6e5","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Created by Facebook 2012, open-sourced 2015. Solves REST''s over-fetching and N+1 request problems with a typed query language."}]}]}},"revision":1},{"id":"0be69bd6-c02f-7d39-8d97-92a6a07eb5c8","type":"callout","position":"a1","content":{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"GraphQL","marks":[{"type":"bold"}]},{"type":"text","text":" — client asks for exactly what it needs. Single endpoint handles all operations. Schema is the contract. Self-documenting via introspection."}]}]}},"revision":1},{"id":"bb6c47c7-1466-7150-b787-d2c20e8bb563","type":"callout","position":"a2","content":{"variant":"note","title":"REST: 4 requests for one screen","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"GET /api/users/123","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"GET /api/users/123/posts","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"GET /api/users/123/comments","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"GET /api/users/123/likes","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"→ 4 round trips, wasted data","marks":[{"type":"code"}]}]}]}},"revision":1},{"id":"6884e53d-b490-7241-b952-53245a92da70","type":"callout","position":"a3","content":{"variant":"note","title":"GraphQL: 1 request, exact data","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"query {","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"  user(id: \"123\") {","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"    name","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"    posts { title }","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"    comments { text }","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"  }","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"} → 1 round trip","marks":[{"type":"code"}]}]}]}},"revision":1},{"id":"d9623465-a454-7dfc-870b-9a080524a7ea","type":"heading","position":"a4","content":{"level":1,"content":[{"type":"text","text":"Operations"}]},"revision":1},{"id":"70b23161-d71b-71f3-9f8e-c489b5f65d19","type":"callout","position":"a5","content":{"variant":"note","title":"Query (read)","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Fetch data. Client specifies exact fields. Equivalent to GET."}]}]}},"revision":1},{"id":"bc7826bd-d412-72bb-900f-8680086d1a68","type":"callout","position":"a6","content":{"variant":"note","title":"Mutation (write)","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Create, update, or delete data. Equivalent to POST/PUT/DELETE."}]}]}},"revision":1},{"id":"0d3f8b69-92eb-715a-8df0-d01312ac7a27","type":"callout","position":"a7","content":{"variant":"note","title":"Subscription (real-time)","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"WebSocket-based. Server pushes updates when data changes."}]}]}},"revision":1},{"id":"5ae06ea4-3842-7701-b805-334fd8f2524a","type":"callout","position":"a8","content":{"variant":"warning","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"GraphQL always returns "},{"type":"text","text":"200 OK","marks":[{"type":"bold"}]},{"type":"text","text":" — even for errors. You must check the "},{"type":"text","text":"errors","marks":[{"type":"code"}]},{"type":"text","text":" field. Common gotcha from REST."}]}]}},"revision":1},{"id":"a815d35a-0622-7b3b-bf22-95f57ae41b73","type":"heading","position":"a9","content":{"level":1,"content":[{"type":"text","text":"GraphQL pitfalls"}]},"revision":1},{"id":"37d292d5-ac3c-7c8e-806a-8cc31bbce78a","type":"callout","position":"aA","content":{"variant":"note","title":"N+1 query problem","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Resolving each user''s posts individually fires N database queries. Fix: DataLoader (batching resolver)."}]}]}},"revision":1},{"id":"74a24326-c641-7508-8b2a-ce3bdb3c4b3e","type":"callout","position":"aB","content":{"variant":"note","title":"Query depth attacks","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Deeply nested queries cause exponential DB load. Fix: max query depth, complexity limits."}]}]}},"revision":1},{"id":"74cb10c4-b747-7d7b-a752-c7d1b7cb8263","type":"callout","position":"aC","content":{"variant":"note","title":"Caching complexity","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"All goes through POST /graphql — HTTP caching doesn''t work. Need app-level caching (Apollo Client, persisted queries)."}]}]}},"revision":1},{"id":"b4bc4aa6-c8cd-780c-81c3-76c3d31abcd0","type":"callout","position":"aD","content":{"variant":"note","title":"Over-permissive schemas","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Apply field-level authorization — not just resolver-level. Check auth per field for sensitive data."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
