  WHERE n.id = 'e4445caa-fd71-7f84-abbd-47036729ea59' AND n.visibility = 'PUBLIC' AND n."publishedVersionId" = '1236cb91-8890-7c6d-908e-f87070086a29' AND n."deletedAt" IS NULL
