INSERT INTO "notes"."NoteVersion" ("id", "noteId", "number", "kind", "title", "cards", "createdById", "createdAt")
SELECT '680bf835-8a4c-7f9a-87a4-0b0981287a84', '16c686d1-b142-7988-98a5-b4982b73235a', 1, 'PUBLISHED', 'HTTP methods', '[{"id":"4b94507b-2dda-750f-88de-2cd018a13e30","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Each HTTP method maps to a CRUD operation. Safe = no state change. Idempotent = repeating has the same effect as doing it once."}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"GET"}]},{"type":"paragraph","content":[{"type":"text","text":"Read — retrieve a resource"}]},{"type":"paragraph","content":[{"type":"text","text":"Safe and idempotent. Never change state. GET /products = all. GET /products/123 = one."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"POST"}]},{"type":"paragraph","content":[{"type":"text","text":"Create — make a new resource"}]},{"type":"paragraph","content":[{"type":"text","text":"Not safe, not idempotent — calling twice creates two resources. Returns 201 Created + Location header."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"PUT"}]},{"type":"paragraph","content":[{"type":"text","text":"Update (replace) — full replacement"}]},{"type":"paragraph","content":[{"type":"text","text":"Idempotent. Replaces the entire resource. Missing fields become null/default."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"PATCH"}]},{"type":"paragraph","content":[{"type":"text","text":"Update (partial) — modify fields"}]},{"type":"paragraph","content":[{"type":"text","text":"Send only the fields to change. Others remain. Preferred over PUT for most updates."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"DELETE"}]},{"type":"paragraph","content":[{"type":"text","text":"Delete — remove a resource"}]},{"type":"paragraph","content":[{"type":"text","text":"Idempotent — deleting something that doesn''t exist is still OK. Returns 204 No Content."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"HEAD"}]},{"type":"paragraph","content":[{"type":"text","text":"Like GET — no body in response"}]},{"type":"paragraph","content":[{"type":"text","text":"Check if resource exists, get metadata, validate cache freshness."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"OPTIONS"}]},{"type":"paragraph","content":[{"type":"text","text":"Describe available methods"}]},{"type":"paragraph","content":[{"type":"text","text":"Returns allowed methods. Used by browsers in CORS preflight requests."}]}]}]}]}},"revision":1},{"id":"2fb79272-7021-7169-9e55-03dfcb79c953","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Safe vs idempotent"}]},"revision":1},{"id":"66bece69-9b40-7c98-824c-9f6231950c12","type":"table","position":"a2","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Method"}],[{"type":"text","text":"Safe"}],[{"type":"text","text":"Idempotent"}],[{"type":"text","text":"Has body"}],[{"type":"text","text":"Success code"}]],[[{"type":"text","text":"GET"}],[{"type":"text","text":"✓"}],[{"type":"text","text":"✓"}],[{"type":"text","text":"No"}],[{"type":"text","text":"200"}]],[[{"type":"text","text":"POST"}],[{"type":"text","text":"✗"}],[{"type":"text","text":"✗"}],[{"type":"text","text":"Yes"}],[{"type":"text","text":"201"}]],[[{"type":"text","text":"PUT"}],[{"type":"text","text":"✗"}],[{"type":"text","text":"✓"}],[{"type":"text","text":"Yes"}],[{"type":"text","text":"200"}]],[[{"type":"text","text":"PATCH"}],[{"type":"text","text":"✗"}],[{"type":"text","text":"✗"}],[{"type":"text","text":"Yes"}],[{"type":"text","text":"200"}]],[[{"type":"text","text":"DELETE"}],[{"type":"text","text":"✗"}],[{"type":"text","text":"✓"}],[{"type":"text","text":"No"}],[{"type":"text","text":"204"}]]]},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
