INSERT INTO "notes"."NoteVersion" ("id", "noteId", "number", "kind", "title", "cards", "createdById", "createdAt")
SELECT '0cde2622-9462-7c6e-9bda-39233408187f', '161cdd52-0833-7a71-b08f-b64f1ee96252', 1, 'PUBLISHED', 'Pagination', '[{"id":"71eba7b9-3a29-70db-a516-5a909cb3ec35","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Never return unbounded lists. Even if there are only 10 rows today, there will be 10 million tomorrow. Pagination is non-optional."}]}]}},"revision":1},{"id":"5f8b9a19-f6dd-7ed4-ba3d-194e59f77941","type":"heading","position":"a1","content":{"level":3,"content":[{"type":"text","text":"Offset"}]},"revision":1},{"id":"d23a9afd-5aba-710e-a17b-4b9c076f8c78","type":"callout","position":"a2","content":{"variant":"note","title":"Offset pagination","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Skip N records, return next M. Simple. Works for small datasets. UI can jump to any page."}]}]}},"revision":1},{"id":"ce2b27e7-b024-75a3-bad9-84978214ec94","type":"code","position":"a3","content":{"language":"","code":"GET /products?offset=40&limit=20\n// SQL: SELECT * FROM products LIMIT 20 OFFSET 40\n\n{ \"data\": [...], \"pagination\": { \"total\": 1250, \"offset\": 40, \"limit\": 20 } }"},"revision":1},{"id":"e976bf1e-4f1a-702a-8729-deb020a83850","type":"callout","position":"a4","content":{"variant":"warning","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Problems at scale:","marks":[{"type":"bold"}]},{"type":"text","text":" Large OFFSET scans all skipped rows. Page 10,000 requires DB to scan 200,000 rows. Also: inserts/deletes cause duplicate or skipped items."}]}]}},"revision":1},{"id":"60fc08ac-b771-73a7-bd05-e75093e5145d","type":"heading","position":"a5","content":{"level":3,"content":[{"type":"text","text":"Cursor (recommended)"}]},"revision":1},{"id":"56dceab5-6f98-75d3-970b-29c09e8f00ec","type":"callout","position":"a6","content":{"variant":"note","title":"Cursor pagination (Stripe, Slack, Twitter style)","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Each response includes an opaque cursor. Next request starts from there. O(1) regardless of depth. Stable under inserts/deletes."}]}]}},"revision":1},{"id":"ab548f65-f871-744a-a9b7-c29af2a82618","type":"code","position":"a7","content":{"language":"","code":"GET /products?limit=20\n\n// Response:\n{ \"data\": [...], \"pagination\": { \"next_cursor\": \"eyJpZCI6MTIzfQ==\", \"has_more\": true } }\n\n// Next request:\nGET /products?after=eyJpZCI6MTIzfQ==&limit=20"},"revision":1},{"id":"45b24964-d953-7e42-ad3c-52f78798e15c","type":"callout","position":"a8","content":{"variant":"tip","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Best for:","marks":[{"type":"bold"}]},{"type":"text","text":" Infinite scroll, feeds, high-volume datasets. Cursor is typically base64-encoded ID."}]}]}},"revision":1},{"id":"021d75bf-f90f-71dd-be53-d6010da4dda1","type":"heading","position":"a9","content":{"level":3,"content":[{"type":"text","text":"Keyset"}]},"revision":1},{"id":"0a8df3d7-a177-7169-b21c-ac0601cf9c28","type":"callout","position":"aA","content":{"variant":"note","title":"Keyset pagination","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Uses actual column values. "},{"type":"text","text":"WHERE id > last_id","marks":[{"type":"code"}]},{"type":"text","text":". Performant — uses index scan not full table scan."}]}]}},"revision":1},{"id":"13baf353-4b94-7937-83e2-6c12a4396068","type":"code","position":"aB","content":{"language":"","code":"GET /products?after_id=123&limit=20\n// SQL: WHERE id > 123 ORDER BY id ASC LIMIT 20"},"revision":1},{"id":"aa8e0e3b-d406-76e3-8b8e-29fb3600e0e3","type":"callout","position":"aC","content":{"variant":"tip","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Transparent (no opaque cursor). Works well for time-series. Requires stable sort column with index."}]}]}},"revision":1},{"id":"18d896d8-2cc5-7aee-bed2-84575a337504","type":"heading","position":"aD","content":{"level":1,"content":[{"type":"text","text":"Strategy comparison"}]},"revision":1},{"id":"09623f00-d707-7d2a-a503-a546b9003406","type":"table","position":"aE","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Strategy"}],[{"type":"text","text":"Performance"}],[{"type":"text","text":"Stable under inserts?"}],[{"type":"text","text":"Random access"}],[{"type":"text","text":"Best for"}]],[[{"type":"text","text":"Offset"}],[{"type":"text","text":"Poor (table scan)"}],[{"type":"text","text":"No"}],[{"type":"text","text":"Yes"}],[{"type":"text","text":"Small datasets"}]],[[{"type":"text","text":"Cursor"}],[{"type":"text","text":"Excellent"}],[{"type":"text","text":"Yes"}],[{"type":"text","text":"No"}],[{"type":"text","text":"Infinite scroll, feeds"}]],[[{"type":"text","text":"Keyset"}],[{"type":"text","text":"Excellent"}],[{"type":"text","text":"Yes"}],[{"type":"text","text":"No"}],[{"type":"text","text":"Time-series, append-only"}]]]},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
