  SELECT 1 FROM "notes"."Note" n
  WHERE n.id = '1ba8148e-d464-75d1-889a-1a4753579309' AND n.visibility = 'PUBLIC' AND n."publishedVersionId" = 'a25dbbe0-0ad6-7419-97d3-65178e51e9a7' AND n."deletedAt" IS NULL
)
