INSERT INTO "notes"."NoteVersion" ("id", "noteId", "number", "kind", "title", "cards", "createdById", "createdAt")
SELECT '157c81e5-8ee2-72e3-a76e-109dbe5e6559', '5dd9c9ad-700c-7a21-85cf-1c89a5044e47', 1, 'PUBLISHED', 'RESTful APIs', '[{"id":"ab7d5685-55f5-7b32-9c48-1fa90cc812d2","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Resource-based URL design, filtering, sorting, pagination, and versioning — the complete REST playbook."}]}]}},"revision":1},{"id":"103ba902-6c21-770e-85c0-863cdbf7c2fb","type":"callout","position":"a1","content":{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"REST","marks":[{"type":"bold"}]},{"type":"text","text":" uses standard HTTP methods and resource-based URLs. 6 constraints: stateless, uniform interface, client-server separation, layered system, cacheable, code on demand (optional)."}]}]}},"revision":1},{"id":"bbc2f612-588f-798c-a018-95a63cf7a34d","type":"heading","position":"a2","content":{"level":1,"content":[{"type":"text","text":"URL patterns"}]},"revision":1},{"id":"d63be68b-4855-7751-86d2-7d5d22fb804b","type":"code","position":"a3","content":{"language":"","code":"Collection:\nGET   /api/v1/products\nPOST  /api/v1/products\n\nSpecific resource:\nGET    /api/v1/products/:id\nPATCH  /api/v1/products/:id\nDELETE /api/v1/products/:id\n\nNested (relationship):\nGET /api/v1/products/:id/reviews\n\nActions (when needed):\nPOST /api/v1/orders/:id/cancel"},"revision":1},{"id":"8b8ad2f1-f076-7a8a-a2ab-96dcd4c11ddd","type":"heading","position":"a4","content":{"level":1,"content":[{"type":"text","text":"Filtering, sorting, field selection"}]},"revision":1},{"id":"e8424650-f5f6-701a-aec6-44edc52516ce","type":"callout","position":"a5","content":{"variant":"note","title":"Filtering","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"GET /api/v1/products?category=electronics&inStock=true&minPrice=10","marks":[{"type":"code"}]}]}]}},"revision":1},{"id":"87901f96-0130-70d1-b29b-5f0d63acb254","type":"callout","position":"a6","content":{"variant":"note","title":"Sorting","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"GET /api/v1/products?sort=price_asc","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"GET /api/v1/products?sort=-created_at  // minus = desc","marks":[{"type":"code"}]}]}]}},"revision":1},{"id":"9d12500b-58ed-7912-872e-090cef97a382","type":"callout","position":"a7","content":{"variant":"note","title":"Field selection (sparse fieldsets)","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"GET /api/v1/products?fields=id,name,price","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"// Returns only: { id, name, price }","marks":[{"type":"code"}]}]}]}},"revision":1},{"id":"df379241-fb2c-7dcf-b1b6-209247b1c5ad","type":"heading","position":"a8","content":{"level":1,"content":[{"type":"text","text":"REST best practices"}]},"revision":1},{"id":"58f84a86-b5b4-7841-b6a4-3f2c8e5cf31c","type":"text","position":"a9","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Plural nouns (/products not /product) · No verbs in URLs (GET /users/:id not /getUser) · Version with /v1, /v2 · Consistent response envelope · Return appropriate status codes · Never return unbounded lists · Never put credentials in URLs · Never return 200 for errors"}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
