  ('d63be68b-4855-7751-86d2-7d5d22fb804b', 'a3', 'code', '{"language":"","code":"Collection:\nGET   /api/v1/products\nPOST  /api/v1/products\n\nSpecific resource:\nGET    /api/v1/products/:id\nPATCH  /api/v1/products/:id\nDELETE /api/v1/products/:id\n\nNested (relationship):\nGET /api/v1/products/:id/reviews\n\nActions (when needed):\nPOST /api/v1/orders/:id/cancel"}'),
  ('8b8ad2f1-f076-7a8a-a2ab-96dcd4c11ddd', 'a4', 'heading', '{"level":1,"content":[{"type":"text","text":"Filtering, sorting, field selection"}]}'),
  ('e8424650-f5f6-701a-aec6-44edc52516ce', 'a5', 'callout', '{"variant":"note","title":"Filtering","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"GET /api/v1/products?category=electronics&inStock=true&minPrice=10","marks":[{"type":"code"}]}]}]}}'),
  ('87901f96-0130-70d1-b29b-5f0d63acb254', 'a6', 'callout', '{"variant":"note","title":"Sorting","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"GET /api/v1/products?sort=price_asc","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"GET /api/v1/products?sort=-created_at  // minus = desc","marks":[{"type":"code"}]}]}]}}'),
  ('9d12500b-58ed-7912-872e-090cef97a382', 'a7', 'callout', '{"variant":"note","title":"Field selection (sparse fieldsets)","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"GET /api/v1/products?fields=id,name,price","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"// Returns only: { id, name, price }","marks":[{"type":"code"}]}]}]}}'),
  ('df379241-fb2c-7dcf-b1b6-209247b1c5ad', 'a8', 'heading', '{"level":1,"content":[{"type":"text","text":"REST best practices"}]}'),
  ('58f84a86-b5b4-7841-b6a4-3f2c8e5cf31c', 'a9', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Plural nouns (/products not /product) · No verbs in URLs (GET /users/:id not /getUser) · Version with /v1, /v2 · Consistent response envelope · Return appropriate status codes · Never return unbounded lists · Never put credentials in URLs · Never return 200 for errors"}]}]}}')
