  WHERE n.id = '5dd9c9ad-700c-7a21-85cf-1c89a5044e47' AND n.visibility = 'PUBLIC' AND n."publishedVersionId" = '157c81e5-8ee2-72e3-a76e-109dbe5e6559' AND n."deletedAt" IS NULL
)
