INSERT INTO "notes"."NoteVersion" ("id", "noteId", "number", "kind", "title", "cards", "createdById", "createdAt")
SELECT 'f7a5718d-fea0-7a84-a641-03f740c10ae7', '9f6fff72-62b9-7d3c-81bb-5666b8b63049', 1, 'PUBLISHED', 'Security techniques', '[{"id":"3c2d16fc-f253-7184-b80e-1cec5b694e21","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Security is not a feature — it''s a foundation. Every production API needs all of these."}]}]}},"revision":1},{"id":"ae210935-0877-704b-adff-d0fbec1bc9da","type":"callout","position":"a1","content":{"variant":"note","title":"1. Rate limiting","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Limit requests per user/IP/key per time window. Prevents DDoS, brute-force, API abuse. Return 429 with Retry-After."}]}]}},"revision":1},{"id":"9c9e6f85-8a98-7036-bb18-2c4abb194bd7","type":"callout","position":"a2","content":{"variant":"note","title":"2. CORS","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Tells browsers which domains can call your API. Prevents malicious sites from making API calls using user''s session."}]},{"type":"paragraph","content":[{"type":"text","text":"Access-Control-Allow-Origin: https://app.yourdomain.com","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"// Never \"*\" for authenticated APIs","marks":[{"type":"code"}]}]}]}},"revision":1},{"id":"a1f6179b-747d-7376-ba2e-d3f4b3eac764","type":"callout","position":"a3","content":{"variant":"note","title":"3. SQL / NoSQL injection","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Attacker sends malicious input executed as DB query. Still #1 on OWASP Top 10."}]},{"type":"paragraph","content":[{"type":"text","text":"\"SELECT * FROM users WHERE name=''\" + input + \"''\"","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"// VULNERABLE","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"db.query(\"SELECT * FROM users WHERE name=?\", [input])","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"// SAFE — parameterized","marks":[{"type":"code"}]}]}]}},"revision":1},{"id":"0ce36137-41b1-7de8-83fb-c7e6b7861078","type":"callout","position":"a4","content":{"variant":"note","title":"4. Input validation","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Validate every input. Type check, length limits, format validation, allowlists. Reject early with 400 + field-level errors."}]}]}},"revision":1},{"id":"e015a0f5-ceee-758f-b90e-f479cd989533","type":"callout","position":"a5","content":{"variant":"note","title":"5. CSRF","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Attacker tricks logged-in user''s browser into making unintended API call using session cookie."}]},{"type":"paragraph","content":[{"type":"text","text":"X-CSRF-Token: <random_server_issued_token>","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"// Or: SameSite=Strict cookie attribute","marks":[{"type":"code"}]}]}]}},"revision":1},{"id":"1954b9a1-df23-7b9f-9a1b-c7927295810b","type":"callout","position":"a6","content":{"variant":"note","title":"6. XSS","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Attacker injects malicious JS into your app. Runs in other users'' browsers — steals cookies, tokens."}]},{"type":"paragraph","content":[{"type":"text","text":"Fix:","marks":[{"type":"bold"}]},{"type":"text","text":" Escape user input before rendering. Use CSP headers. Never "},{"type":"text","text":"innerHTML","marks":[{"type":"code"}]},{"type":"text","text":" with user data. HttpOnly cookies."}]}]}},"revision":1},{"id":"b4bce4a1-7d28-75f4-9e21-1dc12e284131","type":"callout","position":"a7","content":{"variant":"note","title":"7. HTTPS + HSTS","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Always HTTPS. HSTS forces browsers to only use HTTPS — prevents downgrade attacks."}]},{"type":"paragraph","content":[{"type":"text","text":"Strict-Transport-Security: max-age=31536000; includeSubDomains; preload","marks":[{"type":"code"}]}]}]}},"revision":1},{"id":"dcdda57a-16f3-77db-9636-858a9c1ed162","type":"callout","position":"a8","content":{"variant":"note","title":"8. WAF","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Web Application Firewall filters malicious traffic at layer 7. Blocks OWASP Top 10 patterns, suspicious IPs, bot traffic."}]},{"type":"paragraph","content":[{"type":"text","text":"AWS WAF · Cloudflare WAF · Azure Front Door"}]}]}},"revision":1},{"id":"4555f352-b56d-7e7d-ba77-02472fb3cb2a","type":"callout","position":"a9","content":{"variant":"note","title":"9. VPN access controls","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"For internal APIs, require requests from within VPN. Limits access to known networks. Critical for admin APIs."}]}]}},"revision":1},{"id":"2a1726b7-4fa9-7396-bb9f-eb19e2889344","type":"heading","position":"aA","content":{"level":1,"content":[{"type":"text","text":"OWASP API Security Top 10"}]},"revision":1},{"id":"f5dd9aab-67d3-7992-8331-42e4457badd8","type":"text","position":"aB","content":{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"1"}]},{"type":"paragraph","content":[{"type":"text","text":"Broken Object Level Authorization"}]},{"type":"paragraph","content":[{"type":"text","text":"API returns data for IDs it shouldn''t. Check ownership on every request."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"2"}]},{"type":"paragraph","content":[{"type":"text","text":"Broken Authentication"}]},{"type":"paragraph","content":[{"type":"text","text":"Weak tokens, no expiry, credential stuffing."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"3"}]},{"type":"paragraph","content":[{"type":"text","text":"Broken Object Property Level Auth"}]},{"type":"paragraph","content":[{"type":"text","text":"Exposing internal fields, mass assignment (set isAdmin=true)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"4"}]},{"type":"paragraph","content":[{"type":"text","text":"Unrestricted Resource Consumption"}]},{"type":"paragraph","content":[{"type":"text","text":"No rate limiting, no payload size limits."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"5"}]},{"type":"paragraph","content":[{"type":"text","text":"Broken Function Level Authorization"}]},{"type":"paragraph","content":[{"type":"text","text":"Admin endpoints accessible to normal users."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"6"}]},{"type":"paragraph","content":[{"type":"text","text":"Unrestricted Sensitive Flows"}]},{"type":"paragraph","content":[{"type":"text","text":"No brute-force protection on login, OTP, password reset."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"7"}]},{"type":"paragraph","content":[{"type":"text","text":"SSRF"}]},{"type":"paragraph","content":[{"type":"text","text":"API fetches URLs from user input — attacker targets internal services."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"8"}]},{"type":"paragraph","content":[{"type":"text","text":"Security Misconfiguration"}]},{"type":"paragraph","content":[{"type":"text","text":"Debug endpoints exposed, verbose errors in prod."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"9"}]},{"type":"paragraph","content":[{"type":"text","text":"Improper Inventory Management"}]},{"type":"paragraph","content":[{"type":"text","text":"Old API versions still live, undocumented endpoints."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"10"}]},{"type":"paragraph","content":[{"type":"text","text":"Unsafe API Consumption"}]},{"type":"paragraph","content":[{"type":"text","text":"Blindly trusting third-party API data without validation."}]}]}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
WHERE EXISTS (SELECT 1 FROM "notes"."Note" n WHERE n.id = '9f6fff72-62b9-7d3c-81bb-5666b8b63049' AND n."ownerId" = '019a118c-f480-7000-8000-000000000001' AND n."publishedVersionId" IS NULL AND n.visibility = 'PRIVATE' AND n."deletedAt" IS NULL AND n."draftUpdatedAt" = TIMESTAMPTZ '2026-10-07 03:23:53+00')
