  ('1954b9a1-df23-7b9f-9a1b-c7927295810b', 'a6', 'callout', '{"variant":"note","title":"6. XSS","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Attacker injects malicious JS into your app. Runs in other users'' browsers — steals cookies, tokens."}]},{"type":"paragraph","content":[{"type":"text","text":"Fix:","marks":[{"type":"bold"}]},{"type":"text","text":" Escape user input before rendering. Use CSP headers. Never "},{"type":"text","text":"innerHTML","marks":[{"type":"code"}]},{"type":"text","text":" with user data. HttpOnly cookies."}]}]}}'),
  ('b4bce4a1-7d28-75f4-9e21-1dc12e284131', 'a7', 'callout', '{"variant":"note","title":"7. HTTPS + HSTS","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Always HTTPS. HSTS forces browsers to only use HTTPS — prevents downgrade attacks."}]},{"type":"paragraph","content":[{"type":"text","text":"Strict-Transport-Security: max-age=31536000; includeSubDomains; preload","marks":[{"type":"code"}]}]}]}}'),
