  SELECT 1 FROM "notes"."Note" n
  WHERE n.id = '825c0d3f-6460-77a5-ada7-7f13920fb6c4' AND n.visibility = 'PUBLIC' AND n."publishedVersionId" = '4005f13f-ff99-7681-b79b-3f700ac33625' AND n."deletedAt" IS NULL
)
