SELECT 'b7f7ac20-9a26-72ea-b14a-0a4436429213', '8ea4e0b3-7646-71a5-b7ab-747279d00021', 1, 'PUBLISHED', 'Versioning', '[{"id":"618223c5-df74-7e55-93a5-a5e6e9cf955e","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Once clients depend on your API, you can never break them. Versioning lets you evolve the API while keeping old consumers working."}]}]}},"revision":1},{"id":"e7cbb4cc-1bd2-77ea-bc95-b2ff02966712","type":"callout","position":"a1","content":{"variant":"note","title":"Breaking changes (require new version)","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Removing a field · Renaming a field · Changing field type · Removing an endpoint · Changing URL structure · Changing auth mechanism"}]}]}},"revision":1},{"id":"8a6266df-82ba-742d-9c1f-f03c2e91aced","type":"callout","position":"a2","content":{"variant":"note","title":"Non-breaking changes (safe)","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Adding a new field · Adding a new endpoint · Making required optional · Adding new optional params · Performance improvements"}]}]}},"revision":1},{"id":"25eec050-3894-7b7f-92da-89e3e78f002e","type":"heading","position":"a3","content":{"level":1,"content":[{"type":"text","text":"Versioning strategies"}]},"revision":1},{"id":"ce278667-14e6-770e-8a7c-383a921def84","type":"heading","position":"a4","content":{"level":3,"content":[{"type":"text","text":"URL path"}]},"revision":1},{"id":"384049d3-a73c-7d8d-97f2-a5fa85a9425a","type":"callout","position":"a5","content":{"variant":"note","title":"URL path versioning (most common)","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Version in the URL. Visible, easy to test with curl. Used by Stripe, Twitter, GitHub."}]}]}},"revision":1},{"id":"d3d04869-12a8-7bc9-ad0d-73f2af29115d","type":"code","position":"a6","content":{"language":"","code":"GET /api/v1/users/123\nGET /api/v2/users/123\n// v1 and v2 run simultaneously"},"revision":1},{"id":"f5b465a4-05d5-71f5-8a94-2d4b74421a8e","type":"callout","position":"a7","content":{"variant":"tip","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Easy to understand. Logs show which version each client uses. Simple to route in API gateway."}]}]}},"revision":1},{"id":"0991586f-3d71-7349-bc1a-1362cc749c60","type":"heading","position":"a8","content":{"level":3,"content":[{"type":"text","text":"Request header"}]},"revision":1},{"id":"b75fa5f6-a93b-7993-8d55-f38467d53658","type":"callout","position":"a9","content":{"variant":"note","title":"Custom request header","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Client sends a custom header. URL stays stable."}]}]}},"revision":1},{"id":"57764d77-8959-74d2-bd04-687599b3f10d","type":"code","position":"aA","content":{"language":"","code":"GET /api/users/123\nX-API-Version: 2"},"revision":1},{"id":"47ca17b7-d086-7312-a336-430de322eec0","type":"callout","position":"aB","content":{"variant":"warning","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Less visible. Harder to test. Easy to forget the header. Hard to share versioned URLs."}]}]}},"revision":1},{"id":"d9344dde-3999-7f69-862a-85f1ffb1dbb0","type":"heading","position":"aC","content":{"level":3,"content":[{"type":"text","text":"Query param"}]},"revision":1},{"id":"d0c69f4c-22ae-720c-a4db-5d0762343f23","type":"callout","position":"aD","content":{"variant":"note","title":"Query parameter versioning","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Version as a query param. Easy to test but pollutes the URL."}]}]}},"revision":1},{"id":"247ae304-d36d-7005-bcc8-305f039971e0","type":"code","position":"aE","content":{"language":"","code":"GET /api/users/123?version=2"},"revision":1},{"id":"76b04138-f859-789c-885f-31036659f1ab","type":"callout","position":"aF","content":{"variant":"warning","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Not recommended for primary strategy. Easy to accidentally omit."}]}]}},"revision":1},{"id":"af6d781a-86c5-763b-9382-2046111c8eab","type":"heading","position":"aG","content":{"level":1,"content":[{"type":"text","text":"Deprecation policy"}]},"revision":1},{"id":"7a2a534d-781e-76dd-a2c1-f256419f5c6f","type":"callout","position":"aH","content":{"variant":"note","doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Announce 6–12 months ahead","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Add "},{"type":"text","text":"Deprecation","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"Sunset","marks":[{"type":"code"}]},{"type":"text","text":" headers to v1 responses."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Document the migration","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Write a clear migration guide. Show what changed, why, and how to update."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Reach out to heavy users","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Monitor which API keys still hit v1. Email them directly."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Sunset the version","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Return 410 Gone after the sunset date."}]}]}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
