INSERT INTO "notes"."NoteVersion" ("id", "noteId", "number", "kind", "title", "cards", "createdById", "createdAt")
SELECT '07b1f259-7f06-7f59-9330-004d945489c5', '844a020f-756f-7852-b66f-d312b5e5fa04', 1, 'PUBLISHED', 'Types of Agents', '[{"id":"3dc5c62a-59e6-7dc3-ae19-9c9fd0d9a3f7","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Agent programs range from simple lookup rules to systems that plan, weigh trade-offs and improve themselves. Each type adds one capability to the previous one."}]}]}},"revision":1},{"id":"ea7bd778-605a-78f1-aca6-5994c497abb0","type":"table","position":"a1","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Agent type"}],[{"type":"text","text":"Decides using"}],[{"type":"text","text":"Strength"}],[{"type":"text","text":"Limitation"}],[{"type":"text","text":"Example"}]],[[{"type":"text","text":"Simple reflex","marks":[{"type":"bold"}]}],[{"type":"text","text":"Condition–action rules on the "},{"type":"text","text":"current","marks":[{"type":"italic"}]},{"type":"text","text":" percept"}],[{"type":"text","text":"Fast, simple"}],[{"type":"text","text":"Fails when the world is partially observable; can loop forever"}],[{"type":"text","text":"Thermostat, the vacuum agent above"}]],[[{"type":"text","text":"Model-based reflex","marks":[{"type":"bold"}]}],[{"type":"text","text":"Rules + an internal "},{"type":"text","text":"state","marks":[{"type":"bold"}]},{"type":"text","text":" updated by a model of how the world evolves"}],[{"type":"text","text":"Handles partial observability"}],[{"type":"text","text":"Still has no explicit goals"}],[{"type":"text","text":"Car tracking vehicles it can''t currently see"}]],[[{"type":"text","text":"Goal-based","marks":[{"type":"bold"}]}],[{"type":"text","text":"A model + "},{"type":"text","text":"goals","marks":[{"type":"bold"}]},{"type":"text","text":"; searches/plans for action sequences that reach them"}],[{"type":"text","text":"Flexible — change the goal, not the rules"}],[{"type":"text","text":"Goals are binary: all paths to the goal look equally good"}],[{"type":"text","text":"Route planner, puzzle solver"}]],[[{"type":"text","text":"Utility-based","marks":[{"type":"bold"}]}],[{"type":"text","text":"A "},{"type":"text","text":"utility function","marks":[{"type":"bold"}]},{"type":"text","text":" scoring how "},{"type":"text","text":"desirable","marks":[{"type":"italic"}]},{"type":"text","text":" each state is; maximises expected utility"}],[{"type":"text","text":"Trades off speed, safety, cost; handles uncertainty"}],[{"type":"text","text":"Utility is hard to specify; heavy computation"}],[{"type":"text","text":"Self-driving car choosing a route"}]],[[{"type":"text","text":"Learning agent","marks":[{"type":"bold"}]}],[{"type":"text","text":"Any of the above + components that improve it from experience"}],[{"type":"text","text":"Works in unknown environments; gets better"}],[{"type":"text","text":"Needs data/experience; can learn wrong things"}],[{"type":"text","text":"Spam filter, game-playing RL agent"}]]]},"revision":1},{"id":"3f8aae23-6242-7052-9eef-cd9dca88a427","type":"heading","position":"a2","content":{"level":1,"content":[{"type":"text","text":"Why internal state matters"}]},"revision":1},{"id":"e1987d06-c1bc-7f89-a1da-d1907804eef7","type":"text","position":"a3","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Add a cost of 1 point per move to the vacuum world. The simple reflex agent can''t remember that B is already clean, so it shuttles back and forth forever. A model-based agent remembers both squares and stops ("},{"type":"text","text":"NoOp","marks":[{"type":"code"}]},{"type":"text","text":"):"}]}]}},"revision":1},{"id":"497886de-beff-714a-bba7-3895c3664b60","type":"code","position":"a4","content":{"language":"python","code":"def reflex_agent(percept):\n    location, status = percept\n    if status == \"Dirty\":\n        return \"Suck\"\n    return \"Right\" if location == \"A\" else \"Left\"\n\ndef make_model_based_agent():\n    model = {\"A\": None, \"B\": None}               # internal state: what we believe about each square\n    def agent(percept):\n        location, status = percept\n        model[location] = status                 # update the model from the percept\n        if status == \"Dirty\":\n            model[location] = \"Clean\"            # predict the effect of our own action\n            return \"Suck\"\n        if model[\"A\"] == model[\"B\"] == \"Clean\":\n            return \"NoOp\"\n        return \"Right\" if location == \"A\" else \"Left\"\n    return agent\n\ndef run(agent, steps=10):\n    world, location, score = {\"A\": \"Dirty\", \"B\": \"Dirty\"}, \"A\", 0\n    for _ in range(steps):\n        action = agent((location, world[location]))\n        if action == \"Suck\":\n            world[location] = \"Clean\"\n        elif action in (\"Left\", \"Right\"):\n            location = \"B\" if action == \"Right\" else \"A\"\n            score -= 1                                          # moving costs energy\n        score += sum(s == \"Clean\" for s in world.values())\n    return score\n\nprint(run(reflex_agent))               # 10 ← keeps paying for pointless moves\nprint(run(make_model_based_agent()))   # 17 ← stops once it knows both squares are clean","filename":"Python"},"revision":1},{"id":"afd5fb73-3470-7377-9868-0464e64717d2","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"Goals vs utilities"}]},"revision":1},{"id":"3b144e37-3660-777b-a0a0-227ab26c8247","type":"text","position":"a6","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A goal-based agent asks "},{"type":"text","text":"“does this reach the goal?”","marks":[{"type":"italic"}]},{"type":"text","text":"; a utility-based agent asks "},{"type":"text","text":"“how good is this outcome?”","marks":[{"type":"italic"}]},{"type":"text","text":". Utility is needed whenever goals conflict (speed vs safety) or success is uncertain — the agent then maximises "},{"type":"text","text":"expected utility","marks":[{"type":"bold"}]},{"type":"text","text":" (see "},{"type":"text","text":"Utility & Markov Decision Processes","marks":[{"type":"bold"}]},{"type":"text","text":")."}]}]}},"revision":1},{"id":"e8e2e910-7436-7f0c-ad74-8cc994891992","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"The learning agent"}]},"revision":1},{"id":"d756d920-2f80-72ea-83c7-fed2cf66deb0","type":"callout","position":"a8","content":{"variant":"note","title":"Performance element","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The agent proper — selects actions (any of the four designs above)."}]}]}},"revision":1},{"id":"5cf3ba2e-5b78-71f2-8e6a-1ef75945d777","type":"callout","position":"a9","content":{"variant":"note","title":"Critic","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Judges how well the agent is doing against a fixed performance standard and gives feedback (e.g. a reward)."}]}]}},"revision":1},{"id":"692831b4-6244-762b-9e8c-ec00442ac14a","type":"callout","position":"aA","content":{"variant":"note","title":"Learning element","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Uses the critic''s feedback to improve the performance element."}]}]}},"revision":1},{"id":"bca6843b-b250-7f49-9c81-453abc092134","type":"callout","position":"aB","content":{"variant":"note","title":"Problem generator","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Suggests exploratory actions that lead to new, informative experiences — exploration."}]}]}},"revision":1},{"id":"9b1c724b-703e-7431-815f-7d31b4465f26","type":"callout","position":"aC","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"LLM-based “AI agents” fit this template: the LLM is the performance element choosing actions (tool calls), a memory/scratchpad is the internal state, the user''s task is the goal, and feedback loops play the critic. See the "},{"type":"text","text":"Generative AI","marks":[{"type":"bold"}]},{"type":"text","text":" notes."}]}]}},"revision":1},{"id":"23655b44-ccf7-7e27-9cd4-8ac0e210a980","type":"question","position":"aD","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"When is a simple reflex agent enough?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"When the environment is fully observable and the right action depends only on the current percept — e.g. a thermostat. With partial observability it needs internal state (model-based) or it may loop forever."}]}]}},"revision":1},{"id":"1b0d16ce-a11d-772e-b7b3-fc30fbfb4c80","type":"question","position":"aE","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why would you prefer a utility-based agent over a goal-based one?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Goals only distinguish success from failure. A utility function ranks outcomes, so the agent can trade off conflicting objectives and weigh the probability of success — essential under uncertainty."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
