INSERT INTO "notes"."NoteVersion" ("id", "noteId", "number", "kind", "title", "cards", "createdById", "createdAt")
SELECT '1bfd450e-28d3-7acd-8ce5-e323760086f2', 'a61ce8f5-78e1-7ca1-b433-46e7c84c8fb0', 1, 'PUBLISHED', 'Interview Questions', '[{"id":"d16d7ec5-f8e2-7c42-bfe7-ed56aaa5beaa","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Classical AI questions from university exams and ML/AI engineer interviews — short answers you can say out loud, with pointers to the topic that explains each one."}]}]}},"revision":1},{"id":"4733d97d-743c-71fe-8db0-5bbcbd99573e","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Foundations"}]},"revision":1},{"id":"6ec57788-ca17-7786-a1b5-b41ce6f92e64","type":"question","position":"a2","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is an intelligent agent? What makes it rational?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Anything that perceives its environment through sensors and acts through actuators. It is rational if, for each percept sequence, it chooses the action expected to maximise its performance measure given its percepts and built-in knowledge. (See "},{"type":"text","text":"Intelligent Agents & Environments","marks":[{"type":"bold"}]},{"type":"text","text":".)"}]}]}},"revision":1},{"id":"46c5d3d8-d048-7f54-bd3e-edd27b5a2fef","type":"question","position":"a3","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Describe the task environment of a self-driving car."}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"PEAS — performance: safety, time, legality, comfort; environment: roads, traffic, pedestrians, weather; actuators: steering, throttle, brake, signals; sensors: cameras, LiDAR, radar, GPS. It is partially observable, multi-agent, stochastic, sequential, dynamic, continuous."}]}]}},"revision":1},{"id":"b586bfeb-2e7f-73c6-ac0e-a1ab24a858c0","type":"question","position":"a4","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Name the five agent architectures."}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Simple reflex, model-based reflex, goal-based, utility-based and learning agents — each adds internal state, goals, preferences or self-improvement to the previous one."}]}]}},"revision":1},{"id":"4ae6a933-0a08-7a47-961f-eb6250792de0","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"Search"}]},"revision":1},{"id":"14fda72d-a6fe-7bed-86fe-933d2367ff2b","type":"question","position":"a6","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Compare BFS, DFS, UCS and iterative deepening."}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"BFS: complete, optimal for unit costs, "},{"type":"text","text":"O(bᵈ)","marks":[{"type":"code"}]},{"type":"text","text":" time and memory. DFS: "},{"type":"text","text":"O(bm)","marks":[{"type":"code"}]},{"type":"text","text":" memory but not complete or optimal. UCS: optimal for any positive costs, expands by path cost. IDDFS: BFS''s guarantees with DFS''s memory, at ~11% extra time for "},{"type":"text","text":"b = 10","marks":[{"type":"code"}]},{"type":"text","text":". (See "},{"type":"text","text":"Depth-Limited, Iterative Deepening & Bidirectional Search","marks":[{"type":"bold"}]},{"type":"text","text":".)"}]}]}},"revision":1},{"id":"4d6cbc74-eda3-75f8-8379-4840d71caba6","type":"question","position":"a7","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why is A* optimal, and what conditions does the heuristic need?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"It expands nodes in order of "},{"type":"text","text":"f = g + h","marks":[{"type":"code"}]},{"type":"text","text":". With an admissible "},{"type":"text","text":"h","marks":[{"type":"code"}]},{"type":"text","text":" it can never pop a suboptimal goal before some node on the optimal path; graph search additionally needs consistency so the first path found to every state is its cheapest."}]}]}},"revision":1},{"id":"f0839879-7286-73e7-aeb3-49503766c44a","type":"question","position":"a8","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How would you design a heuristic for a new problem?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Relax the problem — remove constraints until it is easy to solve exactly — and use the relaxed optimal cost (Manhattan distance, straight-line distance, ignore-delete-lists). Combine several admissible heuristics with "},{"type":"text","text":"max","marks":[{"type":"code"}]},{"type":"text","text":", or precompute pattern databases."}]}]}},"revision":1},{"id":"cde3bb38-ae0d-732c-bc3e-4b4a3d82b729","type":"question","position":"a9","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"When would you use local search instead of systematic search?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"When only the final state matters, the space is huge or continuous, and a good (not necessarily optimal) solution is enough — scheduling, layout, n-queens with millions of queens. Hill climbing with restarts, simulated annealing or genetic algorithms."}]}]}},"revision":1},{"id":"ce988eca-3d76-73d0-a92f-514e09d821d8","type":"heading","position":"aA","content":{"level":1,"content":[{"type":"text","text":"Games & CSPs"}]},"revision":1},{"id":"a4875b63-1da7-79c9-a705-1fe21b86dfcf","type":"question","position":"aB","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Explain alpha-beta pruning and its best case."}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Minimax with bounds α (MAX''s guaranteed value) and β (MIN''s). When "},{"type":"text","text":"α ≥ β","marks":[{"type":"code"}]},{"type":"text","text":" the rest of a node''s children can''t affect the decision and are skipped. With perfect move ordering the cost falls from "},{"type":"text","text":"O(bᵐ)","marks":[{"type":"code"}]},{"type":"text","text":" to "},{"type":"text","text":"O(b^(m/2))","marks":[{"type":"code"}]},{"type":"text","text":", doubling the searchable depth."}]}]}},"revision":1},{"id":"8fa25e6a-7dbb-72d0-a82a-3fb1e372996c","type":"question","position":"aC","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why did Go need MCTS instead of alpha-beta?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Go''s branching factor (~250) makes full-width search shallow, and good evaluation functions were very hard to hand-write. MCTS grows an asymmetric tree using playouts and UCB1, and AlphaGo added learned policy and value networks."}]}]}},"revision":1},{"id":"cbbf5007-37c7-7ead-bc1d-35346ab4f1b2","type":"question","position":"aD","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How do MRV, forward checking and AC-3 speed up a CSP solver?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"MRV picks the most constrained variable so dead ends appear early; forward checking prunes neighbours'' domains after each assignment; AC-3 propagates constraints across all arcs, detecting conflicts between unassigned variables before search reaches them."}]}]}},"revision":1},{"id":"f060804f-17a9-7fc0-97a5-4ba60d5a32aa","type":"heading","position":"aE","content":{"level":1,"content":[{"type":"text","text":"Logic, knowledge & planning"}]},"revision":1},{"id":"c6422837-a659-78f0-ab68-32c4873d85ee","type":"question","position":"aF","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is the difference between soundness and completeness?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A sound inference procedure derives only entailed sentences; a complete one derives every entailed sentence. Resolution is sound and refutation-complete for propositional logic; forward chaining is sound and complete for Horn clauses."}]}]}},"revision":1},{"id":"51b1afe0-748e-7ebc-82c2-d264bf24a3ec","type":"question","position":"aG","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Explain forward vs backward chaining with an example."}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Forward chaining starts from known facts and fires rules until the goal appears (production systems, monitoring). Backward chaining starts from the goal and works back through rules whose conclusion matches it (Prolog, diagnosis). (See "},{"type":"text","text":"Resolution, Forward & Backward Chaining","marks":[{"type":"bold"}]},{"type":"text","text":".)"}]}]}},"revision":1},{"id":"1d96f0ac-74ad-7a40-81a1-d37dc59d9a36","type":"question","position":"aH","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is unification and where is it used?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Finding the most general substitution that makes two logical expressions identical, e.g. "},{"type":"text","text":"Knows(John, x)","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"Knows(y, Mary)","marks":[{"type":"code"}]},{"type":"text","text":" → "},{"type":"text","text":"{y/John, x/Mary}","marks":[{"type":"code"}]},{"type":"text","text":". Used in generalised modus ponens, Prolog, and first-order resolution."}]}]}},"revision":1},{"id":"b92a405c-6c0b-7354-9c0c-8922dc54bc93","type":"question","position":"aI","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is the frame problem?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The difficulty of representing what does "},{"type":"text","text":"not","marks":[{"type":"italic"}]},{"type":"text","text":" change when an action occurs without writing an explicit axiom for every unaffected fact. STRIPS handles it by assuming everything not in an action''s add/delete lists stays the same."}]}]}},"revision":1},{"id":"daf49295-9f96-7b42-aabd-d7da2bffa2c1","type":"question","position":"aJ","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is STRIPS / PDDL?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A planning language where states are sets of facts and actions have preconditions, add lists and delete lists. PDDL is the standard modern form; the structure lets planners compute domain-independent heuristics such as ignore-delete-lists."}]}]}},"revision":1},{"id":"7a158ad8-1e5a-70f8-b643-f9336165709d","type":"heading","position":"aK","content":{"level":1,"content":[{"type":"text","text":"Uncertainty, decisions & learning"}]},"revision":1},{"id":"f16a7329-3d6b-7761-a8b0-5a5971a7f0bd","type":"question","position":"aL","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why are Bayesian networks more compact than a full joint distribution?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"They encode conditional independence: each variable depends directly only on its parents, so the joint factorises into small CPTs. The burglary network needs 10 numbers instead of 31; the gap grows exponentially with more variables."}]}]}},"revision":1},{"id":"4c5231ef-1c11-7d56-9336-fa8ef1348dd8","type":"question","position":"aM","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is an HMM and what is the Viterbi algorithm?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A Markov chain over hidden states with noisy observations of each state. Viterbi is dynamic programming that finds the single most likely hidden-state sequence for an observation sequence in time linear in its length."}]}]}},"revision":1},{"id":"8e9bb779-2976-7f03-b779-d6e32438ca28","type":"question","position":"aN","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Define an MDP and the Bellman equation."}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"An MDP is states, actions, a transition model "},{"type":"text","text":"P(s′|s,a)","marks":[{"type":"code"}]},{"type":"text","text":", rewards and a discount "},{"type":"text","text":"γ","marks":[{"type":"code"}]},{"type":"text","text":". The Bellman equation "},{"type":"text","text":"U(s) = maxₐ Σ P(s′|s,a)[R + γU(s′)]","marks":[{"type":"code"}]},{"type":"text","text":" characterises optimal utilities; value iteration applies it repeatedly."}]}]}},"revision":1},{"id":"543a08a8-a7ea-7b27-86de-843e38ed5f0a","type":"question","position":"aO","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What''s the difference between an MDP and reinforcement learning?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"In an MDP the transition and reward models are known, so you can plan (value/policy iteration). In RL they are unknown and the agent must learn from experienced transitions — model-based (learn the model, then plan) or model-free (Q-learning, policy gradients)."}]}]}},"revision":1},{"id":"049c9ab7-e280-78ea-9271-981190011b40","type":"question","position":"aP","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Explain the Q-learning update."}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Q(s,a) ← Q(s,a) + α[r + γ maxₐ′ Q(s′,a′) − Q(s,a)]","marks":[{"type":"code"}]},{"type":"text","text":": move the estimate toward the observed reward plus the discounted value of the best next action. It''s off-policy and converges to the optimal Q with enough exploration and a decaying learning rate."}]}]}},"revision":1},{"id":"f8f639b5-d750-77cb-a260-21259a52187d","type":"heading","position":"aQ","content":{"level":1,"content":[{"type":"text","text":"Big picture"}]},"revision":1},{"id":"baea5b92-ac59-730f-ba3e-ad5747935c06","type":"question","position":"aR","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What were the causes of the AI winters, and are we in a bubble now?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Over-promising followed by technical walls: combinatorial explosion in search and brittle, expensive expert systems. Today''s systems deliver real value at scale, but costs, reliability (hallucination) and unmet expectations are the usual warning signs to watch."}]}]}},"revision":1},{"id":"5a67607e-5882-73da-bc28-150161180192","type":"question","position":"aS","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How would you explain the difference between AI, ML, DL and generative AI to a non-technical person?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"AI is making computers do things that seem intelligent. ML is doing that by learning from examples instead of hand-written rules. Deep learning is ML with large neural networks. Generative AI uses deep learning to create new text, images or audio."}]}]}},"revision":1},{"id":"54ddad03-edb5-792a-ae56-a84b9ee597c4","type":"question","position":"aT","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What are the main ethical risks of AI systems?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Unfair outcomes from biased data, opaque decisions without recourse, privacy leakage, unsafe behaviour under distribution shift or attack, misuse (deepfakes, fraud), and misaligned objectives. Mitigations: subgroup evaluation, documentation, human oversight, monitoring and regulation-aligned governance."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
WHERE EXISTS (SELECT 1 FROM "notes"."Note" n WHERE n.id = 'a61ce8f5-78e1-7ca1-b433-46e7c84c8fb0' AND n."ownerId" = '019a118c-f480-7000-8000-000000000001' AND n."publishedVersionId" IS NULL AND n.visibility = 'PRIVATE' AND n."deletedAt" IS NULL AND n."draftUpdatedAt" = TIMESTAMPTZ '2026-10-07 03:23:53+00')
ON CONFLICT DO NOTHING;

INSERT INTO "notes"."Card" ("id", "noteId", "position", "type", "content", "revision", "createdAt", "updatedAt")
SELECT c.id::uuid, 'a61ce8f5-78e1-7ca1-b433-46e7c84c8fb0', c.position, c.type::"notes"."CardType", c.content::jsonb, 1, TIMESTAMPTZ '2026-10-07 03:23:53+00', TIMESTAMPTZ '2026-10-07 03:23:53+00'
FROM (VALUES
  ('d16d7ec5-f8e2-7c42-bfe7-ed56aaa5beaa', 'a0', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Classical AI questions from university exams and ML/AI engineer interviews — short answers you can say out loud, with pointers to the topic that explains each one."}]}]}}'),
  ('4733d97d-743c-71fe-8db0-5bbcbd99573e', 'a1', 'heading', '{"level":1,"content":[{"type":"text","text":"Foundations"}]}'),
  ('6ec57788-ca17-7786-a1b5-b41ce6f92e64', 'a2', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is an intelligent agent? What makes it rational?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Anything that perceives its environment through sensors and acts through actuators. It is rational if, for each percept sequence, it chooses the action expected to maximise its performance measure given its percepts and built-in knowledge. (See "},{"type":"text","text":"Intelligent Agents & Environments","marks":[{"type":"bold"}]},{"type":"text","text":".)"}]}]}}'),
  ('46c5d3d8-d048-7f54-bd3e-edd27b5a2fef', 'a3', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Describe the task environment of a self-driving car."}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"PEAS — performance: safety, time, legality, comfort; environment: roads, traffic, pedestrians, weather; actuators: steering, throttle, brake, signals; sensors: cameras, LiDAR, radar, GPS. It is partially observable, multi-agent, stochastic, sequential, dynamic, continuous."}]}]}}'),
  ('b586bfeb-2e7f-73c6-ac0e-a1ab24a858c0', 'a4', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Name the five agent architectures."}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Simple reflex, model-based reflex, goal-based, utility-based and learning agents — each adds internal state, goals, preferences or self-improvement to the previous one."}]}]}}'),
  ('4ae6a933-0a08-7a47-961f-eb6250792de0', 'a5', 'heading', '{"level":1,"content":[{"type":"text","text":"Search"}]}'),
  ('14fda72d-a6fe-7bed-86fe-933d2367ff2b', 'a6', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Compare BFS, DFS, UCS and iterative deepening."}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"BFS: complete, optimal for unit costs, "},{"type":"text","text":"O(bᵈ)","marks":[{"type":"code"}]},{"type":"text","text":" time and memory. DFS: "},{"type":"text","text":"O(bm)","marks":[{"type":"code"}]},{"type":"text","text":" memory but not complete or optimal. UCS: optimal for any positive costs, expands by path cost. IDDFS: BFS''s guarantees with DFS''s memory, at ~11% extra time for "},{"type":"text","text":"b = 10","marks":[{"type":"code"}]},{"type":"text","text":". (See "},{"type":"text","text":"Depth-Limited, Iterative Deepening & Bidirectional Search","marks":[{"type":"bold"}]},{"type":"text","text":".)"}]}]}}'),
  ('4d6cbc74-eda3-75f8-8379-4840d71caba6', 'a7', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why is A* optimal, and what conditions does the heuristic need?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"It expands nodes in order of "},{"type":"text","text":"f = g + h","marks":[{"type":"code"}]},{"type":"text","text":". With an admissible "},{"type":"text","text":"h","marks":[{"type":"code"}]},{"type":"text","text":" it can never pop a suboptimal goal before some node on the optimal path; graph search additionally needs consistency so the first path found to every state is its cheapest."}]}]}}'),
  ('f0839879-7286-73e7-aeb3-49503766c44a', 'a8', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How would you design a heuristic for a new problem?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Relax the problem — remove constraints until it is easy to solve exactly — and use the relaxed optimal cost (Manhattan distance, straight-line distance, ignore-delete-lists). Combine several admissible heuristics with "},{"type":"text","text":"max","marks":[{"type":"code"}]},{"type":"text","text":", or precompute pattern databases."}]}]}}'),
  ('cde3bb38-ae0d-732c-bc3e-4b4a3d82b729', 'a9', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"When would you use local search instead of systematic search?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"When only the final state matters, the space is huge or continuous, and a good (not necessarily optimal) solution is enough — scheduling, layout, n-queens with millions of queens. Hill climbing with restarts, simulated annealing or genetic algorithms."}]}]}}'),
  ('ce988eca-3d76-73d0-a92f-514e09d821d8', 'aA', 'heading', '{"level":1,"content":[{"type":"text","text":"Games & CSPs"}]}'),
  ('a4875b63-1da7-79c9-a705-1fe21b86dfcf', 'aB', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Explain alpha-beta pruning and its best case."}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Minimax with bounds α (MAX''s guaranteed value) and β (MIN''s). When "},{"type":"text","text":"α ≥ β","marks":[{"type":"code"}]},{"type":"text","text":" the rest of a node''s children can''t affect the decision and are skipped. With perfect move ordering the cost falls from "},{"type":"text","text":"O(bᵐ)","marks":[{"type":"code"}]},{"type":"text","text":" to "},{"type":"text","text":"O(b^(m/2))","marks":[{"type":"code"}]},{"type":"text","text":", doubling the searchable depth."}]}]}}'),
  ('8fa25e6a-7dbb-72d0-a82a-3fb1e372996c', 'aC', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why did Go need MCTS instead of alpha-beta?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Go''s branching factor (~250) makes full-width search shallow, and good evaluation functions were very hard to hand-write. MCTS grows an asymmetric tree using playouts and UCB1, and AlphaGo added learned policy and value networks."}]}]}}'),
  ('cbbf5007-37c7-7ead-bc1d-35346ab4f1b2', 'aD', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How do MRV, forward checking and AC-3 speed up a CSP solver?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"MRV picks the most constrained variable so dead ends appear early; forward checking prunes neighbours'' domains after each assignment; AC-3 propagates constraints across all arcs, detecting conflicts between unassigned variables before search reaches them."}]}]}}'),
  ('f060804f-17a9-7fc0-97a5-4ba60d5a32aa', 'aE', 'heading', '{"level":1,"content":[{"type":"text","text":"Logic, knowledge & planning"}]}'),
  ('c6422837-a659-78f0-ab68-32c4873d85ee', 'aF', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is the difference between soundness and completeness?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A sound inference procedure derives only entailed sentences; a complete one derives every entailed sentence. Resolution is sound and refutation-complete for propositional logic; forward chaining is sound and complete for Horn clauses."}]}]}}'),
  ('51b1afe0-748e-7ebc-82c2-d264bf24a3ec', 'aG', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Explain forward vs backward chaining with an example."}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Forward chaining starts from known facts and fires rules until the goal appears (production systems, monitoring). Backward chaining starts from the goal and works back through rules whose conclusion matches it (Prolog, diagnosis). (See "},{"type":"text","text":"Resolution, Forward & Backward Chaining","marks":[{"type":"bold"}]},{"type":"text","text":".)"}]}]}}'),
  ('1d96f0ac-74ad-7a40-81a1-d37dc59d9a36', 'aH', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is unification and where is it used?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Finding the most general substitution that makes two logical expressions identical, e.g. "},{"type":"text","text":"Knows(John, x)","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"Knows(y, Mary)","marks":[{"type":"code"}]},{"type":"text","text":" → "},{"type":"text","text":"{y/John, x/Mary}","marks":[{"type":"code"}]},{"type":"text","text":". Used in generalised modus ponens, Prolog, and first-order resolution."}]}]}}'),
  ('b92a405c-6c0b-7354-9c0c-8922dc54bc93', 'aI', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is the frame problem?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The difficulty of representing what does "},{"type":"text","text":"not","marks":[{"type":"italic"}]},{"type":"text","text":" change when an action occurs without writing an explicit axiom for every unaffected fact. STRIPS handles it by assuming everything not in an action''s add/delete lists stays the same."}]}]}}'),
  ('daf49295-9f96-7b42-aabd-d7da2bffa2c1', 'aJ', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is STRIPS / PDDL?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A planning language where states are sets of facts and actions have preconditions, add lists and delete lists. PDDL is the standard modern form; the structure lets planners compute domain-independent heuristics such as ignore-delete-lists."}]}]}}'),
  ('7a158ad8-1e5a-70f8-b643-f9336165709d', 'aK', 'heading', '{"level":1,"content":[{"type":"text","text":"Uncertainty, decisions & learning"}]}'),
  ('f16a7329-3d6b-7761-a8b0-5a5971a7f0bd', 'aL', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why are Bayesian networks more compact than a full joint distribution?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"They encode conditional independence: each variable depends directly only on its parents, so the joint factorises into small CPTs. The burglary network needs 10 numbers instead of 31; the gap grows exponentially with more variables."}]}]}}'),
  ('4c5231ef-1c11-7d56-9336-fa8ef1348dd8', 'aM', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is an HMM and what is the Viterbi algorithm?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A Markov chain over hidden states with noisy observations of each state. Viterbi is dynamic programming that finds the single most likely hidden-state sequence for an observation sequence in time linear in its length."}]}]}}'),
  ('8e9bb779-2976-7f03-b779-d6e32438ca28', 'aN', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Define an MDP and the Bellman equation."}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"An MDP is states, actions, a transition model "},{"type":"text","text":"P(s′|s,a)","marks":[{"type":"code"}]},{"type":"text","text":", rewards and a discount "},{"type":"text","text":"γ","marks":[{"type":"code"}]},{"type":"text","text":". The Bellman equation "},{"type":"text","text":"U(s) = maxₐ Σ P(s′|s,a)[R + γU(s′)]","marks":[{"type":"code"}]},{"type":"text","text":" characterises optimal utilities; value iteration applies it repeatedly."}]}]}}'),
  ('543a08a8-a7ea-7b27-86de-843e38ed5f0a', 'aO', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What''s the difference between an MDP and reinforcement learning?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"In an MDP the transition and reward models are known, so you can plan (value/policy iteration). In RL they are unknown and the agent must learn from experienced transitions — model-based (learn the model, then plan) or model-free (Q-learning, policy gradients)."}]}]}}'),
  ('049c9ab7-e280-78ea-9271-981190011b40', 'aP', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Explain the Q-learning update."}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Q(s,a) ← Q(s,a) + α[r + γ maxₐ′ Q(s′,a′) − Q(s,a)]","marks":[{"type":"code"}]},{"type":"text","text":": move the estimate toward the observed reward plus the discounted value of the best next action. It''s off-policy and converges to the optimal Q with enough exploration and a decaying learning rate."}]}]}}'),
  ('f8f639b5-d750-77cb-a260-21259a52187d', 'aQ', 'heading', '{"level":1,"content":[{"type":"text","text":"Big picture"}]}'),
  ('baea5b92-ac59-730f-ba3e-ad5747935c06', 'aR', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What were the causes of the AI winters, and are we in a bubble now?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Over-promising followed by technical walls: combinatorial explosion in search and brittle, expensive expert systems. Today''s systems deliver real value at scale, but costs, reliability (hallucination) and unmet expectations are the usual warning signs to watch."}]}]}}'),
  ('5a67607e-5882-73da-bc28-150161180192', 'aS', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How would you explain the difference between AI, ML, DL and generative AI to a non-technical person?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"AI is making computers do things that seem intelligent. ML is doing that by learning from examples instead of hand-written rules. Deep learning is ML with large neural networks. Generative AI uses deep learning to create new text, images or audio."}]}]}}'),
  ('54ddad03-edb5-792a-ae56-a84b9ee597c4', 'aT', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What are the main ethical risks of AI systems?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Unfair outcomes from biased data, opaque decisions without recourse, privacy leakage, unsafe behaviour under distribution shift or attack, misuse (deepfakes, fraud), and misaligned objectives. Mitigations: subgroup evaluation, documentation, human oversight, monitoring and regulation-aligned governance."}]}]}}')
) AS c(id, position, type, content)
WHERE EXISTS (SELECT 1 FROM "notes"."Note" n WHERE n.id = 'a61ce8f5-78e1-7ca1-b433-46e7c84c8fb0' AND n."ownerId" = '019a118c-f480-7000-8000-000000000001' AND n."publishedVersionId" IS NULL AND n.visibility = 'PRIVATE' AND n."deletedAt" IS NULL AND n."draftUpdatedAt" = TIMESTAMPTZ '2026-10-07 03:23:53+00')
ON CONFLICT DO NOTHING;

