INSERT INTO "notes"."NoteVersion" ("id", "noteId", "number", "kind", "title", "cards", "createdById", "createdAt")
SELECT '814f6dca-7434-7f38-a8df-57205c828622', '5a0ca1ec-fae8-7128-b3f9-9793f6d3771b', 1, 'PUBLISHED', 'Alpha-Beta Pruning', '[{"id":"71be50d6-35c4-74db-96be-6e5f19f4ff6f","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Alpha-beta pruning returns exactly the minimax value while skipping branches that cannot affect the decision. With good move ordering it searches roughly "},{"type":"text","text":"twice as deep","marks":[{"type":"bold"}]},{"type":"text","text":" in the same time."}]}]}},"revision":1},{"id":"b44d4c6b-4fc3-7592-ae0f-218236898cfa","type":"callout","position":"a1","content":{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"α (alpha)","marks":[{"type":"bold"}]},{"type":"text","text":" — the best value MAX can already guarantee somewhere along the path to the root — a lower bound."}]}]}},"revision":1},{"id":"c75d76d2-ee97-7e49-a187-68de314e35a1","type":"callout","position":"a2","content":{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"β (beta)","marks":[{"type":"bold"}]},{"type":"text","text":" — the best (lowest) value MIN can already guarantee along the path — an upper bound."}]}]}},"revision":1},{"id":"9f5c415c-d97e-79c6-bf8e-c6704555a692","type":"text","position":"a3","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"While searching, if a node''s value is proven to be outside "},{"type":"text","text":"[α, β]","marks":[{"type":"code"}]},{"type":"text","text":", the player above will never let the game reach it, so its remaining children are "},{"type":"text","text":"pruned","marks":[{"type":"bold"}]},{"type":"text","text":": whenever "},{"type":"text","text":"α ≥ β","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"74046f92-3507-71d4-9c25-44cc7476326f","type":"code","position":"a4","content":{"language":"python","code":"TREE = {\"A\": [\"B\", \"C\", \"D\"],\n        \"B\": [3, 12, 8], \"C\": [2, 4, 6], \"D\": [14, 5, 2]}\nvisited = []\n\ndef alphabeta(node, alpha, beta, maximizing):\n    if isinstance(node, int):\n        visited.append(node)\n        return node\n    if maximizing:\n        value = float(\"-inf\")\n        for child in TREE[node]:\n            value = max(value, alphabeta(child, alpha, beta, False))\n            alpha = max(alpha, value)\n            if alpha >= beta:\n                break                              # β cut-off: MIN above won''t allow this\n        return value\n    value = float(\"inf\")\n    for child in TREE[node]:\n        value = min(value, alphabeta(child, alpha, beta, True))\n        beta = min(beta, value)\n        if alpha >= beta:\n            break                                  # α cut-off: MAX above already has better\n    return value\n\nprint(alphabeta(\"A\", float(\"-inf\"), float(\"inf\"), True))   # 3 ← same answer as minimax\nprint(visited, f\"{len(visited)} of 9 leaves\")               # [3, 12, 8, 2, 14, 5, 2] 7 of 9 leaves","filename":"Python"},"revision":1},{"id":"f0d38265-c9dc-7962-8f7c-f7ce9277b41b","type":"text","position":"a5","content":{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Explore B","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"MIN sees 3, 12, 8 → B = 3. At the root α = 3: MAX is guaranteed at least 3."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"First leaf of C is 2","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"MIN at C can force ≤ 2, which is worse for MAX than the 3 it already has — so C''s other leaves (4, 6) are "},{"type":"text","text":"pruned","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Explore D","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"14 → 5 → 2: D''s value is only bounded after the last leaf, so nothing is pruned there."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Result","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Root = max(3, ≤2, 2) = 3 — identical to minimax, with 7 leaves instead of 9."}]}]}]}]}},"revision":1},{"id":"355eb654-c664-7a0e-a58a-2b60ad94a3a0","type":"heading","position":"a6","content":{"level":1,"content":[{"type":"text","text":"Move ordering is everything"}]},"revision":1},{"id":"00eff8b4-5783-7437-8cf4-bb64627319dd","type":"text","position":"a7","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Pruning depends on examining the "},{"type":"text","text":"best moves first","marks":[{"type":"bold"}]},{"type":"text","text":". On a random tree of depth 4 with 4 moves per node (256 leaves):"}]}]}},"revision":1},{"id":"a83717ce-40d6-7e8c-a451-fc995c3b5847","type":"code","position":"a8","content":{"language":"python","code":"import random\n\nrandom.seed(3)\nB, DEPTH = 4, 4\ndef build(depth):\n    return random.randint(0, 99) if depth == 0 else [build(depth - 1) for _ in range(B)]\ntree = build(DEPTH)\n\ndef minimax(node, maximizing):\n    if isinstance(node, int):\n        return node\n    vals = [minimax(c, not maximizing) for c in node]\n    return max(vals) if maximizing else min(vals)\n\ndef alphabeta(node, alpha, beta, maximizing, order, count):\n    if isinstance(node, int):\n        count[0] += 1\n        return node\n    best = float(\"-inf\") if maximizing else float(\"inf\")\n    for child in order(node, maximizing):\n        v = alphabeta(child, alpha, beta, not maximizing, order, count)\n        if maximizing:\n            best, alpha = max(best, v), max(alpha, v)\n        else:\n            best, beta = min(best, v), min(beta, v)\n        if alpha >= beta:\n            break\n    return best\n\nas_given = lambda node, maximizing: node\nworst_first = lambda node, maximizing: sorted(node, key=lambda c: minimax(c, not maximizing), reverse=not maximizing)\nbest_first = lambda node, maximizing: sorted(node, key=lambda c: minimax(c, not maximizing), reverse=maximizing)\n\ncounts = {}\nfor name, order in [(\"worst-first\", worst_first), (\"as generated\", as_given), (\"best-first\", best_first)]:\n    count = [0]\n    alphabeta(tree, float(\"-inf\"), float(\"inf\"), True, order, count)\n    counts[name] = count[0]\n\nprint(minimax(tree, True), B ** DEPTH)     # 47 256 ← value, and leaves plain minimax looks at\nprint(counts[\"worst-first\"])               # 238\nprint(counts[\"as generated\"])              # 61\nprint(counts[\"best-first\"])                # 31 ← 2·b^(d/2) − 1 = 31: the theoretical minimum","filename":"Python"},"revision":1},{"id":"b7616be2-bdc6-7829-9cd9-c7de3ac27e6a","type":"table","position":"a9","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Move ordering"}],[{"type":"text","text":"Nodes examined"}],[{"type":"text","text":"Effective branching factor"}],[{"type":"text","text":"Depth reachable in the same time"}]],[[{"type":"text","text":"Worst (best moves last)"}],[{"type":"text","text":"O(bᵐ)","marks":[{"type":"code"}]},{"type":"text","text":" — no pruning"}],[{"type":"text","text":"b","marks":[{"type":"code"}]}],[{"type":"text","text":"d","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Random"}],[{"type":"text","text":"≈ "},{"type":"text","text":"O(b^(3m/4))","marks":[{"type":"code"}]}],[{"type":"text","text":"≈ "},{"type":"text","text":"b^(3/4)","marks":[{"type":"code"}]}],[{"type":"text","text":"≈ "},{"type":"text","text":"4d/3","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Perfect (best moves first)"}],[{"type":"text","text":"O(b^(m/2))","marks":[{"type":"code"}]}],[{"type":"text","text":"√b","marks":[{"type":"code"}]},{"type":"text","text":" (chess: 35 → ~6)"}],[{"type":"text","text":"2d","marks":[{"type":"code"}]}]]]},"revision":1},{"id":"eae140d4-3396-79de-90e4-749d1b4086f5","type":"callout","position":"aA","content":{"variant":"note","title":"Iterative deepening","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Search depth 1, 2, 3… and try the previous iteration''s best move first — the deeper search inherits a near-perfect ordering."}]}]}},"revision":1},{"id":"a1cf5fa9-5db9-70b0-abff-4cae29944d04","type":"callout","position":"aB","content":{"variant":"note","title":"Killer moves","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Moves that caused a cut-off at the same depth elsewhere are likely to cause one here — try them early."}]}]}},"revision":1},{"id":"7fc453e6-c4e8-763d-bea1-2e4457c26159","type":"callout","position":"aC","content":{"variant":"note","title":"History heuristic","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Keep a score of moves that caused cut-offs anywhere; order by it."}]}]}},"revision":1},{"id":"0e4b96b8-5058-7ce2-aa7c-008101175130","type":"callout","position":"aD","content":{"variant":"note","title":"Transposition table","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Hash positions already evaluated (reached by different move orders) and reuse their values and best moves."}]}]}},"revision":1},{"id":"1cb78bf3-4b6b-7942-b47f-6e5b0da138d2","type":"callout","position":"aE","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Alpha-beta never changes the minimax value at the root — if your pruned search returns a different move value than plain minimax, there''s a bug (usually α/β passed or updated at the wrong level)."}]}]}},"revision":1},{"id":"6391ec0f-a8ad-7257-89e7-57b557897da4","type":"question","position":"aF","content":{"prompt":{"type":"d