SELECT '92bdf413-7dbb-7add-83a9-8726d57a9db7', '87650d5b-2b9c-71e5-a39d-47dc328f3684', 1, 'PUBLISHED', 'Classical Planning (STRIPS & PDDL)', '[{"id":"e82375f8-cbf5-7a4e-8bb5-4ab9307f6cee","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Planning finds a sequence of actions that achieves a goal, using a "},{"type":"text","text":"factored","marks":[{"type":"bold"}]},{"type":"text","text":" representation: states are sets of facts and actions are schemas with preconditions and effects. That structure allows domain-independent heuristics that make planners scale to huge problems."}]}]}},"revision":1},{"id":"c5fa4ae6-427e-7642-80bd-ed59ae7eac6b","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"The STRIPS representation"}]},"revision":1},{"id":"f4f1445f-f399-74ee-bd2f-e2c8bd7cfe97","type":"table","position":"a2","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Part"}],[{"type":"text","text":"Meaning"}],[{"type":"text","text":"Blocks world"}]],[[{"type":"text","text":"State"}],[{"type":"text","text":"Conjunction of ground facts (fluents); everything else is false (closed world)"}],[{"type":"text","text":"On(C, A) ∧ OnTable(A) ∧ OnTable(B) ∧ Clear(C) ∧ Clear(B)","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Goal"}],[{"type":"text","text":"Conjunction of facts that must hold (a partial state)"}],[{"type":"text","text":"On(A, B) ∧ On(B, C)","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Action schema"}],[{"type":"text","text":"Name, "},{"type":"text","text":"preconditions","marks":[{"type":"bold"}]},{"type":"text","text":", "},{"type":"text","text":"add list","marks":[{"type":"bold"}]},{"type":"text","text":", "},{"type":"text","text":"delete list","marks":[{"type":"bold"}]}],[{"type":"text","text":"Move(b, x, y)","marks":[{"type":"code"}]}]]]},"revision":1},{"id":"a4b4aa38-0877-7706-a2e4-9c967a9b1959","type":"text","position":"a3","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"An action is applicable when its preconditions hold; its result is "},{"type":"text","text":"(state − delete list) ∪ add list","marks":[{"type":"code"}]},{"type":"text","text":". Facts not mentioned stay unchanged — this is how STRIPS sidesteps the frame problem. "},{"type":"text","text":"PDDL","marks":[{"type":"bold"}]},{"type":"text","text":" (Planning Domain Definition Language) is the standard modern syntax:"}]}]}},"revision":1},{"id":"e6379e1e-4b96-78d9-9973-4e64d9bcb522","type":"code","position":"a4","content":{"language":"text","code":"(:action move\n  :parameters (?b ?x ?y)\n  :precondition (and (on ?b ?x) (clear ?b) (clear ?y))\n  :effect (and (on ?b ?y) (clear ?x)\n               (not (on ?b ?x)) (not (clear ?y))))","filename":"PDDL"},"revision":1},{"id":"45a8e24a-43bb-7f4b-bc08-432a1c2d0619","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"Forward (progression) planning"}]},"revision":1},{"id":"43c6a402-a2e8-7efa-8973-b5d313c95a5b","type":"text","position":"a6","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Treat planning as search: states are fact sets, successors come from applicable ground actions. Here is the "},{"type":"text","text":"Sussman anomaly","marks":[{"type":"bold"}]},{"type":"text","text":" — start with C on A; goal A on B on C:"}]}]}},"revision":1},{"id":"dde2ec9d-5fea-7759-a40b-584f7162bae5","type":"code","position":"a7","content":{"language":"python","code":"from collections import deque\n\nBLOCKS = [\"A\", \"B\", \"C\"]\nPLACES = BLOCKS + [\"Table\"]\n\ndef ground_actions():                               # every instance of Move(b, x, y)\n    for b in BLOCKS:\n        for x in PLACES:\n            for y in PLACES:\n                if len({b, x, y}) == 3:\n                    pre = {(\"On\", b, x), (\"Clear\", b)} | ({(\"Clear\", y)} if y != \"Table\" else set())\n                    add = {(\"On\", b, y)} | ({(\"Clear\", x)} if x != \"Table\" else set())\n                    delete = {(\"On\", b, x)} | ({(\"Clear\", y)} if y != \"Table\" else set())\n                    yield f\"Move({b},{x},{y})\", frozenset(pre), frozenset(add), frozenset(delete)\n\nACTIONS = list(ground_actions())\n\ndef plan(start, goal):                              # breadth-first progression search\n    frontier, seen = deque([(start, [])]), {start}\n    while frontier:\n        state, steps = frontier.popleft()\n        if goal <= state:\n            return steps, len(seen)\n        for name, pre, add, delete in ACTIONS:\n            if pre <= state:\n                nxt = (state - delete) | add\n                if nxt not in seen:\n                    seen.add(nxt)\n                    frontier.append((nxt, steps + [name]))\n\nstart = frozenset({(\"On\", \"C\", \"A\"), (\"On\", \"A\", \"Table\"), (\"On\", \"B\", \"Table\"), (\"Clear\", \"C\"), (\"Clear\", \"B\")})\ngoal = {(\"On\", \"A\", \"B\"), (\"On\", \"B\", \"C\")}\nprint(len(ACTIONS))           # 18 ← ground actions from one schema\nprint(plan(start, goal))      # ([''Move(C,A,Table)'', ''Move(B,Table,C)'', ''Move(A,Table,B)''], 13)","filename":"Python"},"revision":1},{"id":"7724e07b-4c0d-7c3c-9e63-11f2e8e0271e","type":"callout","position":"a8","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The Sussman anomaly defeats planners that achieve goals "},{"type":"text","text":"one at a time","marks":[{"type":"bold"}]},{"type":"text","text":": stacking A on B first (after clearing C) must be undone to get B onto C, and achieving B on C first buries A. The goals interact, so a planner must interleave them."}]}]}},"revision":1},{"id":"a1e2c8a5-3443-70db-9a58-d8cb1bf69484","type":"heading","position":"a9","content":{"level":1,"content":[{"type":"text","text":"Search strategies and heuristics"}]},"revision":1},{"id":"42b44476-16f6-7e89-b91e-1573ce6f48eb","type":"table","position":"aA","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Approach"}],[{"type":"text","text":"Idea"}]],[[{"type":"text","text":"Forward (progression)","marks":[{"type":"bold"}]},{"type":"text","text":" search"}],[{"type":"text","text":"From the initial state apply applicable actions. Many irrelevant actions — needs a good heuristic."}]],[[{"type":"text","text":"Backward (regression)","marks":[{"type":"bold"}]},{"type":"text","text":" search"}],[{"type":"text","text":"From the goal, consider only "},{"type":"text","text":"relevant","marks":[{"type":"italic"}]},{"type":"text","text":" actions (that add a goal fact without deleting another); regress the goal through them. Smaller branching factor."}]],[[{"type":"text","text":"Ignore-delete-lists","marks":[{"type":"bold"}]},{"type":"text","text":" heuristic"}],[{"type":"text","text":"Solve the relaxed problem where actions never remove facts (the basis of FF and HSP planners). Admissible variants give A*-optimal plans."}]],[[{"type":"text","text":"Ignore-preconditions","marks":[{"type":"bold"}]},{"type":"text","text":" heuristic"}],[{"type":"text","text":"Count how many actions are needed if any action could always be applied — roughly the number of unsatisfied goals."}]],[[{"type":"text","text":"Planning graphs / GraphPlan","marks":[{"type":"bold"}]}],[{"type":"text","text":"Layered graph of reachable facts and actions with mutex links; the level where all goals first appear is a heuristic estimate."}]],[[{"type":"text","text":"SAT planning","marks":[{"type":"bold"}]}],[{"type":"text","text":"Encode “is there a plan of length "},{"type":"text","text":"T","marks":[{"type":"code"}]},{"type":"text","text":"?” as a Boolean formula and hand it to a SAT solver."}]]]},"revision":1},{"id":"8d1790cb-812c-745e-940b-b4fa849e732f","type":"heading","position":"aB","content":{"level":1,"content":[{"type":"text","text":"Partial-order planning"}]},"revision":1},{"id":"28d4a75f-e93a-769a-aa8d-ae64d4efc9e2","type":"text","position":"aC","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A "},{"type":"text","text":"partial-order planner","marks":[{"type":"bold"}]},{"type":"text","text":" (POP) searches in the space of "},{"type":"text","text":"plans","marks":[{"type":"italic"}]},{"type":"text","text":", not states, and commits to an ordering only when necessary ("},{"type":"text","text":"least commitment","marks":[{"type":"bold"}]},{"type":"text","text":"). A plan has actions, ordering constraints "},{"type":"text","text":"A ≺ B","marks":[{"type":"code"}]},{"type":"text","text":", and "},{"type":"text","text":"causal links","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"A →p→ B","marks":[{"type":"code"}]},{"type":"text","text":" (A achieves precondition "},{"type":"text","text":"p","marks":[{"type":"code"}]},{"type":"text","text":" of B). A "},{"type":"text","text":"threat","marks":[{"type":"bold"}]},{"type":"text","text":" is an action that could delete "},{"type":"text","text":"p","marks":[{"type":"code"}]},{"type":"text","text":" between A and B — resolved by ordering it before A (demotion) or after B (promotion)."}]}]}},"revision":1},{"id":"afede327-054e-798c-a444-1a950b4ecf2e","type":"callout","position":"aD","content":{"variant":"tip","title":"Least commitment","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Putting on shoes: "},{"type":"text","text":"RightSock ≺ RightShoe","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"LeftSock ≺ LeftShoe","marks":[{"type":"code"}]},{"type":"text","text":", but the left and right sides are unordered — the plan allows any of the 6 interleavings."}]}]}},"revision":1},{"id":"38a07e80-37ac-7041-a0cd-ccdabbd3a646","type":"table","position":"aE","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Beyond classical planning"}],[{"type":"text","text":"Handles"}]],[[{"type":"text","text":"Hierarchical task networks (HTN)"}],[{"type":"text","text":"High-level actions refined into sub-plans — how most real planners (and games'' NPCs) work"}]],[[{"type":"text","text":"Scheduling with resources"}],[{"type":"text","text":"Durations, deadlines, limited machines/crew — critical-path method"}]],[[{"type":"text","text":"Contingent / conformant planning"}],[{"type":"text","text":"Partial observability: plans with sensing actions and branches"}]],[[{"type":"text","text":"Replanning & execution monitoring"}],[{"type":"text","text":"Detect when the world deviates from the plan and repair it"}]],[[{"type":"text","text":"MDPs (next group)"}],[{"type":"text","text":"Stochastic action outcomes — a "},{"type":"text","text":"policy","marks":[{"type":"italic"}]},{"type":"text","text":" instead of a fixed sequence"}]]]},"revision":1},{"id":"4e3fc942-f735-7ad6-92fa-a5d65cac7c47","type":"question","position":"aF","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is STRIPS?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A planning representation where states are sets of ground facts and each action has preconditions, an add list and a delete list. Anything not mentioned is unchanged, which avoids writing frame axioms. PDDL is its modern, more expressive successor."}]}]}},"revision":1},{"id":"d700f1b3-15d6-7d60-92ae-b8c2bafa827a","type":"question","position":"aG","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Forward vs backward state-space planning?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Forward search starts from the initial state and applies applicable actions — simple but branches on many irrelevant actions. Backward (regression) search starts from the goal and only considers relevant actions, giving a smaller branching factor, but works on sets of states and makes heuristics harder."}]}]}},"revision":1},{"id":"5872a44c-2ae6-7d9e-8938-87189a4d4319","type":"question","position":"aH","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why can planning use domain-independent heuristics while plain search cannot?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The factored representation exposes the structure of actions, so a planner can automatically build relaxed problems — ignoring delete lists or preconditions — and solve them to get heuristic estimates without any domain-specific coding."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
WHERE EXISTS (SELECT 1 FROM "notes"."Note" n WHERE n.id = '87650d5b-2b9c-71e5-a39d-47dc328f3684' AND n."ownerId" = '019a118c-f480-7000-8000-000000000001' AND n."publishedVersionId" IS NULL AND n.visibility = 'PRIVATE' AND n."deletedAt" IS NULL AND n."draftUpdatedAt" = TIMESTAMPTZ '2026-10-07 03:23:53+00')
