  ('4e3fc942-f735-7ad6-92fa-a5d65cac7c47', 'aF', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is STRIPS?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A planning representation where states are sets of ground facts and each action has preconditions, an add list and a delete list. Anything not mentioned is unchanged, which avoids writing frame axioms. PDDL is its modern, more expressive successor."}]}]}}'),
  ('d700f1b3-15d6-7d60-92ae-b8c2bafa827a', 'aG', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Forward vs backward state-space planning?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Forward search starts from the initial state and applies applicable actions — simple but branches on many irrelevant actions. Backward (regression) search starts from the goal and only considers relevant actions, giving a smaller branching factor, but works on sets of states and makes heuristics harder."}]}]}}'),
