SELECT 'ed7e4554-d16a-776f-9ff8-f4ad9873a2df', '1da7fb9c-78f2-7c6e-a93a-d9179853a5b1', 1, 'PUBLISHED', 'CSP Heuristics, Forward Checking & AC-3', '[{"id":"97b76933-dc69-717c-9a4c-ef7dc60fce6d","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Three questions make backtracking fast: "},{"type":"text","text":"which variable","marks":[{"type":"bold"}]},{"type":"text","text":" next, "},{"type":"text","text":"which value","marks":[{"type":"bold"}]},{"type":"text","text":" first, and "},{"type":"text","text":"what can we infer","marks":[{"type":"bold"}]},{"type":"text","text":" after each assignment. Good answers turn exponential searches into near-linear ones."}]}]}},"revision":1},{"id":"86400da9-a027-7684-b870-63d60c3a4096","type":"table","position":"a1","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Heuristic"}],[{"type":"text","text":"Rule"}],[{"type":"text","text":"Intuition"}]],[[{"type":"text","text":"MRV","marks":[{"type":"bold"}]},{"type":"text","text":" — minimum remaining values"}],[{"type":"text","text":"Pick the variable with the fewest legal values left"}],[{"type":"text","text":"Fail first","marks":[{"type":"italic"}]},{"type":"text","text":": tackle the most constrained variable before it becomes impossible"}]],[[{"type":"text","text":"Degree heuristic","marks":[{"type":"bold"}]}],[{"type":"text","text":"Tie-break by the variable involved in the most constraints with unassigned variables"}],[{"type":"text","text":"Reduces future branching (SA first in Australia)"}]],[[{"type":"text","text":"LCV","marks":[{"type":"bold"}]},{"type":"text","text":" — least constraining value"}],[{"type":"text","text":"Try the value that rules out the fewest choices for neighbours"}],[{"type":"text","text":"Fail last","marks":[{"type":"italic"}]},{"type":"text","text":": leave maximum flexibility — we only need one solution"}]]]},"revision":1},{"id":"862573db-9bc3-73f8-823e-166fa323ba45","type":"heading","position":"a2","content":{"level":1,"content":[{"type":"text","text":"Inference: forward checking and arc consistency"}]},"revision":1},{"id":"cd65c2ed-53c3-74ad-a789-055ee5d6f221","type":"callout","position":"a3","content":{"variant":"note","title":"Forward checking","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"After assigning "},{"type":"text","text":"X = v","marks":[{"type":"code"}]},{"type":"text","text":", delete "},{"type":"text","text":"v","marks":[{"type":"code"}]},{"type":"text","text":"-inconsistent values from the domains of "},{"type":"text","text":"X","marks":[{"type":"code"}]},{"type":"text","text":"''s unassigned neighbours. If a domain becomes empty, backtrack immediately."}]}]}},"revision":1},{"id":"edd0185c-f885-7c44-8c37-ac5570001ed5","type":"callout","position":"a4","content":{"variant":"note","title":"Arc consistency","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Arc "},{"type":"text","text":"X → Y","marks":[{"type":"code"}]},{"type":"text","text":" is consistent if every value of "},{"type":"text","text":"X","marks":[{"type":"code"}]},{"type":"text","text":" has "},{"type":"text","text":"some","marks":[{"type":"italic"}]},{"type":"text","text":" supporting value in "},{"type":"text","text":"Y","marks":[{"type":"code"}]},{"type":"text","text":". AC-3 enforces this for all arcs, propagating deletions until nothing changes."}]}]}},"revision":1},{"id":"bb0bfefc-7e55-73e6-ab89-1af770e6c462","type":"callout","position":"a5","content":{"variant":"note","title":"MAC","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Maintaining arc consistency","marks":[{"type":"italic"}]},{"type":"text","text":": run AC-3 after every assignment during backtracking — stronger than forward checking."}]}]}},"revision":1},{"id":"3f45c182-5b78-750b-a7c6-13d0b71b9f47","type":"code","position":"a6","content":{"language":"python","code":"def solve(n, mrv=False, forward_check=False):\n    nodes = 0\n    def backtrack(assign, domains):\n        nonlocal nodes\n        if len(assign) == n:\n            return dict(assign)\n        free = [c for c in range(n) if c not in assign]\n        var = min(free, key=lambda c: len(domains[c])) if mrv else free[0]\n        for row in sorted(domains[var]):\n            if any(row == r or abs(row - r) == abs(var - c) for c, r in assign.items()):\n                continue\n            nodes += 1\n            assign[var] = row\n            new = domains\n            if forward_check:              # prune neighbours'' domains; empty domain → dead end\n                new = {c: d if c in assign else {x for x in d if x != row and abs(x - row) != abs(c - var)}\n                       for c, d in domains.items()}\n            if all(new[c] for c in new if c not in assign) and (res := backtrack(assign, new)):\n                return res\n            del assign[var]\n        return None\n    backtrack({}, {c: set(range(n)) for c in range(n)})\n    return nodes\n\nprint(solve(16))                                  # 10052 ← plain backtracking\nprint(solve(16, forward_check=True))              # 7560\nprint(solve(16, mrv=True, forward_check=True))    # 44 ← MRV + forward checking","filename":"Python"},"revision":1},{"id":"4a07ddb3-ee6f-7c85-9bb1-3ce64a8bf9b3","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"AC-3"}]},"revision":1},{"id":"92e3c603-9136-708a-abd0-047138baa337","type":"text","position":"a8","content":{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Queue every arc","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"For each binary constraint between X and Y add both arcs "},{"type":"text","text":"(X, Y)","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"(Y, X)","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Revise","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Pop an arc "},{"type":"text","text":"(X, Y)","marks":[{"type":"code"}]},{"type":"text","text":"; delete each value of "},{"type":"text","text":"X","marks":[{"type":"code"}]},{"type":"text","text":" that has no compatible value in "},{"type":"text","text":"Y","marks":[{"type":"code"}]},{"type":"text","text":"''s domain."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Propagate","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"If "},{"type":"text","text":"X","marks":[{"type":"code"}]},{"type":"text","text":"''s domain shrank, re-queue every arc "},{"type":"text","text":"(Z, X)","marks":[{"type":"code"}]},{"type":"text","text":" for neighbours "},{"type":"text","text":"Z ≠ Y","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Stop","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"When the queue is empty (arc-consistent) — or a domain becomes empty (no solution)."}]}]}]}]}},"revision":1},{"id":"1a144df3-618e-79af-a061-7c0eaff635ad","type":"code","position":"a9","content":{"language":"python","code":"from collections import deque\n\ndef ac3(domains, constraints):\n    \"\"\"constraints: {(X, Y): predicate(x, y)} — both directions must be listed.\"\"\"\n    queue = deque(constraints)\n    while queue:\n        x, y = queue.popleft()\n        ok = constraints[(x, y)]\n        removed = {vx for vx in domains[x] if not any(ok(vx, vy) for vy in domains[y])}\n        if removed:\n            domains[x] -= removed\n            if not domains[x]:\n                return False                                  # inconsistency detected\n            queue.extend((z, w) for (z, w) in constraints if w == x and z != y)\n    return True\n\n# X < Y < Z with values 1..3: propagation alone solves it\ndoms = {v: {1, 2, 3} for v in \"XYZ\"}\nlt, gt = (lambda a, b: a < b), (lambda a, b: a > b)\nprint(ac3(doms, {(\"X\", \"Y\"): lt, (\"Y\", \"X\"): gt, (\"Y\", \"Z\"): lt, (\"Z\", \"Y\"): gt}), doms)   # True {''X'': {1}, ''Y'': {2}, ''Z'': {3}}\n\n# Australia after WA = red, Q = green: forward checking leaves NT = SA = {blue} and doesn''t notice…\nedges = [(\"WA\", \"NT\"), (\"WA\", \"SA\"), (\"NT\", \"SA\"), (\"NT\", \"Q\"), (\"SA\", \"Q\"), (\"SA\", \"NSW\"),\n         (\"SA\", \"V\"), (\"Q\", \"NSW\"), (\"NSW\", \"V\")]\nne = lambda a, b: a != b\ncons = {**{(a, b): ne for a, b in edges}, **{(b, a): ne for a, b in edges}}\ndoms = {v: {\"red\", \"green\", \"blue\"} for v in [\"WA\", \"NT\", \"SA\", \"Q\", \"NSW\", \"V\", \"T\"]}\ndoms[\"WA\"], doms[\"Q\"] = {\"red\"}, {\"green\"}\nprint(ac3(doms, cons))       # False ← …AC-3 proves there is no solution with this partial assignment","filename":"Python"},"revision":1},{"id":"5d1a2f77-7614-7ebc-b690-d2c3451a7bee","type":"text","position":"aA","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"AC-3 runs in "},{"type":"text","text":"O(c·d³)","marks":[{"type":"code"}]},{"type":"text","text":" for "},{"type":"text","text":"c","marks":[{"type":"code"}]},{"type":"text","text":" arcs and domain size "},{"type":"text","text":"d","marks":[{"type":"code"}]},{"type":"text","text":". Arc consistency alone doesn''t always find a solution (map colouring with 2 colours on a triangle stays arc-consistent), but combined with search it removes most dead ends early."}]}]}},"revision":1},{"id":"f391f752-4232-7e1c-8237-8db729d99354","type":"heading","position":"aB","content":{"level":1,"content":[{"type":"text","text":"Local search for CSPs: min-conflicts"}]},"revision":1},{"id":"e13ab454-64b1-7d87-b916-63136068c651","type":"text","position":"aC","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Start from a complete (inconsistent) assignment; repeatedly pick a conflicted variable and give it the value with the "},{"type":"text","text":"fewest conflicts","marks":[{"type":"bold"}]},{"type":"text","text":". Remarkably effective on large, loosely constrained problems — started from a greedy initial assignment it solves the million-queens problem in about 50 steps on average, and it is used for real-time rescheduling."}]}]}},"revision":1},{"id":"b6eb5a9c-b747-7b85-8601-2d3841aab3fd","type":"code","position":"aD","content":{"language":"python","code":"import random\n\ndef min_conflicts(n, max_steps=1000):\n    rows = [random.randrange(n) for _ in range(n)]\n    def conflicts(c, r):\n        return sum(1 for c2 in range(n) if c2 != c and (rows[c2] == r or abs(rows[c2] - r) == abs(c2 - c)))\n    for step in range(max_steps):\n        bad = [c for c in range(n) if conflicts(c, rows[c])]\n        if not bad:\n            return rows, step\n        c = random.choice(bad)\n        rows[c] = min(range(n), key=lambda r: (conflicts(c, r), random.random()))   # random tie-break\n    return None, max_steps\n\nrandom.seed(0)\nrows, steps = min_conflicts(40)\nprint(steps)     # 152 ← steps to solve 40-queens from a random start","filename":"Python"},"revision":1},{"id":"48c874dd-32b1-7336-8d34-3c7b41ef8bd9","type":"heading","position":"aE","content":{"level":1,"content":[{"type":"text","text":"Exploiting problem structure"}]},"revision":1},{"id":"9cd20ff9-fdd0-786a-b03e-5deea853fa0d","type":"table","position":"aF","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Structure"}],[{"type":"text","text":"Technique"}],[{"type":"text","text":"Cost"}]],[[{"type":"text","text":"Independent sub-problems (Tasmania)"}],[{"type":"text","text":"Solve connected components separately"}],[{"type":"text","text":"O(dᶜ · n/c)","marks":[{"type":"code"}]},{"type":"text","text":" instead of "},{"type":"text","text":"O(dⁿ)","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Tree-structured constraint graph"}],[{"type":"text","text":"Order topologically, make arcs consistent backwards, assign forwards"}],[{"type":"text","text":"O(n·d²)","marks":[{"type":"code"}]},{"type":"text","text":" — linear in "},{"type":"text","text":"n","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Nearly a tree"}],[{"type":"text","text":"Cutset conditioning","marks":[{"type":"bold"}]},{"type":"text","text":": assign a small cycle cutset, solve the remaining tree"}],[{"type":"text","text":"O(dᶜ · (n − c)·d²)","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Symmetric values"}],[{"type":"text","text":"Symmetry-breaking constraints (e.g. NT < SA < WA)"}],[{"type":"text","text":"Removes equivalent solutions"}]]]},"revision":1},{"id":"ae9aa10f-61fa-7aeb-8c3e-67025732ff10","type":"question","position":"aG","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Explain MRV and LCV — why is one ''fail first'' and the other ''fail last''?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"MRV picks the variable with the fewest legal values: every variable must be assigned eventually, so discovering a dead end early saves work. LCV orders the chosen variable''s values so the one that leaves neighbours the most options comes first: we only need one solution, so try the value most likely to succeed."}]}]}},"revision":1},{"id":"5ec10183-d530-7f10-8968-1c032a8ce224","type":"question","position":"aH","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Forward checking vs arc consistency?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Forward checking only prunes the domains of variables directly connected to the one just assigned. Arc consistency (AC-3) propagates further: every arc is revised until stable, catching conflicts between two "},{"type":"text","text":"unassigned","marks":[{"type":"italic"}]},{"type":"text","text":" variables — like NT and SA both reduced to {blue}."}]}]}},"revision":1},{"id":"09d9a7d2-481d-712a-93ac-1ed974c241e1","type":"question","position":"aI","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is the time complexity of AC-3?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"O(c·d³)","marks":[{"type":"code"}]},{"type":"text","text":": each of the "},{"type":"text","text":"c","marks":[{"type":"code"}]},{"type":"text","text":" arcs can be re-queued at most "},{"type":"text","text":"d","marks":[{"type":"code"}]},{"type":"text","text":" times (once per deleted value), and revising an arc costs "},{"type":"text","text":"O(d²)","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
