  ('edd0185c-f885-7c44-8c37-ac5570001ed5', 'a4', 'callout', '{"variant":"note","title":"Arc consistency","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Arc "},{"type":"text","text":"X → Y","marks":[{"type":"code"}]},{"type":"text","text":" is consistent if every value of "},{"type":"text","text":"X","marks":[{"type":"code"}]},{"type":"text","text":" has "},{"type":"text","text":"some","marks":[{"type":"italic"}]},{"type":"text","text":" supporting value in "},{"type":"text","text":"Y","marks":[{"type":"code"}]},{"type":"text","text":". AC-3 enforces this for all arcs, propagating deletions until nothing changes."}]}]}}'),
  ('bb0bfefc-7e55-73e6-ab89-1af770e6c462', 'a5', 'callout', '{"variant":"note","title":"MAC","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Maintaining arc consistency","marks":[{"type":"italic"}]},{"type":"text","text":": run AC-3 after every assignment during backtracking — stronger than forward checking."}]}]}}'),
  ('3f45c182-5b78-750b-a7c6-13d0b71b9f47', 'a6', 'code', '{"language":"python","code":"def solve(n, mrv=False, forward_check=False):\n    nodes = 0\n    def backtrack(assign, domains):\n        nonlocal nodes\n        if len(assign) == n:\n            return dict(assign)\n        free = [c for c in range(n) if c not in assign]\n        var = min(free, key=lambda c: len(domains[c])) if mrv else free[0]\n        for row in sorted(domains[var]):\n            if any(row == r or abs(row - r) == abs(var - c) for c, r in assign.items()):\n                continue\n            nodes += 1\n            assign[var] = row\n            new = domains\n            if forward_check:              # prune neighbours'' domains; empty domain → dead end\n                new = {c: d if c in assign else {x for x in d if x != row and abs(x - row) != abs(c - var)}\n                       for c, d in domains.items()}\n            if all(new[c] for c in new if c not in assign) and (res := backtrack(assign, new)):\n                return res\n            del assign[var]\n        return None\n    backtrack({}, {c: set(range(n)) for c in range(n)})\n    return nodes\n\nprint(solve(16))                                  # 10052 ← plain backtracking\nprint(solve(16, forward_check=True))              # 7560\nprint(solve(16, mrv=True, forward_check=True))    # 44 ← MRV + forward checking","filename":"Python"}'),
  ('4a07ddb3-ee6f-7c85-9bb1-3ce64a8bf9b3', 'a7', 'heading', '{"level":1,"content":[{"type":"text","text":"AC-3"}]}'),
  ('92e3c603-9136-708a-abd0-047138baa337', 'a8', 'text', '{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Queue every arc","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"For each binary constraint between X and Y add both arcs "},{"type":"text","text":"(X, Y)","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"(Y, X)","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Revise","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Pop an arc "},{"type":"text","text":"(X, Y)","marks":[{"type":"code"}]},{"type":"text","text":"; delete each value of "},{"type":"text","text":"X","marks":[{"type":"code"}]},{"type":"text","text":" that has no compatible value in "},{"type":"text","text":"Y","marks":[{"type":"code"}]},{"type":"text","text":"''s domain."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Propagate","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"If "},{"type":"text","text":"X","marks":[{"type":"code"}]},{"type":"text","text":"''s domain shrank, re-queue every arc "},{"type":"text","text":"(Z, X)","marks":[{"type":"code"}]},{"type":"text","text":" for neighbours "},{"type":"text","text":"Z ≠ Y","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Stop","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"When the queue is empty (arc-consistent) — or a domain becomes empty (no solution)."}]}]}]}]}}'),
  ('1a144df3-618e-79af-a061-7c0eaff635ad', 'a9', 'code', '{"language":"python","code":"from collections import deque\n\ndef ac3(domains, constraints):\n    \"\"\"constraints: {(X, Y): predicate(x, y)} — both directions must be listed.\"\"\"\n    queue = deque(constraints)\n    while queue:\n        x, y = queue.popleft()\n        ok = constraints[(x, y)]\n        removed = {vx for vx in domains[x] if not any(ok(vx, vy) for vy in domains[y])}\n        if removed:\n            domains[x] -= removed\n            if not domains[x]:\n                return False                                  # inconsistency detected\n            queue.extend((z, w) for (z, w) in constraints if w == x and z != y)\n    return True\n\n# X < Y < Z with values 1..3: propagation alone solves it\ndoms = {v: {1, 2, 3} for v in \"XYZ\"}\nlt, gt = (lambda a, b: a < b), (lambda a, b: a > b)\nprint(ac3(doms, {(\"X\", \"Y\"): lt, (\"Y\", \"X\"): gt, (\"Y\", \"Z\"): lt, (\"Z\", \"Y\"): gt}), doms)   # True {''X'': {1}, ''Y'': {2}, ''Z'': {3}}\n\n# Australia after WA = red, Q = green: forward checking leaves NT = SA = {blue} and doesn''t notice…\nedges = [(\"WA\", \"NT\"), (\"WA\", \"SA\"), (\"NT\", \"SA\"), (\"NT\", \"Q\"), (\"SA\", \"Q\"), (\"SA\", \"NSW\"),\n         (\"SA\", \"V\"), (\"Q\", \"NSW\"), (\"NSW\", \"V\")]\nne = lambda a, b: a != b\ncons = {**{(a, b): ne for a, b in edges}, **{(b, a): ne for a, b in edges}}\ndoms = {v: {\"red\", \"green\", \"blue\"} for v in [\"WA\", \"NT\", \"SA\", \"Q\", \"NSW\", \"V\", \"T\"]}\ndoms[\"WA\"], doms[\"Q\"] = {\"red\"}, {\"green\"}\nprint(ac3(doms, cons))       # False ← …AC-3 proves there is no solution with this partial assignment","filename":"Python"}'),
