SELECT '1ab52bde-f443-7390-9541-c1b1e71f8232', '3908c556-6f3b-7e76-9235-a4de45b1fdaa', 1, 'PUBLISHED', 'First-Order Logic & Unification', '[{"id":"7262619f-3823-7aa1-bd71-dc518af08770","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Propositional logic needs a separate symbol for every fact. First-order logic (FOL) adds "},{"type":"text","text":"objects, relations, functions and quantifiers","marks":[{"type":"bold"}]},{"type":"text","text":", so one sentence can say something about "},{"type":"text","text":"all","marks":[{"type":"italic"}]},{"type":"text","text":" objects — “every king is a person”."}]}]}},"revision":1},{"id":"f9dd7912-ae13-7208-9e4f-eec7db2d617b","type":"table","position":"a1","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Element"}],[{"type":"text","text":"Examples"}],[{"type":"text","text":"Denotes"}]],[[{"type":"text","text":"Constant symbols"}],[{"type":"text","text":"John","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"Richard","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"2","marks":[{"type":"code"}]}],[{"type":"text","text":"Objects"}]],[[{"type":"text","text":"Predicate symbols"}],[{"type":"text","text":"King(x)","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"Brother(x, y)","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":">","marks":[{"type":"code"}]}],[{"type":"text","text":"Relations (true/false)"}]],[[{"type":"text","text":"Function symbols"}],[{"type":"text","text":"LeftLeg(x)","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"Mother(x)","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"+","marks":[{"type":"code"}]}],[{"type":"text","text":"Functions returning objects"}]],[[{"type":"text","text":"Variables"}],[{"type":"text","text":"x","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"y","marks":[{"type":"code"}]}],[{"type":"text","text":"Range over objects"}]],[[{"type":"text","text":"Quantifiers"}],[{"type":"text","text":"∀x","marks":[{"type":"code"}]},{"type":"text","text":" (for all), "},{"type":"text","text":"∃x","marks":[{"type":"code"}]},{"type":"text","text":" (there exists)"}],[{"type":"text","text":"Generality"}]],[[{"type":"text","text":"Equality"}],[{"type":"text","text":"Father(John) = Henry","marks":[{"type":"code"}]}],[{"type":"text","text":"Two terms name the same object"}]]]},"revision":1},{"id":"4a80060e-2bb7-7805-a3ec-42b9ab21ea38","type":"heading","position":"a2","content":{"level":1,"content":[{"type":"text","text":"Translating English"}]},"revision":1},{"id":"4bf81385-c752-7e0e-a4f9-e5b8b0ef4939","type":"table","position":"a3","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"English"}],[{"type":"text","text":"First-order logic"}]],[[{"type":"text","text":"All kings are persons"}],[{"type":"text","text":"∀x King(x) ⇒ Person(x)","marks":[{"type":"code"}]}]],[[{"type":"text","text":"King John has a crown on his head"}],[{"type":"text","text":"∃x Crown(x) ∧ OnHead(x, John)","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Everybody loves somebody"}],[{"type":"text","text":"∀x ∃y Loves(x, y)","marks":[{"type":"code"}]}]],[[{"type":"text","text":"There is someone who is loved by everyone"}],[{"type":"text","text":"∃y ∀x Loves(x, y)","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Nobody likes taxes"}],[{"type":"text","text":"¬∃x Likes(x, Taxes)","marks":[{"type":"code"}]},{"type":"text","text":" ≡ "},{"type":"text","text":"∀x ¬Likes(x, Taxes)","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Brothers are siblings"}],[{"type":"text","text":"∀x, y Brother(x, y) ⇒ Sibling(x, y)","marks":[{"type":"code"}]}]]]},"revision":1},{"id":"0ab03d0b-51d2-7641-a3b8-80beaf335e0f","type":"callout","position":"a4","content":{"variant":"tip","title":"Do","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Pair "},{"type":"text","text":"∀","marks":[{"type":"code"}]},{"type":"text","text":" with "},{"type":"text","text":"⇒","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"∃","marks":[{"type":"code"}]},{"type":"text","text":" with "},{"type":"text","text":"∧","marks":[{"type":"code"}]},{"type":"text","text":": "},{"type":"text","text":"∀x King(x) ⇒ Person(x)","marks":[{"type":"code"}]},{"type":"text","text":"; "},{"type":"text","text":"∃x Crown(x) ∧ OnHead(x, John)","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"63879902-7124-7a1b-9f82-b96045081377","type":"callout","position":"a5","content":{"variant":"danger","title":"Avoid","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"∀x King(x) ∧ Person(x)","marks":[{"type":"code"}]},{"type":"text","text":" (says "},{"type":"text","text":"everything","marks":[{"type":"italic"}]},{"type":"text","text":" is a king) or "},{"type":"text","text":"∃x Crown(x) ⇒ OnHead(x, John)","marks":[{"type":"code"}]},{"type":"text","text":" (true as soon as anything is not a crown)."}]}]}},"revision":1},{"id":"c05bc148-ffe9-7e29-8245-c18c2997f0a9","type":"callout","position":"a6","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Quantifier order matters: "},{"type":"text","text":"∀x ∃y Loves(x, y)","marks":[{"type":"code"}]},{"type":"text","text":" (everyone loves someone, maybe different people) is much weaker than "},{"type":"text","text":"∃y ∀x Loves(x, y)","marks":[{"type":"code"}]},{"type":"text","text":" (one person loved by all). Duality: "},{"type":"text","text":"¬∀x P ≡ ∃x ¬P","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"¬∃x P ≡ ∀x ¬P","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"bb321785-6f30-7676-a1cf-bef1b0e5c79c","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"Unification"}]},"revision":1},{"id":"356e234d-8974-7920-92ce-7dc4b8a68a23","type":"callout","position":"a8","content":{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Unification","marks":[{"type":"bold"}]},{"type":"text","text":" — finding a substitution θ that makes two expressions identical: "},{"type":"text","text":"Unify(p, q) = θ","marks":[{"type":"code"}]},{"type":"text","text":" where "},{"type":"text","text":"Subst(θ, p) = Subst(θ, q)","marks":[{"type":"code"}]},{"type":"text","text":". The "},{"type":"text","text":"most general unifier","marks":[{"type":"bold"}]},{"type":"text","text":" (MGU) commits to as little as possible."}]}]}},"revision":1},{"id":"51fef333-387a-744a-b9bd-adf199f7f4c1","type":"code","position":"a9","content":{"language":"python","code":"def is_var(t):\n    return isinstance(t, str) and t[0].islower()        # variables: lowercase; constants: Capitalised\n\ndef substitute(t, theta):\n    if is_var(t):\n        return substitute(theta[t], theta) if t in theta else t\n    if isinstance(t, tuple):\n        return tuple(substitute(a, theta) for a in t)\n    return t\n\ndef occurs(var, t, theta):\n    t = substitute(t, theta)\n    return t == var or (isinstance(t, tuple) and any(occurs(var, a, theta) for a in t))\n\ndef unify(x, y, theta):\n    if theta is None:\n        return None\n    x, y = substitute(x, theta), substitute(y, theta)\n    if x == y:\n        return theta\n    if is_var(x):\n        return None if occurs(x, y, theta) else {**theta, x: y}      # occurs check\n    if is_var(y):\n        return unify(y, x, theta)\n    if isinstance(x, tuple) and isinstance(y, tuple) and len(x) == len(y):\n        for a, b in zip(x, y):\n            theta = unify(a, b, theta)\n        return theta\n    return None\n\ndef show(theta):\n    return theta if theta is None else {v: substitute(v, theta) for v in theta}\n\nq = (\"Knows\", \"John\", \"x\")\nprint(show(unify(q, (\"Knows\", \"John\", \"Jane\"), {})))               # {''x'': ''Jane''}\nprint(show(unify(q, (\"Knows\", \"y\", \"Bill\"), {})))                  # {''y'': ''John'', ''x'': ''Bill''}\nprint(show(unify(q, (\"Knows\", \"y\", (\"Mother\", \"y\")), {})))         # {''y'': ''John'', ''x'': (''Mother'', ''John'')}\nprint(show(unify(q, (\"Knows\", \"x\", \"Elizabeth\"), {})))             # None ← x can''t be John and Elizabeth\nprint(show(unify(q, (\"Knows\", \"x2\", \"Elizabeth\"), {})))            # {''x2'': ''John'', ''x'': ''Elizabeth''} ← fixed by standardising apart","filename":"Python"},"revision":1},{"id":"01a33b7b-2981-725f-bd1c-33b07d637956","type":"heading","position":"aA","content":{"level":1,"content":[{"type":"text","text":"Inference in FOL"}]},"revision":1},{"id":"f98969f3-1039-7f86-9af4-3adafd43093c","type":"text","position":"aB","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Generalised modus ponens","marks":[{"type":"bold"}]},{"type":"text","text":" lifts modus ponens with unification: from "},{"type":"text","text":"King(John)","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"Greedy(y)","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"∀x King(x) ∧ Greedy(x) ⇒ Evil(x)","marks":[{"type":"code"}]},{"type":"text","text":", unify to "},{"type":"text","text":"θ = {x/John, y/John}","marks":[{"type":"code"}]},{"type":"text","text":" and infer "},{"type":"text","text":"Evil(John)","marks":[{"type":"code"}]},{"type":"text","text":" — only if "},{"type":"text","text":"Greedy(John)","marks":[{"type":"code"}]},{"type":"text","text":" also unifies. Forward chaining with it gives Datalog-style reasoning. The classic crime KB:"}]}]}},"revision":1},{"id":"3b6a00a5-4a2e-7112-bf65-682237f2e6d9","type":"code","position":"aC","content":{"language":"python","code":"FACTS = {(\"American\", \"West\"), (\"Missile\", \"M1\"), (\"Owns\", \"Nono\", \"M1\"), (\"Enemy\", \"Nono\", \"America\")}\nRULES = [\n    ([(\"American\", \"x\"), (\"Weapon\", \"y\"), (\"Sells\", \"x\", \"y\", \"z\"), (\"Hostile\", \"z\")], (\"Criminal\", \"x\")),\n    ([(\"Missile\", \"x\"), (\"Owns\", \"Nono\", \"x\")], (\"Sells\", \"West\", \"x\", \"Nono\")),\n    ([(\"Missile\", \"x\")], (\"Weapon\", \"x\")),\n    ([(\"Enemy\", \"x\", \"America\")], (\"Hostile\", \"x\")),\n]\n\ndef match(pattern, fact, theta):                   # one-way unification: variables only in the pattern\n    if len(pattern) != len(fact) or pattern[0] != fact[0]:\n        return None\n    theta = dict(theta)\n    for p, f in zip(pattern[1:], fact[1:]):\n        if p[0].islower():\n            if theta.setdefault(p, f) != f:\n                return None\n        elif p != f:\n            return None\n    return theta\n\ndef solutions(premises, facts, theta):\n    if not premises:\n        yield theta\n        return\n    for fact in sorted(facts):\n        t = match(premises[0], fact, theta)\n        if t is not None:\n            yield from solutions(premises[1:], facts, t)\n\ndef forward_chain(facts, rules):\n    facts, rounds = set(facts), []\n    while True:\n        new = {tuple(theta.get(a, a) for a in concl)\n               for prem, concl in rules for theta in solutions(prem, facts, {})} - facts\n        if not new:\n            return facts, rounds\n        rounds.append(sorted(new))\n        facts |= new\n\nfacts, rounds = forward_chain(FACTS, RULES)\nprint(rounds[0])                                   # [(''Hostile'', ''Nono''), (''Sells'', ''West'', ''M1'', ''Nono''), (''Weapon'', ''M1'')]\nprint(rounds[1])                                   # [(''Criminal'', ''West'')]\nprint((\"Criminal\", \"West\") in facts)               # True","filename":"Python"},"revision":1},{"id":"f893cd49-6c3b-7993-9e1f-0d5510ef88c9","type":"table","position":"aD","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Method"}],[{"type":"text","text":"How"}],[{"type":"text","text":"Used in"}]],[[{"type":"text","text":"Forward chaining"}],[{"type":"text","text":"Generalised modus ponens from facts until nothing new"}],[{"type":"text","text":"Datalog, production systems, deductive databases"}]],[[{"type":"text","text":"Backward chaining"}],[{"type":"text","text":"Depth-first from the goal, unifying with rule heads"}],[{"type":"text","text":"Prolog","marks":[{"type":"bold"}]},{"type":"text","text":", logic programming"}]],[[{"type":"text","text":"Resolution"}],[{"type":"text","text":"Convert to clausal form (Skolemise ∃), resolve with unification"}],[{"type":"text","text":"Automated theorem provers (Vampire, E)"}]]]},"revision":1},{"id":"e56cd7b0-4728-7d02-b818-6a200e08f41b","type":"callout","position":"aE","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"FOL entailment is only "},{"type":"text","text":"semi-decidable","marks":[{"type":"bold"}]},{"type":"text","text":": if "},{"type":"text","text":"KB ⊨ α","marks":[{"type":"code"}]},{"type":"text","text":" a complete procedure will eventually say so, but if not it may run forever. That''s why practical systems restrict the language (Horn clauses, Datalog, description logics)."}]}]}},"revision":1},{"id":"881421be-6c16-7b05-abf5-655ea2c4e11b","type":"question","position":"aF","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why is first-order logic more expressive than propositional logic?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"It has objects, relations, functions and quantifiers, so general rules ("},{"type":"text","text":"∀x King(x) ⇒ Person(x)","marks":[{"type":"code"}]},{"type":"text","text":") replace one propositional symbol per individual fact. It can describe infinite domains that propositional logic cannot."}]}]}},"revision":1},{"id":"a46e5821-9016-73c3-bb22-a797aa308677","type":"question","position":"aG","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What does unification do? Give an example."}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"It finds the most general substitution making two expressions identical. "},{"type":"text","text":"Knows(John, x)","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"Knows(y, Mother(y))","marks":[{"type":"code"}]},{"type":"text","text":" unify with "},{"type":"text","text":"{y/John, x/Mother(John)}","marks":[{"type":"code"}]},{"type":"text","text":". It''s the core step of generalised modus ponens, Prolog and resolution."}]}]}},"revision":1},{"id":"c2b0f0ff-3432-72d5-9ad4-79551a8db81a","type":"question","position":"aH","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is the occurs check?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Before binding a variable "},{"type":"text","text":"x","marks":[{"type":"code"}]},{"type":"text","text":" to a term, check that "},{"type":"text","text":"x","marks":[{"type":"code"}]},{"type":"text","text":" does not occur inside that term — otherwise "},{"type":"text","text":"x = F(x)","marks":[{"type":"code"}]},{"type":"text","text":" would create an infinite term. Prolog omits it by default for speed."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
WHERE EXISTS (SELECT 1 FROM "notes"."Note" n WHERE n.id = '3908c556-6f3b-7e76-9235-a4de45b1fdaa' AND n."ownerId" = '019a118c-f480-7000-8000-000000000001' AND n."publishedVersionId" IS NULL AND n.visibility = 'PRIVATE' AND n."deletedAt" IS NULL AND n."draftUpdatedAt" = TIMESTAMPTZ '2026-10-07 03:23:53+00')
