  ('c05bc148-ffe9-7e29-8245-c18c2997f0a9', 'a6', 'callout', '{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Quantifier order matters: "},{"type":"text","text":"∀x ∃y Loves(x, y)","marks":[{"type":"code"}]},{"type":"text","text":" (everyone loves someone, maybe different people) is much weaker than "},{"type":"text","text":"∃y ∀x Loves(x, y)","marks":[{"type":"code"}]},{"type":"text","text":" (one person loved by all). Duality: "},{"type":"text","text":"¬∀x P ≡ ∃x ¬P","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"¬∃x P ≡ ∀x ¬P","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}'),
