  SELECT 1 FROM "notes"."Note" n
  WHERE n.id = '47748d51-304b-709b-be30-977d8e0dcef8' AND n.visibility = 'PUBLIC' AND n."publishedVersionId" = '2dbff371-7be2-7da8-b166-459a6d12efe1' AND n."deletedAt" IS NULL
)
