INSERT INTO "notes"."NoteVersion" ("id", "noteId", "number", "kind", "title", "cards", "createdById", "createdAt")
SELECT '436d9ab5-161c-7ce4-98ec-4dab97deef90', '1433cd31-636d-7937-a4f8-c8ad282ce60b', 1, 'PUBLISHED', 'Designing Heuristics', '[{"id":"8cef9c69-15af-777d-a5ea-640f4b2ddaae","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A* is only as good as its heuristic. Good heuristics are admissible, as close to the true cost as possible, and cheap to compute — and the standard way to invent one is to "},{"type":"text","text":"relax","marks":[{"type":"bold"}]},{"type":"text","text":" the problem."}]}]}},"revision":1},{"id":"f2dd6804-706b-7bef-bba0-7daab1c29577","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Two classic 8-puzzle heuristics"}]},"revision":1},{"id":"e3362613-5a4f-7475-8198-d33cea3cf937","type":"table","position":"a2","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Heuristic"}],[{"type":"text","text":"Definition"}],[{"type":"text","text":"Relaxed problem it solves exactly"}]],[[{"type":"text","text":"h₁","marks":[{"type":"code"}]},{"type":"text","text":" — misplaced tiles"}],[{"type":"text","text":"Number of tiles not in their goal square"}],[{"type":"text","text":"A tile can jump "},{"type":"text","text":"anywhere","marks":[{"type":"italic"}]},{"type":"text","text":" in one move"}]],[[{"type":"text","text":"h₂","marks":[{"type":"code"}]},{"type":"text","text":" — Manhattan distance"}],[{"type":"text","text":"Sum over tiles of |row − goal row| + |col − goal col|"}],[{"type":"text","text":"A tile can move to "},{"type":"text","text":"any adjacent","marks":[{"type":"italic"}]},{"type":"text","text":" square, even an occupied one"}]]]},"revision":1},{"id":"6079b77d-46ac-7b93-9ad1-9078567c985c","type":"text","position":"a3","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A relaxed problem has "},{"type":"text","text":"more","marks":[{"type":"italic"}]},{"type":"text","text":" actions, so its optimal cost can only be lower — that is why a heuristic derived from a relaxation is automatically admissible (and consistent)."}]}]}},"revision":1},{"id":"ee889b2a-5ffa-73b9-9e7b-487c6ff2e114","type":"code","position":"a4","content":{"language":"python","code":"import heapq\n\nGOAL = (0, 1, 2, 3, 4, 5, 6, 7, 8)         # 0 = blank\n\ndef h1(s):                                  # misplaced tiles (the blank doesn''t count)\n    return sum(1 for i, tile in enumerate(s) if tile and tile != i)\n\ndef h2(s):                                  # Manhattan distance\n    return sum(abs(i // 3 - t // 3) + abs(i % 3 - t % 3) for i, t in enumerate(s) if t)\n\ndef neighbours(s):\n    i = s.index(0)\n    r, c = divmod(i, 3)\n    for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):\n        if 0 <= r + dr < 3 and 0 <= c + dc < 3:\n            j = (r + dr) * 3 + c + dc\n            t = list(s)\n            t[i], t[j] = t[j], t[i]\n            yield tuple(t)\n\ndef astar(start, h):\n    frontier, best, expanded = [(h(start), 0, start)], {start: 0}, 0\n    while frontier:\n        f, g, s = heapq.heappop(frontier)\n        if s == GOAL:\n            return g, expanded\n        if g > best[s]:\n            continue\n        expanded += 1\n        for t in neighbours(s):\n            if g + 1 < best.get(t, 99):\n                best[t] = g + 1\n                heapq.heappush(frontier, (g + 1 + h(t), g + 1, t))\n\nstart = (7, 2, 4,\n         5, 0, 6,\n         8, 3, 1)\nprint(h1(start), h2(start))                 # 8 18 ← true cost is 26\nprint(astar(start, lambda s: 0))            # (26, 162240) ← h = 0 is uniform-cost search\nprint(astar(start, h1))                     # (26, 44988)\nprint(astar(start, h2))                     # (26, 4085)","filename":"Python"},"revision":1},{"id":"b992c022-79b6-7198-88d9-b3256785ac45","type":"text","position":"a5","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"All three find the optimal 26-move solution; Manhattan distance does it with roughly "},{"type":"text","text":"40× fewer","marks":[{"type":"bold"}]},{"type":"text","text":" expansions than no heuristic."}]}]}},"revision":1},{"id":"218cbca6-9bd8-727c-87a8-ea1e5d088ce1","type":"heading","position":"a6","content":{"level":1,"content":[{"type":"text","text":"Dominance and the effective branching factor"}]},"revision":1},{"id":"594ab3dd-265a-743c-9014-428ebf571eb8","type":"callout","position":"a7","content":{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Dominance","marks":[{"type":"bold"}]},{"type":"text","text":" — if "},{"type":"text","text":"h₂(n) ≥ h₁(n)","marks":[{"type":"code"}]},{"type":"text","text":" for every "},{"type":"text","text":"n","marks":[{"type":"code"}]},{"type":"text","text":" and both are admissible, "},{"type":"text","text":"h₂","marks":[{"type":"code"}]},{"type":"text","text":" "},{"type":"text","text":"dominates","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"h₁","marks":[{"type":"code"}]},{"type":"text","text":" and A* with "},{"type":"text","text":"h₂","marks":[{"type":"code"}]},{"type":"text","text":" never expands more nodes. Larger is better — as long as it stays admissible."}]}]}},"revision":1},{"id":"42251b88-1034-7dff-9770-01cfcfe507be","type":"text","position":"a8","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"To compare heuristics independently of problem size, compute the "},{"type":"text","text":"effective branching factor","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"b*","marks":[{"type":"code"}]},{"type":"text","text":": the branching factor a uniform tree of depth "},{"type":"text","text":"d","marks":[{"type":"code"}]},{"type":"text","text":" would need to contain the "},{"type":"text","text":"N","marks":[{"type":"code"}]},{"type":"text","text":" nodes A* expanded. Close to 1 is ideal."}]},{"type":"paragraph","content":[{"type":"text","text":"N + 1 = 1 + b* + (b*)² + … + (b*)ᵈ","marks":[{"type":"code"}]}]}]}},"revision":1},{"id":"5d8c7a38-db52-76ea-a7d2-febe7bd57c97","type":"code","position":"a9","content":{"language":"python","code":"def effective_branching(n_expanded, depth):\n    lo, hi = 1.0, 10.0\n    for _ in range(60):                        # bisection\n        b = (lo + hi) / 2\n        total = sum(b ** i for i in range(depth + 1))\n        lo, hi = (b, hi) if total < n_expanded + 1 else (lo, b)\n    return round(b, 2)\n\nprint(effective_branching(162240, 26))     # 1.52 ← no heuristic\nprint(effective_branching(44988, 26))      # 1.44 ← misplaced tiles\nprint(effective_branching(4085, 26))       # 1.3 ← Manhattan distance","filename":"Python"},"revision":1},{"id":"a3f5ff14-5e24-7453-afd9-94a8c589f515","type":"heading","position":"aA","content":{"level":1,"content":[{"type":"text","text":"Recipes for heuristics"}]},"revision":1},{"id":"4b82728e-4626-7369-afa2-99dd57db63b7","type":"callout","position":"aB","content":{"variant":"note","title":"Relax the problem","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Remove constraints until the problem is easy to solve exactly: straight-line distance (ignore roads), Manhattan distance (ignore other tiles), ignore-preconditions in planning."}]}]}},"revision":1},{"id":"f6304797-5529-77b9-845a-6dfa03ea27b3","type":"callout","position":"aC","content":{"variant":"note","title":"Max of admissible heuristics","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"h(n) = max(h₁(n), …, hₖ(n))","marks":[{"type":"code"}]},{"type":"text","text":" is admissible and dominates each component — use it when no single one is best everywhere."}]}]}},"revision":1},{"id":"32ac97ff-8a3a-7004-94e5-fd18506ea3b9","type":"callout","position":"aD","content":{"variant":"note","title":"Pattern databases","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Precompute exact costs for a sub-problem (e.g. tiles 1–4 only) for every configuration and look them up. Disjoint patterns can be "},{"type":"text","text":"added","marks":[{"type":"italic"}]},{"type":"text","text":". Solves the 15-puzzle and Rubik''s cube quickly."}]}]}},"revision":1},{"id":"672de642-8a33-7ef3-bebd-3d8829fca1c1","type":"callout","position":"aE","content":{"variant":"note","title":"Learn a heuristic","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Train a model to predict cost-to-go from features of a state (AlphaGo''s value network is a learned evaluation). Fast, but no admissibility guarantee."}]}]}},"revision":1},{"id":"5789d6ea-21f1-72e3-96e3-c3a3bf17604a","type":"table","position":"aF","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Domain"}],[{"type":"text","text":"Admissible heuristic"}]],[[{"type":"text","text":"Grid, 4-way moves"}],[{"type":"text","text":"Manhattan distance "},{"type":"text","text":"|dx| + |dy|","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Grid, 8-way moves (diagonal cost √2)"}],[{"type":"text","text":"Octile distance "},{"type":"text","text":"max(dx, dy) + (√2 − 1)·min(dx, dy)","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Any-angle / road maps"}],[{"type":"text","text":"Euclidean (straight-line) distance"}]],[[{"type":"text","text":"Travelling salesperson"}],[{"type":"text","text":"Cost of a minimum spanning tree of unvisited cities"}]]]},"revision":1},{"id":"f7259b22-c778-706f-be09-867936f38904","type":"callout","position":"aG","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Manhattan distance is "},{"type":"text","text":"not","marks":[{"type":"bold"}]},{"type":"text","text":" admissible on an 8-connected grid — one diagonal step (cost √2 ≈ 1.41) covers Manhattan distance 2, so it overestimates."}]}]}},"revision":1},{"id":"8edddb41-9553-742f-967a-6d85bf071af0","type":"question","position":"aH","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What makes a heuristic admissible? Give one for the 8-puzzle."}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"It never overestimates the true cost to the goal. Manhattan distance: every tile must move at least its row and column offset, one square per move, so the sum can''t exceed the real number of moves."}]}]}},"revision":1},{"id":"470faeb4-e32a-75fe-b2d2-35b0627c852a","type":"question","position":"aI","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Admissible vs consistent?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Admissible: "},{"type":"text","text":"h(n) ≤ h*(n)","marks":[{"type":"code"}]},{"type":"text","text":". Consistent: "},{"type":"text","text":"h(n) ≤ c(n, n′) + h(n′)","marks":[{"type":"code"}]},{"type":"text","text":" for every edge — a stronger condition that implies admissibility and guarantees "},{"type":"text","text":"f","marks":[{"type":"code"}]},{"type":"text","text":" is non-decreasing along paths, so graph-search A* never needs to re-open nodes."}]}]}},"revision":1},{"id":"971adf43-f885-76d5-8d47-ff9f7f1f9ce5","type":"question","position":"aJ","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"If h₂ dominates h₁, is h₂ always better?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"It never expands more nodes, but it may cost more to "},{"type":"text","text":"compute","marks":[{"type":"italic"}]},{"type":"text","text":" per node. The best heuristic balances accuracy against evaluation time."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
