INSERT INTO "notes"."NoteVersion" ("id", "noteId", "number", "kind", "title", "cards", "createdById", "createdAt")
SELECT '01905d0a-031d-7a4b-ae05-57fa24708fd7', 'aa5b2a91-1ca9-7ce5-af45-f0c4d1bce6a1', 1, 'PUBLISHED', 'Informed Search: Greedy & A*', '[{"id":"e7d7bf5a-26c7-7099-947c-a0e915260a6b","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Informed search uses a "},{"type":"text","text":"heuristic","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"h(n)","marks":[{"type":"code"}]},{"type":"text","text":" — an estimate of the cost from "},{"type":"text","text":"n","marks":[{"type":"code"}]},{"type":"text","text":" to the goal — to expand promising nodes first. A* combines the cost so far with the estimate to go, and is optimal when the heuristic never overestimates."}]}]}},"revision":1},{"id":"0cec06b0-c2a7-7559-9a0b-33ae61796440","type":"table","position":"a1","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Strategy"}],[{"type":"text","text":"Evaluation "},{"type":"text","text":"f(n)","marks":[{"type":"code"}]}],[{"type":"text","text":"Behaviour"}]],[[{"type":"text","text":"Uniform-cost"}],[{"type":"text","text":"g(n)","marks":[{"type":"code"}]}],[{"type":"text","text":"Cheapest-so-far — ignores the goal"}]],[[{"type":"text","text":"Greedy best-first","marks":[{"type":"bold"}]}],[{"type":"text","text":"h(n)","marks":[{"type":"code"}]}],[{"type":"text","text":"Whatever "},{"type":"text","text":"looks","marks":[{"type":"italic"}]},{"type":"text","text":" closest to the goal — fast, not optimal"}]],[[{"type":"text","text":"A","marks":[{"type":"bold"}]},{"type":"text","text":"*"}],[{"type":"text","text":"g(n) + h(n)","marks":[{"type":"code"}]}],[{"type":"text","text":"Cheapest estimated "},{"type":"text","text":"total","marks":[{"type":"italic"}]},{"type":"text","text":" path through "},{"type":"text","text":"n","marks":[{"type":"code"}]},{"type":"text","text":" — optimal with an admissible "},{"type":"text","text":"h","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Weighted A*"}],[{"type":"text","text":"g(n) + w·h(n)","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"w > 1","marks":[{"type":"code"}]}],[{"type":"text","text":"Faster, cost at most "},{"type":"text","text":"w ×","marks":[{"type":"code"}]},{"type":"text","text":" optimal"}]]]},"revision":1},{"id":"f178b4cf-bb58-79e6-a7f0-25e5b6d999ea","type":"text","position":"a2","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"f(n) = g(n) + h(n) g = cost from start to n, h = estimated cost from n to goal","marks":[{"type":"code"}]}]},{"type":"paragraph","content":[{"type":"text","text":"For route finding, the straight-line distance (SLD) to Bucharest is a natural heuristic — a road can''t be shorter than a straight line:"}]}]}},"revision":1},{"id":"55c79243-5692-77de-b0ec-d7a07ff8cc9c","type":"code","position":"a3","content":{"language":"python","code":"ROADS = \"\"\"Arad Zerind 75, Arad Sibiu 140, Arad Timisoara 118, Zerind Oradea 71, Oradea Sibiu 151,\nTimisoara Lugoj 111, Lugoj Mehadia 70, Mehadia Drobeta 75, Drobeta Craiova 120, Craiova Rimnicu 146,\nCraiova Pitesti 138, Sibiu Fagaras 99, Sibiu Rimnicu 80, Rimnicu Pitesti 97, Fagaras Bucharest 211,\nPitesti Bucharest 101, Bucharest Giurgiu 90, Bucharest Urziceni 85, Urziceni Hirsova 98,\nHirsova Eforie 86, Urziceni Vaslui 142, Vaslui Iasi 92, Iasi Neamt 87\"\"\"\ngraph = {}                                  # city -> {neighbour: road km}  (\"Rimnicu\" = Rimnicu Vilcea)\nfor road in ROADS.split(\",\"):\n    a, b, km = road.split()\n    graph.setdefault(a, {})[b] = int(km)\n    graph.setdefault(b, {})[a] = int(km)\n\nimport heapq\n\nSLD = {\"Arad\": 366, \"Bucharest\": 0, \"Craiova\": 160, \"Drobeta\": 242, \"Eforie\": 161, \"Fagaras\": 176,\n       \"Giurgiu\": 77, \"Hirsova\": 151, \"Iasi\": 226, \"Lugoj\": 244, \"Mehadia\": 241, \"Neamt\": 234,\n       \"Oradea\": 380, \"Pitesti\": 100, \"Rimnicu\": 193, \"Sibiu\": 253, \"Timisoara\": 329,\n       \"Urziceni\": 80, \"Vaslui\": 199, \"Zerind\": 374}\n\ndef best_first(start, goal, f):\n    frontier = [(f(0, start), 0, start, [start])]          # (priority, g, city, route)\n    best_g, expanded = {start: 0}, []\n    while frontier:\n        _, g, node, route = heapq.heappop(frontier)\n        if node == goal:\n            return route, g, expanded\n        if g > best_g[node]:\n            continue\n        expanded.append(node)\n        for nbr, km in graph[node].items():\n            g2 = g + km\n            if g2 < best_g.get(nbr, float(\"inf\")):\n                best_g[nbr] = g2\n                heapq.heappush(frontier, (f(g2, nbr), g2, nbr, route + [nbr]))\n\ngreedy = lambda g, city: SLD[city]              # f = h\nastar = lambda g, city: g + SLD[city]           # f = g + h\n\nroute, cost, expanded = best_first(\"Arad\", \"Bucharest\", greedy)\nprint(route, cost)       # [''Arad'', ''Sibiu'', ''Fagaras'', ''Bucharest''] 450\nprint(expanded)          # [''Arad'', ''Sibiu'', ''Fagaras'']\nroute, cost, expanded = best_first(\"Arad\", \"Bucharest\", astar)\nprint(route, cost)       # [''Arad'', ''Sibiu'', ''Rimnicu'', ''Pitesti'', ''Bucharest''] 418\nprint(expanded)          # [''Arad'', ''Sibiu'', ''Rimnicu'', ''Fagaras'', ''Pitesti'']","filename":"Python"},"revision":1},{"id":"f50dd3d5-21d5-777a-9799-4880d65a3155","type":"text","position":"a4","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Greedy heads for Fagaras because it is closest to Bucharest in a straight line, and ends up 32 km worse. A* expands Fagaras too, but when Bucharest appears with "},{"type":"text","text":"f = 450","marks":[{"type":"code"}]},{"type":"text","text":" it first expands Pitesti ("},{"type":"text","text":"f = 317 + 100 = 417","marks":[{"type":"code"}]},{"type":"text","text":") and finds the 418 km route. UCS needed 12 expansions for the same answer; A* needed 5."}]}]}},"revision":1},{"id":"7e3db32b-1e64-7ee7-bc7e-8ee9f30df76d","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"Why A* is optimal"}]},"revision":1},{"id":"8b3a9a9f-a41e-756a-bb3d-69c97c9da454","type":"callout","position":"a6","content":{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Admissible heuristic","marks":[{"type":"bold"}]},{"type":"text","text":" — never overestimates the true cost to reach the goal: "},{"type":"text","text":"h(n) ≤ h*(n)","marks":[{"type":"code"}]},{"type":"text","text":" for every "},{"type":"text","text":"n","marks":[{"type":"code"}]},{"type":"text","text":". It is "},{"type":"text","text":"optimistic","marks":[{"type":"italic"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"cdaef958-a889-7e9a-8887-26d661bdf55b","type":"callout","position":"a7","content":{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Consistent (monotone) heuristic","marks":[{"type":"bold"}]},{"type":"text","text":" — for every node "},{"type":"text","text":"n","marks":[{"type":"code"}]},{"type":"text","text":" and successor "},{"type":"text","text":"n′","marks":[{"type":"code"}]},{"type":"text","text":" via action "},{"type":"text","text":"a","marks":[{"type":"code"}]},{"type":"text","text":": "},{"type":"text","text":"h(n) ≤ c(n, a, n′) + h(n′)","marks":[{"type":"code"}]},{"type":"text","text":" — a triangle inequality. Along any path, "},{"type":"text","text":"f","marks":[{"type":"code"}]},{"type":"text","text":" never decreases. Every consistent heuristic is admissible."}]}]}},"revision":1},{"id":"6aff30de-faae-7622-8f46-da4211d009f3","type":"text","position":"a8","content":{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Admissible h","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"f(n) = g(n) + h(n)","marks":[{"type":"code"}]},{"type":"text","text":" never overestimates the cost of the best solution through "},{"type":"text","text":"n","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Suboptimal goal G₂ on the frontier","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"f(G₂) = g(G₂) > C*","marks":[{"type":"code"}]},{"type":"text","text":" because "},{"type":"text","text":"h(G₂) = 0","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Some node n on the optimal path is also on the frontier","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"f(n) ≤ C* < f(G₂)","marks":[{"type":"code"}]},{"type":"text","text":", so "},{"type":"text","text":"n","marks":[{"type":"code"}]},{"type":"text","text":" is expanded before "},{"type":"text","text":"G₂","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Conclusion","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"A* never pops a suboptimal goal before the optimal one. With graph search, consistency guarantees each state''s first expansion is via its cheapest path."}]}]}]}]}},"revision":1},{"id":"0f27afe7-d775-7a0c-8f86-c7477763432b","type":"table","position":"a9","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Property of A*"}],[{"type":"text","text":"Holds when"}]],[[{"type":"text","text":"Complete"}],[{"type":"text","text":"Finite branching and step costs ≥ "},{"type":"text","text":"ε > 0","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Optimal — tree search"}],[{"type":"text","text":"h","marks":[{"type":"code"}]},{"type":"text","text":" admissible"}]],[[{"type":"text","text":"Optimal — graph search (no re-opening)"}],[{"type":"text","text":"h","marks":[{"type":"code"}]},{"type":"text","text":" consistent"}]],[[{"type":"text","text":"Optimally efficient"}],[{"type":"text","text":"No other optimal algorithm using the same "},{"type":"text","text":"h","marks":[{"type":"code"}]},{"type":"text","text":" expands fewer nodes (up to ties)"}]],[[{"type":"text","text":"Space"}],[{"type":"text","text":"Exponential — keeps every generated node; this is A*''s real bottleneck"}]]]},"revision":1},{"id":"6425f163-af2f-7413-a3c9-dff87712cc3e","type":"callout","position":"aA","content":{"variant":"note","title":"IDA*","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Iterative deepening on "},{"type":"text","text":"f","marks":[{"type":"code"}]},{"type":"text","text":" instead of depth: each iteration''s cutoff is the smallest "},{"type":"text","text":"f","marks":[{"type":"code"}]},{"type":"text","text":" that exceeded the last one. Linear memory; good for puzzles with unit costs."}]}]}},"revision":1},{"id":"2ce1ba26-7c64-7aab-9970-197a20cf7789","type":"callout","position":"aB","content":{"variant":"note","title":"SMA* / memory-bounded","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Runs A* until memory is full, then drops the worst leaf and remembers its "},{"type":"text","text":"f","marks":[{"type":"code"}]},{"type":"text","text":" in the parent."}]}]}},"revision":1},{"id":"c048fb1f-e598-77cf-b7b2-0ff61100181b","type":"callout","position":"aC","content":{"variant":"note","title":"Weighted A*","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"f = g + w·h","marks":[{"type":"code"}]},{"type":"text","text":" with "},{"type":"text","text":"w > 1","marks":[{"type":"code"}]},{"type":"text","text":": expands far fewer nodes, solution cost ≤ "},{"type":"text","text":"w · C*","marks":[{"type":"code"}]},{"type":"text","text":". Common in games and robotics."}]}]}},"revision":1},{"id":"7dc36750-a945-7a08-aaf3-51a6528fba0e","type":"callout","position":"aD","content":{"variant":"note","title":"Greedy best-first","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"f = h","marks":[{"type":"code"}]},{"type":"text","text":". Often very fast, but not optimal and (tree search) not complete — it can loop."}]}]}},"revision":1},{"id":"0dda630d-414c-7559-b08b-adbeeab14017","type":"callout","position":"aE","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"An "},{"type":"text","text":"inadmissible","marks":[{"type":"bold"}]},{"type":"text","text":" heuristic (one that sometimes overestimates) can make A* skip the optimal path. And a heuristic that is admissible but "},{"type":"text","text":"inconsistent","marks":[{"type":"italic"}]},{"type":"text","text":" needs graph search that can re-open closed nodes — otherwise optimality is lost."}]}]}},"revision":1},{"id":"3899a4ed-62eb-73cb-9ace-02919d84c5a1","type":"question","position":"aF","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Explain A* and when it is optimal."}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A* is best-first search on "},{"type":"text","text":"f(n) = g(n) + h(n)","marks":[{"type":"code"}]},{"type":"text","text":", the estimated cost of the cheapest solution through "},{"type":"text","text":"n","marks":[{"type":"code"}]},{"type":"text","text":". It is optimal if "},{"type":"text","text":"h","marks":[{"type":"code"}]},{"type":"text","text":" is admissible (tree search) or consistent (graph search), and complete with positive step costs and finite branching."}]}]}},"revision":1},{"id":"b16efa80-b5db-79ea-aa70-6f1672ceace1","type":"question","position":"aG","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What happens to A* when h = 0? When h = h* exactly?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"h = 0","marks":[{"type":"code"}]},{"type":"text","text":" gives uniform-cost search (still optimal, but uninformed). With the perfect heuristic "},{"type":"text","text":"h = h*","marks":[{"type":"code"}]},{"type":"text","text":", A* expands only nodes on an optimal path — straight to the goal."}]}]}},"revision":1},{"id":"98c29e76-f768-7309-8757-4baa02433506","type":"question","position":"aH","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why does greedy best-first search fail to be optimal?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"It ignores the cost already paid ("},{"type":"text","text":"g","marks":[{"type":"code"}]},{"type":"text","text":"), so it follows whatever looks closest even when that route is expensive — Arad → Sibiu → Fagaras → Bucharest (450 km) instead of 418 km."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
