INSERT INTO "notes"."NoteVersion" ("id", "noteId", "number", "kind", "title", "cards", "createdById", "createdAt")
SELECT 'd6b04c74-cb6f-740a-ab04-53bdd2fd434c', '5598fefb-3573-7958-951a-49a75bad2aaf', 1, 'PUBLISHED', 'Depth-Limited, Iterative Deepening & Bidirectional Search', '[{"id":"7c9453ce-cb36-7195-b3ee-f50d416eeb98","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Iterative deepening combines DFS''s tiny memory with BFS''s completeness and optimality — and is the preferred uninformed method when the solution depth is unknown. Bidirectional search meets in the middle to cut "},{"type":"text","text":"bᵈ","marks":[{"type":"code"}]},{"type":"text","text":" to "},{"type":"text","text":"2·b^(d/2)","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"a7d63dc3-7019-725f-a657-14f69fd83ce0","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Depth-limited and iterative deepening DFS"}]},"revision":1},{"id":"6efba9e8-7c53-703b-897e-097bbed0d346","type":"text","position":"a2","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Depth-limited search (DLS)","marks":[{"type":"bold"}]},{"type":"text","text":" is DFS that treats nodes at depth "},{"type":"text","text":"ℓ","marks":[{"type":"code"}]},{"type":"text","text":" as leaves — it can''t loop forever, but misses goals deeper than "},{"type":"text","text":"ℓ","marks":[{"type":"code"}]},{"type":"text","text":". "},{"type":"text","text":"Iterative deepening (IDDFS)","marks":[{"type":"bold"}]},{"type":"text","text":" runs DLS with "},{"type":"text","text":"ℓ = 0, 1, 2, …","marks":[{"type":"code"}]},{"type":"text","text":" until a goal is found."}]}]}},"revision":1},{"id":"1d8c2ae8-601d-7f17-b832-f2f7b1e5d1a0","type":"code","position":"a3","content":{"language":"python","code":"ROADS = \"\"\"Arad Zerind 75, Arad Sibiu 140, Arad Timisoara 118, Zerind Oradea 71, Oradea Sibiu 151,\nTimisoara Lugoj 111, Lugoj Mehadia 70, Mehadia Drobeta 75, Drobeta Craiova 120, Craiova Rimnicu 146,\nCraiova Pitesti 138, Sibiu Fagaras 99, Sibiu Rimnicu 80, Rimnicu Pitesti 97, Fagaras Bucharest 211,\nPitesti Bucharest 101, Bucharest Giurgiu 90, Bucharest Urziceni 85, Urziceni Hirsova 98,\nHirsova Eforie 86, Urziceni Vaslui 142, Vaslui Iasi 92, Iasi Neamt 87\"\"\"\ngraph = {}                                  # city -> {neighbour: road km}  (\"Rimnicu\" = Rimnicu Vilcea)\nfor road in ROADS.split(\",\"):\n    a, b, km = road.split()\n    graph.setdefault(a, {})[b] = int(km)\n    graph.setdefault(b, {})[a] = int(km)\n\ndef dls(node, goal, limit, route, counter):\n    counter[0] += 1                                    # count expansions\n    if node == goal:\n        return route\n    if limit == 0:\n        return None                                    # cutoff\n    for nbr in graph[node]:\n        if nbr not in route:                           # avoid cycles along the current path\n            found = dls(nbr, goal, limit - 1, route + [nbr], counter)\n            if found:\n                return found\n    return None\n\ndef iddfs(start, goal, max_depth=10):\n    total = 0\n    for limit in range(max_depth + 1):\n        counter = [0]\n        found = dls(start, goal, limit, [start], counter)\n        total += counter[0]\n        if found:\n            return found, limit, total\n\nprint(dls(\"Arad\", \"Bucharest\", 2, [\"Arad\"], [0]))     # None ← limit too small\nprint(iddfs(\"Arad\", \"Bucharest\"))                     # ([''Arad'', ''Sibiu'', ''Fagaras'', ''Bucharest''], 3, 23)","filename":"Python"},"revision":1},{"id":"8b29ddf9-ffb8-7d93-8b1a-c360b60c266c","type":"text","position":"a4","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Re-generating the shallow levels looks wasteful, but in a tree most nodes are at the bottom level, so the overhead is small:"}]},{"type":"paragraph","content":[{"type":"text","text":"N(IDS) = d·b + (d−1)·b² + … + 1·bᵈ N(BFS) = b + b² + … + bᵈ","marks":[{"type":"code"}]}]}]}},"revision":1},{"id":"dd31c5f9-1dd3-7707-9977-5c3e2bf000f3","type":"code","position":"a5","content":{"language":"python","code":"b, d = 10, 5\nn_bfs = sum(b ** i for i in range(1, d + 1))\nn_ids = sum((d - i + 1) * b ** i for i in range(1, d + 1))\nprint(n_bfs, n_ids, f\"{n_ids / n_bfs - 1:.0%}\")    # 111110 123450 11% ← only ~11% more nodes, with O(bd) memory","filename":"Python"},"revision":1},{"id":"01d90bbd-3e12-7c4b-9671-fbb799eb5983","type":"heading","position":"a6","content":{"level":1,"content":[{"type":"text","text":"Bidirectional search"}]},"revision":1},{"id":"6c2dd35a-2cd6-7a05-9717-2bdd8f3cf0b1","type":"text","position":"a7","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Search forward from the start and backward from the goal at the same time; stop when the frontiers meet. Two searches of depth "},{"type":"text","text":"d/2","marks":[{"type":"code"}]},{"type":"text","text":" generate "},{"type":"text","text":"2·b^(d/2)","marks":[{"type":"code"}]},{"type":"text","text":" nodes — far fewer than "},{"type":"text","text":"bᵈ","marks":[{"type":"code"}]},{"type":"text","text":" (for "},{"type":"text","text":"b = 10, d = 6","marks":[{"type":"code"}]},{"type":"text","text":": 2,000 vs 1,000,000). It needs actions that can be "},{"type":"text","text":"reversed","marks":[{"type":"italic"}]},{"type":"text","text":" and an explicit goal state."}]}]}},"revision":1},{"id":"da37a4b6-0d73-7c34-addc-45f8661a67f2","type":"code","position":"a8","content":{"language":"python","code":"ROADS = \"\"\"Arad Zerind 75, Arad Sibiu 140, Arad Timisoara 118, Zerind Oradea 71, Oradea Sibiu 151,\nTimisoara Lugoj 111, Lugoj Mehadia 70, Mehadia Drobeta 75, Drobeta Craiova 120, Craiova Rimnicu 146,\nCraiova Pitesti 138, Sibiu Fagaras 99, Sibiu Rimnicu 80, Rimnicu Pitesti 97, Fagaras Bucharest 211,\nPitesti Bucharest 101, Bucharest Giurgiu 90, Bucharest Urziceni 85, Urziceni Hirsova 98,\nHirsova Eforie 86, Urziceni Vaslui 142, Vaslui Iasi 92, Iasi Neamt 87\"\"\"\ngraph = {}                                  # city -> {neighbour: road km}  (\"Rimnicu\" = Rimnicu Vilcea)\nfor road in ROADS.split(\",\"):\n    a, b, km = road.split()\n    graph.setdefault(a, {})[b] = int(km)\n    graph.setdefault(b, {})[a] = int(km)\n\nfrom collections import deque\n\ndef bidirectional(start, goal):\n    parents = {start: {start: None}, goal: {goal: None}}      # one search tree per direction\n    frontiers = {start: deque([start]), goal: deque([goal])}\n    while frontiers[start] and frontiers[goal]:\n        for side, other in ((start, goal), (goal, start)):    # alternate one layer each\n            for _ in range(len(frontiers[side])):\n                node = frontiers[side].popleft()\n                for nbr in graph[node]:\n                    if nbr not in parents[side]:\n                        parents[side][nbr] = node\n                        frontiers[side].append(nbr)\n                    if nbr in parents[other]:                  # the two searches meet\n                        left, right, n = [], [], nbr\n                        while n: left.append(n); n = parents[start][n]\n                        n = parents[goal][nbr]\n                        while n: right.append(n); n = parents[goal][n]\n                        return left[::-1] + right, nbr\n\nprint(bidirectional(\"Arad\", \"Bucharest\"))    # ([''Arad'', ''Sibiu'', ''Fagaras'', ''Bucharest''], ''Fagaras'')","filename":"Python"},"revision":1},{"id":"bcc47675-d7cc-7554-a160-dad2765a19e8","type":"heading","position":"a9","content":{"level":1,"content":[{"type":"text","text":"Comparing the uninformed strategies"}]},"revision":1},{"id":"1be5129b-8deb-7fc8-a697-aeb3534b055a","type":"table","position":"aA","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Criterion"}],[{"type":"text","text":"BFS"}],[{"type":"text","text":"UCS"}],[{"type":"text","text":"DFS"}],[{"type":"text","text":"Depth-limited"}],[{"type":"text","text":"Iterative deepening"}],[{"type":"text","text":"Bidirectional"}]],[[{"type":"text","text":"Complete?"}],[{"type":"text","text":"Yes¹"}],[{"type":"text","text":"Yes¹ ²"}],[{"type":"text","text":"No"}],[{"type":"text","text":"No (if "},{"type":"text","text":"ℓ < d","marks":[{"type":"code"}]},{"type":"text","text":")"}],[{"type":"text","text":"Yes¹"}],[{"type":"text","text":"Yes¹ ⁴"}]],[[{"type":"text","text":"Optimal?"}],[{"type":"text","text":"Yes³"}],[{"type":"text","text":"Yes"}],[{"type":"text","text":"No"}],[{"type":"text","text":"No"}],[{"type":"text","text":"Yes³"}],[{"type":"text","text":"Yes³ ⁴"}]],[[{"type":"text","text":"Time"}],[{"type":"text","text":"O(bᵈ)","marks":[{"type":"code"}]}],[{"type":"text","text":"O(b^(1+⌊C*/ε⌋))","marks":[{"type":"code"}]}],[{"type":"text","text":"O(bᵐ)","marks":[{"type":"code"}]}],[{"type":"text","text":"O(bˡ)","marks":[{"type":"code"}]}],[{"type":"text","text":"O(bᵈ)","marks":[{"type":"code"}]}],[{"type":"text","text":"O(b^(d/2))","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Space"}],[{"type":"text","text":"O(bᵈ)","marks":[{"type":"code"}]}],[{"type":"text","text":"O(b^(1+⌊C*/ε⌋))","marks":[{"type":"code"}]}],[{"type":"text","text":"O(bm)","marks":[{"type":"code"}]}],[{"type":"text","text":"O(bℓ)","marks":[{"type":"code"}]}],[{"type":"text","text":"O(bd)","marks":[{"type":"code"}]}],[{"type":"text","text":"O(b^(d/2))","marks":[{"type":"code"}]}]]]},"revision":1},{"id":"12d6f26d-f03b-7e08-b9c7-53465f3c3d53","type":"text","position":"aB","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"¹ if "},{"type":"text","text":"b","marks":[{"type":"code"}]},{"type":"text","text":" is finite. ² if every step cost ≥ "},{"type":"text","text":"ε > 0","marks":[{"type":"code"}]},{"type":"text","text":". ³ if all step costs are equal. ⁴ if both directions use BFS (or UCS)."}]}]}},"revision":1},{"id":"0978f438-5ff5-7845-bc09-0976b0d925e3","type":"callout","position":"aC","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Rule of thumb: "},{"type":"text","text":"IDDFS","marks":[{"type":"bold"}]},{"type":"text","text":" when the space is large and the solution depth unknown; "},{"type":"text","text":"UCS","marks":[{"type":"bold"}]},{"type":"text","text":" when step costs differ; "},{"type":"text","text":"BFS","marks":[{"type":"bold"}]},{"type":"text","text":" only when the space is small enough to fit in memory; "},{"type":"text","text":"DFS","marks":[{"type":"bold"}]},{"type":"text","text":" when memory is tight and any solution will do (or all solutions are deep and plentiful)."}]}]}},"revision":1},{"id":"a568f36f-a1c7-7219-abf9-65ca9215883e","type":"question","position":"aD","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why is iterative deepening not as wasteful as it looks?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"With branching factor "},{"type":"text","text":"b","marks":[{"type":"code"}]},{"type":"text","text":", the bottom level holds about "},{"type":"text","text":"(b−1)/b","marks":[{"type":"code"}]},{"type":"text","text":" of all nodes, so re-generating the upper levels adds only a constant factor (~11% for "},{"type":"text","text":"b = 10","marks":[{"type":"code"}]},{"type":"text","text":"). In return you get BFS''s completeness/optimality with DFS''s "},{"type":"text","text":"O(bd)","marks":[{"type":"code"}]},{"type":"text","text":" memory."}]}]}},"revision":1},{"id":"47646c3a-7166-778b-bdca-22c5101d1500","type":"question","position":"aE","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What does bidirectional search need to work?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"An explicit goal state (or a small set of them) and the ability to compute predecessors — i.e. reversible actions. It also needs an efficient check for when the two frontiers intersect (a hash set)."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
WHERE EXISTS (SELECT 1 FROM "notes"."Note" n WHERE n.id = '5598fefb-3573-7958-951a-49a75bad2aaf' AND n."ownerId" = '019a118c-f480-7000-8000-000000000001' AND n."publishedVersionId" IS NULL AND n.visibility = 'PRIVATE' AND n."deletedAt" IS NULL AND n."draftUpdatedAt" = TIMESTAMPTZ '2026-10-07 03:23:53+00')
