  ('1d8c2ae8-601d-7f17-b832-f2f7b1e5d1a0', 'a3', 'code', '{"language":"python","code":"ROADS = \"\"\"Arad Zerind 75, Arad Sibiu 140, Arad Timisoara 118, Zerind Oradea 71, Oradea Sibiu 151,\nTimisoara Lugoj 111, Lugoj Mehadia 70, Mehadia Drobeta 75, Drobeta Craiova 120, Craiova Rimnicu 146,\nCraiova Pitesti 138, Sibiu Fagaras 99, Sibiu Rimnicu 80, Rimnicu Pitesti 97, Fagaras Bucharest 211,\nPitesti Bucharest 101, Bucharest Giurgiu 90, Bucharest Urziceni 85, Urziceni Hirsova 98,\nHirsova Eforie 86, Urziceni Vaslui 142, Vaslui Iasi 92, Iasi Neamt 87\"\"\"\ngraph = {}                                  # city -> {neighbour: road km}  (\"Rimnicu\" = Rimnicu Vilcea)\nfor road in ROADS.split(\",\"):\n    a, b, km = road.split()\n    graph.setdefault(a, {})[b] = int(km)\n    graph.setdefault(b, {})[a] = int(km)\n\ndef dls(node, goal, limit, route, counter):\n    counter[0] += 1                                    # count expansions\n    if node == goal:\n        return route\n    if limit == 0:\n        return None                                    # cutoff\n    for nbr in graph[node]:\n        if nbr not in route:                           # avoid cycles along the current path\n            found = dls(nbr, goal, limit - 1, route + [nbr], counter)\n            if found:\n                return found\n    return None\n\ndef iddfs(start, goal, max_depth=10):\n    total = 0\n    for limit in range(max_depth + 1):\n        counter = [0]\n        found = dls(start, goal, limit, [start], counter)\n        total += counter[0]\n        if found:\n            return found, limit, total\n\nprint(dls(\"Arad\", \"Bucharest\", 2, [\"Arad\"], [0]))     # None ← limit too small\nprint(iddfs(\"Arad\", \"Bucharest\"))                     # ([''Arad'', ''Sibiu'', ''Fagaras'', ''Bucharest''], 3, 23)","filename":"Python"}'),
  ('8b29ddf9-ffb8-7d93-8b1a-c360b60c266c', 'a4', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Re-generating the shallow levels looks wasteful, but in a tree most nodes are at the bottom level, so the overhead is small:"}]},{"type":"paragraph","content":[{"type":"text","text":"N(IDS) = d·b + (d−1)·b² + … + 1·bᵈ N(BFS) = b + b² + … + bᵈ","marks":[{"type":"code"}]}]}]}}'),
  ('dd31c5f9-1dd3-7707-9977-5c3e2bf000f3', 'a5', 'code', '{"language":"python","code":"b, d = 10, 5\nn_bfs = sum(b ** i for i in range(1, d + 1))\nn_ids = sum((d - i + 1) * b ** i for i in range(1, d + 1))\nprint(n_bfs, n_ids, f\"{n_ids / n_bfs - 1:.0%}\")    # 111110 123450 11% ← only ~11% more nodes, with O(bd) memory","filename":"Python"}'),
  ('01d90bbd-3e12-7c4b-9671-fbb799eb5983', 'a6', 'heading', '{"level":1,"content":[{"type":"text","text":"Bidirectional search"}]}'),
  ('6c2dd35a-2cd6-7a05-9717-2bdd8f3cf0b1', 'a7', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Search forward from the start and backward from the goal at the same time; stop when the frontiers meet. Two searches of depth "},{"type":"text","text":"d/2","marks":[{"type":"code"}]},{"type":"text","text":" generate "},{"type":"text","text":"2·b^(d/2)","marks":[{"type":"code"}]},{"type":"text","text":" nodes — far fewer than "},{"type":"text","text":"bᵈ","marks":[{"type":"code"}]},{"type":"text","text":" (for "},{"type":"text","text":"b = 10, d = 6","marks":[{"type":"code"}]},{"type":"text","text":": 2,000 vs 1,000,000). It needs actions that can be "},{"type":"text","text":"reversed","marks":[{"type":"italic"}]},{"type":"text","text":" and an explicit goal state."}]}]}}'),
  ('da37a4b6-0d73-7c34-addc-45f8661a67f2', 'a8', 'code', '{"language":"python","code":"ROADS = \"\"\"Arad Zerind 75, Arad Sibiu 140, Arad Timisoara 118, Zerind Oradea 71, Oradea Sibiu 151,\nTimisoara Lugoj 111, Lugoj Mehadia 70, Mehadia Drobeta 75, Drobeta Craiova 120, Craiova Rimnicu 146,\nCraiova Pitesti 138, Sibiu Fagaras 99, Sibiu Rimnicu 80, Rimnicu Pitesti 97, Fagaras Bucharest 211,\nPitesti Bucharest 101, Bucharest Giurgiu 90, Bucharest Urziceni 85, Urziceni Hirsova 98,\nHirsova Eforie 86, Urziceni Vaslui 142, Vaslui Iasi 92, Iasi Neamt 87\"\"\"\ngraph = {}                                  # city -> {neighbour: road km}  (\"Rimnicu\" = Rimnicu Vilcea)\nfor road in ROADS.split(\",\"):\n    a, b, km = road.split()\n    graph.setdefault(a, {})[b] = int(km)\n    graph.setdefault(b, {})[a] = int(km)\n\nfrom collections import deque\n\ndef bidirectional(start, goal):\n    parents = {start: {start: None}, goal: {goal: None}}      # one search tree per direction\n    frontiers = {start: deque([start]), goal: deque([goal])}\n    while frontiers[start] and frontiers[goal]:\n        for side, other in ((start, goal), (goal, start)):    # alternate one layer each\n            for _ in range(len(frontiers[side])):\n                node = frontiers[side].popleft()\n                for nbr in graph[node]:\n                    if nbr not in parents[side]:\n                        parents[side][nbr] = node\n                        frontiers[side].append(nbr)\n                    if nbr in parents[other]:                  # the two searches meet\n                        left, right, n = [], [], nbr\n                        while n: left.append(n); n = parents[start][n]\n                        n = parents[goal][nbr]\n                        while n: right.append(n); n = parents[goal][n]\n                        return left[::-1] + right, nbr\n\nprint(bidirectional(\"Arad\", \"Bucharest\"))    # ([''Arad'', ''Sibiu'', ''Fagaras'', ''Bucharest''], ''Fagaras'')","filename":"Python"}'),
  ('bcc47675-d7cc-7554-a160-dad2765a19e8', 'a9', 'heading', '{"level":1,"content":[{"type":"text","text":"Comparing the uninformed strategies"}]}'),
  ('1be5129b-8deb-7fc8-a697-aeb3534b055a', 'aA', 'table', '{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Criterion"}],[{"type":"text","text":"BFS"}],[{"type":"text","text":"UCS"}],[{"type":"text","text":"DFS"}],[{"type":"text","text":"Depth-limited"}],[{"type":"text","text":"Iterative deepening"}],[{"type":"text","text":"Bidirectional"}]],[[{"type":"text","text":"Complete?"}],[{"type":"text","text":"Yes¹"}],[{"type":"text","text":"Yes¹ ²"}],[{"type":"text","text":"No"}],[{"type":"text","text":"No (if "},{"type":"text","text":"ℓ < d","marks":[{"type":"code"}]},{"type":"text","text":")"}],[{"type":"text","text":"Yes¹"}],[{"type":"text","text":"Yes¹ ⁴"}]],[[{"type":"text","text":"Optimal?"}],[{"type":"text","text":"Yes³"}],[{"type":"text","text":"Yes"}],[{"type":"text","text":"No"}],[{"type":"text","text":"No"}],[{"type":"text","text":"Yes³"}],[{"type":"text","text":"Yes³ ⁴"}]],[[{"type":"text","text":"Time"}],[{"type":"text","text":"O(bᵈ)","marks":[{"type":"code"}]}],[{"type":"text","text":"O(b^(1+⌊C*/ε⌋))","marks":[{"type":"code"}]}],[{"type":"text","text":"O(bᵐ)","marks":[{"type":"code"}]}],[{"type":"text","text":"O(bˡ)","marks":[{"type":"code"}]}],[{"type":"text","text":"O(bᵈ)","marks":[{"type":"code"}]}],[{"type":"text","text":"O(b^(d/2))","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Space"}],[{"type":"text","text":"O(bᵈ)","marks":[{"type":"code"}]}],[{"type":"text","text":"O(b^(1+⌊C*/ε⌋))","marks":[{"type":"code"}]}],[{"type":"text","text":"O(bm)","marks":[{"type":"code"}]}],[{"type":"text","text":"O(bℓ)","marks":[{"type":"code"}]}],[{"type":"text","text":"O(bd)","marks":[{"type":"code"}]}],[{"type":"text","text":"O(b^(d/2))","marks":[{"type":"code"}]}]]]}'),
