INSERT INTO "notes"."NoteVersion" ("id", "noteId", "number", "kind", "title", "cards", "createdById", "createdAt")
SELECT 'e3e68c53-3c9a-7abd-bc51-29c50c352821', '0212e0d0-5a8b-77ec-950a-cce4f7e4d5d6', 1, 'PUBLISHED', 'Knowledge Representation & Expert Systems', '[{"id":"f549e4b7-b154-7dc7-9277-50376b2233fd","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Knowledge representation (KR) is about organising what an agent knows — categories, objects, properties, defaults and rules — so that inference is efficient. Expert systems were AI''s first big commercial success, and today''s knowledge graphs are their descendants."}]}]}},"revision":1},{"id":"ab438f92-8d18-70dd-96ca-e0262eb802d3","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Main representation schemes"}]},"revision":1},{"id":"d8a74531-8861-723a-8ddc-75b4cb5eeec4","type":"callout","position":"a2","content":{"variant":"note","title":"Semantic networks","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A graph: nodes are objects/categories, labelled edges are relations ("},{"type":"text","text":"is-a","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"part-of","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"has","marks":[{"type":"code"}]},{"type":"text","text":"). Properties are "},{"type":"text","text":"inherited","marks":[{"type":"bold"}]},{"type":"text","text":" down "},{"type":"text","text":"is-a","marks":[{"type":"code"}]},{"type":"text","text":" links. Easy to visualise; weak on negation and quantifiers."}]}]}},"revision":1},{"id":"7394cdd3-4de7-7f1a-8670-fa361ffe5876","type":"callout","position":"a3","content":{"variant":"note","title":"Frames","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Record-like structures (Minsky, 1974): a frame for "},{"type":"text","text":"Restaurant","marks":[{"type":"italic"}]},{"type":"text","text":" has "},{"type":"text","text":"slots","marks":[{"type":"bold"}]},{"type":"text","text":" (cuisine, price) with "},{"type":"text","text":"default","marks":[{"type":"bold"}]},{"type":"text","text":" values and procedures (“if-needed”). The ancestor of objects and classes in OOP."}]}]}},"revision":1},{"id":"8eae11aa-f7d4-778c-8d84-2beb1d68ea4f","type":"callout","position":"a4","content":{"variant":"note","title":"Ontologies","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A formal, shared vocabulary of categories and relations for a domain. Upper ontologies define general concepts (events, time, physical objects); OWL/RDF encode them as triples; description logics give decidable reasoning."}]}]}},"revision":1},{"id":"f98b8302-19e1-78cf-ae24-f4892e35e5ac","type":"callout","position":"a5","content":{"variant":"note","title":"Rules / production systems","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"IF-THEN rules over a working memory of facts, fired by an inference engine (forward or backward chaining). Conflict resolution picks which matching rule fires; the Rete algorithm matches efficiently."}]}]}},"revision":1},{"id":"f410faaf-1848-7f86-b772-1b2d5152c09c","type":"heading","position":"a6","content":{"level":1,"content":[{"type":"text","text":"Inheritance with exceptions"}]},"revision":1},{"id":"6902e94f-9c46-7365-af3b-1d3475678d1f","type":"code","position":"a7","content":{"language":"python","code":"# a semantic network as (subject, relation, object) triples\nTRIPLES = [\n    (\"Bird\", \"is-a\", \"Animal\"), (\"Animal\", \"breathes\", True),\n    (\"Bird\", \"can-fly\", True), (\"Bird\", \"has\", \"feathers\"),\n    (\"Penguin\", \"is-a\", \"Bird\"), (\"Penguin\", \"can-fly\", False),     # an exception overrides the default\n    (\"Tweety\", \"instance-of\", \"Bird\"), (\"Pingu\", \"instance-of\", \"Penguin\"),\n]\n\ndef lookup(entity, attribute):\n    node = entity\n    while node:\n        for s, r, o in TRIPLES:\n            if s == node and r == attribute:\n                return o                           # the most specific value wins\n        parents = [o for s, r, o in TRIPLES if s == node and r in (\"is-a\", \"instance-of\")]\n        node = parents[0] if parents else None     # climb the is-a hierarchy\n    return None\n\nprint(lookup(\"Tweety\", \"can-fly\"), lookup(\"Pingu\", \"can-fly\"))     # True False\nprint(lookup(\"Pingu\", \"has\"), lookup(\"Pingu\", \"breathes\"))         # feathers True ← inherited from Bird and Animal","filename":"Python"},"revision":1},{"id":"3f684120-699a-7c8b-aa23-67e7dbd01deb","type":"text","position":"a8","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"This is "},{"type":"text","text":"default (non-monotonic) reasoning","marks":[{"type":"bold"}]},{"type":"text","text":": birds fly "},{"type":"text","text":"unless","marks":[{"type":"italic"}]},{"type":"text","text":" we learn otherwise. Classical logic is "},{"type":"text","text":"monotonic","marks":[{"type":"italic"}]},{"type":"text","text":" — adding facts never removes conclusions — so defaults need special logics (default logic, circumscription) or the inheritance trick above."}]}]}},"revision":1},{"id":"fb1605ad-ef20-77b5-811a-4addc39c2735","type":"heading","position":"a9","content":{"level":1,"content":[{"type":"text","text":"Expert systems"}]},"revision":1},{"id":"16184d2a-3274-7d93-8ea7-05f02850a642","type":"table","position":"aA","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Component"}],[{"type":"text","text":"Role"}]],[[{"type":"text","text":"Knowledge base","marks":[{"type":"bold"}]}],[{"type":"text","text":"Domain rules and facts captured from human experts"}]],[[{"type":"text","text":"Inference engine","marks":[{"type":"bold"}]}],[{"type":"text","text":"Applies the rules (forward or backward chaining) to the case at hand"}]],[[{"type":"text","text":"Working memory","marks":[{"type":"bold"}]}],[{"type":"text","text":"Facts about the current case (symptoms, test results)"}]],[[{"type":"text","text":"Explanation facility","marks":[{"type":"bold"}]}],[{"type":"text","text":"Answers "},{"type":"text","text":"why","marks":[{"type":"italic"}]},{"type":"text","text":" a question is asked and "},{"type":"text","text":"how","marks":[{"type":"italic"}]},{"type":"text","text":" a conclusion was reached"}]],[[{"type":"text","text":"Knowledge-acquisition interface","marks":[{"type":"bold"}]}],[{"type":"text","text":"Lets experts and engineers add and edit rules"}]]]},"revision":1},{"id":"c79681df-c645-7520-881d-56e15266a76e","type":"code","position":"aB","content":{"language":"python","code":"RULES = [\n    (\"R1\", {\"fever\", \"cough\"}, \"flu-suspected\"),\n    (\"R2\", {\"flu-suspected\", \"short-of-breath\"}, \"refer-to-doctor\"),\n    (\"R3\", {\"sneezing\", \"itchy-eyes\"}, \"allergy-suspected\"),\n]\n\ndef diagnose(symptoms):\n    facts, how = set(symptoms), {}\n    changed = True\n    while changed:                                  # forward chaining until nothing new fires\n        changed = False\n        for name, conditions, conclusion in RULES:\n            if conditions <= facts and conclusion not in facts:\n                facts.add(conclusion)\n                how[conclusion] = f\"{name}: {'' + ''.join(sorted(conditions))}\"\n                changed = True\n    return how\n\nresult = diagnose({\"fever\", \"cough\", \"short-of-breath\"})\nprint(list(result))                         # [''flu-suspected'', ''refer-to-doctor'']\nprint(result[\"refer-to-doctor\"])            # R2: flu-suspected + short-of-breath ← the \"how\" explanation","filename":"Python"},"revision":1},{"id":"742027b3-e0d8-7ded-b64a-59b79b7bad02","type":"table","position":"aC","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"System"}],[{"type":"text","text":"Domain"}],[{"type":"text","text":"Note"}]],[[{"type":"text","text":"DENDRAL (1965)"}],[{"type":"text","text":"Inferring molecular structure from mass spectra"}],[{"type":"text","text":"First expert system"}]],[[{"type":"text","text":"MYCIN (1970s)"}],[{"type":"text","text":"Diagnosing blood infections, recommending antibiotics"}],[{"type":"text","text":"Hundreds of backward-chaining rules with "},{"type":"text","text":"certainty factors","marks":[{"type":"bold"}]},{"type":"text","text":"; matched specialists but was never used clinically"}]],[[{"type":"text","text":"XCON / R1 (1980)"}],[{"type":"text","text":"Configuring DEC VAX computers"}],[{"type":"text","text":"Saved DEC an estimated $40M a year; grew to thousands of rules"}]]]},"revision":1},{"id":"e69abd69-b5b4-74cc-bf98-6cb2ea890cbf","type":"callout","position":"aD","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why expert systems faded: the "},{"type":"text","text":"knowledge-acquisition bottleneck","marks":[{"type":"bold"}]},{"type":"text","text":" (experts can''t articulate everything), brittleness outside their narrow rules, no learning, and heavy maintenance as rule bases grew. Machine learning replaced much of this — but rule engines still run business logic, and "},{"type":"text","text":"knowledge graphs","marks":[{"type":"bold"}]},{"type":"text","text":" (Wikidata, Google Knowledge Graph) ground search and LLM answers (retrieval-augmented generation)."}]}]}},"revision":1},{"id":"9dd99cc7-317c-7597-9c4e-734ce3843337","type":"heading","position":"aE","content":{"level":1,"content":[{"type":"text","text":"Hard problems in KR"}]},"revision":1},{"id":"b3c63427-5277-772d-aae2-ce8f0ea618c7","type":"table","position":"aF","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Problem"}],[{"type":"text","text":"Description"}]],[[{"type":"text","text":"Frame problem","marks":[{"type":"bold"}]}],[{"type":"text","text":"Representing what does "},{"type":"text","text":"not","marks":[{"type":"italic"}]},{"type":"text","text":" change when an action happens without writing an axiom for every unaffected fact"}]],[[{"type":"text","text":"Qualification problem","marks":[{"type":"bold"}]}],[{"type":"text","text":"Listing every precondition of an action is impossible (the car starts… unless the battery is dead, the tank empty, a potato in the exhaust…)"}]],[[{"type":"text","text":"Closed-world assumption","marks":[{"type":"bold"}]}],[{"type":"text","text":"Databases and Prolog treat anything not known to be true as false — convenient, but not valid for open worlds like the web"}]],[[{"type":"text","text":"Common sense","marks":[{"type":"bold"}]}],[{"type":"text","text":"Vast everyday knowledge (water is wet, people have one mother) that is hard to write down — the target of projects like Cyc"}]]]},"revision":1},{"id":"e05b3858-afc6-79e8-b628-e30b060221fd","type":"question","position":"aG","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Compare semantic networks and frames."}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Both organise knowledge around objects and categories with inheritance. Semantic networks emphasise relations as labelled graph edges; frames bundle an object''s properties into slots with defaults and attached procedures. They are largely interchangeable and both map to subsets of first-order logic."}]}]}},"revision":1},{"id":"43de20eb-f11c-7e09-9811-f94fb30fd39f","type":"question","position":"aH","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What are the components of an expert system?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A knowledge base of rules, an inference engine (forward/backward chaining), working memory for case facts, an explanation facility, and a knowledge-acquisition interface. The user interface asks questions and presents conclusions."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
WHERE EXISTS (SELECT 1 FROM "notes"."Note" n WHERE n.id = '0212e0d0-5a8b-77ec-950a-cce4f7e4d5d6' AND n."ownerId" = '019a118c-f480-7000-8000-000000000001' AND n."publishedVersionId" IS NULL AND n.visibility = 'PRIVATE' AND n."deletedAt" IS NULL AND n."draftUpdatedAt" = TIMESTAMPTZ '2026-10-07 03:23:53+00')
ON CONFLICT DO NOTHING;

