  ('c79681df-c645-7520-881d-56e15266a76e', 'aB', 'code', '{"language":"python","code":"RULES = [\n    (\"R1\", {\"fever\", \"cough\"}, \"flu-suspected\"),\n    (\"R2\", {\"flu-suspected\", \"short-of-breath\"}, \"refer-to-doctor\"),\n    (\"R3\", {\"sneezing\", \"itchy-eyes\"}, \"allergy-suspected\"),\n]\n\ndef diagnose(symptoms):\n    facts, how = set(symptoms), {}\n    changed = True\n    while changed:                                  # forward chaining until nothing new fires\n        changed = False\n        for name, conditions, conclusion in RULES:\n            if conditions <= facts and conclusion not in facts:\n                facts.add(conclusion)\n                how[conclusion] = f\"{name}: {'' + ''.join(sorted(conditions))}\"\n                changed = True\n    return how\n\nresult = diagnose({\"fever\", \"cough\", \"short-of-breath\"})\nprint(list(result))                         # [''flu-suspected'', ''refer-to-doctor'']\nprint(result[\"refer-to-doctor\"])            # R2: flu-suspected + short-of-breath ← the \"how\" explanation","filename":"Python"}'),
  ('742027b3-e0d8-7ded-b64a-59b79b7bad02', 'aC', 'table', '{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"System"}],[{"type":"text","text":"Domain"}],[{"type":"text","text":"Note"}]],[[{"type":"text","text":"DENDRAL (1965)"}],[{"type":"text","text":"Inferring molecular structure from mass spectra"}],[{"type":"text","text":"First expert system"}]],[[{"type":"text","text":"MYCIN (1970s)"}],[{"type":"text","text":"Diagnosing blood infections, recommending antibiotics"}],[{"type":"text","text":"Hundreds of backward-chaining rules with "},{"type":"text","text":"certainty factors","marks":[{"type":"bold"}]},{"type":"text","text":"; matched specialists but was never used clinically"}]],[[{"type":"text","text":"XCON / R1 (1980)"}],[{"type":"text","text":"Configuring DEC VAX computers"}],[{"type":"text","text":"Saved DEC an estimated $40M a year; grew to thousands of rules"}]]]}'),
  ('e69abd69-b5b4-74cc-bf98-6cb2ea890cbf', 'aD', 'callout', '{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why expert systems faded: the "},{"type":"text","text":"knowledge-acquisition bottleneck","marks":[{"type":"bold"}]},{"type":"text","text":" (experts can''t articulate everything), brittleness outside their narrow rules, no learning, and heavy maintenance as rule bases grew. Machine learning replaced much of this — but rule engines still run business logic, and "},{"type":"text","text":"knowledge graphs","marks":[{"type":"bold"}]},{"type":"text","text":" (Wikidata, Google Knowledge Graph) ground search and LLM answers (retrieval-augmented generation)."}]}]}}'),
