INSERT INTO "notes"."NoteVersion" ("id", "noteId", "number", "kind", "title", "cards", "createdById", "createdAt")
SELECT '68ae5339-19dd-7efc-a62d-2ec823d88900', '26a6b89c-fcba-701e-b6af-158058850d7d', 1, 'PUBLISHED', 'Games & Minimax', '[{"id":"54a2fc72-a018-71a9-8b13-e764ad3801d1","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"In a game the agent faces an "},{"type":"text","text":"opponent","marks":[{"type":"bold"}]},{"type":"text","text":" who is trying to make it lose. Minimax plans for the worst case: MAX picks the move with the highest value assuming MIN always answers with the move that is worst for MAX."}]}]}},"revision":1},{"id":"8f275641-33ef-7aed-8ec2-f1fdb0164361","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Kinds of games"}]},"revision":1},{"id":"ac921ab4-c714-76f2-afd3-61aa748eff6f","type":"table","position":"a2","content":{"hasHeaderRow":true,"rows":[[[],[{"type":"text","text":"Deterministic"}],[{"type":"text","text":"Chance"}]],[[{"type":"text","text":"Perfect information","marks":[{"type":"bold"}]}],[{"type":"text","text":"Chess, Go, checkers, tic-tac-toe, connect-four"}],[{"type":"text","text":"Backgammon, Monopoly"}]],[[{"type":"text","text":"Imperfect information","marks":[{"type":"bold"}]}],[{"type":"text","text":"Battleship, Stratego"}],[{"type":"text","text":"Poker, bridge, Scrabble"}]]]},"revision":1},{"id":"b3d04489-d40f-79fa-93cf-8c25aac6c9ad","type":"text","position":"a3","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Classical game search targets "},{"type":"text","text":"two-player, turn-taking, zero-sum, perfect-information","marks":[{"type":"bold"}]},{"type":"text","text":" games — one player''s gain is exactly the other''s loss."}]}]}},"revision":1},{"id":"0baf4441-12dc-7877-a447-729571ce6e11","type":"heading","position":"a4","content":{"level":1,"content":[{"type":"text","text":"A game as a search problem"}]},"revision":1},{"id":"55a3be06-7ea6-77bc-97e1-acd8084ca03b","type":"table","position":"a5","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Element"}],[{"type":"text","text":"Meaning"}]],[[{"type":"text","text":"S₀","marks":[{"type":"code"}]}],[{"type":"text","text":"Initial state (starting position)"}]],[[{"type":"text","text":"ToMove(s)","marks":[{"type":"code"}]}],[{"type":"text","text":"Whose turn it is (MAX or MIN)"}]],[[{"type":"text","text":"Actions(s)","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"Result(s, a)","marks":[{"type":"code"}]}],[{"type":"text","text":"Legal moves and the position they lead to"}]],[[{"type":"text","text":"IsTerminal(s)","marks":[{"type":"code"}]}],[{"type":"text","text":"Is the game over?"}]],[[{"type":"text","text":"Utility(s, p)","marks":[{"type":"code"}]}],[{"type":"text","text":"Final payoff for player "},{"type":"text","text":"p","marks":[{"type":"code"}]},{"type":"text","text":": e.g. +1 win, 0 draw, −1 loss"}]]]},"revision":1},{"id":"33ac50b4-1b43-71c0-a1f0-7951840fb854","type":"text","position":"a6","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"MINIMAX(s) = Utility(s) if terminal; max over a of MINIMAX(Result(s, a)) if MAX to move; min over a … if MIN to move","marks":[{"type":"code"}]}]}]}},"revision":1},{"id":"138f7397-2f3b-7789-aee4-90847437ac96","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"Minimax on a two-ply tree"}]},"revision":1},{"id":"cfccbd0e-772e-796c-b6b1-d3890b1a9f6a","type":"text","position":"a8","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The standard textbook tree: MAX moves at the root (A), MIN replies at B, C and D, and the leaves are utilities for MAX."}]}]}},"revision":1},{"id":"b4ee9112-1cb5-7fd3-b7b4-f373ed9deb6d","type":"code","position":"a9","content":{"language":"python","code":"TREE = {\"A\": [\"B\", \"C\", \"D\"],                    # MAX node\n        \"B\": [3, 12, 8], \"C\": [2, 4, 6], \"D\": [14, 5, 2]}   # MIN nodes → leaf utilities\n\ndef minimax(node, maximizing):\n    if isinstance(node, int):                     # leaf: utility\n        return node\n    values = [minimax(child, not maximizing) for child in TREE[node]]\n    return max(values) if maximizing else min(values)\n\nprint([minimax(n, False) for n in TREE[\"A\"]])     # [3, 2, 2] ← MIN''s replies at B, C, D\nprint(minimax(\"A\", True))                         # 3 ← MAX moves to B","filename":"Python"},"revision":1},{"id":"fe8d0c8b-c3ff-7697-98e4-467c81d98d23","type":"heading","position":"aA","content":{"level":1,"content":[{"type":"text","text":"Perfect tic-tac-toe"}]},"revision":1},{"id":"0bf71d88-61fa-73a8-a7d2-83bff2d4f34c","type":"code","position":"aB","content":{"language":"python","code":"from functools import lru_cache\n\nLINES = [(0, 1, 2), (3, 4, 5), (6, 7, 8), (0, 3, 6), (1, 4, 7), (2, 5, 8), (0, 4, 8), (2, 4, 6)]\n\ndef winner(b):\n    for i, j, k in LINES:\n        if b[i] != \".\" and b[i] == b[j] == b[k]:\n            return b[i]\n    return None\n\n@lru_cache(maxsize=None)                  # the same position is reached by many move orders\ndef value(board, player):                 # +1 = X wins, 0 = draw, −1 = O wins (perfect play)\n    w = winner(board)\n    if w:\n        return 1 if w == \"X\" else -1\n    if \".\" not in board:\n        return 0\n    nxt = \"O\" if player == \"X\" else \"X\"\n    vals = [value(board[:i] + player + board[i + 1:], nxt) for i in range(9) if board[i] == \".\"]\n    return max(vals) if player == \"X\" else min(vals)\n\ndef best_move(board, player):\n    nxt = \"O\" if player == \"X\" else \"X\"\n    moves = [i for i in range(9) if board[i] == \".\"]\n    pick = max if player == \"X\" else min\n    return pick(moves, key=lambda i: value(board[:i] + player + board[i + 1:], nxt))\n\nprint(value(\".\" * 9, \"X\"))                # 0 ← perfect play from the empty board is a draw\nprint(value.cache_info().currsize)        # 5478 ← distinct positions evaluated\nboard = \"XX.\" \\\n        \"OO.\" \\\n        \"...\"\nprint(best_move(board, \"X\"))              # 2 ← win at once (square 2)\nprint(best_move(\"XO..O...X\", \"X\"))        # 7 ← must block O''s middle column","filename":"Python"},"revision":1},{"id":"1b45c35c-b0c2-7b58-ab5b-6aab96ab6e6a","type":"heading","position":"aC","content":{"level":1,"content":[{"type":"text","text":"Cost of minimax"}]},"revision":1},{"id":"b34d8fdf-a69e-79f3-a3a0-3fe78069c823","type":"text","position":"aD","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Minimax is a complete depth-first exploration of the game tree: time "},{"type":"text","text":"O(bᵐ)","marks":[{"type":"code"}]},{"type":"text","text":", space "},{"type":"text","text":"O(bm)","marks":[{"type":"code"}]},{"type":"text","text":". Tic-tac-toe has fewer than 9! = 362,880 move sequences, but chess has "},{"type":"text","text":"b ≈ 35","marks":[{"type":"code"}]},{"type":"text","text":" and games of ~80 plies — about 10¹²³ positions in the tree. Real programs therefore "},{"type":"text","text":"prune","marks":[{"type":"bold"}]},{"type":"text","text":" (alpha-beta) and "},{"type":"text","text":"cut off","marks":[{"type":"bold"}]},{"type":"text","text":" the search at a fixed depth with an evaluation function."}]}]}},"revision":1},{"id":"09af8082-27d8-7697-a66b-c4f6f3f97c19","type":"callout","position":"aE","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Minimax is optimal against an optimal opponent. Against a weak opponent another strategy may win more — but minimax never does worse than its computed value."}]}]}},"revision":1},{"id":"cc933af0-c3d3-716e-9ed3-d4b66a08efd9","type":"question","position":"aF","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Explain minimax."}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Recursively evaluate the game tree: terminal states get their utility, MAX nodes take the maximum of their children and MIN nodes the minimum. The root''s best child is the move that guarantees the best outcome against an opponent who also plays optimally."}]}]}},"revision":1},{"id":"4440b383-b65b-74da-a128-5d1e55488009","type":"question","position":"aG","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is the time complexity of minimax?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"O(bᵐ)","marks":[{"type":"code"}]},{"type":"text","text":" time and "},{"type":"text","text":"O(bm)","marks":[{"type":"code"}]},{"type":"text","text":" space (depth-first), where "},{"type":"text","text":"b","marks":[{"type":"code"}]},{"type":"text","text":" is the branching factor and "},{"type":"text","text":"m","marks":[{"type":"code"}]},{"type":"text","text":" the maximum depth — infeasible for chess or Go without pruning and depth cut-offs."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
