SELECT 'c715efad-18fa-7f50-a15b-d5defac123f5', '301a707d-d666-7cc3-8efd-7dd3e417c4cd', 1, 'PUBLISHED', 'The Modern AI Landscape', '[{"id":"b3e92b7f-0f9d-7787-9e32-e4f56f2f796a","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Today “AI” usually means machine learning, and especially deep learning and large language models. But the classical ideas in these notes — search, constraints, logic, probability, decision theory — are still inside modern systems, often combined with learned components."}]}]}},"revision":1},{"id":"5afc203d-144e-7339-8c37-9fec0709532a","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"How the pieces fit"}]},"revision":1},{"id":"57240717-a2ba-75cf-9f54-8047b929436e","type":"table","position":"a2","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Paradigm"}],[{"type":"text","text":"Knowledge comes from"}],[{"type":"text","text":"Core techniques"}],[{"type":"text","text":"Where to read more"}]],[[{"type":"text","text":"Search & planning"}],[{"type":"text","text":"A problem formulation"}],[{"type":"text","text":"BFS/A*, alpha-beta, MCTS, STRIPS planners, CSP solvers"}],[{"type":"text","text":"This subject"}]],[[{"type":"text","text":"Logic & knowledge"}],[{"type":"text","text":"Hand-written facts and rules"}],[{"type":"text","text":"Resolution, chaining, ontologies, knowledge graphs"}],[{"type":"text","text":"This subject"}]],[[{"type":"text","text":"Probabilistic reasoning"}],[{"type":"text","text":"Expert-built or learned models"}],[{"type":"text","text":"Bayesian networks, HMMs, MDPs"}],[{"type":"text","text":"This subject"}]],[[{"type":"text","text":"Machine learning"}],[{"type":"text","text":"Labelled/unlabelled data"}],[{"type":"text","text":"Regression, trees, SVMs, clustering, evaluation"}],[{"type":"text","text":"Machine Learning","marks":[{"type":"bold"}]},{"type":"text","text":", "},{"type":"text","text":"Data Science","marks":[{"type":"bold"}]}]],[[{"type":"text","text":"Deep learning"}],[{"type":"text","text":"Large datasets + gradient descent"}],[{"type":"text","text":"CNNs, RNNs, Transformers, generative models"}],[{"type":"text","text":"Deep Learning","marks":[{"type":"bold"}]}]],[[{"type":"text","text":"Generative AI / LLMs"}],[{"type":"text","text":"Web-scale pretraining + fine-tuning + RLHF"}],[{"type":"text","text":"Prompting, RAG, agents, evaluation"}],[{"type":"text","text":"Generative AI","marks":[{"type":"bold"}]}]],[[{"type":"text","text":"Reinforcement learning"}],[{"type":"text","text":"Interaction and reward"}],[{"type":"text","text":"Q-learning, policy gradients, self-play"}],[{"type":"text","text":"This subject (intro) + "},{"type":"text","text":"Deep Learning","marks":[{"type":"bold"}]}]]]},"revision":1},{"id":"bc5b6d39-109a-73a4-aee7-9c047f55efb3","type":"heading","position":"a3","content":{"level":1,"content":[{"type":"text","text":"Classical AI inside modern systems"}]},"revision":1},{"id":"d22fd9c5-03e9-7fe3-bca1-39992adbcbfa","type":"table","position":"a4","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Classical idea"}],[{"type":"text","text":"Still used in"}]],[[{"type":"text","text":"A* and graph search"}],[{"type":"text","text":"Maps and ride-hailing routing, game path-finding, robot motion planning"}]],[[{"type":"text","text":"Minimax / MCTS"}],[{"type":"text","text":"Chess engines (Stockfish: alpha-beta + a neural evaluation), AlphaZero, game AI"}]],[[{"type":"text","text":"Constraint solving & SAT"}],[{"type":"text","text":"Airline crew and timetable scheduling, chip verification, package managers'' dependency resolution"}]],[[{"type":"text","text":"Planning (PDDL/HTN)"}],[{"type":"text","text":"Logistics, space missions, NPC behaviour in games, LLM agents that decompose tasks"}]],[[{"type":"text","text":"Logic & knowledge graphs"}],[{"type":"text","text":"Search-engine knowledge panels, business rules engines, grounding LLM answers (RAG over graphs)"}]],[[{"type":"text","text":"Bayesian reasoning & HMMs"}],[{"type":"text","text":"Spam filters, medical decision support, Kalman/particle filters in robots and GPS"}]],[[{"type":"text","text":"MDPs & RL"}],[{"type":"text","text":"Recommendation, ad bidding, robotics, and RLHF for aligning LLMs"}]],[[{"type":"text","text":"Beam search"}],[{"type":"text","text":"Decoding text in translation and speech models"}]]]},"revision":1},{"id":"1b528b64-c693-7fad-be4e-d621ec0bc41f","type":"callout","position":"a5","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"An "},{"type":"text","text":"LLM agent","marks":[{"type":"bold"}]},{"type":"text","text":" is the agent loop from the "},{"type":"text","text":"Intelligent Agents","marks":[{"type":"bold"}]},{"type":"text","text":" topic with an LLM as the decision-maker: it perceives (reads tool results), keeps state (memory), reasons toward a goal (plans), and acts (calls tools). Adding classical search or verification on top of LLM proposals is an active research area — "},{"type":"text","text":"neuro-symbolic","marks":[{"type":"italic"}]},{"type":"text","text":" AI."}]}]}},"revision":1},{"id":"22fd4b9c-e6d1-7fb3-a043-58c65798b2fa","type":"heading","position":"a6","content":{"level":1,"content":[{"type":"text","text":"Natural language processing"}]},"revision":1},{"id":"e8b25adc-ddc8-71df-9743-de8d5d1af646","type":"table","position":"a7","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Era"}],[{"type":"text","text":"Approach"}],[{"type":"text","text":"Example"}]],[[{"type":"text","text":"1960s–80s"}],[{"type":"text","text":"Hand-written rules and grammars"}],[{"type":"text","text":"ELIZA, SHRDLU"}]],[[{"type":"text","text":"1990s–2000s"}],[{"type":"text","text":"Statistical: n-gram language models, HMMs, CRFs"}],[{"type":"text","text":"Statistical machine translation, POS tagging"}]],[[{"type":"text","text":"2013–2017"}],[{"type":"text","text":"Word embeddings + RNN/LSTM sequence models"}],[{"type":"text","text":"word2vec, seq2seq translation"}]],[[{"type":"text","text":"2018–now"}],[{"type":"text","text":"Pretrained Transformers, then LLMs"}],[{"type":"text","text":"BERT, GPT family, instruction-tuned chat models"}]]]},"revision":1},{"id":"a61c1c96-0105-72c7-8f0b-5ad8630d089e","type":"text","position":"a8","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The idea behind every language model is the same — predict the next word from the context. A bigram model is the smallest version:"}]}]}},"revision":1},{"id":"ae1de8e2-8c1e-7e8b-a93e-368104c85b5b","type":"code","position":"a9","content":{"language":"python","code":"from collections import Counter, defaultdict\n\ncorpus = \"the cat sat on the mat . the cat ate the fish . the dog sat on the log .\".split()\nbigrams = defaultdict(Counter)\nfor w1, w2 in zip(corpus, corpus[1:]):\n    bigrams[w1][w2] += 1\n\ndef next_word_probs(word):\n    counts = bigrams[word]\n    total = sum(counts.values())\n    return {w: round(c / total, 2) for w, c in counts.most_common()}\n\ndef generate(word, n=5):\n    out = [word]\n    for _ in range(n):\n        word = bigrams[word].most_common(1)[0][0]     # greedy decoding\n        out.append(word)\n    return \" \".join(out)\n\nprint(next_word_probs(\"the\"))     # {''cat'': 0.33, ''mat'': 0.17, ''fish'': 0.17, ''dog'': 0.17, ''log'': 0.17}\nprint(generate(\"dog\"))            # dog sat on the cat sat ← greedy decoding soon loops","filename":"Python"},"revision":1},{"id":"22f26f4a-f135-7625-81c8-f6fbe1edba47","type":"text","position":"aA","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"An LLM replaces the one-word context with thousands of tokens and the count table with a Transformer of billions of parameters — see the "},{"type":"text","text":"Deep Learning","marks":[{"type":"bold"}]},{"type":"text","text":" (Transformers) and "},{"type":"text","text":"Generative AI","marks":[{"type":"bold"}]},{"type":"text","text":" notes."}]}]}},"revision":1},{"id":"3771b988-992a-73f0-9289-26db9166b67f","type":"table","position":"aB","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"NLP task"}],[{"type":"text","text":"Input → output"}]],[[{"type":"text","text":"Classification (sentiment, spam, intent)"}],[{"type":"text","text":"Text → label"}]],[[{"type":"text","text":"Named-entity recognition, POS tagging"}],[{"type":"text","text":"Text → label per token"}]],[[{"type":"text","text":"Machine translation, summarisation"}],[{"type":"text","text":"Text → text"}]],[[{"type":"text","text":"Question answering, retrieval"}],[{"type":"text","text":"Question (+ documents) → answer"}]],[[{"type":"text","text":"Speech recognition / synthesis"}],[{"type":"text","text":"Audio ↔ text"}]]]},"revision":1},{"id":"016731f1-055a-73d8-a2ea-603bf0fc62d7","type":"heading","position":"aC","content":{"level":1,"content":[{"type":"text","text":"Computer vision"}]},"revision":1},{"id":"fa12cc45-deb9-77ae-b412-47c50b4cdc08","type":"table","position":"aD","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Task"}],[{"type":"text","text":"Output"}],[{"type":"text","text":"Typical models"}]],[[{"type":"text","text":"Image classification"}],[{"type":"text","text":"One label per image"}],[{"type":"text","text":"CNNs (ResNet), Vision Transformers"}]],[[{"type":"text","text":"Object detection"}],[{"type":"text","text":"Boxes + labels"}],[{"type":"text","text":"YOLO, DETR"}]],[[{"type":"text","text":"Segmentation"}],[{"type":"text","text":"A label per pixel (semantic / instance)"}],[{"type":"text","text":"U-Net, Mask R-CNN, SAM"}]],[[{"type":"text","text":"Tracking, pose, depth"}],[{"type":"text","text":"Trajectories, keypoints, 3-D structure"}],[{"type":"text","text":"Specialised CNN/Transformer heads"}]],[[{"type":"text","text":"Generation & editing"}],[{"type":"text","text":"New images"}],[{"type":"text","text":"Diffusion models"}]],[[{"type":"text","text":"Vision–language"}],[{"type":"text","text":"Captions, answers about images"}],[{"type":"text","text":"CLIP-style encoders, multimodal LLMs"}]]]},"revision":1},{"id":"b2752611-deab-7374-bdee-42f45803ae1e","type":"text","position":"aE","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Vision went through the same shift as NLP: hand-designed features (edges, SIFT, HOG) + a classifier, replaced after 2012 by features "},{"type":"text","text":"learned","marks":[{"type":"italic"}]},{"type":"text","text":" end-to-end by CNNs, and more recently by Transformers and multimodal models."}]},{"type":"paragraph","content":[{"type":"text","text":"robotics · speech · recommender systems · autonomous vehicles · multi-agent systems · AI for science (protein folding) · neuro-symbolic AI"}]}]}},"revision":1},{"id":"6aeb4c71-bf75-7285-ad4d-bc3cba60984d","type":"question","position":"aF","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Is classical (symbolic) AI obsolete now that we have deep learning?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"No. Learning excels at perception and pattern-matching from data; search, planning, constraint solving and logic excel at exact, verifiable reasoning over explicit structure. Strong systems combine them — AlphaZero (MCTS + networks), LLM agents with planners and tools, RAG over knowledge graphs."}]}]}},"revision":1},{"id":"149384e2-4e08-76ef-bab8-ccc168b1a51b","type":"question","position":"aG","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is the difference between narrow AI systems today and AGI?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Today''s systems — even broad LLMs — are trained for particular distributions of tasks and fail in unfamiliar ways (hallucination, brittle planning). AGI would learn and perform essentially any intellectual task a human can, adapting robustly to new situations. Whether scaling current methods leads there is debated."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
