INSERT INTO "notes"."NoteVersion" ("id", "noteId", "number", "kind", "title", "cards", "createdById", "createdAt")
SELECT 'd21422b0-9d6c-72e8-81a2-4a0297fca054', '76e801fa-6222-7f9d-a10c-a7e2f6063cc5', 1, 'PUBLISHED', 'Problem Formulation & State Spaces', '[{"id":"9977b73c-0e4a-7dd5-ab11-e1f4635ba72a","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Before an agent can search for a solution, the problem must be stated precisely: what a state is, which actions exist, what they do, what counts as the goal and what each step costs. A good formulation can shrink the search space by orders of magnitude."}]}]}},"revision":1},{"id":"84146424-0326-7c54-8c2a-ae0a8bde54d8","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"The five components of a search problem"}]},"revision":1},{"id":"cd949a1e-fd0f-7c9e-b254-5e93aa1cf12c","type":"table","position":"a2","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Component"}],[{"type":"text","text":"Meaning"}],[{"type":"text","text":"Route finding (Romania)"}],[{"type":"text","text":"8-puzzle"}]],[[{"type":"text","text":"Initial state","marks":[{"type":"bold"}]}],[{"type":"text","text":"Where the agent starts"}],[{"type":"text","text":"In(Arad)"}],[{"type":"text","text":"A scrambled board"}]],[[{"type":"text","text":"Actions(s)","marks":[{"type":"bold"}]}],[{"type":"text","text":"Moves applicable in state "},{"type":"text","text":"s","marks":[{"type":"code"}]}],[{"type":"text","text":"Drive to a neighbouring city"}],[{"type":"text","text":"Slide the blank Up/Down/Left/Right"}]],[[{"type":"text","text":"Transition model","marks":[{"type":"bold"}]},{"type":"text","text":" Result(s, a)"}],[{"type":"text","text":"The state an action leads to"}],[{"type":"text","text":"In(Sibiu) after driving Arad → Sibiu"}],[{"type":"text","text":"Board with blank and tile swapped"}]],[[{"type":"text","text":"Goal test","marks":[{"type":"bold"}]}],[{"type":"text","text":"Is "},{"type":"text","text":"s","marks":[{"type":"code"}]},{"type":"text","text":" a goal?"}],[{"type":"text","text":"In(Bucharest)"}],[{"type":"text","text":"Tiles in order 0–8"}]],[[{"type":"text","text":"Path cost","marks":[{"type":"bold"}]}],[{"type":"text","text":"Sum of step costs "},{"type":"text","text":"c(s, a, s′)","marks":[{"type":"code"}]}],[{"type":"text","text":"Road kilometres"}],[{"type":"text","text":"1 per move"}]]]},"revision":1},{"id":"b35348d9-cfb1-7d6a-bf97-0591c9468948","type":"text","position":"a3","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Initial state + actions + transition model define the "},{"type":"text","text":"state space","marks":[{"type":"bold"}]},{"type":"text","text":" — a graph whose nodes are states and edges are actions. A "},{"type":"text","text":"solution","marks":[{"type":"bold"}]},{"type":"text","text":" is an action sequence from the initial state to a goal; an "},{"type":"text","text":"optimal","marks":[{"type":"bold"}]},{"type":"text","text":" solution has the lowest path cost."}]}]}},"revision":1},{"id":"189cb613-847d-7e7c-8c11-3f9fe72c7aa4","type":"heading","position":"a4","content":{"level":1,"content":[{"type":"text","text":"Formulating the 8-puzzle"}]},"revision":1},{"id":"e9443a49-7003-7c5b-953f-29f7cfc5298c","type":"code","position":"a5","content":{"language":"python","code":"from collections import deque\n\nGOAL = (0, 1, 2,\n        3, 4, 5,\n        6, 7, 8)                       # 0 is the blank\n\ndef actions(state):\n    row, col = divmod(state.index(0), 3)\n    moves = []\n    if row > 0: moves.append(\"Up\")\n    if row < 2: moves.append(\"Down\")\n    if col > 0: moves.append(\"Left\")\n    if col < 2: moves.append(\"Right\")\n    return moves\n\ndef result(state, action):              # transition model: slide the blank\n    i = state.index(0)\n    j = i + {\"Up\": -3, \"Down\": 3, \"Left\": -1, \"Right\": 1}[action]\n    s = list(state)\n    s[i], s[j] = s[j], s[i]\n    return tuple(s)\n\nstart = (3, 1, 2,\n         0, 4, 5,\n         6, 7, 8)\nprint(actions(start))                            # [''Up'', ''Down'', ''Right'']\nprint(result(start, \"Up\") == GOAL)               # True\n\n# the whole state space reachable from the goal, by breadth-first expansion\nseen, frontier = {GOAL}, deque([GOAL])\nwhile frontier:\n    s = frontier.popleft()\n    for a in actions(s):\n        t = result(s, a)\n        if t not in seen:\n            seen.add(t)\n            frontier.append(t)\nprint(len(seen))                                 # 181440 ← 9!/2: only half of all 9! boards are reachable","filename":"Python"},"revision":1},{"id":"a5662a02-3128-740e-ad04-988dbe2581cc","type":"heading","position":"a6","content":{"level":1,"content":[{"type":"text","text":"Formulation decides the size of the space"}]},"revision":1},{"id":"d53d73a7-76ec-73ab-a33c-68063909079c","type":"table","position":"a7","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Problem"}],[{"type":"text","text":"Formulation"}],[{"type":"text","text":"States"}]],[[{"type":"text","text":"8-queens"}],[{"type":"text","text":"Add queens anywhere, one at a time (64 squares, 8 queens)"}],[{"type":"text","text":"64 · 63 · … · 57 ≈ 1.8 × 10¹⁴ sequences"}]],[[{"type":"text","text":"8-queens"}],[{"type":"text","text":"One queen per column, left to right, never attacking an earlier one"}],[{"type":"text","text":"2,057"}]],[[{"type":"text","text":"8-puzzle"}],[{"type":"text","text":"All boards"}],[{"type":"text","text":"9!/2 = 181,440 reachable"}]],[[{"type":"text","text":"15-puzzle"}],[{"type":"text","text":"All boards"}],[{"type":"text","text":"16!/2 ≈ 1.05 × 10¹³"}]],[[{"type":"text","text":"Rubik''s cube"}],[{"type":"text","text":"All positions"}],[{"type":"text","text":"≈ 4.3 × 10¹⁹"}]]]},"revision":1},{"id":"0d20453e-a6a1-7954-88ed-345e37a11dca","type":"callout","position":"a8","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Abstraction","marks":[{"type":"bold"}]},{"type":"text","text":" is the art of formulation: drop every detail that doesn''t affect the solution (the radio, the weather, the exact route between cities). A good abstraction is valid (every abstract solution maps to a real one) and useful (the abstract actions are easy to carry out)."}]}]}},"revision":1},{"id":"2654229d-182a-7fa7-8927-7a17feac2c15","type":"heading","position":"a9","content":{"level":1,"content":[{"type":"text","text":"Search trees, frontiers and repeated states"}]},"revision":1},{"id":"d19d9eb0-4010-7ee1-96a3-2e8e2f2e0b74","type":"text","position":"aA","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Search algorithms grow a "},{"type":"text","text":"search tree","marks":[{"type":"bold"}]},{"type":"text","text":" over the state space. Each "},{"type":"text","text":"node","marks":[{"type":"bold"}]},{"type":"text","text":" stores a state, its parent, the action that produced it, the path cost "},{"type":"text","text":"g","marks":[{"type":"code"}]},{"type":"text","text":" and the depth. The "},{"type":"text","text":"frontier","marks":[{"type":"bold"}]},{"type":"text","text":" (open list) holds generated-but-not-expanded nodes; the order in which it is expanded is the "},{"type":"text","text":"only","marks":[{"type":"italic"}]},{"type":"text","text":" difference between most search strategies."}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Initialise","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Put a node for the initial state on the frontier."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Choose","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Remove a node from the frontier according to the strategy (FIFO, LIFO, lowest cost…)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Test","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"If its state is a goal, return the path (follow parent links back)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Expand","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Otherwise generate its children — one per applicable action — and add them to the frontier."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Repeat","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Until the frontier is empty → failure."}]}]}]}]}},"revision":1},{"id":"1116b0a3-acd8-78df-85c5-2d12b2d2f4a3","type":"callout","position":"aB","content":{"variant":"tip","title":"Do","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Use "},{"type":"text","text":"graph search","marks":[{"type":"bold"}]},{"type":"text","text":": keep a "},{"type":"text","text":"reached/explored","marks":[{"type":"italic"}]},{"type":"text","text":" set so each state is expanded at most once — cycles and redundant paths (A→B→A→B…) are pruned."}]}]}},"revision":1},{"id":"0ac83503-69f7-725e-90a1-9d1e0122ba1b","type":"callout","position":"aC","content":{"variant":"danger","title":"Avoid","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Plain "},{"type":"text","text":"tree search","marks":[{"type":"bold"}]},{"type":"text","text":" on a graph with cycles or many paths to the same state — it can loop forever or blow up exponentially."}]}]}},"revision":1},{"id":"9e92c7e1-b2cf-78aa-a3e7-2085709d1e01","type":"heading","position":"aD","content":{"level":1,"content":[{"type":"text","text":"Measuring a search strategy"}]},"revision":1},{"id":"ec6ee68d-2959-79b2-aec0-71c5ef5e8e56","type":"table","position":"aE","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Criterion"}],[{"type":"text","text":"Question"}],[{"type":"text","text":"Symbols used"}]],[[{"type":"text","text":"Completeness","marks":[{"type":"bold"}]}],[{"type":"text","text":"Is it guaranteed to find a solution when one exists?"}],[{"type":"text","text":"b","marks":[{"type":"code"}]},{"type":"text","text":" = branching factor (max children per node)"}]],[[{"type":"text","text":"Optimality","marks":[{"type":"bold"}]},{"type":"text","text":" (cost-optimal)"}],[{"type":"text","text":"Does it find the lowest-cost solution?"}],[{"type":"text","text":"d","marks":[{"type":"code"}]},{"type":"text","text":" = depth of the shallowest goal"}]],[[{"type":"text","text":"Time complexity","marks":[{"type":"bold"}]}],[{"type":"text","text":"How many nodes does it generate?"}],[{"type":"text","text":"m","marks":[{"type":"code"}]},{"type":"text","text":" = maximum depth of the state space (may be ∞)"}]],[[{"type":"text","text":"Space complexity","marks":[{"type":"bold"}]}],[{"type":"text","text":"How many nodes are in memory at once?"}],[{"type":"text","text":"C*","marks":[{"type":"code"}]},{"type":"text","text":" = optimal cost, "},{"type":"text","text":"ε","marks":[{"type":"code"}]},{"type":"text","text":" = smallest step cost"}]]]},"revision":1},{"id":"00015655-d09a-7b02-b452-7017b38dd6de","type":"question","position":"aF","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What are the components of a well-defined search problem?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Initial state, actions, transition model, goal test and path-cost function. The first three implicitly define the state space."}]}]}},"revision":1},{"id":"7879881a-c86c-77b2-94b1-f7bad5932bf9","type":"question","position":"aG","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is the difference between a state and a node?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A state is a configuration of the world. A node is a bookkeeping structure in the search tree: a state plus parent pointer, action, path cost and depth. The same state can appear in many nodes (reached by different paths)."}]}]}},"revision":1},{"id":"e65d7a2a-82eb-75e8-a940-e6a99744d141","type":"question","position":"aH","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Tree search vs graph search?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Graph search remembers visited states and never re-expands them, so it avoids loops and redundant paths at the cost of memory. Tree search keeps no such set and can revisit states indefinitely."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
WHERE EXISTS (SELECT 1 FROM "notes"."Note" n WHERE n.id = '76e801fa-6222-7f9d-a10c-a7e2f6063cc5' AND n."ownerId" = '019a118c-f480-7000-8000-000000000001' AND n."publishedVersionId" IS NULL AND n.visibility = 'PRIVATE' AND n."deletedAt" IS NULL AND n."draftUpdatedAt" = TIMESTAMPTZ '2026-10-07 03:23:53+00')
