INSERT INTO "notes"."NoteVersion" ("id", "noteId", "number", "kind", "title", "cards", "createdById", "createdAt")
SELECT '84d375dc-9a8f-7be6-9ff7-6e6c5ef35cf6', 'd2fb5420-62fd-7b04-b9c4-b0a9d282d35e', 1, 'PUBLISHED', 'Resolution, Forward & Backward Chaining', '[{"id":"ffa132eb-e4a3-7128-ae82-fca793d27772","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Resolution is a single inference rule that is complete for propositional logic when used for proof by contradiction. For the restricted but common "},{"type":"text","text":"Horn clause","marks":[{"type":"bold"}]},{"type":"text","text":" form, forward and backward chaining are simpler and run in linear time."}]}]}},"revision":1},{"id":"e1d4216c-6c80-7003-8147-e8a24ff88346","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Converting to CNF"}]},"revision":1},{"id":"4761d7e6-4701-72d5-8557-d34ac1501182","type":"text","position":"a2","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Resolution works on "},{"type":"text","text":"conjunctive normal form","marks":[{"type":"bold"}]},{"type":"text","text":" (CNF): a conjunction of "},{"type":"text","text":"clauses","marks":[{"type":"bold"}]},{"type":"text","text":", each a disjunction of literals. Any sentence can be converted:"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Eliminate ⇔","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"α ⇔ β","marks":[{"type":"code"}]},{"type":"text","text":" → "},{"type":"text","text":"(α ⇒ β) ∧ (β ⇒ α)","marks":[{"type":"code"}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Eliminate ⇒","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"α ⇒ β","marks":[{"type":"code"}]},{"type":"text","text":" → "},{"type":"text","text":"¬α ∨ β","marks":[{"type":"code"}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Move ¬ inwards","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"De Morgan and double negation until ¬ applies only to symbols"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Distribute ∨ over ∧","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"α ∨ (β ∧ γ)","marks":[{"type":"code"}]},{"type":"text","text":" → "},{"type":"text","text":"(α ∨ β) ∧ (α ∨ γ)","marks":[{"type":"code"}]}]}]}]}]}},"revision":1},{"id":"12570249-2623-72b7-8d30-f9dd3cb55aed","type":"callout","position":"a3","content":{"variant":"tip","title":"CNF example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"B ⇔ (P ∨ Q)","marks":[{"type":"code"}]},{"type":"text","text":" → "},{"type":"text","text":"(¬B ∨ P ∨ Q) ∧ (¬P ∨ B) ∧ (¬Q ∨ B)","marks":[{"type":"code"}]}]}]}},"revision":1},{"id":"79f177b8-7fc4-7363-9080-e0ea03dcf1a5","type":"heading","position":"a4","content":{"level":1,"content":[{"type":"text","text":"Resolution refutation"}]},"revision":1},{"id":"8bd2a6c7-8091-7ad0-9182-feb56ced7316","type":"text","position":"a5","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"To prove "},{"type":"text","text":"α","marks":[{"type":"code"}]},{"type":"text","text":": add "},{"type":"text","text":"¬α","marks":[{"type":"code"}]},{"type":"text","text":" to the KB''s clauses and resolve pairs of clauses with complementary literals. Deriving the "},{"type":"text","text":"empty clause","marks":[{"type":"bold"}]},{"type":"text","text":" (a contradiction) proves "},{"type":"text","text":"KB ⊨ α","marks":[{"type":"code"}]},{"type":"text","text":"; if no new clauses can be produced, "},{"type":"text","text":"α","marks":[{"type":"code"}]},{"type":"text","text":" is not entailed."}]}]}},"revision":1},{"id":"02839767-22d7-79e5-8a82-45f5e1aa18d3","type":"code","position":"a6","content":{"language":"python","code":"from itertools import combinations\n\ndef resolve(a, b):\n    out = []\n    for lit in sorted(a):\n        neg = lit[1:] if lit.startswith(\"~\") else \"~\" + lit\n        if neg in b:\n            out.append((a - {lit}) | (b - {neg}))\n    return out\n\ndef resolution(clauses, query):\n    neg = query[1:] if query.startswith(\"~\") else \"~\" + query\n    clauses = set(clauses) | {frozenset([neg])}              # add the negated goal\n    derived = []\n    while True:\n        new = set()\n        for a, b in combinations(sorted(clauses, key=sorted), 2):\n            for r in resolve(a, b):\n                if not r:\n                    return True, derived                     # empty clause: contradiction\n                if r not in clauses and r not in new:\n                    new.add(frozenset(r))\n                    derived.append(sorted(r))\n        if not new:\n            return False, derived                            # nothing new: not entailed\n        clauses |= new\n\n# KB:  P ⇒ Q,  Q ⇒ R,  P       as clauses: {¬P, Q}, {¬Q, R}, {P}\nkb = [frozenset({\"~P\", \"Q\"}), frozenset({\"~Q\", \"R\"}), frozenset({\"P\"})]\nproved, derived = resolution(kb, \"R\")\nprint(proved, derived)          # True [[''Q''], [''R'', ''~P''], [''~Q''], [''R'']]\nprint(resolution(kb, \"~R\")[0])  # False ← R is entailed, so ¬R is not","filename":"Python"},"revision":1},{"id":"c72fd006-1cf3-7a23-91a5-6e6e87d6ad3a","type":"callout","position":"a7","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Resolution is "},{"type":"text","text":"refutation-complete","marks":[{"type":"bold"}]},{"type":"text","text":": if "},{"type":"text","text":"KB ⊨ α","marks":[{"type":"code"}]},{"type":"text","text":", resolution on "},{"type":"text","text":"KB ∧ ¬α","marks":[{"type":"code"}]},{"type":"text","text":" will eventually derive the empty clause. Modern "},{"type":"text","text":"SAT solvers","marks":[{"type":"bold"}]},{"type":"text","text":" (DPLL / CDCL, WalkSAT) decide satisfiability of millions of clauses and power hardware verification, planning and scheduling."}]}]}},"revision":1},{"id":"ac3509bc-9bd3-78e2-8485-af5a3183d1e8","type":"heading","position":"a8","content":{"level":1,"content":[{"type":"text","text":"Horn clauses, forward and backward chaining"}]},"revision":1},{"id":"6efa8535-b1d6-78e6-82e2-cbdf617060b4","type":"callout","position":"a9","content":{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Definite / Horn clause","marks":[{"type":"bold"}]},{"type":"text","text":" — a clause with at most one positive literal — equivalently a rule "},{"type":"text","text":"A ∧ B ∧ … ⇒ C","marks":[{"type":"code"}]},{"type":"text","text":" or a fact "},{"type":"text","text":"C","marks":[{"type":"code"}]},{"type":"text","text":". Inference with Horn clauses takes time linear in the size of the KB and is easy for humans to read."}]}]}},"revision":1},{"id":"e6f3b451-31eb-7e9b-bbd0-772d63875c34","type":"text","position":"aA","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The textbook KB: "},{"type":"text","text":"P ⇒ Q","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"L ∧ M ⇒ P","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"B ∧ L ⇒ M","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"A ∧ P ⇒ L","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"A ∧ B ⇒ L","marks":[{"type":"code"}]},{"type":"text","text":", and facts "},{"type":"text","text":"A","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"B","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"4822c883-a7de-7c53-adb9-357e8dcdc01f","type":"code","position":"aB","content":{"language":"python","code":"RULES = [([\"P\"], \"Q\"), ([\"L\", \"M\"], \"P\"), ([\"B\", \"L\"], \"M\"), ([\"A\", \"P\"], \"L\"), ([\"A\", \"B\"], \"L\")]\nFACTS = [\"A\", \"B\"]\n\ndef forward_chain(rules, facts, query):\n    known, agenda, order = set(), list(facts), []\n    count = {i: len(prem) for i, (prem, _) in enumerate(rules)}    # unsatisfied premises per rule\n    while agenda:\n        p = agenda.pop(0)\n        if p in known:\n            continue\n        known.add(p)\n        order.append(p)\n        if p == query:\n            return True, order\n        for i, (prem, concl) in enumerate(rules):\n            if p in prem:\n                count[i] -= 1\n                if count[i] == 0:                                   # all premises known → fire\n                    agenda.append(concl)\n    return False, order\n\ndef backward_chain(rules, facts, goal, seen=()):\n    if goal in facts:\n        return True\n    if goal in seen:                                                # avoid looping on P ⇒ … ⇒ P\n        return False\n    return any(all(backward_chain(rules, facts, g, seen + (goal,)) for g in prem)\n               for prem, concl in rules if concl == goal)\n\nprint(forward_chain(RULES, FACTS, \"Q\"))     # (True, [''A'', ''B'', ''L'', ''M'', ''P'', ''Q''])\nprint(backward_chain(RULES, FACTS, \"Q\"))    # True\nprint(backward_chain(RULES, FACTS, \"Z\"))    # False ← no rule concludes Z","filename":"Python"},"revision":1},{"id":"5c5e4322-4824-7956-8a40-19ae4896f451","type":"table","position":"aC","content":{"hasHeaderRow":true,"rows":[[[],[{"type":"text","text":"Forward chaining"}],[{"type":"text","text":"Backward chaining"}]],[[{"type":"text","text":"Direction"}],[{"type":"text","text":"Data-driven","marks":[{"type":"bold"}]},{"type":"text","text":": from known facts to all consequences"}],[{"type":"text","text":"Goal-driven","marks":[{"type":"bold"}]},{"type":"text","text":": from the query back to facts"}]],[[{"type":"text","text":"Fires"}],[{"type":"text","text":"Every rule whose premises become true"}],[{"type":"text","text":"Only rules relevant to the goal"}]],[[{"type":"text","text":"Good for"}],[{"type":"text","text":"Monitoring, reacting to new data, deriving everything"}],[{"type":"text","text":"Answering specific questions"}]],[[{"type":"text","text":"Cost"}],[{"type":"text","text":"May derive many irrelevant facts"}],[{"type":"text","text":"Often much less than linear in KB size"}]],[[{"type":"text","text":"Used in"}],[{"type":"text","text":"Production systems, expert-system shells (CLIPS), Datalog"}],[{"type":"text","text":"Prolog, diagnostic systems (MYCIN)"}]]]},"revision":1},{"id":"3de851d5-2227-797e-ab13-23f3614d4c91","type":"question","position":"aD","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Explain resolution refutation."}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Convert KB ∧ ¬α to CNF, then repeatedly resolve pairs of clauses containing a literal and its negation, adding the resolvents. Deriving the empty clause shows KB ∧ ¬α is unsatisfiable, so KB ⊨ α. It''s sound and refutation-complete."}]}]}},"revision":1},{"id":"1f2f6161-1536-76fe-9793-eb06b6798107","type":"question","position":"aE","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Forward vs backward chaining — when to use which?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Forward chaining is data-driven: good when new facts arrive and you want all consequences (alerting, production systems). Backward chaining is goal-driven: good for answering a specific query, since it only explores rules relevant to the goal (Prolog, diagnosis)."}]}]}},"revision":1},{"id":"7d0169a6-a0dc-7164-b4aa-7b9143230474","type":"question","position":"aF","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is a Horn clause and why does it matter?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A clause with at most one positive literal, i.e. a rule with a single conclusion or a fact. With Horn clauses, entailment can be decided in linear time using forward or backward chaining, instead of the exponential worst case of general propositional inference."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
