INSERT INTO "notes"."NoteVersion" ("id", "noteId", "number", "kind", "title", "cards", "createdById", "createdAt")
SELECT '36b878dd-b05c-7199-b76e-e6f0b2746afa', '46f69a0d-4f2a-7f84-8ee1-a63141f21c39', 1, 'PUBLISHED', 'Simulated Annealing & Beam Search', '[{"id":"9ed2529d-751a-785e-a2f4-7fef7794564e","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Simulated annealing is hill climbing that sometimes accepts a "},{"type":"text","text":"worse","marks":[{"type":"italic"}]},{"type":"text","text":" move — often early on, rarely later — so it can shake itself out of local optima. Beam search keeps several states instead of one."}]},{"type":"paragraph","content":[{"type":"text","text":"The name comes from metallurgy: heating metal and cooling it slowly lets atoms settle into a low-energy crystal. The algorithm picks a "},{"type":"text","text":"random","marks":[{"type":"bold"}]},{"type":"text","text":" neighbour; if it is better it always moves, and if it is worse by "},{"type":"text","text":"ΔE","marks":[{"type":"code"}]},{"type":"text","text":" it moves with probability:"}]},{"type":"paragraph","content":[{"type":"text","text":"P(accept worse move) = e^(−ΔE / T)","marks":[{"type":"code"}]}]}]}},"revision":1},{"id":"562ed764-e082-74cf-b405-95ea14cac856","type":"code","position":"a1","content":{"language":"python","code":"import math\n\naccept = {T: [round(math.exp(-delta / T), 3) for delta in (1, 2, 5)] for T in (10, 1, 0.1)}\nprint(accept[10])      # [0.905, 0.819, 0.607] ← hot: almost any move is accepted (ΔE = 1, 2, 5)\nprint(accept[1])       # [0.368, 0.135, 0.007]\nprint(accept[0.1])     # [0.0, 0.0, 0.0] ← cold: pure hill climbing","filename":"Python"},"revision":1},{"id":"82dc8a3c-d1e9-71b2-8ecc-cd60e0b39df7","type":"text","position":"a2","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","text":"temperature","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"T","marks":[{"type":"code"}]},{"type":"text","text":" starts high (random walk) and decreases according to a "},{"type":"text","text":"schedule","marks":[{"type":"bold"}]},{"type":"text","text":" (e.g. "},{"type":"text","text":"T ← 0.99·T","marks":[{"type":"code"}]},{"type":"text","text":"). As "},{"type":"text","text":"T → 0","marks":[{"type":"code"}]},{"type":"text","text":" it becomes plain hill climbing. If "},{"type":"text","text":"T","marks":[{"type":"code"}]},{"type":"text","text":" is lowered slowly enough, it finds the global optimum with probability approaching 1."}]}]}},"revision":1},{"id":"9ec0044d-a5bc-742a-9577-5b94a25eb374","type":"code","position":"a3","content":{"language":"python","code":"import math\nimport random\n\ndef conflicts(s):\n    return sum(1 for i in range(8) for j in range(i + 1, 8) if s[i] == s[j] or abs(s[i] - s[j]) == j - i)\n\ndef simulated_annealing(state, T=2.0, cooling=0.995, steps=20000):\n    for t in range(steps):\n        if conflicts(state) == 0:\n            return state, t\n        col, row = random.randrange(8), random.randrange(8)\n        nxt = state[:col] + (row,) + state[col + 1:]           # a random neighbour\n        delta = conflicts(nxt) - conflicts(state)              # > 0 means worse\n        if delta <= 0 or random.random() < math.exp(-delta / T):\n            state = nxt\n        T = max(T * cooling, 1e-3)                             # cooling schedule\n    return state, steps\n\nrandom.seed(1)\nstart = tuple(random.randrange(8) for _ in range(8))      # the start where hill climbing got stuck\nend, t = simulated_annealing(start)\nprint(end, conflicts(end), t)                             # (2, 5, 7, 0, 3, 6, 4, 1) 0 711","filename":"Python"},"revision":1},{"id":"8bba91f4-5aa1-710f-ae30-28ca1a5887a9","type":"heading","position":"a4","content":{"level":1,"content":[{"type":"text","text":"Local beam search"}]},"revision":1},{"id":"30654367-b6fa-73b0-96f7-5c7cf7c180c0","type":"text","position":"a5","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Keep "},{"type":"text","text":"k","marks":[{"type":"bold"}]},{"type":"text","text":" states instead of one. Each step, generate all successors of all "},{"type":"text","text":"k","marks":[{"type":"code"}]},{"type":"text","text":" states and keep the best "},{"type":"text","text":"k","marks":[{"type":"code"}]},{"type":"text","text":" overall. Unlike "},{"type":"text","text":"k","marks":[{"type":"code"}]},{"type":"text","text":" independent restarts, information is shared: states on a good hill attract the whole beam."}]}]}},"revision":1},{"id":"80b86c18-7399-76a4-853f-79ac2ccbe753","type":"callout","position":"a6","content":{"variant":"note","title":"Local beam search","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Deterministic: top-"},{"type":"text","text":"k","marks":[{"type":"code"}]},{"type":"text","text":" of all successors. Risk: the beam collapses into one small region (lack of diversity)."}]}]}},"revision":1},{"id":"771e7c46-6b7e-7765-9ecb-153aab59c881","type":"callout","position":"a7","content":{"variant":"note","title":"Stochastic beam search","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Choose "},{"type":"text","text":"k","marks":[{"type":"code"}]},{"type":"text","text":" successors at random, weighted by value — keeps diversity. Resembles natural selection, leading to genetic algorithms."}]}]}},"revision":1},{"id":"c238442a-3898-71f2-a5b3-1cd005eda5a6","type":"callout","position":"a8","content":{"variant":"note","title":"Beam search in NLP","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The same idea decodes text from a language model: keep the "},{"type":"text","text":"k","marks":[{"type":"code"}]},{"type":"text","text":" most probable partial sentences at each step (see "},{"type":"text","text":"Generative AI","marks":[{"type":"bold"}]},{"type":"text","text":")."}]}]}},"revision":1},{"id":"b06de404-2904-7d7f-8928-81b37712952f","type":"table","position":"a9","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Method"}],[{"type":"text","text":"States kept"}],[{"type":"text","text":"Accepts worse moves?"}],[{"type":"text","text":"Complete?"}]],[[{"type":"text","text":"Hill climbing"}],[{"type":"text","text":"1"}],[{"type":"text","text":"No"}],[{"type":"text","text":"No"}]],[[{"type":"text","text":"Random-restart HC"}],[{"type":"text","text":"1 (many runs)"}],[{"type":"text","text":"No"}],[{"type":"text","text":"With probability → 1"}]],[[{"type":"text","text":"Simulated annealing"}],[{"type":"text","text":"1"}],[{"type":"text","text":"Yes, with prob. "},{"type":"text","text":"e^(−ΔE/T)","marks":[{"type":"code"}]}],[{"type":"text","text":"With a slow enough schedule (in the limit)"}]],[[{"type":"text","text":"Local beam search"}],[{"type":"text","text":"k","marks":[{"type":"code"}]}],[{"type":"text","text":"Only via the beam"}],[{"type":"text","text":"No"}]],[[{"type":"text","text":"Genetic algorithm"}],[{"type":"text","text":"Population"}],[{"type":"text","text":"Yes (selection is stochastic)"}],[{"type":"text","text":"No"}]]]},"revision":1},{"id":"49609ad9-1801-7408-800f-12d73c9a2349","type":"callout","position":"aA","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The cooling schedule is the hard part: too fast and it freezes in a local optimum like hill climbing; too slow and it wastes time as a random walk. Tune the start temperature so early acceptance of worse moves is high (~80%)."}]}]}},"revision":1},{"id":"d37fc446-a2d5-7e01-809f-2afa7d748471","type":"question","position":"aB","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How does simulated annealing escape local optima?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"It accepts worse moves with probability "},{"type":"text","text":"e^(−ΔE/T)","marks":[{"type":"code"}]},{"type":"text","text":". At high temperature many downhill moves are accepted (exploration); as "},{"type":"text","text":"T","marks":[{"type":"code"}]},{"type":"text","text":" falls, it accepts fewer and settles into a good optimum (exploitation)."}]}]}},"revision":1},{"id":"2abf7c2a-69fb-7e57-8b6d-94f5e1009a66","type":"question","position":"aC","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Local beam search vs k random restarts?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Restarts run independently. Beam search pools all successors and keeps the best "},{"type":"text","text":"k","marks":[{"type":"code"}]},{"type":"text","text":", so effort moves to the most promising regions — faster, but prone to losing diversity."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
