SELECT 'da011546-cd35-7527-8acb-7c9a8d87e312', '7b95f647-1bf4-7bc5-99b1-2e305b5f910f', 1, 'PUBLISHED', 'Uninformed Search: BFS, DFS & UCS', '[{"id":"11c3fbc3-bbda-7ffa-9817-c33b025cf00e","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Uninformed (blind) strategies know nothing about where the goal is — only how to generate successors and test for the goal. They differ solely in "},{"type":"text","text":"which frontier node to expand next","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"ddc63e40-afd3-7f24-9580-f9dbd3fa1a0d","type":"table","position":"a1","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Strategy"}],[{"type":"text","text":"Frontier"}],[{"type":"text","text":"Expands"}],[{"type":"text","text":"Finds"}]],[[{"type":"text","text":"Breadth-first (BFS)","marks":[{"type":"bold"}]}],[{"type":"text","text":"FIFO queue"}],[{"type":"text","text":"Shallowest node first — level by level"}],[{"type":"text","text":"The path with the "},{"type":"text","text":"fewest steps","marks":[{"type":"bold"}]}]],[[{"type":"text","text":"Depth-first (DFS)","marks":[{"type":"bold"}]}],[{"type":"text","text":"LIFO stack (or recursion)"}],[{"type":"text","text":"Deepest node first"}],[{"type":"text","text":"Some","marks":[{"type":"italic"}]},{"type":"text","text":" path — often long"}]],[[{"type":"text","text":"Uniform-cost (UCS)","marks":[{"type":"bold"}]}],[{"type":"text","text":"Priority queue on path cost "},{"type":"text","text":"g(n)","marks":[{"type":"code"}]}],[{"type":"text","text":"Cheapest-so-far node first"}],[{"type":"text","text":"The "},{"type":"text","text":"lowest-cost","marks":[{"type":"bold"}]},{"type":"text","text":" path (Dijkstra''s algorithm)"}]]]},"revision":1},{"id":"b96a23c2-3348-7ba3-ba05-6274ca7d852e","type":"heading","position":"a2","content":{"level":1,"content":[{"type":"text","text":"BFS and DFS on the Romania map"}]},"revision":1},{"id":"f6f3a532-06a2-784f-8971-c9f3a1675e90","type":"text","position":"a3","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The classic textbook example: drive from Arad to Bucharest. Roads have lengths in km; the neighbour order below is the order roads were listed."}]}]}},"revision":1},{"id":"2748fb7c-c067-74db-b809-a5b98461522e","type":"code","position":"a4","content":{"language":"python","code":"ROADS = \"\"\"Arad Zerind 75, Arad Sibiu 140, Arad Timisoara 118, Zerind Oradea 71, Oradea Sibiu 151,\nTimisoara Lugoj 111, Lugoj Mehadia 70, Mehadia Drobeta 75, Drobeta Craiova 120, Craiova Rimnicu 146,\nCraiova Pitesti 138, Sibiu Fagaras 99, Sibiu Rimnicu 80, Rimnicu Pitesti 97, Fagaras Bucharest 211,\nPitesti Bucharest 101, Bucharest Giurgiu 90, Bucharest Urziceni 85, Urziceni Hirsova 98,\nHirsova Eforie 86, Urziceni Vaslui 142, Vaslui Iasi 92, Iasi Neamt 87\"\"\"\ngraph = {}                                  # city -> {neighbour: road km}  (\"Rimnicu\" = Rimnicu Vilcea)\nfor road in ROADS.split(\",\"):\n    a, b, km = road.split()\n    graph.setdefault(a, {})[b] = int(km)\n    graph.setdefault(b, {})[a] = int(km)\n\nfrom collections import deque\n\ndef path(parent, node):\n    out = []\n    while node:\n        out.append(node)\n        node = parent[node]\n    return out[::-1]\n\ndef bfs(start, goal):\n    frontier, parent, expanded = deque([start]), {start: None}, 0\n    while frontier:\n        node = frontier.popleft()                     # FIFO: oldest node first\n        expanded += 1\n        for nbr in graph[node]:\n            if nbr not in parent:\n                parent[nbr] = node\n                if nbr == goal:                       # BFS may test the goal when a node is generated\n                    return path(parent, nbr), expanded\n                frontier.append(nbr)\n\ndef dfs(start, goal):\n    frontier, parent, expanded = [start], {start: None}, 0\n    while frontier:\n        node = frontier.pop()                         # LIFO: newest node first\n        if node == goal:\n            return path(parent, node), expanded\n        expanded += 1\n        for nbr in graph[node]:\n            if nbr not in parent:\n                parent[nbr] = node\n                frontier.append(nbr)\n\ndef cost(route):\n    return sum(graph[a][b] for a, b in zip(route, route[1:]))\n\nroute, n = bfs(\"Arad\", \"Bucharest\")\nprint(route, cost(route), n)     # [''Arad'', ''Sibiu'', ''Fagaras'', ''Bucharest''] 450 6\nroute, n = dfs(\"Arad\", \"Bucharest\")\nprint(route, cost(route), n)     # [''Arad'', ''Timisoara'', ''Lugoj'', ''Mehadia'', ''Drobeta'', ''Craiova'', ''Pitesti'', ''Bucharest''] 733 7","filename":"Python"},"revision":1},{"id":"bd5debfa-77bf-70d7-aee9-8b9d451d8c13","type":"text","position":"a5","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"BFS finds the route with the fewest roads (3), but it is "},{"type":"text","text":"not","marks":[{"type":"bold"}]},{"type":"text","text":" the shortest in km. DFS dives down whichever branch it pushed last and returns a much longer route."}]}]}},"revision":1},{"id":"7bed62dd-0352-71fc-9145-4aace4e62936","type":"heading","position":"a6","content":{"level":1,"content":[{"type":"text","text":"Uniform-cost search"}]},"revision":1},{"id":"ff1bcb70-7537-7286-a4d3-3839b549c5bc","type":"text","position":"a7","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"UCS always expands the frontier node with the lowest path cost "},{"type":"text","text":"g(n)","marks":[{"type":"code"}]},{"type":"text","text":". It must test for the goal when a node is "},{"type":"text","text":"popped","marks":[{"type":"bold"}]},{"type":"text","text":", not when it is generated — a cheaper route to the goal may still be on the frontier."}]}]}},"revision":1},{"id":"5d785217-aaf0-7661-9cdb-9cefde588f8d","type":"code","position":"a8","content":{"language":"python","code":"ROADS = \"\"\"Arad Zerind 75, Arad Sibiu 140, Arad Timisoara 118, Zerind Oradea 71, Oradea Sibiu 151,\nTimisoara Lugoj 111, Lugoj Mehadia 70, Mehadia Drobeta 75, Drobeta Craiova 120, Craiova Rimnicu 146,\nCraiova Pitesti 138, Sibiu Fagaras 99, Sibiu Rimnicu 80, Rimnicu Pitesti 97, Fagaras Bucharest 211,\nPitesti Bucharest 101, Bucharest Giurgiu 90, Bucharest Urziceni 85, Urziceni Hirsova 98,\nHirsova Eforie 86, Urziceni Vaslui 142, Vaslui Iasi 92, Iasi Neamt 87\"\"\"\ngraph = {}                                  # city -> {neighbour: road km}  (\"Rimnicu\" = Rimnicu Vilcea)\nfor road in ROADS.split(\",\"):\n    a, b, km = road.split()\n    graph.setdefault(a, {})[b] = int(km)\n    graph.setdefault(b, {})[a] = int(km)\n\nimport heapq\n\ndef ucs(start, goal):\n    frontier = [(0, start)]                           # (path cost g, city)\n    best, parent, expanded = {start: 0}, {start: None}, []\n    while frontier:\n        g, node = heapq.heappop(frontier)\n        if node == goal:                              # goal test on expansion → optimal\n            route = [node]\n            while parent[route[-1]]:\n                route.append(parent[route[-1]])\n            return route[::-1], g, expanded\n        if g > best[node]:\n            continue                                  # stale entry: a cheaper path was found later\n        expanded.append(node)\n        for nbr, km in graph[node].items():\n            if g + km < best.get(nbr, float(\"inf\")):\n                best[nbr], parent[nbr] = g + km, node\n                heapq.heappush(frontier, (g + km, nbr))\n\nroute, g, expanded = ucs(\"Arad\", \"Bucharest\")\nprint(route, g)          # [''Arad'', ''Sibiu'', ''Rimnicu'', ''Pitesti'', ''Bucharest''] 418\nprint(len(expanded))     # 12\nprint(expanded[:6])      # [''Arad'', ''Zerind'', ''Timisoara'', ''Sibiu'', ''Oradea'', ''Rimnicu'']","filename":"Python"},"revision":1},{"id":"4d2b5b6d-90fd-7669-96cc-abf6337b152e","type":"callout","position":"a9","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"UCS is Dijkstra''s algorithm stopped at the goal. It expands nodes in rings of increasing cost — in all directions, because it has no idea where Bucharest is. Adding that knowledge gives A* (see "},{"type":"text","text":"Informed Search","marks":[{"type":"bold"}]},{"type":"text","text":")."}]}]}},"revision":1},{"id":"487002c0-9681-73e1-b1c2-f29b3f1752eb","type":"table","position":"aA","content":{"hasHeaderRow":true,"rows":[[[],[{"type":"text","text":"BFS"}],[{"type":"text","text":"DFS"}],[{"type":"text","text":"UCS"}]],[[{"type":"text","text":"Complete?"}],[{"type":"text","text":"Yes (finite "},{"type":"text","text":"b","marks":[{"type":"code"}]},{"type":"text","text":")"}],[{"type":"text","text":"No in infinite spaces or with loops (tree search); yes for finite graph search"}],[{"type":"text","text":"Yes if every step cost ≥ "},{"type":"text","text":"ε > 0","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Optimal?"}],[{"type":"text","text":"Only if all step costs are equal"}],[{"type":"text","text":"No"}],[{"type":"text","text":"Yes"}]],[[{"type":"text","text":"Time"}],[{"type":"text","text":"O(bᵈ)","marks":[{"type":"code"}]}],[{"type":"text","text":"O(bᵐ)","marks":[{"type":"code"}]}],[{"type":"text","text":"O(b^(1 + ⌊C*/ε⌋))","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Space"}],[{"type":"text","text":"O(bᵈ)","marks":[{"type":"code"}]},{"type":"text","text":" — keeps the whole frontier"}],[{"type":"text","text":"O(bm)","marks":[{"type":"code"}]},{"type":"text","text":" — only the current path + siblings"}],[{"type":"text","text":"O(b^(1 + ⌊C*/ε⌋))","marks":[{"type":"code"}]}]]]},"revision":1},{"id":"b71a2655-82f1-7b1b-a889-e882d03d2af7","type":"callout","position":"aB","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"BFS''s real problem is "},{"type":"text","text":"memory","marks":[{"type":"bold"}]},{"type":"text","text":", not time: at "},{"type":"text","text":"b = 10","marks":[{"type":"code"}]},{"type":"text","text":", depth 10 means ~10¹⁰ nodes in memory — terabytes. DFS uses linear memory but can wander down an infinite branch."}]}]}},"revision":1},{"id":"e7838f16-eff3-70e7-a415-49f8fda10dd0","type":"question","position":"aC","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"When is BFS optimal?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"When every action has the same cost (or cost is a non-decreasing function of depth). Then the shallowest goal is also the cheapest. With varied step costs use UCS."}]}]}},"revision":1},{"id":"05ff0849-26cc-79ea-a245-5dc62ea64598","type":"question","position":"aD","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why must UCS test the goal on expansion rather than generation?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"When the goal is first generated it may be via an expensive edge (Fagaras → Bucharest, total 450) while a cheaper route (via Pitesti, 418) is still on the frontier. Waiting until the goal is popped guarantees it''s the cheapest."}]}]}},"revision":1},{"id":"0e5b4269-0b0f-7678-a7ab-d554cb9f9216","type":"question","position":"aE","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Is Dijkstra''s algorithm the same as UCS?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Essentially yes. Dijkstra computes shortest paths from a source to all nodes in an explicit graph; UCS stops at the goal and works on implicit graphs generated on the fly."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
