SELECT c.id::uuid, 'b3ab52d9-7d8a-73af-9c90-f8a2d74919aa', c.position, c.type::"notes"."CardType", c.content::jsonb, 1, TIMESTAMPTZ '2026-10-07 03:23:53+00', TIMESTAMPTZ '2026-10-07 03:23:53+00'
FROM (VALUES
  ('0eeeefbc-91cc-73a1-aafd-492c7e7dff64', 'a0', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Artificial Intelligence is the study and construction of "},{"type":"text","text":"agents that act intelligently","marks":[{"type":"bold"}]},{"type":"text","text":" — systems that perceive their situation, reason about it and choose actions that achieve goals. Machine learning is one (now dominant) way to build them; search, logic and probability are the others."}]}]}}'),
  ('c1c3b714-dc02-77a1-b816-e87f4cb5736e', 'a1', 'callout', '{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Artificial Intelligence","marks":[{"type":"bold"}]},{"type":"text","text":" — the field that builds computer systems able to perform tasks that normally need human intelligence — perceiving, reasoning, planning, learning, understanding language and acting in the world."}]}]}}'),
  ('84d2093a-bef5-773b-873a-bc6de9b2ec53', 'a2', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Artificial Intelligence → Machine Learning → Deep Learning → Generative AI / LLMs"}]},{"type":"paragraph","content":[{"type":"text","text":"Every arrow is a "},{"type":"text","text":"subset","marks":[{"type":"italic"}]},{"type":"text","text":": all deep learning is machine learning, and all machine learning is AI — but a chess engine using search, a route planner using A* and a medical expert system using rules are AI "},{"type":"text","text":"without","marks":[{"type":"bold"}]},{"type":"text","text":" any learning. Those classical techniques are what this subject covers; learning-based AI has its own notes ("},{"type":"text","text":"Machine Learning","marks":[{"type":"bold"}]},{"type":"text","text":", "},{"type":"text","text":"Deep Learning","marks":[{"type":"bold"}]},{"type":"text","text":", "},{"type":"text","text":"Generative AI","marks":[{"type":"bold"}]},{"type":"text","text":")."}]}]}}'),
  ('98a4637e-7529-759a-b1bc-95222a89eb70', 'a3', 'heading', '{"level":1,"content":[{"type":"text","text":"Four ways to define AI"}]}'),
  ('7083bc09-7837-7119-a65d-b9bf7c58d234', 'a4', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Russell & Norvig''s classic textbook sorts definitions along two axes — "},{"type":"text","text":"thinking","marks":[{"type":"italic"}]},{"type":"text","text":" vs "},{"type":"text","text":"acting","marks":[{"type":"italic"}]},{"type":"text","text":", and matching "},{"type":"text","text":"humans","marks":[{"type":"italic"}]},{"type":"text","text":" vs being "},{"type":"text","text":"rational","marks":[{"type":"italic"}]},{"type":"text","text":" (doing the right thing):"}]}]}}'),
  ('7844f194-83d9-7d20-a39d-8f213e1d7491', 'a5', 'table', '{"hasHeaderRow":true,"rows":[[[],[{"type":"text","text":"Human-like"}],[{"type":"text","text":"Rational"}]],[[{"type":"text","text":"Thinking","marks":[{"type":"bold"}]}],[{"type":"text","text":"Thinking humanly","marks":[{"type":"italic"}]},{"type":"text","text":" — cognitive modelling: build programs that reason the way people do (cognitive science)"}],[{"type":"text","text":"Thinking rationally","marks":[{"type":"italic"}]},{"type":"text","text":" — the “laws of thought”: correct inference with formal logic"}]],[[{"type":"text","text":"Acting","marks":[{"type":"bold"}]}],[{"type":"text","text":"Acting humanly","marks":[{"type":"italic"}]},{"type":"text","text":" — the Turing test: behave indistinguishably from a person"}],[{"type":"text","text":"Acting rationally","marks":[{"type":"italic"}]},{"type":"text","text":" — the "},{"type":"text","text":"rational agent","marks":[{"type":"bold"}]},{"type":"text","text":": act to achieve the best expected outcome"}]]]}'),
  ('c564d19f-e67e-7e7a-858a-4201cb338426', 'a6', 'callout', '{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Modern AI mostly follows the "},{"type":"text","text":"rational agent","marks":[{"type":"bold"}]},{"type":"text","text":" approach: it is general (logic is one tool, not the only one), and “best expected outcome” is mathematically precise — unlike “human-like”."}]}]}}'),
  ('df748fad-a457-7f1b-8110-48942c6f25dc', 'a7', 'heading', '{"level":1,"content":[{"type":"text","text":"The Turing test and the Chinese room"}]}'),
  ('b6235478-1443-7e8d-b252-73eb262407b3', 'a8', 'callout', '{"variant":"note","title":"Turing test (1950)","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A human judge chats by text with a hidden person and a hidden machine. If the judge can''t reliably tell which is which, the machine passes. Passing needs natural-language processing, knowledge representation, automated reasoning and machine learning. The "},{"type":"text","text":"total","marks":[{"type":"italic"}]},{"type":"text","text":" Turing test adds computer vision and robotics."}]}]}}'),
  ('3a5167eb-1cd4-7e92-b0af-2e366c7979ae', 'a9', 'callout', '{"variant":"note","title":"Chinese room (Searle, 1980)","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A person who knows no Chinese follows a rulebook to answer Chinese notes and looks fluent from outside. Searle''s point: manipulating symbols (syntax) is not the same as understanding (semantics) — so passing the Turing test would not prove a machine "},{"type":"text","text":"thinks","marks":[{"type":"italic"}]},{"type":"text","text":"."}]}]}}'),
  ('7b028221-0793-7577-a4bd-5ccca68527f6', 'aA', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A 1966 program already shows why "},{"type":"text","text":"acting","marks":[{"type":"italic"}]},{"type":"text","text":" human is a weak test of "},{"type":"text","text":"being","marks":[{"type":"italic"}]},{"type":"text","text":" intelligent. ELIZA imitated a therapist with a handful of pattern → template rules and no understanding at all:"}]}]}}'),
  ('84660038-1bd2-7cdf-8cd7-907252312680', 'aB', 'code', '{"language":"python","code":"import re\n\nRULES = [                                  # tried in order; the last one always matches\n    (r\"I need (.*)\", \"Why do you need {0}?\"),\n    (r\"I am (.*)\", \"How long have you been {0}?\"),\n    (r\".*\\bmother\\b.*\", \"Tell me more about your family.\"),\n    (r\"(.*)\", \"Please, go on.\"),\n]\nREFLECT = {\"my\": \"your\", \"me\": \"you\", \"i\": \"you\", \"am\": \"are\"}\n\ndef eliza(text):\n    for pattern, reply in RULES:\n        m = re.fullmatch(pattern, text.rstrip(\".!\"), re.IGNORECASE)\n        if m:\n            parts = [\" \".join(REFLECT.get(w.lower(), w) for w in g.split()) for g in m.groups()]\n            return reply.format(*parts)\n\nprint(eliza(\"I need a holiday\"))                  # Why do you need a holiday?\nprint(eliza(\"I am worried about my exams.\"))      # How long have you been worried about your exams?\nprint(eliza(\"My mother calls every day\"))         # Tell me more about your family.\nprint(eliza(\"The weather is nice\"))               # Please, go on.","filename":"Python"}'),
  ('e796e7c1-19cb-7670-b95f-502ec13f3622', 'aC', 'heading', '{"level":1,"content":[{"type":"text","text":"Weak vs strong, narrow vs general"}]}'),
  ('f76cefac-6d11-7de6-aa48-d74064137bc7', 'aD', 'table', '{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Term"}],[{"type":"text","text":"Meaning"}],[{"type":"text","text":"Status"}]],[[{"type":"text","text":"Weak AI","marks":[{"type":"bold"}]}],[{"type":"text","text":"Machines can "},{"type":"text","text":"act as if","marks":[{"type":"italic"}]},{"type":"text","text":" they were intelligent"}],[{"type":"text","text":"Philosophical claim — widely accepted"}]],[[{"type":"text","text":"Strong AI","marks":[{"type":"bold"}]}],[{"type":"text","text":"Machines that act intelligently really "},{"type":"text","text":"think","marks":[{"type":"italic"}]},{"type":"text","text":" / have minds"}],[{"type":"text","text":"Philosophical claim — open (Chinese room debate)"}]],[[{"type":"text","text":"Narrow AI (ANI)","marks":[{"type":"bold"}]}],[{"type":"text","text":"Excels at one task or domain: chess, face recognition, spam filtering, translation"}],[{"type":"text","text":"Every deployed system today"}]],[[{"type":"text","text":"General AI (AGI)","marks":[{"type":"bold"}]}],[{"type":"text","text":"Human-level competence across essentially all cognitive tasks, able to transfer and learn new ones"}],[{"type":"text","text":"Research goal; LLMs are broader than older systems but debated"}]],[[{"type":"text","text":"Superintelligence (ASI)","marks":[{"type":"bold"}]}],[{"type":"text","text":"Far exceeds humans in every domain"}],[{"type":"text","text":"Hypothetical — central to AI-safety discussions"}]]]}'),
  ('7c2436b8-8afc-72ff-8dd1-0b2741dc9872', 'aE', 'callout', '{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Don''t mix the two pairs up: "},{"type":"text","text":"weak/strong","marks":[{"type":"italic"}]},{"type":"text","text":" is about whether the machine has a mind; "},{"type":"text","text":"narrow/general","marks":[{"type":"italic"}]},{"type":"text","text":" is about how many tasks it can do. A system could in principle be general but “weak”."}]}]}}'),
