INSERT INTO "notes"."NoteVersion" ("id", "noteId", "number", "kind", "title", "cards", "createdById", "createdAt")
SELECT '1a5dc92f-e229-70ee-b46a-17184879e277', 'eda16518-9da8-710a-8319-e1ce1add33b5', 1, 'PUBLISHED', 'AI Architecture', '[{"id":"0b73f968-f245-719d-a033-32932cfdc877","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How to design large-scale infrastructure for GenAI applications."}]}]}},"revision":1},{"id":"81bcf867-370e-7e8f-902a-70511ab3035b","type":"callout","position":"a1","content":{"variant":"note","title":"LLM APIs vs Local Models","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"- "},{"type":"text","text":"APIs (OpenAI, Gemini)","marks":[{"type":"bold"}]},{"type":"text","text":": Serverless, state-of-the-art reasoning, no hosting overhead. High variable cost, rate limits, data privacy/compliance concerns."},{"type":"hardBreak"},{"type":"text","text":" - "},{"type":"text","text":"Local (Llama, Mistral)","marks":[{"type":"bold"}]},{"type":"text","text":": Hosted on private GPUs. Fixed cost, data privacy control, low latency (if cached). Requires complex infrastructure setup and GPU maintenance."}]}]}},"revision":1},{"id":"4d14e865-a280-7c2f-8f70-4a4aee4908fa","type":"callout","position":"a2","content":{"variant":"note","title":"Latency & GPU Inference","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"LLM latency is broken into: "},{"type":"hardBreak"},{"type":"text","text":"- "},{"type":"text","text":"Time-to-First-Token (TTFT)","marks":[{"type":"bold"}]},{"type":"text","text":": Time taken to process the input prompt (prefill phase). Compute bound (all prompt tokens processed in parallel). "},{"type":"hardBreak"},{"type":"text","text":"- "},{"type":"text","text":"Inter-Token Latency (ITL)","marks":[{"type":"bold"}]},{"type":"text","text":": Time taken to generate subsequent tokens autoregressively. Memory-bandwidth bound (weights and KV cache are re-read for every token)."}]}]}},"revision":1},{"id":"2e0c9ecb-133a-78a8-b602-b1ee1961dfdc","type":"heading","position":"a3","content":{"level":1,"content":[{"type":"text","text":"Operational Optimizations"}]},"revision":1},{"id":"76e7b3b5-b553-7c1c-ae11-053e2b50ee21","type":"callout","position":"a4","content":{"variant":"note","title":"Streaming","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Pushing tokens to the client via Server-Sent Events (SSE) as they are generated, rather than waiting for the entire sequence to complete. This drastically reduces perceived latency for the user."}]}]}},"revision":1},{"id":"5d27830d-caca-7b82-8e56-066839b263f0","type":"callout","position":"a5","content":{"variant":"note","title":"Prompt Caching","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Caching the key-value states of long prefix prompts (like system prompts or large context segments) on the inference server (or by the API provider). If a subsequent request shares the same prefix, we skip the prefill calculations, cutting TTFT and API costs by up to 90%."}]}]}},"revision":1},{"id":"35c8aac7-a908-7807-93c3-ae745a2a037f","type":"callout","position":"a6","content":{"variant":"note","title":"Tool Calling / Function Calling","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The model outputs structured arguments (JSON) indicating a function it wants to invoke (e.g., "},{"type":"text","text":"get_weather(location=\"Seattle\")","marks":[{"type":"code"}]},{"type":"text","text":"). The backend executes the function, feeds the result back to the model, and the model synthesizes the final response."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
WHERE EXISTS (SELECT 1 FROM "notes"."Note" n WHERE n.id = 'eda16518-9da8-710a-8319-e1ce1add33b5' AND n."ownerId" = '019a118c-f480-7000-8000-000000000001' AND n."publishedVersionId" IS NULL AND n.visibility = 'PRIVATE' AND n."deletedAt" IS NULL AND n."draftUpdatedAt" = TIMESTAMPTZ '2026-10-07 03:23:53+00')
ON CONFLICT DO NOTHING;

