  WHERE n.id = '97de74a6-8f1b-7736-8719-e600bd9821b2' AND n.visibility = 'PUBLIC' AND n."publishedVersionId" = '82b7cca8-6950-7556-a4ff-16d97727c913' AND n."deletedAt" IS NULL
