SELECT 'e389bc8a-7293-7461-8446-12b5e4149920', 'fe803151-c570-7737-ad8e-589d32d02ffa', 1, 'PUBLISHED', 'Fine-Tuning & PEFT', '[{"id":"ddcbd240-c6c1-703b-b6fe-aa0b087a7a18","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Updating weights to adapt models for specific formatting, behavior, and specialized tasks."}]}]}},"revision":1},{"id":"4ee3a87a-7162-712f-8bac-173a9e48858c","type":"callout","position":"a1","content":{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Fine-Tuning","marks":[{"type":"bold"}]},{"type":"text","text":" updates the model parameters. "},{"type":"text","text":"PEFT (Parameter-Efficient Fine-Tuning)","marks":[{"type":"bold"}]},{"type":"text","text":" updates a tiny subset of parameters (e.g., <1%) to make custom fine-tuning achievable on consumer hardware."}]}]}},"revision":1},{"id":"4753c678-c646-75e9-90b5-e637240c5a94","type":"heading","position":"a2","content":{"level":1,"content":[{"type":"text","text":"PEFT Methodologies"}]},"revision":1},{"id":"519df4b0-1181-7829-9070-e0655c4d1384","type":"callout","position":"a3","content":{"variant":"note","title":"LoRA (Low-Rank Adaptation)","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Instead of updating the full high-dimensional weight matrix (W"},{"type":"text","text":"0","marks":[{"type":"subscript"}]},{"type":"text","text":"), LoRA freezes it and injects two smaller low-rank decomposition matrices (A and B) alongside it. This cuts trainable parameters by orders of magnitude (up to 10,000x for GPT-3 175B in the original paper) and greatly reduces GPU memory."}]},{"type":"paragraph","content":[{"type":"text","text":"W_new = W_0 + (alpha/r) * (B * A)   // B: d×r, A: r×k, small rank r (e.g., r=8 or r=16)","marks":[{"type":"code"}]}]}]}},"revision":1},{"id":"28cf4952-cb9e-7adc-9705-57d81ac9b4cb","type":"callout","position":"a4","conte