INSERT INTO "notes"."NoteVersion" ("id", "noteId", "number", "kind", "title", "cards", "createdById", "createdAt")
SELECT '2f38d305-b8d9-7f77-b94a-7adebece93fb', 'efe30f5c-7546-728c-b34f-e6c1c010e912', 1, 'PUBLISHED', 'L2: Interview Q&A', '[{"id":"93753c29-d930-70ba-840a-aab0302f4943","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Detailed interview answers on GenAI systems mechanics. Read-times are approximately 2-3 minutes per answer."}]}]}},"revision":1},{"id":"be13f440-7fdd-7250-9f5b-c02d49a2d739","type":"question","position":"a1","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"\"Explain RAG.\""}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Fast Answer:","marks":[{"type":"bold"}]},{"type":"text","text":" Retrieving relevant text snippets from a database and injecting them into the LLM prompt so it can answer questions based on private facts."}]},{"type":"paragraph","content":[{"type":"text","text":"Retrieval-Augmented Generation (RAG) is an architectural pattern designed to optimize LLM outputs without training. It has two parts: "},{"type":"hardBreak"},{"type":"text","text":"1. "},{"type":"text","text":"Ingestion","marks":[{"type":"bold"}]},{"type":"text","text":": Documents are split into chunks, converted to vector embeddings, and stored in a Vector DB. "},{"type":"hardBreak"},{"type":"text","text":"2. "},{"type":"text","text":"Query","marks":[{"type":"bold"}]},{"type":"text","text":": When a user asks a question, we compute its embedding, query the Vector DB for the top-k semantically closest document chunks, construct a prompt combining these chunks with the user question, and pass it to the LLM. The LLM synthesizes a response grounded in the retrieved context, which reduces (but does not eliminate) hallucinations and enables source citation."}]}]}},"revision":1},{"id":"5c8b5d93-5924-7e66-b50b-3402d309ea0d","type":"question","position":"a2","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"\"Difference between RAG and Fine Tuning.\""}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Fast Answer:","marks":[{"type":"bold"}]},{"type":"text","text":" RAG provides external context at query time (fact-lookup). Fine-tuning adjusts the model weights (behavior/style adjustment)."}]},{"type":"paragraph","content":[{"type":"text","text":"Think of RAG as giving the LLM an open-book exam: the model reads relevant pages to answer questions. Think of Fine-Tuning as having the model study for weeks: it changes internal weight states so it remembers formatting structures, style rules, or domain behaviors. Use "},{"type":"text","text":"RAG","marks":[{"type":"bold"}]},{"type":"text","text":" for dynamic fact lookup, document search, and real-time updates. Use "},{"type":"text","text":"Fine-Tuning","marks":[{"type":"bold"}]},{"type":"text","text":" to teach formatting schemas (e.g. JSON), custom tones, code syntaxes, or to optimize smaller open-source models for specialized tasks."}]}]}},"revision":1},{"id":"dd06d300-f27b-70e0-9dad-11b55d9c7569","type":"question","position":"a3","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"\"How do embeddings work?\""}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Fast Answer:","marks":[{"type":"bold"}]},{"type":"text","text":" They map words/sentences into high-dimensional vectors where semantic similarity correlates with geometric proximity."}]},{"type":"paragraph","content":[{"type":"text","text":"An embedding model processes a string of text and outputs a dense vector of floating-point numbers (e.g., 1536 floats). The model has been trained to assign vectors such that words with similar meanings (e.g., \"king\" and \"queen\") point in similar geometric directions in this multi-dimensional space. The distance or angle between these vectors is measured to calculate how semantically similar two concepts are."}]}]}},"revision":1},{"id":"21345dc7-46a5-72e7-8014-5e44250a7c0a","type":"question","position":"a4","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"\"Why cosine similarity?\""}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Fast Answer:","marks":[{"type":"bold"}]},{"type":"text","text":" It measures vector alignment direction rather than magnitude, making it length-invariant and fast to compute."}]},{"type":"paragraph","content":[{"type":"text","text":"Cosine similarity calculates the cosine of the angle between two vectors: "},{"type":"hardBreak"},{"type":"text","text":"Similarity = (A · B) / (‖A‖ × ‖B‖) "},{"type":"hardBreak"},{"type":"text","text":"In text embedding space, magnitude (vector length) often correlates with text frequency or document length. Cosine similarity factors out length, focusing purely on semantic direction. Furthermore, if vectors are normalized to unit length, cosine similarity is simply the dot product, making calculations extremely fast on GPUs."}]}]}},"revision":1},{"id":"7fc8532f-eefa-7e58-b9e9-0e72fa9062f0","type":"question","position":"a5","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"\"How does GPT generate text?\""}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Fast Answer:","marks":[{"type":"bold"}]},{"type":"text","text":" Autoregressively. It predicts the next token based on previous tokens, selects one, appends it, and repeats."}]},{"type":"paragraph","content":[{"type":"text","text":"GPT models are autoregressive decoder-only Transformers. The generation loop is: "},{"type":"hardBreak"},{"type":"text","text":"1. Feed the sequence of existing tokens (the prompt) into the model. "},{"type":"hardBreak"},{"type":"text","text":"2. The model outputs a probability distribution over the entire vocabulary for the next slot. "},{"type":"hardBreak"},{"type":"text","text":"3. We sample a token based on this distribution (configured by temperature, top-k/top-p). "},{"type":"hardBreak"},{"type":"text","text":"4. Append the selected token to the input sequence and feed it back into the model to predict the next token. "},{"type":"hardBreak"},{"type":"text","text":"This continues until the model outputs an End-of-Sequence (EOS) token or reaches limits."}]}]}},"revision":1},{"id":"31335e32-144a-7c62-a6c5-3f3a7f5b9fdd","type":"question","position":"a6","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"\"Explain Self Attention.\""}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Fast Answer:","marks":[{"type":"bold"}]},{"type":"text","text":" A mechanism allowing tokens in a sequence to calculate how much relevance they have to every other token."}]},{"type":"paragraph","content":[{"type":"text","text":"Self-attention computes dynamic attention weights between tokens. For each input token, the model projects: "},{"type":"hardBreak"},{"type":"text","text":"- "},{"type":"text","text":"Query (Q)","marks":[{"type":"bold"}]},{"type":"text","text":": What context it is searching for. "},{"type":"hardBreak"},{"type":"text","text":"- "},{"type":"text","text":"Key (K)","marks":[{"type":"bold"}]},{"type":"text","text":": What information profile it offers. "},{"type":"hardBreak"},{"type":"text","text":"- "},{"type":"text","text":"Value (V)","marks":[{"type":"bold"}]},{"type":"text","text":": The actual payload content. "},{"type":"hardBreak"},{"type":"text","text":"We compute attention scores by calculating the dot product of all Queries with all Keys, scaling it (dividing by √d"},{"type":"text","text":"k","marks":[{"type":"subscript"}]},{"type":"text","text":"), applying Softmax to get percentages, and multiplying these weights by the Values: "},{"type":"hardBreak"},{"type":"text","text":"$\\text{Attention}(Q, K, V) = \\text{softmax}\\left(\\frac{Q K^T}{\\sqrt{d_k}}\\right) V$ "},{"type":"hardBreak"},{"type":"text","text":"This allows tokens to gather context dynamically (e.g., in \"The bank of the river,\" the token \"bank\" attends heavily to \"river\", steering it toward the riverbank sense rather than the financial one)."}]}]}},"revision":1},{"id":"3de6ad65-2ebc-7cf6-949d-b58e2c0c7f97","type":"question","position":"a7","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"\"Difference between GPT and BERT.\""}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Fast Answer:","marks":[{"type":"bold"}]},{"type":"text","text":" GPT is decoder-only, autoregressive, and causal (generates text). BERT is encoder-only, non-generative, and bidirectional (extracts context)."}]},{"type":"paragraph","content":[{"type":"text","text":"GPT","marks":[{"type":"bold"}]},{"type":"text","text":" is built on stacked masked Decoder blocks. It uses causal attention, meaning a token can only look at preceding tokens, making it optimized for next-token prediction and generation. "},{"type":"text","text":"BERT","marks":[{"type":"bold"}]},{"type":"text","text":" is built on stacked Encoder blocks. It has no causal mask, meaning tokens can attend bidirectionally to both past and future positions, making it optimal for feature extraction, semantic search representation, and classification tasks but unable to generate text sequence outputs."}]}]}},"revision":1},{"id":"6c0b3cb3-f0d1-7006-b00b-0ff44497bece","type":"question","position":"a8","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"\"When should we use Fine Tuning?\""}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Fast Answer:","marks":[{"type":"bold"}]},{"type":"text","text":" Use it to teach a model custom styles, strict formatting outputs, domain jargon, or to compress performance into a smaller model."}]},{"type":"paragraph","content":[{"type":"text","text":"Fine-tuning is recommended when: "},{"type":"hardBreak"},{"type":"text","text":"1. You need strict adherence to formatting instructions (e.g., force a model to always output a specific JSON structure). "},{"type":"hardBreak"},{"type":"text","text":"2. You want to adjust style, tone, or voice to match a brand. "},{"type":"hardBreak"},{"type":"text","text":"3. You need to train the model on a specialized programming language or proprietary API syntax. "},{"type":"hardBreak"},{"type":"text","text":"4. You want to train a small, cheap, open-source model (like Llama-3-8B) to perform a specific task with accuracy approaching a frontier model, reducing operational costs."}]}]}},"revision":1},{"id":"ee66bec7-b1c6-7849-bb3e-68eccece144a","type":"question","position":"a9","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"\"Why use LoRA?\""}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Fast Answer:","marks":[{"type":"bold"}]},{"type":"text","text":" It reduces trainable parameters by 99%+, saving massive GPU memory and compute while reducing (not eliminating) catastrophic forgetting."}]},{"type":"paragraph","content":[{"type":"text","text":"Low-Rank Adaptation (LoRA) is a Parameter-Efficient Fine-Tuning (PEFT) method. Instead of modifying all parameters in a weight matrix of size d × k (which requires storing massive gradients in GPU RAM), LoRA freezes the original weights and inserts two small low-rank matrices of sizes d × r and r × k (where r ≪ d, k, e.g., r = 8). Because only these small matrices are updated, trainable parameters drop by up to 99.9%, enabling fine-tuning on consumer hardware and allowing rapid hot-swapping of LoRA adapters on a single base model instance in production."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
WHERE EXISTS (SELECT 1 FROM "notes"."Note" n WHERE n.id = 'efe30f5c-7546-728c-b34f-e6c1c010e912' AND n."ownerId" = '019a118c-f480-7000-8000-000000000001' AND n."publishedVersionId" IS NULL AND n.visibility = 'PRIVATE' AND n."deletedAt" IS NULL AND n."draftUpdatedAt" = TIMESTAMPTZ '2026-10-07 03:23:53+00')
ON CONFLICT DO NOTHING;

