INSERT INTO "notes"."NoteVersion" ("id", "noteId", "number", "kind", "title", "cards", "createdById", "createdAt")
SELECT 'c0a801d1-53fd-7a8b-9a31-5f266a79b027', 'e2713061-1bdc-7900-b53c-abbc3269f87b', 1, 'PUBLISHED', 'L3: Interview Q&A', '[{"id":"766d27e9-2b91-7211-8ca8-c9f6e040c67b","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Advanced GenAI system design interview scenarios. Read-times are approximately 3-5 minutes per answer."}]}]}},"revision":1},{"id":"6c514895-4420-7dce-83f2-0ade670121b0","type":"question","position":"a1","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"\"Design ChatGPT for Amazon.\""}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"System Focus:","marks":[{"type":"bold"}]},{"type":"text","text":" Multi-tool routing, transactional safety, scale queries, and localized recommendations."}]},{"type":"paragraph","content":[{"type":"text","text":"System Architecture:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"hardBreak"},{"type":"text","text":"1. "},{"type":"text","text":"Gateway & Guardrails","marks":[{"type":"bold"}]},{"type":"text","text":": User queries enter an API gateway where inputs are filtered for jailbreaks, toxicity, and PII. "},{"type":"hardBreak"},{"type":"text","text":"2. "},{"type":"text","text":"Orchestrator Agent","marks":[{"type":"bold"}]},{"type":"text","text":": A core router model (e.g., Claude or fine-tuned Llama) coordinates the response. It has access to tools: "},{"type":"hardBreak"},{"type":"text","text":" - "},{"type":"text","text":"Catalog Search Tool","marks":[{"type":"italic"}]},{"type":"text","text":": Triggers a hybrid search (Vector search for semantic intent + Lexical search for exact product names) in the Product DB. "},{"type":"hardBreak"},{"type":"text","text":" - "},{"type":"text","text":"Order History Tool","marks":[{"type":"italic"}]},{"type":"text","text":": Connects to relational order databases via secure APIs using authenticated customer IDs. "},{"type":"hardBreak"},{"type":"text","text":" - "},{"type":"text","text":"Returns API Tool","marks":[{"type":"italic"}]},{"type":"text","text":": Initiates returns protocols. "},{"type":"hardBreak"},{"type":"text","text":"3. "},{"type":"text","text":"Knowledge Base (RAG)","marks":[{"type":"bold"}]},{"type":"text","text":": Serves Amazon policy pages, help docs, and FAQ materials stored in a Vector DB (Pinecone/Milvus). "},{"type":"hardBreak"},{"type":"text","text":"4. "},{"type":"text","text":"Response Generation","marks":[{"type":"bold"}]},{"type":"text","text":": Synthesizes responses using retrieved documents, product ratings, and user order context. "},{"type":"hardBreak"},{"type":"text","text":"5. "},{"type":"text","text":"Latency Optimization","marks":[{"type":"bold"}]},{"type":"text","text":": Implements streaming token output directly to the UI, prompt caching of system rules, and speculative decoding for fast generation. "},{"type":"hardBreak"},{"type":"text","text":"6. "},{"type":"text","text":"Output Guardrails","marks":[{"type":"bold"}]},{"type":"text","text":": Audits generated content to ensure it does not mention competitors, leak tokens, or output toxic content."}]}]}},"revision":1},{"id":"a01c767f-abb4-7690-adb9-6f8dd3b04896","type":"question","position":"a2","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"\"Design a document chatbot.\""}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"System Focus:","marks":[{"type":"bold"}]},{"type":"text","text":" Ingestion parsing, vector chunk indexing, metadata filtering, and citation verification."}]},{"type":"paragraph","content":[{"type":"text","text":"System Design:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"hardBreak"},{"type":"text","text":"1. "},{"type":"text","text":"Ingestion Pipeline","marks":[{"type":"bold"}]},{"type":"text","text":": "},{"type":"hardBreak"},{"type":"text","text":" - Parse documents (PDF, Word, Markdown) into raw text using OCR if needed. "},{"type":"hardBreak"},{"type":"text","text":" - Segment text using recursive character splitters into 512-token chunks with 50-token overlap. "},{"type":"hardBreak"},{"type":"text","text":" - Pass chunks to an embedding model (e.g. OpenAI text-embedding-3-small). "},{"type":"hardBreak"},{"type":"text","text":" - Store vectors alongside metadata (document_id, page_number, filename, access_roles) in a Vector DB. "},{"type":"hardBreak"},{"type":"text","text":"2. "},{"type":"text","text":"Retrieval Pipeline","marks":[{"type":"bold"}]},{"type":"text","text":": "},{"type":"hardBreak"},{"type":"text","text":" - The user submits a question and their auth token. "},{"type":"hardBreak"},{"type":"text","text":" - Generate a query vector embedding. "},{"type":"hardBreak"},{"type":"text","text":" - Execute a vector similarity query with "},{"type":"text","text":"metadata pre-filtering","marks":[{"type":"bold"}]},{"type":"text","text":" (ensuring the user is authorized to read the retrieved documents). "},{"type":"hardBreak"},{"type":"text","text":" - Fetch top-5 document chunks. "},{"type":"hardBreak"},{"type":"text","text":"3. "},{"type":"text","text":"Synthesis & Verification","marks":[{"type":"bold"}]},{"type":"text","text":": "},{"type":"hardBreak"},{"type":"text","text":" - Pass the query and retrieved document chunks to the LLM with a system prompt enforcing the model to only answer using provided chunks and output inline citations. "},{"type":"hardBreak"},{"type":"text","text":" - Verify citations post-generation by checking if they exist verbatim in the retrieved chunks."}]}]}},"revision":1},{"id":"269c3979-8260-7626-8d52-a7d4ef1e1223","type":"question","position":"a3","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"\"How would you reduce hallucinations?\""}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"System Focus:","marks":[{"type":"bold"}]},{"type":"text","text":" Context grounding, prompt design, reflection algorithms, and low sampling settings."}]},{"type":"paragraph","content":[{"type":"text","text":"To systematically reduce hallucinations in a production system: "},{"type":"hardBreak"},{"type":"text","text":"1. "},{"type":"text","text":"Context Grounding (RAG)","marks":[{"type":"bold"}]},{"type":"text","text":": Ensure the LLM never generates responses purely from memory. Inject relevant reference documents into the context. "},{"type":"hardBreak"},{"type":"text","text":"2. "},{"type":"text","text":"Strict Prompt Engineering","marks":[{"type":"bold"}]},{"type":"text","text":": Explicitly instruct the model: "},{"type":"text","text":"\"If you cannot find the answer in the provided documents, say ''I do not know''. Do not make up facts.\"","marks":[{"type":"italic"}]},{"type":"text","text":" "},{"type":"hardBreak"},{"type":"text","text":"3. "},{"type":"text","text":"Lower Temperature (0–0.2)","marks":[{"type":"bold"}]},{"type":"text","text":": Reduces sampling randomness for more consistent answers; it does not by itself prevent confident errors. "},{"type":"hardBreak"},{"type":"text","text":"4. "},{"type":"text","text":"Self-Reflection / Self-Correction","marks":[{"type":"bold"}]},{"type":"text","text":": Use a secondary LLM checker to review outputs: "},{"type":"text","text":"\"Check if the answer is fully supported by the reference documents. If it contains unsupported facts, rewrite it.\"","marks":[{"type":"italic"}]},{"type":"text","text":" "},{"type":"hardBreak"},{"type":"text","text":"5. "},{"type":"text","text":"Guardrail Frameworks","marks":[{"type":"bold"}]},{"type":"text","text":": Implement NeMo Guardrails or Guardrails AI to automatically validate outputs against schemas or run alignment checks."}]}]}},"revision":1},{"id":"9e7be6bc-35bc-7df1-9632-1f11d8b9e6cc","type":"question","position":"a4","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"\"How would you make responses faster?\""}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"System Focus:","marks":[{"type":"bold"}]},{"type":"text","text":" Streaming, KV caching, quantization, and specialized inference runtimes."}]},{"type":"paragraph","content":[{"type":"text","text":"To reduce LLM latency across the stack: "},{"type":"hardBreak"},{"type":"text","text":"1. "},{"type":"text","text":"User Experience","marks":[{"type":"bold"}]},{"type":"text","text":": Enable "},{"type":"text","text":"Streaming","marks":[{"type":"bold"}]},{"type":"text","text":" using Server-Sent Events (SSE). Pushing tokens to the UI as they generate reduces perceived latency to near-zero. "},{"type":"hardBreak"},{"type":"text","text":"2. "},{"type":"text","text":"Server Caching","marks":[{"type":"bold"}]},{"type":"text","text":": Enable "},{"type":"text","text":"KV Caching","marks":[{"type":"bold"}]},{"type":"text","text":" in inference engines to avoid recomputing attention states for historical tokens, and configure "},{"type":"text","text":"Prompt Caching","marks":[{"type":"bold"}]},{"type":"text","text":" to skip prefill phases for repeat system prompts. "},{"type":"hardBreak"},{"type":"text","text":"3. "},{"type":"text","text":"Inference Engine Selection","marks":[{"type":"bold"}]},{"type":"text","text":": Deploy using optimized runtimes like "},{"type":"text","text":"vLLM","marks":[{"type":"bold"}]},{"type":"text","text":" or "},{"type":"text","text":"TensorRT-LLM","marks":[{"type":"bold"}]},{"type":"text","text":" that implement PagedAttention (reduces memory fragmentation) and continuous batching. "},{"type":"hardBreak"},{"type":"text","text":"4. "},{"type":"text","text":"Hardware Optimization","marks":[{"type":"bold"}]},{"type":"text","text":": Quantize weights to 8-bit or 4-bit (reducing weight size and memory footprint), use speculative decoding (using small models to draft tokens), or deploy models across multiple GPUs with tensor parallelism."}]}]}},"revision":1},{"id":"683465d0-53d3-7bd8-8edc-bf97422015ea","type":"question","position":"a5","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"\"How would you reduce API cost?\""}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"System Focus:","marks":[{"type":"bold"}]},{"type":"text","text":" Caching strategies, model routing tiers, context reduction, and open-source models."}]},{"type":"paragraph","content":[{"type":"text","text":"Cost reduction strategies: "},{"type":"hardBreak"},{"type":"text","text":"1. "},{"type":"text","text":"Semantic Caching","marks":[{"type":"bold"}]},{"type":"text","text":": Implement a cache (like GPTCache with Redis) that stores queries. If a new question is semantically similar to a cached query (e.g. cosine similarity > 0.95), return the cached answer instead of calling the LLM. "},{"type":"hardBreak"},{"type":"text","text":"2. "},{"type":"text","text":"Model Cascading / Routing","marks":[{"type":"bold"}]},{"type":"text","text":": Run a cheap classifier to evaluate query complexity. Route simple queries (e.g., classification, summarization) to cheap models (e.g. small \"mini\"-tier or ~8B open-weight models) and reserve expensive models (e.g. flagship GPT, Claude or Gemini models) for complex logic queries. "},{"type":"hardBreak"},{"type":"text","text":"3. "},{"type":"text","text":"Minimize Token Lengths","marks":[{"type":"bold"}]},{"type":"text","text":": Prune retrieved RAG contexts to remove redundant text. Compress prompt templates. "},{"type":"hardBreak"},{"type":"text","text":"4. "},{"type":"text","text":"Self-Host Open Source","marks":[{"type":"bold"}]},{"type":"text","text":": For heavy workloads, self-host a fine-tuned open-source model (Llama-3) on private GPUs to exchange high variable API costs for fixed infrastructure costs."}]}]}},"revision":1},{"id":"091833c7-0f06-7e31-8b4f-1f4823fa47ee","type":"question","position":"a6","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"\"When would you choose GPT vs Llama?\""}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"System Focus:","marks":[{"type":"bold"}]},{"type":"text","text":" Hosting capability, security/privacy, cost metrics, and scale demands."}]},{"type":"paragraph","content":[{"type":"text","text":"Choose GPT (or other proprietary API models) when:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"hardBreak"},{"type":"text","text":"- You want rapid prototyping (zero infrastructure to manage). "},{"type":"hardBreak"},{"type":"text","text":"- You require state-of-the-art reasoning or mathematical capabilities. "},{"type":"hardBreak"},{"type":"text","text":"- Your request volume is low or highly variable (paying per token is cheaper than running a dedicated GPU). "},{"type":"hardBreak"},{"type":"text","text":"Choose Llama (or other open-weight models) when:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"hardBreak"},{"type":"text","text":"- Data privacy is critical (medical records, financial contracts) and data cannot leave your virtual private cloud (VPC). "},{"type":"hardBreak"},{"type":"text","text":"- You have massive query volumes where renting dedicated GPUs (fixed cost) is significantly cheaper than API tokens. "},{"type":"hardBreak"},{"type":"text","text":"- You need low-latency local execution (e.g., running on-device or within edge servers). "},{"type":"hardBreak"},{"type":"text","text":"- You want to fine-tune the model on proprietary domain data to specialize it for a niche task."}]}]}},"revision":1},{"id":"4e4d6a88-d2a3-7258-ad17-a05527271aa7","type":"question","position":"a7","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"\"Explain vector databases.\""}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Fast Answer:","marks":[{"type":"bold"}]},{"type":"text","text":" Specialized databases built to index, store, and execute vector similarity searches at high speeds over millions of records."}]},{"type":"paragraph","content":[{"type":"text","text":"Traditional databases index records using keys, columns, or keywords. In contrast, Vector Databases index high-dimensional vectors representing semantic embeddings. They are optimized for mathematical similarity computations (e.g. cosine distance). Because searching millions of 1536-dimensional vectors is computationally intensive, Vector DBs use specialized Approximate Nearest Neighbor (ANN) index structures (like HNSW or IVF) to narrow down search spaces, returning results in milliseconds. They also support concurrent metadata filtering (e.g., \"find vectors similar to X but only files updated after Monday\")."}]}]}},"revision":1},{"id":"6bd92283-a34f-7e03-aa71-3b36fff4a43e","type":"question","position":"a8","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"\"Explain ANN search.\""}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Fast Answer:","marks":[{"type":"bold"}]},{"type":"text","text":" An approximation method that groups vectors to find closest matches in sub-millisecond O(log N) time, sacrificing minor accuracy for massive scale performance."}]},{"type":"paragraph","content":[{"type":"text","text":"Exact nearest neighbor search (k-NN) scans every single vector in the database, which scales linearly O(N) and is too slow for millions of rows. Approximate Nearest Neighbor (ANN) search trades a small amount of recall accuracy for speed. It indexes vectors using one of three methods: "},{"type":"hardBreak"},{"type":"text","text":"1. "},{"type":"text","text":"Graph-based (HNSW)","marks":[{"type":"bold"}]},{"type":"text","text":": Creates a layered graph representing connections. Search traverses long connections, then local details. "},{"type":"hardBreak"},{"type":"text","text":"2. "},{"type":"text","text":"Inverted Files (IVF)","marks":[{"type":"bold"}]},{"type":"text","text":": Clusters space and searches only within the nearest cluster. "},{"type":"hardBreak"},{"type":"text","text":"3. "},{"type":"text","text":"Quantization (PQ)","marks":[{"type":"bold"}]},{"type":"text","text":": Compresses vectors to perform distance calculations on byte signatures. "},{"type":"hardBreak"},{"type":"text","text":"This makes search sub-linear in practice (≈O(log N) for HNSW; IVF scans only a few clusters; PQ makes each distance much cheaper and is often combined with IVF), making massive search queries extremely fast."}]}]}},"revision":1},{"id":"1754271c-4bb1-7ef8-ba59-5f8a0ff9e519","type":"question","position":"a9","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"\"How would you deploy an LLM?\""}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"System Focus:","marks":[{"type":"bold"}]},{"type":"text","text":" Model deployment stacks, autoscaling GPU nodes, and parallel batching."}]},{"type":"paragraph","content":[{"type":"text","text":"A production deployment workflow: "},{"type":"hardBreak"},{"type":"text","text":"1. "},{"type":"text","text":"Packaging & Inference Server","marks":[{"type":"bold"}]},{"type":"text","text":": Wrap the model (e.g., Llama-3-70B quantised to AWQ 4-bit) in an inference engine like "},{"type":"text","text":"vLLM","marks":[{"type":"bold"}]},{"type":"text","text":" or "},{"type":"text","text":"Triton Inference Server with a TensorRT-LLM/vLLM backend","marks":[{"type":"bold"}]},{"type":"text","text":". This grants features like PagedAttention, continuous batching, and an OpenAI-compatible API endpoint. "},{"type":"hardBreak"},{"type":"text","text":"2. "},{"type":"text","text":"GPU Hosting Cluster","marks":[{"type":"bold"}]},{"type":"text","text":": Deploy containers onto a Kubernetes cluster with GPU-enabled nodes (e.g. AWS EKS with G5 or P5 instances containing A10G/H100 GPUs). "},{"type":"hardBreak"},{"type":"text","text":"3. "},{"type":"text","text":"Autoscaling & Queue Management","marks":[{"type":"bold"}]},{"type":"text","text":": Scale GPU instances based on concurrent request counts. Implement a queue (e.g., using Redis) at the API Gateway to buffer request bursts. "},{"type":"hardBreak"},{"type":"text","text":"4. "},{"type":"text","text":"Load Balancing & Routing","marks":[{"type":"bold"}]},{"type":"text","text":": Use an API gateway (e.g. Kong, Nginx) to handle SSL termination, authentication, rate limiting, and round-robin request distribution across active GPU replicas."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
WHERE EXISTS (SELECT 1 FROM "notes"."Note" n WHERE n.id = 'e2713061-1bdc-7900-b53c-abbc3269f87b' AND n."ownerId" = '019a118c-f480-7000-8000-000000000001' AND n."publishedVersionId" IS NULL AND n.visibility = 'PRIVATE' AND n."deletedAt" IS NULL AND n."draftUpdatedAt" = TIMESTAMPTZ '2026-10-07 03:23:53+00')
ON CONFLICT DO NOTHING;

INSERT INTO "notes"."Card" ("id", "noteId", "position", "type", "content", "revision", "createdAt", "updatedAt")
SELECT c.id::uuid, 'e2713061-1bdc-7900-b53c-abbc3269f87b', c.position, c.type::"notes"."CardType", c.content::jsonb, 1, TIMESTAMPTZ '2026-10-07 03:23:53+00', TIMESTAMPTZ '2026-10-07 03:23:53+00'
FROM (VALUES
  ('766d27e9-2b91-7211-8ca8-c9f6e040c67b', 'a0', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Advanced GenAI system design interview scenarios. Read-times are approximately 3-5 minutes per answer."}]}]}}'),
  ('6c514895-4420-7dce-83f2-0ade670121b0', 'a1', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"\"Design ChatGPT for Amazon.\""}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"System Focus:","marks":[{"type":"bold"}]},{"type":"text","text":" Multi-tool routing, transactional safety, scale queries, and localized recommendations."}]},{"type":"paragraph","content":[{"type":"text","text":"System Architecture:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"hardBreak"},{"type":"text","text":"1. "},{"type":"text","text":"Gateway & Guardrails","marks":[{"type":"bold"}]},{"type":"text","text":": User queries enter an API gateway where inputs are filtered for jailbreaks, toxicity, and PII. "},{"type":"hardBreak"},{"type":"text","text":"2. "},{"type":"text","text":"Orchestrator Agent","marks":[{"type":"bold"}]},{"type":"text","text":": A core router model (e.g., Claude or fine-tuned Llama) coordinates the response. It has access to tools: "},{"type":"hardBreak"},{"type":"text","text":" - "},{"type":"text","text":"Catalog Search Tool","marks":[{"type":"italic"}]},{"type":"text","text":": Triggers a hybrid search (Vector search for semantic intent + Lexical search for exact product names) in the Product DB. "},{"type":"hardBreak"},{"type":"text","text":" - "},{"type":"text","text":"Order History Tool","marks":[{"type":"italic"}]},{"type":"text","text":": Connects to relational order databases via secure APIs using authenticated customer IDs. "},{"type":"hardBreak"},{"type":"text","text":" - "},{"type":"text","text":"Returns API Tool","marks":[{"type":"italic"}]},{"type":"text","text":": Initiates returns protocols. "},{"type":"hardBreak"},{"type":"text","text":"3. "},{"type":"text","text":"Knowledge Base (RAG)","marks":[{"type":"bold"}]},{"type":"text","text":": Serves Amazon policy pages, help docs, and FAQ materials stored in a Vector DB (Pinecone/Milvus). "},{"type":"hardBreak"},{"type":"text","text":"4. "},{"type":"text","text":"Response Generation","marks":[{"type":"bold"}]},{"type":"text","text":": Synthesizes responses using retrieved documents, product ratings, and user order context. "},{"type":"hardBreak"},{"type":"text","text":"5. "},{"type":"text","text":"Latency Optimization","marks":[{"type":"bold"}]},{"type":"text","text":": Implements streaming token output directly to the UI, prompt caching of system rules, and speculative decoding for fast generation. "},{"type":"hardBreak"},{"type":"text","text":"6. "},{"type":"text","text":"Output Guardrails","marks":[{"type":"bold"}]},{"type":"text","text":": Audits generated content to ensure it does not mention competitors, leak tokens, or output toxic content."}]}]}}'),
  ('a01c767f-abb4-7690-adb9-6f8dd3b04896', 'a2', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"\"Design a document chatbot.\""}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"System Focus:","marks":[{"type":"bold"}]},{"type":"text","text":" Ingestion parsing, vector chunk indexing, metadata filtering, and citation verification."}]},{"type":"paragraph","content":[{"type":"text","text":"System Design:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"hardBreak"},{"type":"text","text":"1. "},{"type":"text","text":"Ingestion Pipeline","marks":[{"type":"bold"}]},{"type":"text","text":": "},{"type":"hardBreak"},{"type":"text","text":" - Parse documents (PDF, Word, Markdown) into raw text using OCR if needed. "},{"type":"hardBreak"},{"type":"text","text":" - Segment text using recursive character splitters into 512-token chunks with 50-token overlap. "},{"type":"hardBreak"},{"type":"text","text":" - Pass chunks to an embedding model (e.g. OpenAI text-embedding-3-small). "},{"type":"hardBreak"},{"type":"text","text":" - Store vectors alongside metadata (document_id, page_number, filename, access_roles) in a Vector DB. "},{"type":"hardBreak"},{"type":"text","text":"2. "},{"type":"text","text":"Retrieval Pipeline","marks":[{"type":"bold"}]},{"type":"text","text":": "},{"type":"hardBreak"},{"type":"text","text":" - The user submits a question and their auth token. "},{"type":"hardBreak"},{"type":"text","text":" - Generate a query vector embedding. "},{"type":"hardBreak"},{"type":"text","text":" - Execute a vector similarity query with "},{"type":"text","text":"metadata pre-filtering","marks":[{"type":"bold"}]},{"type":"text","text":" (ensuring the user is authorized to read the retrieved documents). "},{"type":"hardBreak"},{"type":"text","text":" - Fetch top-5 document chunks. "},{"type":"hardBreak"},{"type":"text","text":"3. "},{"type":"text","text":"Synthesis & Verification","marks":[{"type":"bold"}]},{"type":"text","text":": "},{"type":"hardBreak"},{"type":"text","text":" - Pass the query and retrieved document chunks to the LLM with a system prompt enforcing the model to only answer using provided chunks and output inline citations. "},{"type":"hardBreak"},{"type":"text","text":" - Verify citations post-generation by checking if they exist verbatim in the retrieved chunks."}]}]}}'),
  ('269c3979-8260-7626-8d52-a7d4ef1e1223', 'a3', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"\"How would you reduce hallucinations?\""}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"System Focus:","marks":[{"type":"bold"}]},{"type":"text","text":" Context grounding, prompt design, reflection algorithms, and low sampling settings."}]},{"type":"paragraph","content":[{"type":"text","text":"To systematically reduce hallucinations in a production system: "},{"type":"hardBreak"},{"type":"text","text":"1. "},{"type":"text","text":"Context Grounding (RAG)","marks":[{"type":"bold"}]},{"type":"text","text":": Ensure the LLM never generates responses purely from memory. Inject relevant reference documents into the context. "},{"type":"hardBreak"},{"type":"text","text":"2. "},{"type":"text","text":"Strict Prompt Engineering","marks":[{"type":"bold"}]},{"type":"text","text":": Explicitly instruct the model: "},{"type":"text","text":"\"If you cannot find the answer in the provided documents, say ''I do not know''. Do not make up facts.\"","marks":[{"type":"italic"}]},{"type":"text","text":" "},{"type":"hardBreak"},{"type":"text","text":"3. "},{"type":"text","text":"Lower Temperature (0–0.2)","marks":[{"type":"bold"}]},{"type":"text","text":": Reduces sampling randomness for more consistent answers; it does not by itself prevent confident errors. "},{"type":"hardBreak"},{"type":"text","text":"4. "},{"type":"text","text":"Self-Reflection / Self-Correction","marks":[{"type":"bold"}]},{"type":"text","text":": Use a secondary LLM checker to review outputs: "},{"type":"text","text":"\"Check if the answer is fully supported by the reference documents. If it contains unsupported facts, rewrite it.\"","marks":[{"type":"italic"}]},{"type":"text","text":" "},{"type":"hardBreak"},{"type":"text","text":"5. "},{"type":"text","text":"Guardrail Frameworks","marks":[{"type":"bold"}]},{"type":"text","text":": Implement NeMo Guardrails or Guardrails AI to automatically validate outputs against schemas or run alignment checks."}]}]}}'),
  ('9e7be6bc-35bc-7df1-9632-1f11d8b9e6cc', 'a4', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"\"How would you make responses faster?\""}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"System Focus:","marks":[{"type":"bold"}]},{"type":"text","text":" Streaming, KV caching, quantization, and specialized inference runtimes."}]},{"type":"paragraph","content":[{"type":"text","text":"To reduce LLM latency across the stack: "},{"type":"hardBreak"},{"type":"text","text":"1. "},{"type":"text","text":"User Experience","marks":[{"type":"bold"}]},{"type":"text","text":": Enable "},{"type":"text","text":"Streaming","marks":[{"type":"bold"}]},{"type":"text","text":" using Server-Sent Events (SSE). Pushing tokens to the UI as they generate reduces perceived latency to near-zero. "},{"type":"hardBreak"},{"type":"text","text":"2. "},{"type":"text","text":"Server Caching","marks":[{"type":"bold"}]},{"type":"text","text":": Enable "},{"type":"text","text":"KV Caching","marks":[{"type":"bold"}]},{"type":"text","text":" in inference engines to avoid recomputing attention states for historical tokens, and configure "},{"type":"text","text":"Prompt Caching","marks":[{"type":"bold"}]},{"type":"text","text":" to skip prefill phases for repeat system prompts. "},{"type":"hardBreak"},{"type":"text","text":"3. "},{"type":"text","text":"Inference Engine Selection","marks":[{"type":"bold"}]},{"type":"text","text":": Deploy using optimized runtimes like "},{"type":"text","text":"vLLM","marks":[{"type":"bold"}]},{"type":"text","text":" or "},{"type":"text","text":"TensorRT-LLM","marks":[{"type":"bold"}]},{"type":"text","text":" that implement PagedAttention (reduces memory fragmentation) and continuous batching. "},{"type":"hardBreak"},{"type":"text","text":"4. "},{"type":"text","text":"Hardware Optimization","marks":[{"type":"bold"}]},{"type":"text","text":": Quantize weights to 8-bit or 4-bit (reducing weight size and memory footprint), use speculative decoding (using small models to draft tokens), or deploy models across multiple GPUs with tensor parallelism."}]}]}}'),
  ('683465d0-53d3-7bd8-8edc-bf97422015ea', 'a5', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"\"How would you reduce API cost?\""}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"System Focus:","marks":[{"type":"bold"}]},{"type":"text","text":" Caching strategies, model routing tiers, context reduction, and open-source models."}]},{"type":"paragraph","content":[{"type":"text","text":"Cost reduction strategies: "},{"type":"hardBreak"},{"type":"text","text":"1. "},{"type":"text","text":"Semantic Caching","marks":[{"type":"bold"}]},{"type":"text","text":": Implement a cache (like GPTCache with Redis) that stores queries. If a new question is semantically similar to a cached query (e.g. cosine similarity > 0.95), return the cached answer instead of calling the LLM. "},{"type":"hardBreak"},{"type":"text","text":"2. "},{"type":"text","text":"Model Cascading / Routing","marks":[{"type":"bold"}]},{"type":"text","text":": Run a cheap classifier to evaluate query complexity. Route simple queries (e.g., classification, summarization) to cheap models (e.g. small \"mini\"-tier or ~8B open-weight models) and reserve expensive models (e.g. flagship GPT, Claude or Gemini models) for complex logic queries. "},{"type":"hardBreak"},{"type":"text","text":"3. "},{"type":"text","text":"Minimize Token Lengths","marks":[{"type":"bold"}]},{"type":"text","text":": Prune retrieved RAG contexts to remove redundant text. Compress prompt templates. "},{"type":"hardBreak"},{"type":"text","text":"4. "},{"type":"text","text":"Self-Host Open Source","marks":[{"type":"bold"}]},{"type":"text","text":": For heavy workloads, self-host a fine-tuned open-source model (Llama-3) on private GPUs to exchange high variable API costs for fixed infrastructure costs."}]}]}}'),
  ('091833c7-0f06-7e31-8b4f-1f4823fa47ee', 'a6', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"\"When would you choose GPT vs Llama?\""}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"System Focus:","marks":[{"type":"bold"}]},{"type":"text","text":" Hosting capability, security/privacy, cost metrics, and scale demands."}]},{"type":"paragraph","content":[{"type":"text","text":"Choose GPT (or other proprietary API models) when:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"hardBreak"},{"type":"text","text":"- You want rapid prototyping (zero infrastructure to manage). "},{"type":"hardBreak"},{"type":"text","text":"- You require state-of-the-art reasoning or mathematical capabilities. "},{"type":"hardBreak"},{"type":"text","text":"- Your request volume is low or highly variable (paying per token is cheaper than running a dedicated GPU). "},{"type":"hardBreak"},{"type":"text","text":"Choose Llama (or other open-weight models) when:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"hardBreak"},{"type":"text","text":"- Data privacy is critical (medical records, financial contracts) and data cannot leave your virtual private cloud (VPC). "},{"type":"hardBreak"},{"type":"text","text":"- You have massive query volumes where renting dedicated GPUs (fixed cost) is significantly cheaper than API tokens. "},{"type":"hardBreak"},{"type":"text","text":"- You need low-latency local execution (e.g., running on-device or within edge servers). "},{"type":"hardBreak"},{"type":"text","text":"- You want to fine-tune the model on proprietary domain data to specialize it for a niche task."}]}]}}'),
  ('4e4d6a88-d2a3-7258-ad17-a05527271aa7', 'a7', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"\"Explain vector databases.\""}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Fast Answer:","marks":[{"type":"bold"}]},{"type":"text","text":" Specialized databases built to index, store, and execute vector similarity searches at high speeds over millions of records."}]},{"type":"paragraph","content":[{"type":"text","text":"Traditional databases index records using keys, columns, or keywords. In contrast, Vector Databases index high-dimensional vectors representing semantic embeddings. They are optimized for mathematical similarity computations (e.g. cosine distance). Because searching millions of 1536-dimensional vectors is computationally intensive, Vector DBs use specialized Approximate Nearest Neighbor (ANN) index structures (like HNSW or IVF) to narrow down search spaces, returning results in milliseconds. They also support concurrent metadata filtering (e.g., \"find vectors similar to X but only files updated after Monday\")."}]}]}}'),
  ('6bd92283-a34f-7e03-aa71-3b36fff4a43e', 'a8', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"\"Explain ANN search.\""}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Fast Answer:","marks":[{"type":"bold"}]},{"type":"text","text":" An approximation method that groups vectors to find closest matches in sub-millisecond O(log N) time, sacrificing minor accuracy for massive scale performance."}]},{"type":"paragraph","content":[{"type":"text","text":"Exact nearest neighbor search (k-NN) scans every single vector in the database, which scales linearly O(N) and is too slow for millions of rows. Approximate Nearest Neighbor (ANN) search trades a small amount of recall accuracy for speed. It indexes vectors using one of three methods: "},{"type":"hardBreak"},{"type":"text","text":"1. "},{"type":"text","text":"Graph-based (HNSW)","marks":[{"type":"bold"}]},{"type":"text","text":": Creates a layered graph representing connections. Search traverses long connections, then local details. "},{"type":"hardBreak"},{"type":"text","text":"2. "},{"type":"text","text":"Inverted Files (IVF)","marks":[{"type":"bold"}]},{"type":"text","text":": Clusters space and searches only within the nearest cluster. "},{"type":"hardBreak"},{"type":"text","text":"3. "},{"type":"text","text":"Quantization (PQ)","marks":[{"type":"bold"}]},{"type":"text","text":": Compresses vectors to perform distance calculations on byte signatures. "},{"type":"hardBreak"},{"type":"text","text":"This makes search sub-linear in practice (≈O(log N) for HNSW; IVF scans only a few clusters; PQ makes each distance much cheaper and is often combined with IVF), making massive search queries extremely fast."}]}]}}'),
  ('1754271c-4bb1-7ef8-ba59-5f8a0ff9e519', 'a9', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"\"How would you deploy an LLM?\""}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"System Focus:","marks":[{"type":"bold"}]},{"type":"text","text":" Model deployment stacks, autoscaling GPU nodes, and parallel batching."}]},{"type":"paragraph","content":[{"type":"text","text":"A production deployment workflow: "},{"type":"hardBreak"},{"type":"text","text":"1. "},{"type":"text","text":"Packaging & Inference Server","marks":[{"type":"bold"}]},{"type":"text","text":": Wrap the model (e.g., Llama-3-70B quantised to AWQ 4-bit) in an inference engine like "},{"type":"text","text":"vLLM","marks":[{"type":"bold"}]},{"type":"text","text":" or "},{"type":"text","text":"Triton Inference Server with a TensorRT-LLM/vLLM backend","marks":[{"type":"bold"}]},{"type":"text","text":". This grants features like PagedAttention, continuous batching, and an OpenAI-compatible API endpoint. "},{"type":"hardBreak"},{"type":"text","text":"2. "},{"type":"text","text":"GPU Hosting Cluster","marks":[{"type":"bold"}]},{"type":"text","text":": Deploy containers onto a Kubernetes cluster with GPU-enabled nodes (e.g. AWS EKS with G5 or P5 instances containing A10G/H100 GPUs). "},{"type":"hardBreak"},{"type":"text","text":"3. "},{"type":"text","text":"Autoscaling & Queue Management","marks":[{"type":"bold"}]},{"type":"text","text":": Scale GPU instances based on concurrent request counts. Implement a queue (e.g., using Redis) at the API Gateway to buffer request bursts. "},{"type":"hardBreak"},{"type":"text","text":"4. "},{"type":"text","text":"Load Balancing & Routing","marks":[{"type":"bold"}]},{"type":"text","text":": Use an API gateway (e.g. Kong, Nginx) to handle SSL termination, authentication, rate limiting, and round-robin request distribution across active GPU replicas."}]}]}}')
