INSERT INTO "notes"."NoteVersion" ("id", "noteId", "number", "kind", "title", "cards", "createdById", "createdAt")
SELECT '17327943-090c-7f28-a54e-350f4827355d', '41884aab-694a-70f9-b31e-1b3f118d90ae', 1, 'PUBLISHED', 'LLM Basics', '[{"id":"e00bc847-06e1-7874-8646-e8c95f511b56","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Core concepts regarding large language models, their properties, and generation control."}]}]}},"revision":1},{"id":"7e039ab7-2665-775f-92be-b40b746c4220","type":"callout","position":"a1","content":{"variant":"note","title":"What makes LLMs different?","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"LLMs are characterized by scale (billions of parameters) and "},{"type":"text","text":"emergent behaviors","marks":[{"type":"bold"}]},{"type":"text","text":" — abilities like zero-shot reasoning or complex coding that arise at scale but are absent in smaller, traditional models. They shift AI from task-specific architectures (e.g., one model for translation, one for classification) to a single general-purpose prompt-based interface."}]}]}},"revision":1},{"id":"717ae5c0-3f5c-7b38-b725-527f3f877edd","type":"callout","position":"a2","content":{"variant":"note","title":"Why GPT is called GPT","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"G","marks":[{"type":"bold"}]},{"type":"text","text":"enerative "},{"type":"text","text":"P","marks":[{"type":"bold"}]},{"type":"text","text":"re-trained "},{"type":"text","text":"T","marks":[{"type":"bold"}]},{"type":"text","text":"ransformer:"},{"type":"hardBreak"},{"type":"text","text":" - "},{"type":"text","text":"Generative","marks":[{"type":"bold"}]},{"type":"text","text":": Creates new text content based on patterns."},{"type":"hardBreak"},{"type":"text","text":" - "},{"type":"text","text":"Pre-trained","marks":[{"type":"bold"}]},{"type":"text","text":": Pre-trained on massive text datasets before being adjusted for specific tasks."},{"type":"hardBreak"},{"type":"text","text":" - "},{"type":"text","text":"Transformer","marks":[{"type":"bold"}]},{"type":"text","text":": Built on the self-attention network architecture introduced by Google in 2017."}]}]}},"revision":1},{"id":"a6570295-9f6c-7e73-80e2-df2650ce2797","type":"callout","position":"a3","content":{"variant":"note","title":"Parameters","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The internal weights and biases of the neural network. During training, the loss optimization updates these parameters. The number of parameters (e.g., 70B, 405B) dictates the model''s capacity to hold knowledge and understand reasoning patterns."}]}]}},"revision":1},{"id":"732e404b-4c8c-7f09-aa12-f16b3cdbba26","type":"callout","position":"a4","content":{"variant":"note","title":"Context Window","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The maximum number of tokens a model can process in a single request (input prompt + generated output response). Exceeding this limit causes an API error, or the application must truncate or summarize older content — which the model then cannot see."}]}]}},"revision":1},{"id":"213fe0e1-7b22-7a1e-895f-c815ada0f6d8","type":"callout","position":"a5","content":{"variant":"note","title":"Temperature, Top-k, & Top-p","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Hyperparameters controlling the randomness of next-token selection during inference: "},{"type":"hardBreak"},{"type":"text","text":"- "},{"type":"text","text":"Temperature","marks":[{"type":"bold"}]},{"type":"text","text":": Scales token logits. 0 = greedy (always pick the top token). 1 = the model''s unmodified distribution; >1 = flatter and more random. "},{"type":"hardBreak"},{"type":"text","text":"- "},{"type":"text","text":"Top-k","marks":[{"type":"bold"}]},{"type":"text","text":": Limits candidates to the top "},{"type":"text","text":"k","marks":[{"type":"italic"}]},{"type":"text","text":" most probable tokens. "},{"type":"hardBreak"},{"type":"text","text":"- "},{"type":"text","text":"Top-p (Nucleus)","marks":[{"type":"bold"}]},{"type":"text","text":": Limits candidates to a cumulative probability threshold "},{"type":"text","text":"p","marks":[{"type":"italic"}]},{"type":"text","text":" (e.g., 0.9 means only consider tokens making up the top 90% of probability mass)."}]}]}},"revision":1},{"id":"d1226646-2cfa-70b7-9c48-c945c74dca32","type":"callout","position":"a6","content":{"variant":"note","title":"Training vs Inference vs Fine-tuning","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"- "},{"type":"text","text":"Training","marks":[{"type":"bold"}]},{"type":"text","text":": Building the model from scratch on raw text (very expensive)."},{"type":"hardBreak"},{"type":"text","text":" - "},{"type":"text","text":"Fine-tuning","marks":[{"type":"bold"}]},{"type":"text","text":": Further training a pre-trained model on structured prompt-response pairs to adapt its style, behavior, or domain specificity."},{"type":"hardBreak"},{"type":"text","text":" - "},{"type":"text","text":"Inference","marks":[{"type":"bold"}]},{"type":"text","text":": Running queries through the trained model to generate predictions (read-only execution)."}]}]}},"revision":1},{"id":"6f51bd2c-4682-7d07-817d-25bd311929c8","type":"callout","position":"a7","content":{"variant":"note","title":"Hallucination","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A phenomenon where an LLM generates factually incorrect statements, false links, or fabricated data with high confidence, due to next-token probability bias rather than verified lookup."}]}]}},"revision":1},{"id":"88f9cf36-89e1-79ce-ac62-affc7c684b3f","type":"callout","position":"a8","content":{"variant":"note","title":"Prompt","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The input text provided to the model. Structuring prompt templates (roles, tasks, examples, system commands) instructs the model on how to formulate its response."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
