  SELECT 1 FROM "notes"."Note" n
  WHERE n.id = '73c3df47-168c-7fcb-aa98-7b9ddc1a030e' AND n.visibility = 'PUBLIC' AND n."publishedVersionId" = '23c8fe75-f9a5-7b94-a915-f3597fd945f2' AND n."deletedAt" IS NULL
)
