SELECT c.id::uuid, '40727caa-f2f3-778b-873d-364fac98733a', c.position, c.type::"notes"."CardType", c.content::jsonb, 1, TIMESTAMPTZ '2026-10-07 03:23:53+00', TIMESTAMPTZ '2026-10-07 03:23:53+00'
FROM (VALUES
  ('66e79764-09a8-77d5-a42b-0be954309498', 'a0', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Understanding the attention mechanism that replaced Recurrent Neural Networks (RNNs) by allowing parallelized sequence processing."}]}]}}'),
  ('056c7761-7ad3-7908-b850-c131d920810b', 'a1', 'callout', '{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Introduced in Google''s landmark paper "},{"type":"text","text":"\"Attention Is All You Need\" (2017)","marks":[{"type":"bold"}]},{"type":"text","text":", the Transformer replaces recurrence with "},{"type":"text","text":"Self-Attention","marks":[{"type":"bold"}]},{"type":"text","text":", processing entire text sequences simultaneously rather than word-by-word."}]}]}}'),
  ('7f38f1bd-83f8-765a-b43b-80d466c30a8a', 'a2', 'heading', '{"level":1,"content":[{"type":"text","text":"Key Components"}]}'),
  ('89b57e87-bb69-7a20-a515-f1ae7747bf36', 'a3', 'callout', '{"variant":"note","title":"Encoder","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Processes the input sequence and constructs a dense representation that captures bidirectional context for each token. Used in task architectures like text classification or NER (e.g., BERT)."}]}]}}'),
  ('5ea761a6-bd8b-78a1-a8a1-467cdc52c0ab', 'a4', 'callout', '{"variant":"note","title":"Decoder","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Generates the output sequence token-by-token. Uses causal masking to ensure prediction for token "},{"type":"text","text":"t","marks":[{"type":"italic"}]},{"type":"text","text":" only depends on tokens prior to it (t-1, t-2). Used in generative models (e.g., GPT)."}]}]}}'),
  ('d4d1dad1-8329-7018-a156-c78bb278cc91', 'a5', 'callout', '{"variant":"note","title":"Self-Attention (Q, K, V)","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Calculates the relevance of each token in the sequence to every other token. For each token, the network projects three vectors: "},{"type":"hardBreak"},{"type":"text","text":"- "},{"type":"text","text":"Query (Q)","marks":[{"type":"bold"}]},{"type":"text","text":": What the token is looking for. "},{"type":"hardBreak"},{"type":"text","text":"- "},{"type":"text","text":"Key (K)","marks":[{"type":"bold"}]},{"type":"text","text":": What characteristics the token possesses. "},{"type":"hardBreak"},{"type":"text","text":"- "},{"type":"text","text":"Value (V)","marks":[{"type":"bold"}]},{"type":"text","text":": The actual content information of the token. "},{"type":"hardBreak"},{"type":"text","text":"The dot product Q·K"},{"type":"text","text":"T","marks":[{"type":"superscript"}]},{"type":"text","text":" measures alignment, scaled and passed to Softmax to get attention weights, which are multiplied by V."}]},{"type":"paragraph","content":[{"type":"text","text":"Attention(Q, K, V) = softmax( (Q * K^T) / sqrt(d_k) ) * V","marks":[{"type":"code"}]}]}]}}'),
  ('a74a0c21-4c97-780d-bb15-e83383ae4e7d', 'a6', 'callout', '{"variant":"note","title":"Multi-Head Attention","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Runs self-attention multiple times in parallel with different linear projections. This allows the model to attend to information from different representation subspaces at different positions simultaneously (e.g., one head tracks subject-verb agreement, another tracks pronouns)."}]}]}}'),
  ('362a9d03-9c10-7641-85e3-4d0c5a93c0b2', 'a7', 'callout', '{"variant":"note","title":"Positional Encoding","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Because Transformers process all tokens in parallel, they have no built-in concept of word order. The original Transformer adds fixed sine/cosine vectors (or learned position embeddings) to the input embeddings; most modern LLMs (e.g., Llama) instead use Rotary Position Embeddings (RoPE), which rotate Q and K inside attention."}]}]}}'),
  ('d35f19c8-6d3f-7490-9e0a-f030d03a2d18', 'a8', 'callout', '{"variant":"note","title":"Normalization & Connections","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"- "},{"type":"text","text":"Residual Connections","marks":[{"type":"bold"}]},{"type":"text","text":": Allow gradients to flow directly through network layers, preventing vanishing gradients in deep stacks. "},{"type":"hardBreak"},{"type":"text","text":"- "},{"type":"text","text":"Layer Normalization","marks":[{"type":"bold"}]},{"type":"text","text":": Stabilizes training dynamics by normalizing inputs across feature dimensions on each layer."}]}]}}')
) AS c(id, position, type, content)
WHERE EXISTS (SELECT 1 FROM "notes"."Note" n WHERE n.id = '40727caa-f2f3-778b-873d-364fac98733a' AND n."ownerId" = '019a118c-f480-7000-8000-000000000001' AND n."publishedVersionId" IS NULL AND n.visibility = 'PRIVATE' AND n."deletedAt" IS NULL AND n."draftUpdatedAt" = TIMESTAMPTZ '2026-10-07 03:23:53+00')
