INSERT INTO "notes"."NoteVersion" ("id", "noteId", "number", "kind", "title", "cards", "createdById", "createdAt")
SELECT '9b4f4213-36c0-70a0-9c2c-f40d49e3ab31', '6c4511eb-2ab6-7d4f-b45f-557a4c6f42b3', 1, 'PUBLISHED', 'Fairness, Privacy & Responsible AI', '[{"id":"3b73f8f1-dfca-7687-9646-e574328e7408","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Models learn from historical data, including its biases, and they act at scale. Responsible ML means measuring who the model fails, protecting the people in the data, and documenting what the model should and shouldn''t be used for."}]}]}},"revision":1},{"id":"d9119cfd-a6f6-732b-9b83-8d28ec5fdabf","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Where bias comes from"}]},"revision":1},{"id":"324c22aa-c69a-7541-b3d2-7e53b9647ae3","type":"table","position":"a2","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Source"}],[{"type":"text","text":"Example"}]],[[{"type":"text","text":"Historical bias"}],[{"type":"text","text":"Past hiring decisions favoured one group; a model trained on them repeats it"}]],[[{"type":"text","text":"Representation bias"}],[{"type":"text","text":"Few examples from some groups (skin tones, accents, regions)"}]],[[{"type":"text","text":"Measurement bias"}],[{"type":"text","text":"A proxy target: “arrests” as a stand-in for “crime”"}]],[[{"type":"text","text":"Aggregation bias"}],[{"type":"text","text":"One model for groups whose features relate to the outcome differently"}]],[[{"type":"text","text":"Evaluation bias"}],[{"type":"text","text":"Benchmark that doesn''t represent the deployed population"}]],[[{"type":"text","text":"Feedback loops"}],[{"type":"text","text":"Predictions change the data that future models are trained on"}]]]},"revision":1},{"id":"11edfa6c-8e49-7b5e-8cb1-5ea076e0df57","type":"heading","position":"a3","content":{"level":1,"content":[{"type":"text","text":"Group fairness metrics"}]},"revision":1},{"id":"8985ae66-ca85-77cf-bbd2-2f27ecef1b90","type":"table","position":"a4","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Criterion"}],[{"type":"text","text":"Requires equal across groups"}],[{"type":"text","text":"Formula (A = group)"}]],[[{"type":"text","text":"Demographic (statistical) parity"}],[{"type":"text","text":"Selection rate"}],[{"type":"text","text":"P(ŷ = 1 | A = a)","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Equal opportunity"}],[{"type":"text","text":"True positive rate"}],[{"type":"text","text":"P(ŷ = 1 | y = 1, A = a)","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Equalized odds"}],[{"type":"text","text":"TPR "},{"type":"text","text":"and","marks":[{"type":"bold"}]},{"type":"text","text":" FPR"}],[{"type":"text","text":"P(ŷ = 1 | y, A = a)","marks":[{"type":"code"}]},{"type":"text","text":" for y = 0 and 1"}]],[[{"type":"text","text":"Predictive parity"}],[{"type":"text","text":"Precision"}],[{"type":"text","text":"P(y = 1 | ŷ = 1, A = a)","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Calibration within groups"}],[{"type":"text","text":"Meaning of a score"}],[{"type":"text","text":"P(y = 1 | score = s, A = a) = s","marks":[{"type":"code"}]}]]]},"revision":1},{"id":"d245ca3e-6541-77ea-ab05-461fd4f3bc8b","type":"text","position":"a5","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","text":"disparate impact ratio","marks":[{"type":"bold"}]},{"type":"text","text":" (lowest selection rate ÷ highest) is often checked against the US “four-fifths rule” (≥ 0.8) as a screening heuristic."}]}]}},"revision":1},{"id":"f1bd40bd-7a0c-7f93-9d34-23b8fa289ce1","type":"code","position":"a6","content":{"language":"python","code":"import numpy as np\nimport pandas as pd\n\nrng = np.random.default_rng(0)\nn = 4000\ngroup = rng.choice([\"A\", \"B\"], n)\ny = (rng.random(n) < np.where(group == \"A\", 0.30, 0.15)).astype(int)     # different base rates\nscore = np.clip(0.35 * y + rng.normal(0.3, 0.15, n) + np.where(group == \"B\", -0.05, 0), 0, 1)\npred = (score >= 0.5).astype(int)\n\ndf = pd.DataFrame({\"group\": group, \"y\": y, \"pred\": pred})\nrows = {}\nfor g, d in df.groupby(\"group\"):\n    rows[g] = {\n        \"base_rate\": d.y.mean(),\n        \"selection_rate\": d.pred.mean(),\n        \"TPR\": d.pred[d.y == 1].mean(),\n        \"FPR\": d.pred[d.y == 0].mean(),\n        \"precision\": d.y[d.pred == 1].mean(),\n    }\nreport = pd.DataFrame(rows).T.round(3)\nprint(report)\nprint(\"disparate impact:\", round(report.selection_rate.min() / report.selection_rate.max(), 3))","filename":"Python"},"revision":1},{"id":"a5f1a769-db2b-7330-83d8-d368d5d88e82","type":"code","position":"a7","content":{"language":"text","code":"   base_rate  selection_rate    TPR    FPR  precision\nA      0.291           0.305  0.850  0.082      0.811\nB      0.159           0.165  0.742  0.056      0.713\ndisparate impact: 0.541","filename":"Output"},"revision":1},{"id":"3ac38653-3aed-7693-8fd1-ae6b8e018f6f","type":"text","position":"a8","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Group B is selected far less often — partly because its base rate is lower (not necessarily unfair) and partly because its scores are shifted down, which lowers its TPR (equal opportunity is violated). Which criterion matters is a policy decision about the application, not a purely technical one."}]}]}},"revision":1},{"id":"08ab3a94-3dce-7e36-811f-a1a7733867ac","type":"callout","position":"a9","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Impossibility result","marks":[{"type":"bold"}]},{"type":"text","text":" (Kleinberg et al.; Chouldechova, 2016–17): when base rates differ between groups, a classifier cannot be calibrated within groups "},{"type":"text","text":"and","marks":[{"type":"italic"}]},{"type":"text","text":" have equal TPR and FPR across them — except in the degenerate case of perfect prediction. You must choose which notion of fairness fits the decision."}]}]}},"revision":1},{"id":"17b5cbab-c2e7-79c5-9592-bef63714900d","type":"callout","position":"aA","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Fairness through unawareness","marks":[{"type":"bold"}]},{"type":"text","text":" — just dropping the protected attribute — doesn''t work: zip code, name, school or shopping history act as proxies. You often need the attribute to "},{"type":"text","text":"measure","marks":[{"type":"italic"}]},{"type":"text","text":" fairness at all."}]}]}},"revision":1},{"id":"6cbbdc2a-dea8-78dd-95f5-27b1c43619a1","type":"heading","position":"aB","content":{"level":1,"content":[{"type":"text","text":"Mitigation"}]},"revision":1},{"id":"f8443a29-a4b1-701f-8d77-1ac98ca22c1f","type":"table","position":"aC","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Stage"}],[{"type":"text","text":"Techniques"}]],[[{"type":"text","text":"Pre-processing"}],[{"type":"text","text":"Collect more representative data, re-weight or re-sample groups, fix biased labels"}]],[[{"type":"text","text":"In-processing"}],[{"type":"text","text":"Fairness constraints or penalties during training (e.g. "},{"type":"text","text":"fairlearn","marks":[{"type":"code"}]},{"type":"text","text":" reductions)"}]],[[{"type":"text","text":"Post-processing"}],[{"type":"text","text":"Group-specific thresholds to equalise TPR/FPR (check legality: some domains forbid group-dependent treatment)"}]],[[{"type":"text","text":"Process"}],[{"type":"text","text":"Slice-based evaluation before launch, human review for high-stakes decisions, appeal mechanisms, monitoring after launch"}]]]},"revision":1},{"id":"ec363252-a001-7c9e-b2e0-2c28e99e0548","type":"heading","position":"aD","content":{"level":1,"content":[{"type":"text","text":"Privacy"}]},"revision":1},{"id":"b8aee212-c1c8-7486-8f85-617b6d4b68a6","type":"text","position":"aE","content":{"doc":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Data minimisation","marks":[{"type":"bold"}]},{"type":"text","text":" — collect and keep only what the model needs; remove direct identifiers."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Anonymisation is hard","marks":[{"type":"bold"}]},{"type":"text","text":" — combinations of quasi-identifiers (zip code, birth date, gender) re-identify most people; models can also leak training data (membership-inference attacks)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Differential privacy (DP)","marks":[{"type":"bold"}]},{"type":"text","text":" — a formal guarantee: a mechanism M is ε-differentially private if for any two datasets differing in one person, "},{"type":"text","text":"P[M(D) ∈ S] ≤ e^ε · P[M(D′) ∈ S]","marks":[{"type":"code"}]},{"type":"text","text":". Adding calibrated noise is how it''s achieved (Laplace mechanism for counts; DP-SGD for training). Smaller ε = more privacy, less accuracy."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Federated learning","marks":[{"type":"bold"}]},{"type":"text","text":" — train across devices without centralising raw data; model updates can still leak information, so it''s combined with secure aggregation and DP."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Regulations such as GDPR (purpose limitation, data subject rights, rules on automated decisions) and the EU AI Act (risk-based obligations) shape what is allowed."}]}]}]}]}},"revision":1},{"id":"67c07853-3038-7a6d-98e9-50a124cf5800","type":"code","position":"aF","content":{"language":"python","code":"import numpy as np\n\nrng = np.random.default_rng(0)\ntrue_count = 132                                   # e.g. patients with a condition\nfor eps in (0.1, 1.0, 10.0):\n    noisy = true_count + rng.laplace(scale=1 / eps, size=5)   # Laplace mechanism: sensitivity 1 / ε\n    print(eps, noisy.round(1).tolist())","filename":"Python"},"revision":1},{"id":"8151e5ee-8065-7d61-a3c9-5636c2020941","type":"code","position":"aG","content":{"language":"text","code":"0.1 [135.2, 125.8, 107.0, 97.9, 141.8]\n1.0 [133.7, 132.2, 132.6, 132.1, 134.0]\n10.0 [132.1, 131.5, 132.1, 131.7, 132.1]","filename":"Output"},"revision":1},{"id":"7e3192fb-5e49-75e3-93b4-0c8f3d9a6880","type":"text","position":"aH","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Smaller ε means more noise: stronger privacy for any individual, less accurate answers."}]}]}},"revision":1},{"id":"5c5886db-9589-7773-8be1-136a2afee3ff","type":"heading","position":"aI","content":{"level":1,"content":[{"type":"text","text":"Documentation and oversight"}]},"revision":1},{"id":"320a01f3-fbb9-77b9-ba80-ec79894a8ab3","type":"text","position":"aJ","content":{"doc":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Model cards","marks":[{"type":"bold"}]},{"type":"text","text":" — intended use, out-of-scope uses, training data, metrics overall and by slice, limitations, ethical considerations."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Datasheets for datasets","marks":[{"type":"bold"}]},{"type":"text","text":" — how data was collected, by whom, consent, known gaps."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Human oversight and contestability for high-stakes decisions (credit, hiring, health, justice)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Security: adversarial examples, data poisoning and model extraction — see "},{"type":"text","text":"Deep Learning","marks":[{"type":"bold"}]},{"type":"text","text":" and "},{"type":"text","text":"Generative AI","marks":[{"type":"bold"}]},{"type":"text","text":" for model-specific risks such as prompt injection and hallucination."}]}]}]}]}},"revision":1},{"id":"29bbf4a4-ae35-7527-9808-23b0d870f14e","type":"question","position":"aK","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is the difference between demographic parity and equalized odds?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Demographic parity requires the same positive-prediction rate in each group regardless of the true labels. Equalized odds requires equal true-positive and false-positive rates — equal error rates conditioned on the true outcome. When base rates differ, satisfying one generally violates the other."}]}]}},"revision":1},{"id":"e5d572c1-816e-7e25-b7f4-167c704917e5","type":"question","position":"aL","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Removing the sensitive attribute makes the model fair — true?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"No. Other features act as proxies, so the model can reconstruct the attribute and reproduce the bias. And without the attribute you can''t even measure group disparities. Fairness needs measurement per group and deliberate mitigation."}]}]}},"revision":1},{"id":"5f08a08b-e530-7d29-b64d-db7b6f67f44f","type":"question","position":"aM","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is differential privacy?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A mathematical guarantee that the output of an analysis or trained model changes very little whether or not any single person''s data is included, bounded by ε. It is achieved by adding calibrated random noise (Laplace mechanism, DP-SGD) and trades privacy against accuracy."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
