SELECT 'a24fee60-eb08-7fde-8d41-6e5ad0f85f74', '6c5d7a2c-363e-7808-b139-78d3627bbe1c', 1, 'PUBLISHED', 'Anomaly Detection', '[{"id":"7f3eea3c-8f5c-7bc8-be12-15351b60a813","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Anomaly detection finds rows that don''t look like the rest — fraud, intrusions, faulty sensors, manufacturing defects. Labels are usually scarce, so most methods learn what "},{"type":"text","text":"normal","marks":[{"type":"italic"}]},{"type":"text","text":" looks like and score deviations from it."}]}]}},"revision":1},{"id":"3725bb2a-2dcc-7790-81d2-318c61b46082","type":"table","position":"a1","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Kind"}],[{"type":"text","text":"Example"}]],[[{"type":"text","text":"Point anomaly"}],[{"type":"text","text":"A $9,000 purchase on a card that averages $40"}]],[[{"type":"text","text":"Contextual anomaly"}],[{"type":"text","text":"30 °C is normal in July, anomalous in January"}]],[[{"type":"text","text":"Collective anomaly"}],[{"type":"text","text":"A burst of small logins from one IP, each normal on its own"}]]]},"revision":1},{"id":"ee9008af-ec69-7d09-b152-b52ed7afe798","type":"heading","position":"a2","content":{"level":1,"content":[{"type":"text","text":"Approaches"}]},"revision":1},{"id":"2d2d2e89-f17b-7558-964c-08548a698e62","type":"table","position":"a3","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Approach"}],[{"type":"text","text":"Method"}],[{"type":"text","text":"Idea"}]],[[{"type":"text","text":"Statistical"}],[{"type":"text","text":"z-score, IQR, robust z-score (median/MAD)"}],[{"type":"text","text":"Far from the centre of one feature''s distribution"}]],[[{"type":"text","text":"Isolation"}],[{"type":"text","text":"IsolationForest","marks":[{"type":"code"}]}],[{"type":"text","text":"Random splits isolate anomalies in fewer steps (shorter tree paths)"}]],[[{"type":"text","text":"Density / distance"}],[{"type":"text","text":"LocalOutlierFactor","marks":[{"type":"code"}]},{"type":"text","text":", k-NN distance"}],[{"type":"text","text":"Much lower local density than the neighbours"}]],[[{"type":"text","text":"Boundary"}],[{"type":"text","text":"OneClassSVM","marks":[{"type":"code"}]}],[{"type":"text","text":"A boundary enclosing the normal data"}]],[[{"type":"text","text":"Reconstruction"}],[{"type":"text","text":"PCA, autoencoders"}],[{"type":"text","text":"Normal data compresses well; anomalies reconstruct badly"}]],[[{"type":"text","text":"Supervised"}],[{"type":"text","text":"Any classifier with class weights"}],[{"type":"text","text":"When enough labelled anomalies exist — usually the most accurate"}]]]},"revision":1},{"id":"f906a72b-576e-7327-b6b9-2ea1878cee0a","type":"text","position":"a4","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"robust z = 0.6745 · (x − median) / MAD flag if |robust z| > 3.5 (MAD = median |x − median|)","marks":[{"type":"code"}]}]}]}},"revision":1},{"id":"1afbf313-d08d-7bdd-a8d5-4c7d092d5e10","type":"code","position":"a5","content":{"language":"python","code":"import numpy as np\n\nx = np.array([12, 14, 13, 15, 14, 13, 16, 14, 95])\nmed = np.median(x)\nmad = np.median(np.abs(x - med))\nrobust_z = 0.6745 * (x - med) / mad\nprint(med, mad, robust_z.round(1).tolist())   # 14.0 1.0 [-1.3, 0.0, -0.7, 0.7, 0.0, -0.7, 1.3, 0.0, 54.6] ← the 95 stands out; the plain z-score gave only 2.83","filename":"Python"},"revision":1},{"id":"b05713f2-d937-7489-a311-0d8b8e5f18de","type":"heading","position":"a6","content":{"level":1,"content":[{"type":"text","text":"Isolation Forest and LOF"}]},"revision":1},{"id":"67b7707a-775a-78a5-b3be-f789105773e0","type":"code","position":"a7","content":{"language":"python","code":"import numpy as np\nfrom sklearn.ensemble import IsolationForest\nfrom sklearn.metrics import precision_score, recall_score\nfrom sklearn.neighbors import LocalOutlierFactor\n\nrng = np.random.default_rng(0)\nnormal = rng.normal(0, 1, size=(300, 2))\nanomalies = rng.uniform(-6, 6, size=(15, 2))\nanomalies = anomalies[np.linalg.norm(anomalies, axis=1) > 4]      # keep clearly unusual points\nX = np.vstack([normal, anomalies])\ntruth = np.r_[np.zeros(len(normal)), np.ones(len(anomalies))]\n\niso = IsolationForest(contamination=0.03, random_state=0).fit(X)\nflag_iso = iso.predict(X) == -1                                    # −1 = anomaly, 1 = normal\nflag_lof = LocalOutlierFactor(n_neighbors=20, contamination=0.03).fit_predict(X) == -1\n\nprint(len(anomalies), int(flag_iso.sum()), int(flag_lof.sum()))    # 11 10 10 ← true anomalies, flagged by each\nprint(round(precision_score(truth, flag_iso), 2), round(recall_score(truth, flag_iso), 2))   # 1.0 0.91 ← Isolation Forest\nprint(round(precision_score(truth, flag_lof), 2), round(recall_score(truth, flag_lof), 2))   # 0.9 0.82 ← LOF","filename":"Python"},"revision":1},{"id":"5bb60c67-9bba-71e6-b6a7-c416eccb5ec2","type":"text","position":"a8","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"contamination","marks":[{"type":"code"}]},{"type":"text","text":" sets the expected share of anomalies — it only moves the "},{"type":"text","text":"threshold","marks":[{"type":"bold"}]},{"type":"text","text":" on the anomaly score ("},{"type":"text","text":"score_samples","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"decision_function","marks":[{"type":"code"}]},{"type":"text","text":"). In practice, rank rows by score and review the top k."}]}]}},"revision":1},{"id":"5a636713-ef2d-776c-8293-2cf1e1a439c4","type":"heading","position":"a9","content":{"level":1,"content":[{"type":"text","text":"Practical notes"}]},"revision":1},{"id":"587daae8-55b0-7578-9bf6-3c57bdcfb9fe","type":"text","position":"aA","content":{"doc":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Outlier detection","marks":[{"type":"bold"}]},{"type":"text","text":" (training data contains anomalies) vs "},{"type":"text","text":"novelty detection","marks":[{"type":"bold"}]},{"type":"text","text":" (train on clean data, score new points — "},{"type":"text","text":"LocalOutlierFactor(novelty=True)","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"OneClassSVM","marks":[{"type":"code"}]},{"type":"text","text":")."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Evaluate with whatever labels exist: precision@k (analysts review k alerts a day), recall on known incidents, PR-AUC. Accuracy is meaningless when 99.9% of rows are normal."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Scale features for distance-based methods; Isolation Forest doesn''t need it."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Once labelled anomalies accumulate, a supervised model (often gradient boosting with class weights) usually beats unsupervised scores — or use the scores as features for it."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Attackers adapt: monitor and retrain (see "},{"type":"text","text":"Deployment, Monitoring & MLOps","marks":[{"type":"bold"}]},{"type":"text","text":")."}]}]}]}]}},"revision":1},{"id":"38bd0599-2496-795a-976a-9b32eef9a42f","type":"question","position":"aB","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How does Isolation Forest work?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"It builds random trees that split on a random feature at a random threshold. Anomalies are few and different, so they are isolated near the root — their average path length across trees is short — while normal points need many splits. The anomaly score is based on that average path length."}]}]}},"revision":1},{"id":"31b367fe-74fd-725c-9215-239ab4165443","type":"question","position":"aC","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How do you evaluate an anomaly detector without labels?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Get at least a small labelled sample (analyst review of the top-scored and a random set of rows), then measure precision@k and recall. Also check stability of scores over time and use synthetic injected anomalies as a sanity check."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
