INSERT INTO "notes"."NoteVersion" ("id", "noteId", "number", "kind", "title", "cards", "createdById", "createdAt")
SELECT '0b8bf8f2-7dd9-7aa3-8a9d-d3f2133fc35d', 'e7dddb06-9952-7291-8179-31c2f34b8611', 1, 'PUBLISHED', 'Common Pitfalls', '[{"id":"8fdd7bbd-7e5e-73c4-9f39-b6bed84f0be7","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Most ML failures are process bugs, not algorithm choices. This checklist collects the classic ones with their symptoms and fixes."}]}]}},"revision":1},{"id":"a4732012-ae96-7ade-ad09-b0aa80e479ad","type":"table","position":"a1","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Pitfall"}],[{"type":"text","text":"Symptom"}],[{"type":"text","text":"Fix"}]],[[{"type":"text","text":"Data leakage"}],[{"type":"text","text":"Offline scores too good; collapse in production"}],[{"type":"text","text":"Split first, "},{"type":"text","text":"Pipeline","marks":[{"type":"code"}]},{"type":"text","text":", check feature availability at prediction time (see "},{"type":"text","text":"Data Leakage","marks":[{"type":"bold"}]},{"type":"text","text":")"}]],[[{"type":"text","text":"Duplicates / same entity across splits"}],[{"type":"text","text":"Near-perfect validation scores"}],[{"type":"text","text":"Deduplicate; group splits"}]],[[{"type":"text","text":"Random split of time-ordered data"}],[{"type":"text","text":"Production worse than validation"}],[{"type":"text","text":"Time-based split / "},{"type":"text","text":"TimeSeriesSplit","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Accuracy on imbalanced data"}],[{"type":"text","text":"High accuracy, useless model"}],[{"type":"text","text":"PR-AUC, recall/precision, cost; baseline comparison"}]],[[{"type":"text","text":"No baseline"}],[{"type":"text","text":"Can''t tell if the model adds value"}],[{"type":"text","text":"Dummy model + existing rule"}]],[[{"type":"text","text":"Tuning on the test set"}],[{"type":"text","text":"Test score optimistic; disappointment later"}],[{"type":"text","text":"Validation/CV for all choices; nested CV"}]],[[{"type":"text","text":"Overfitting the validation set"}],[{"type":"text","text":"Many experiments, tiny “wins” that don''t replicate"}],[{"type":"text","text":"Larger validation set, repeated CV, report variance"}]],[[{"type":"text","text":"Preprocessing fitted on all data"}],[{"type":"text","text":"Slightly-to-very optimistic scores"}],[{"type":"text","text":"Fit scalers/encoders/imputers/selectors inside CV"}]],[[{"type":"text","text":"Training–serving skew"}],[{"type":"text","text":"Same input, different prediction online vs offline"}],[{"type":"text","text":"One shared feature pipeline; log production features and compare"}]],[[{"type":"text","text":"Distribution shift"}],[{"type":"text","text":"Slow decay after launch"}],[{"type":"text","text":"Monitor inputs/outputs, retrain (see "},{"type":"text","text":"Deployment, Monitoring & MLOps","marks":[{"type":"bold"}]},{"type":"text","text":")"}]],[[{"type":"text","text":"Spurious correlations (shortcut learning)"}],[{"type":"text","text":"Great on validation, fails on new sources"}],[{"type":"text","text":"Error analysis, explainability, test on data from other sources/times"}]],[[{"type":"text","text":"Selection / sampling bias"}],[{"type":"text","text":"Model fails on groups under-represented in training"}],[{"type":"text","text":"Fix collection; slice metrics"}]],[[{"type":"text","text":"Label noise"}],[{"type":"text","text":"Plateaued accuracy; confident “errors” that are right"}],[{"type":"text","text":"Audit labels, agreement metrics, clean the test set"}]],[[{"type":"text","text":"Unscaled features for distance/regularised models"}],[{"type":"text","text":"k-NN/SVM/Lasso behave oddly"}],[{"type":"text","text":"Scale inside the pipeline"}]],[[{"type":"text","text":"Single run, no uncertainty"}],[{"type":"text","text":"Improvements within noise"}],[{"type":"text","text":"CV mean ± std, confidence intervals, significance tests"}]],[[{"type":"text","text":"Deep learning on small tabular data"}],[{"type":"text","text":"Hours of tuning, worse than a forest"}],[{"type":"text","text":"Start with linear models and gradient boosting"}]]]},"revision":1},{"id":"37e816a6-4a66-7ae5-b19e-abef153d6734","type":"heading","position":"a2","content":{"level":1,"content":[{"type":"text","text":"Demo: duplicates across the split"}]},"revision":1},{"id":"6322059e-13e1-78a2-8c02-cb5d1ee92fb4","type":"text","position":"a3","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Random labels — nothing to learn — but each row appears three times. A random split puts copies of test rows into training, and a 1-nearest-neighbour model “recognises” them:"}]}]}},"revision":1},{"id":"066a01d8-43f3-7d00-b92d-f721d4df2b7a","type":"code","position":"a4","content":{"language":"python","code":"import numpy as np\nfrom sklearn.model_selection import GroupShuffleSplit, train_test_split\nfrom sklearn.neighbors import KNeighborsClassifier\n\nrng = np.random.default_rng(0)\nX0 = rng.normal(size=(300, 5))\ny0 = rng.integers(0, 2, size=300)                  # random labels\nX, y = np.repeat(X0, 3, axis=0), np.repeat(y0, 3)  # every row duplicated 3×\nrow_id = np.repeat(np.arange(300), 3)\n\nX_tr, X_te, y_tr, y_te = train_test_split(X, y, test_size=0.3, random_state=0)\nprint(round(KNeighborsClassifier(1).fit(X_tr, y_tr).score(X_te, y_te), 2))   # 0.97 ← \"learned\" noise\n\ntr, te = next(GroupShuffleSplit(test_size=0.3, random_state=0).split(X, y, groups=row_id))\nprint(round(KNeighborsClassifier(1).fit(X[tr], y[tr]).score(X[te], y[te]), 2))   # 0.53 ← honest: chance level","filename":"Python"},"revision":1},{"id":"7689ed4b-f19b-7425-9440-f6486f7591ee","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"Before you trust a result"}]},"revision":1},{"id":"2a3d1958-b0e3-74a2-8978-e9c40aa691b0","type":"text","position":"a6","content":{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Is there a baseline, and does the model clearly beat it?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Was the split done first, and by time/group where needed?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Is every feature available at prediction time?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Is all preprocessing inside the pipeline?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Is the metric the one the business cares about, at the threshold that will be used?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Is the improvement larger than the run-to-run variance?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Has the test set been used only once?"}]}]}]}]}},"revision":1},{"id":"e84c7f3e-525e-7c11-82d8-dffa159c929c","type":"question","position":"a7","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What are the most common mistakes in ML projects?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Leakage (target leakage, preprocessing before splitting, duplicates or groups across splits, random splits of time series), evaluating with the wrong metric (accuracy on imbalanced data), no baseline, tuning on the test set, and ignoring training–serving skew and drift after deployment."}]}]}},"revision":1},{"id":"e456f818-55d2-7006-9474-bf3483518c24","type":"question","position":"a8","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A model does great offline but poorly in production. What could be wrong?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Leakage in offline evaluation, training–serving skew (features computed differently online), distribution or concept drift since the training data, a different population in production (selection bias), or a threshold chosen for a different base rate. Compare logged production features and predictions with the training data to find out which."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
