INSERT INTO "notes"."NoteVersion" ("id", "noteId", "number", "kind", "title", "cards", "createdById", "createdAt")
SELECT '0e5d009a-bcc0-7f8a-9115-a7f5064e9ec3', 'e4ca97ad-31d3-7971-b2c4-f7b9ae5a4beb', 1, 'PUBLISHED', 'Data Collection & Labeling', '[{"id":"cf4bd677-6992-79a7-92f5-6c31eeb44d7e","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A model can only be as good as its data. The training set must "},{"type":"text","text":"represent the population the model will serve","marks":[{"type":"bold"}]},{"type":"text","text":", and the labels must be consistent enough to learn from."}]}]}},"revision":1},{"id":"3f044f63-d77a-72a2-a198-9ddfcff4210b","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Where data comes from"}]},"revision":1},{"id":"27988709-c984-7df9-9700-3cd4076b8e96","type":"table","position":"a2","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Source"}],[{"type":"text","text":"Strengths"}],[{"type":"text","text":"Watch out for"}]],[[{"type":"text","text":"Product logs & databases"}],[{"type":"text","text":"Real, plentiful, matches production"}],[{"type":"text","text":"Logging bugs, missing fields, only sees what the current system shows users"}]],[[{"type":"text","text":"Public datasets"}],[{"type":"text","text":"Fast to start, benchmarks"}],[{"type":"text","text":"Different population; license terms"}]],[[{"type":"text","text":"APIs & web scraping"}],[{"type":"text","text":"Broad coverage"}],[{"type":"text","text":"Terms of service, copyright, personal data, rate limits"}]],[[{"type":"text","text":"Sensors / IoT"}],[{"type":"text","text":"High volume, time-stamped"}],[{"type":"text","text":"Drift, calibration errors, gaps"}]],[[{"type":"text","text":"Human annotation"}],[{"type":"text","text":"Labels exactly what you need"}],[{"type":"text","text":"Cost, inconsistency, annotator bias"}]],[[{"type":"text","text":"Synthetic data"}],[{"type":"text","text":"Rare cases, privacy"}],[{"type":"text","text":"May not reflect real-world messiness"}]]]},"revision":1},{"id":"3c5dc5b4-4ea4-777a-809c-ffb7e1afe5a0","type":"heading","position":"a3","content":{"level":1,"content":[{"type":"text","text":"Representativeness and sampling bias"}]},"revision":1},{"id":"84eb1f35-0d3a-71d3-bb41-5259d4950df1","type":"text","position":"a4","content":{"doc":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Selection bias","marks":[{"type":"bold"}]},{"type":"text","text":" — the sample isn''t random: a loan model trained only on "},{"type":"text","text":"approved","marks":[{"type":"italic"}]},{"type":"text","text":" applicants never sees how rejected ones would have repaid."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Survivorship bias","marks":[{"type":"bold"}]},{"type":"text","text":" — only the survivors are recorded (products still on sale, companies still trading)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Coverage gaps","marks":[{"type":"bold"}]},{"type":"text","text":" — a speech model trained on one accent, a vision model trained on daytime photos."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Time mismatch","marks":[{"type":"bold"}]},{"type":"text","text":" — data from last year when behaviour has since changed."}]}]}]}]}},"revision":1},{"id":"8a254972-3cd6-7479-994e-22bb5f80c542","type":"callout","position":"a5","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Ask: "},{"type":"text","text":"would the rows I train on look like the rows the model will score next month?","marks":[{"type":"italic"}]},{"type":"text","text":" If not, fix the collection before tuning any model."}]}]}},"revision":1},{"id":"059cb9d4-cf6a-7634-ae3b-c46e9681ace1","type":"heading","position":"a6","content":{"level":1,"content":[{"type":"text","text":"Labeling"}]},"revision":1},{"id":"51aa38cf-4f94-7fcc-b5a0-1332bcb4ee16","type":"text","position":"a7","content":{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Write guidelines","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Exact definitions and edge cases (“is a sarcastic review negative?”) with examples."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Pilot and measure agreement","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Several annotators label the same items; compute inter-annotator agreement."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Label at scale with checks","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Gold questions with known answers, multiple labels per item, majority vote or a label model."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Audit","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Review disagreements and model–label conflicts; they often reveal unclear guidelines."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Raw percent agreement is inflated by chance. "},{"type":"text","text":"Cohen''s kappa","marks":[{"type":"bold"}]},{"type":"text","text":" corrects for the agreement two annotators would reach by guessing with their own label frequencies:"}]},{"type":"paragraph","content":[{"type":"text","text":"κ = (pₒ − pₑ) / (1 − pₑ) pₒ = observed agreement, pₑ = agreement expected by chance","marks":[{"type":"code"}]}]}]}},"revision":1},{"id":"fdd4ecc3-ad5b-79db-b98a-4534e8ec6d75","type":"code","position":"a8","content":{"language":"python","code":"from sklearn.metrics import cohen_kappa_score\n\na = [\"spam\", \"ham\", \"spam\", \"spam\", \"ham\", \"ham\", \"spam\", \"ham\", \"ham\", \"ham\"]\nb = [\"spam\", \"ham\", \"ham\", \"spam\", \"ham\", \"ham\", \"spam\", \"ham\", \"spam\", \"ham\"]\n\np_o = sum(x == y for x, y in zip(a, b)) / len(a)\np_e = 0.4 * 0.4 + 0.6 * 0.6            # both say spam 40% of the time, ham 60%\nprint(p_o, round(p_e, 2))              # 0.8 0.52\nprint(round((p_o - p_e) / (1 - p_e), 3), round(cohen_kappa_score(a, b), 3))   # 0.583 0.583 ← same number","filename":"Python"},"revision":1},{"id":"fec8da05-1a83-7de4-b556-96d9801bb89b","type":"text","position":"a9","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Rough reading (Landis & Koch): < 0.4 poor to fair, 0.4–0.6 moderate, 0.6–0.8 substantial, > 0.8 near-perfect. Use Fleiss'' kappa or Krippendorff''s alpha for more than two annotators."}]}]}},"revision":1},{"id":"ce5e0eec-adc7-7354-9411-8a7f7e986378","type":"heading","position":"aA","content":{"level":1,"content":[{"type":"text","text":"Getting labels cheaply"}]},"revision":1},{"id":"aa884623-24b2-7c2b-9596-e3360a2e94f1","type":"callout","position":"aB","content":{"variant":"note","title":"Active learning","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Train on a few labels, then ask humans to label the examples the model is "},{"type":"text","text":"least sure","marks":[{"type":"bold"}]},{"type":"text","text":" about — they carry the most information per label."}]}]}},"revision":1},{"id":"8b6e565d-f11a-7ffc-a1bd-a5952e2b5d18","type":"callout","position":"aC","content":{"variant":"note","title":"Weak supervision","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Write several noisy "},{"type":"text","text":"labeling functions","marks":[{"type":"bold"}]},{"type":"text","text":" (keywords, regexes, heuristics, existing models); a label model estimates each function''s accuracy and combines their votes into probabilistic labels (the Snorkel approach)."}]}]}},"revision":1},{"id":"bc6ba0a9-f102-7c1b-83a1-30220ce849c8","type":"callout","position":"aD","content":{"variant":"note","title":"Semi-supervised","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Use many unlabelled rows alongside a few labelled ones, e.g. self-training on confident predictions."}]}]}},"revision":1},{"id":"197cc4e1-4fa5-7ed6-8fce-7df5146c3d7f","type":"callout","position":"aE","content":{"variant":"note","title":"Transfer learning","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Start from a model pre-trained on related data so far fewer labels are needed (see "},{"type":"text","text":"Deep Learning","marks":[{"type":"bold"}]},{"type":"text","text":")."}]}]}},"revision":1},{"id":"37a4d0d7-1ed4-79b2-8bc8-0d9ca692a27a","type":"code","position":"aF","content":{"language":"python","code":"import numpy as np\nfrom sklearn.datasets import make_classification\nfrom sklearn.linear_model import LogisticRegression\n\nX, y = make_classification(n_samples=500, random_state=0)\nlabeled, pool = np.arange(20), np.arange(20, 500)        # we paid for 20 labels so far\n\nmodel = LogisticRegression().fit(X[labeled], y[labeled])\np = model.predict_proba(X[pool])[:, 1]\nmost_uncertain = np.argsort(np.abs(p - 0.5))[:5]           # probabilities closest to 0.5\nprint(pool[most_uncertain])                               # [393 398 245 464 413] ← send these rows to annotators\nprint(p[most_uncertain].round(2))                         # [0.5  0.5  0.51 0.51 0.49]","filename":"Python"},"revision":1},{"id":"62ab201f-ebfa-71ac-99fc-0d5b0f5c6f43","type":"callout","position":"aG","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Keep the raw data, the labeling guidelines and each dataset version together (DVC, lakeFS, or dated snapshots). A model whose training data can''t be reproduced can''t be debugged or audited."}]}]}},"revisio