SELECT 'cda04cdd-bc49-793e-b382-5281b7728c29', '916feb8a-1cf6-7524-babf-681deef2fd5b', 1, 'PUBLISHED', 'What Is Machine Learning?', '[{"id":"6dc7a134-cf40-76a7-a98d-7f5d23cc8b40","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Machine learning builds programs that "},{"type":"text","text":"improve at a task from data","marks":[{"type":"bold"}]},{"type":"text","text":" instead of from hand-written rules. You supply examples; a learning algorithm finds the parameters of a model that generalises to examples it has never seen."}]}]}},"revision":1},{"id":"a197a417-b9e3-7b70-b0a1-923517a80a5f","type":"callout","position":"a1","content":{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Machine learning (Mitchell, 1997)","marks":[{"type":"bold"}]},{"type":"text","text":" — a program "},{"type":"text","text":"learns","marks":[{"type":"italic"}]},{"type":"text","text":" from experience "},{"type":"text","text":"E","marks":[{"type":"bold"}]},{"type":"text","text":" with respect to a task "},{"type":"text","text":"T","marks":[{"type":"bold"}]},{"type":"text","text":" and a performance measure "},{"type":"text","text":"P","marks":[{"type":"bold"}]},{"type":"text","text":" if its performance at T, measured by P, improves with E. Spam filtering: T = label emails, E = emails people marked as spam or not, P = the share of emails labelled correctly."}]}]}},"revision":1},{"id":"1e15d903-2c7e-73b7-9bc8-797c1b2594ab","type":"heading","position":"a2","content":{"level":1,"content":[{"type":"text","text":"Rules vs learning"}]},"revision":1},{"id":"172473d2-4bd7-7f08-a461-aaa994180709","type":"text","position":"a3","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"In traditional programming a person writes the rules. In ML the rules — the model''s parameters — are "},{"type":"text","text":"fitted","marks":[{"type":"italic"}]},{"type":"text","text":" from examples of inputs paired with the right answers."}]},{"type":"paragraph","content":[{"type":"text","text":"Data + hand-written rules → Program → Answers"}]},{"type":"paragraph","content":[{"type":"text","text":"Data + known answers → Learning algorithm → Model (learned rules) → Answers for new data"}]},{"type":"paragraph","content":[{"type":"text","text":"A tiny example: the algorithm is never told the rule "},{"type":"text","text":"y = 3x + 2","marks":[{"type":"code"}]},{"type":"text","text":"; it recovers it from 50 noisy examples."}]}]}},"revision":1},{"id":"0686b181-52f0-7348-b602-61706986569c","type":"code","position":"a4","content":{"language":"python","code":"import numpy as np\nfrom sklearn.linear_model import LinearRegression\n\nrng = np.random.default_rng(0)\nX = rng.uniform(0, 10, size=(50, 1))              # feature: hours studied\ny = 3 * X[:, 0] + 2 + rng.normal(0, 1, size=50)   # target: score, with noise\n\nmodel = LinearRegression().fit(X, y)              # training = fitting parameters\nprint(round(model.coef_[0], 2), round(model.intercept_, 2))  # 3.05 1.76 ← close to the true 3 and 2\nprint(round(model.predict([[4.0]])[0], 1))                   # 14.0 ← inference on a new input (true value 14)","filename":"Python"},"revision":1},{"id":"6815b354-7d9a-7152-8be3-03521dde1326","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"The supervised setting"}]},"revision":1},{"id":"de6c9531-884f-7b1d-bc5a-f9c919320352","type":"text","position":"a6","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"y = f(x) + ε learn f̂ ≈ f from pairs (x₁, y₁), …, (xₙ, yₙ)","marks":[{"type":"code"}]}]},{"type":"paragraph","content":[{"type":"text","text":"f","marks":[{"type":"code"}]},{"type":"text","text":" is the unknown true relationship and "},{"type":"text","text":"ε","marks":[{"type":"code"}]},{"type":"text","text":" is noise no model can predict (measurement error, missing information). Even a perfect "},{"type":"text","text":"f̂","marks":[{"type":"code"}]},{"type":"text","text":" keeps the error caused by "},{"type":"text","text":"ε","marks":[{"type":"code"}]},{"type":"text","text":" — the "},{"type":"text","text":"irreducible error","marks":[{"type":"bold"}]},{"type":"text","text":". This picture covers supervised learning; unsupervised learning has no "},{"type":"text","text":"y","marks":[{"type":"code"}]},{"type":"text","text":" at all (see "},{"type":"text","text":"Types of Learning","marks":[{"type":"bold"}]},{"type":"text","text":")."}]}]}},"revision":1},{"id":"357f6b56-0cb3-7961-a5da-f568aa3e8821","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"Vocabulary"}]},"revision":1},{"id":"1b268930-240c-7db6-8fa8-af32f1664036","type":"table","position":"a8","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Term"}],[{"type":"text","text":"Meaning"}],[{"type":"text","text":"House-price example"}]],[[{"type":"text","text":"Example / sample / row"}],[{"type":"text","text":"One observation"}],[{"type":"text","text":"One house sale"}]],[[{"type":"text","text":"Feature (input, predictor) "},{"type":"text","text":"x","marks":[{"type":"code"}]}],[{"type":"text","text":"A measurable input variable"}],[{"type":"text","text":"Area, bedrooms, distance to metro"}]],[[{"type":"text","text":"Label / target "},{"type":"text","text":"y","marks":[{"type":"code"}]}],[{"type":"text","text":"The value to predict (supervised learning only)"}],[{"type":"text","text":"Sale price"}]],[[{"type":"text","text":"Model"}],[{"type":"text","text":"A function "},{"type":"text","text":"f̂","marks":[{"type":"code"}]},{"type":"text","text":" from features to predictions"}],[{"type":"text","text":"price ≈ w₁·area + w₂·bedrooms + b","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Parameters"}],[{"type":"text","text":"Learned from data during training"}],[{"type":"text","text":"The weights "},{"type":"text","text":"w₁, w₂, b","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Hyperparameters"}],[{"type":"text","text":"Chosen "},{"type":"text","text":"before","marks":[{"type":"italic"}]},{"type":"text","text":" training, tuned on validation data"}],[{"type":"text","text":"Regularisation strength, tree depth"}]],[[{"type":"text","text":"Training / fitting"}],[{"type":"text","text":"Adjusting parameters to reduce a loss on training data"}],[{"type":"text","text":"model.fit(X, y)","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Inference / prediction"}],[{"type":"text","text":"Applying the trained model to new inputs"}],[{"type":"text","text":"model.predict(X_new)","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Generalisation"}],[{"type":"text","text":"Performing well on unseen data from the same distribution"}],[{"type":"text","text":"Accurate prices for next month''s listings"}]]]},"revision":1},{"id":"974c007b-d432-702c-a918-2022db5406d3","type":"heading","position":"a9","content":{"level":1,"content":[{"type":"text","text":"AI, ML and deep learning"}]},"revision":1},{"id":"62f544a8-eddd-7751-9664-7a8e10c99221","type":"text","position":"aA","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Artificial Intelligence → Machine Learning → Deep Learning"}]}]}},"revision":1},{"id":"8dc3aee0-4edb-77bd-85d5-f33783e651c6","type":"table","position":"aB","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Field"}],[{"type":"text","text":"What it is"}],[{"type":"text","text":"Example"}]],[[{"type":"text","text":"Artificial intelligence"}],[{"type":"text","text":"Any technique that makes machines act intelligently — including search, logic and planning that learn nothing from data"}],[{"type":"text","text":"A route planner using A* search"}]],[[{"type":"text","text":"Machine learning"}],[{"type":"text","text":"The part of AI that learns behaviour from data"}],[{"type":"text","text":"Gradient-boosted trees predicting customer churn"}]],[[{"type":"text","text":"Deep learning"}],[{"type":"text","text":"ML with many-layered neural networks that learn their own features from raw data"}],[{"type":"text","text":"A transformer transcribing speech"}]]]},"revision":1},{"id":"4c1024a1-a4f2-7535-907a-39a63f133a74","type":"callout","position":"aC","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"These notes cover classic ML on mostly tabular data. Neural networks are covered in "},{"type":"text","text":"Deep Learning","marks":[{"type":"bold"}]},{"type":"text","text":", LLMs and prompting in "},{"type":"text","text":"Generative AI","marks":[{"type":"bold"}]},{"type":"text","text":", search/logic/planning in "},{"type":"text","text":"Artificial Intelligence","marks":[{"type":"bold"}]},{"type":"text","text":", and NumPy/pandas/plotting in "},{"type":"text","text":"Data Science","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"2dfd17a7-164d-779a-bfcf-bab4781effd2","type":"heading","position":"aD","content":{"level":1,"content":[{"type":"text","text":"When ML is — and isn''t — the right tool"}]},"revision":1},{"id":"8e3fbc32-1153-7b8a-a7c8-11890ea8caf4","type":"callout","position":"aE","content":{"variant":"tip","title":"Do","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Use ML when rules are too many or unknown (spam, fraud, images), the patterns change over time, there is enough representative data, and occasional errors are acceptable."}]}]}},"revision":1},{"id":"513316c5-ae2d-729c-b859-fe5332718ac8","type":"callout","position":"aF","content":{"variant":"danger","title":"Avoid","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Using ML when a few clear rules work, when there is no data (or no labels) to learn from, when every decision must be exactly explainable and guaranteed, or when a wrong answer is catastrophic and cannot be caught."}]}]}},"revision":1},{"id":"06984a47-969f-7f4a-a83f-0162e5ce8f19","type":"heading","position":"aG","content":{"level":1,"content":[{"type":"text","text":"The workflow at a glance"}]},"revision":1},{"id":"4c6f130a-e7ca-7353-b689-ca066464211f","type":"text","position":"aH","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Frame the problem → Collect & explore data → Split train / validation / test → Prepare features → Train a baseline, then better models → Tune & validate → Test once → Deploy & monitor"}]},{"type":"paragraph","content":[{"type":"text","text":"Each box has its own topic in these notes. The split comes "},{"type":"text","text":"before","marks":[{"type":"italic"}]},{"type":"text","text":" any preprocessing is fitted, and the test set is used once at the end — breaking either rule causes "},{"type":"text","text":"data leakage","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"42d4bd95-3d22-7e12-b29b-b280774d22f0","type":"question","position":"aI","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is the difference between a parameter and a hyperparameter?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Parameters are learned from the training data (regression weights, tree split thresholds). Hyperparameters are set before training and control "},{"type":"text","text":"how","marks":[{"type":"italic"}]},{"type":"text","text":" learning happens (learning rate, "},{"type":"text","text":"max_depth","marks":[{"type":"code"}]},{"type":"text","text":", regularisation strength "},{"type":"text","text":"C","marks":[{"type":"code"}]},{"type":"text","text":"); they are chosen by comparing models on validation data or with cross-validation."}]}]}},"revision":1},{"id":"8d5f18f1-9dd1-7408-acb9-670add14b8f3","type":"question","position":"aJ","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What does it mean for a model to generalise?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"It performs about as well on new data from the same distribution as on the data it was trained on. We estimate this with held-out data the model never saw during training or tuning. A model that is excellent on training data but poor on held-out data has overfit."}]}]}},"revision":1},{"id":"bf0a7123-8fda-7f08-9aa5-5657a33a0efc","type":"question","position":"aK","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How is ML different from traditional programming?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Traditional programs apply rules a developer wrote. ML programs apply rules (parameters) that an algorithm "},{"type":"text","text":"fitted","marks":[{"type":"italic"}]},{"type":"text","text":" from examples, so behaviour comes from the data — which is also why data quality, representativeness and leakage matter so much."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
