SELECT 'fd1bb897-e956-73e8-9e8a-44eb6136722d', '79e7730b-e58c-758f-8471-94d2f4ed85c7', 1, 'PUBLISHED', 'Deployment, Monitoring & MLOps', '[{"id":"e9f355fa-df99-79c8-a366-3e1d2e56dfdb","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A model creates value only in production — and production data changes. Deploy safely, monitor inputs, outputs and outcomes, and automate retraining. MLOps is the engineering discipline that makes this repeatable."}]}]}},"revision":1},{"id":"7aa46f3c-9b6c-75b3-91c0-d6041666df96","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Serving patterns"}]},"revision":1},{"id":"f36ed618-d05a-772a-9692-1fdead13fe7a","type":"table","position":"a2","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Pattern"}],[{"type":"text","text":"How"}],[{"type":"text","text":"Example"}]],[[{"type":"text","text":"Batch"}],[{"type":"text","text":"Score everything on a schedule, store results"}],[{"type":"text","text":"Nightly churn scores for the CRM"}]],[[{"type":"text","text":"Online (real-time)"}],[{"type":"text","text":"A service answers each request (REST/gRPC) in milliseconds"}],[{"type":"text","text":"Fraud check at payment time"}]],[[{"type":"text","text":"Streaming"}],[{"type":"text","text":"Score events from a queue (Kafka) as they arrive"}],[{"type":"text","text":"Anomaly alerts on sensor streams"}]],[[{"type":"text","text":"Edge / on-device"}],[{"type":"text","text":"Model runs on the phone or device"}],[{"type":"text","text":"Keyboard suggestions, offline vision"}]]]},"revision":1},{"id":"10217b68-0122-7d8e-9c8c-f5f9b3e6fdad","type":"heading","position":"a3","content":{"level":1,"content":[{"type":"text","text":"Rolling out safely"}]},"revision":1},{"id":"47f58e93-db05-7b0a-93ce-ab5b08487762","type":"table","position":"a4","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Strategy"}],[{"type":"text","text":"How"}],[{"type":"text","text":"Catches"}]],[[{"type":"text","text":"Shadow"}],[{"type":"text","text":"New model scores live traffic, but its outputs are only logged"}],[{"type":"text","text":"Crashes, latency, training–serving skew — no user risk"}]],[[{"type":"text","text":"Canary"}],[{"type":"text","text":"Route a small % of traffic to the new model, grow it gradually"}],[{"type":"text","text":"Problems at small blast radius"}]],[[{"type":"text","text":"A/B test"}],[{"type":"text","text":"Randomised split, compare business metrics"}],[{"type":"text","text":"Whether it actually helps (see "},{"type":"text","text":"A/B Testing","marks":[{"type":"bold"}]},{"type":"text","text":")"}]],[[{"type":"text","text":"Blue–green + rollback"}],[{"type":"text","text":"Keep the previous version ready to switch back instantly"}],[{"type":"text","text":"Anything missed above"}]]]},"revision":1},{"id":"68366b2e-dc7a-74c1-a7ea-4407873007e9","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"Why models decay: drift"}]},"revision":1},{"id":"12828fe7-0d00-783d-a358-70da4a829ea3","type":"table","position":"a6","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Type"}],[{"type":"text","text":"What changes"}],[{"type":"text","text":"Example"}]],[[{"type":"text","text":"Covariate (data) shift"}],[{"type":"text","text":"P(X)","marks":[{"type":"code"}]},{"type":"text","text":" changes, "},{"type":"text","text":"P(y | X)","marks":[{"type":"code"}]},{"type":"text","text":" stays"}],[{"type":"text","text":"A marketing campaign brings younger users"}]],[[{"type":"text","text":"Label (prior) shift"}],[{"type":"text","text":"P(y)","marks":[{"type":"code"}]},{"type":"text","text":" changes"}],[{"type":"text","text":"Fraud rate doubles during a holiday season"}]],[[{"type":"text","text":"Concept drift"}],[{"type":"text","text":"P(y | X)","marks":[{"type":"code"}]},{"type":"text","text":" changes — the same inputs now mean something else"}],[{"type":"text","text":"Spending patterns after a price shock; fraudsters change tactics"}]],[[{"type":"text","text":"Upstream data changes"}],[{"type":"text","text":"A pipeline bug, unit change or new category"}],[{"type":"text","text":"A field starts arriving in cents instead of dollars"}]]]},"revision":1},{"id":"09a23734-8431-7c86-a717-c9cf39e9a1bf","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"Measuring input drift"}]},"revision":1},{"id":"30dc3fcb-75b5-7a96-8918-8de34d6f9e35","type":"text","position":"a8","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"PSI = Σ_bins (actual% − expected%) · ln(actual% / expected%) < 0.1 stable · 0.1–0.25 moderate · > 0.25 major shift","marks":[{"type":"code"}]}]}]}},"revision":1},{"id":"451c7d74-ebba-7957-adc7-fbcb2f26cbd1","type":"code","position":"a9","content":{"language":"python","code":"import numpy as np\nfrom scipy.stats import ks_2samp\n\nrng = np.random.default_rng(0)\ntrain = rng.normal(50, 10, 10000)                 # feature at training time\nsame = rng.normal(50, 10, 5000)                   # production, unchanged\nshifted = rng.normal(56, 12, 5000)                # production, drifted\n\ndef psi(expected, actual, bins=10):\n    edges = np.quantile(expected, np.linspace(0, 1, bins + 1))\n    edges[0], edges[-1] = -np.inf, np.inf\n    e = np.histogram(expected, edges)[0] / len(expected)\n    a = np.histogram(actual, edges)[0] / len(actual)\n    e, a = np.clip(e, 1e-6, None), np.clip(a, 1e-6, None)\n    return float(np.sum((a - e) * np.log(a / e)))\n\nprint(round(psi(train, same), 3), round(psi(train, shifted), 3))                          # 0.002 0.293\nprint(round(ks_2samp(train, same).statistic, 3), round(ks_2samp(train, shifted).statistic, 3))   # 0.008 0.22 ← KS distance","filename":"Python"},"revision":1},{"id":"47684a33-13ef-7b2c-b84f-4158519b54a8","type":"callout","position":"aA","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"With large samples, KS p-values flag even trivial differences as significant — alert on effect sizes (PSI, KS statistic, Wasserstein distance) and on the features that matter most to the model."}]}]}},"revision":1},{"id":"6be48036-39dc-7bfb-9edb-1b3b8efdda4c","type":"heading","position":"aB","content":{"level":1,"content":[{"type":"text","text":"What to monitor"}]},"revision":1},{"id":"2edfe175-9b8e-7f6f-9359-af22e37e351b","type":"table","position":"aC","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Layer"}],[{"type":"text","text":"Signals"}]],[[{"type":"text","text":"Service health"}],[{"type":"text","text":"Latency, throughput, error rate, memory"}]],[[{"type":"text","text":"Data quality"}],[{"type":"text","text":"Schema, missing-value rates, out-of-range values, unseen categories"}]],[[{"type":"text","text":"Input drift"}],[{"type":"text","text":"PSI / KS per important feature"}]],[[{"type":"text","text":"Prediction drift"}],[{"type":"text","text":"Distribution of scores and predicted classes; share of positives"}]],[[{"type":"text","text":"Model performance"}],[{"type":"text","text":"Accuracy/precision/recall or error once labels arrive — often delayed by days or weeks"}]],[[{"type":"text","text":"Business KPIs"}],[{"type":"text","text":"Conversion, fraud losses, complaints"}]]]},"revision":1},{"id":"0e24daea-e589-72c5-b54f-677a460ce09d","type":"heading","position":"aD","content":{"level":1,"content":[{"type":"text","text":"Retraining"}]},"revision":1},{"id":"7fc0386c-18ff-7e5f-a31f-70efe5a0b575","type":"text","position":"aE","content":{"doc":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Scheduled","marks":[{"type":"bold"}]},{"type":"text","text":" — retrain weekly/monthly on a sliding window; simple and predictable."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Triggered","marks":[{"type":"bold"}]},{"type":"text","text":" — retrain when drift or performance alerts fire."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Continuous / online","marks":[{"type":"bold"}]},{"type":"text","text":" — incremental updates ("},{"type":"text","text":"partial_fit","marks":[{"type":"code"}]},{"type":"text","text":") for fast-moving data."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Always validate the new model against the current one on recent data before promoting it; retraining on bad (buggy, poisoned) data makes things worse."}]}]}]}]}},"revision":1},{"id":"b0f25f03-f5dd-72aa-8b3c-4d026ad4c891","type":"heading","position":"aF","content":{"level":1,"content":[{"type":"text","text":"MLOps practices"}]},"revision":1},{"id":"f3cc59ef-7173-726b-be59-da5c6ec8e7dd","type":"table","position":"aG","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Practice"}],[{"type":"text","text":"Why"}],[{"type":"text","text":"Tools (examples)"}]],[[{"type":"text","text":"Version code, data and models"}],[{"type":"text","text":"Reproduce any model and debug regressions"}],[{"type":"text","text":"Git, DVC, lakeFS"}]],[[{"type":"text","text":"Experiment tracking"}],[{"type":"text","text":"Compare runs, parameters, metrics, artefacts"}],[{"type":"text","text":"MLflow, Weights & Biases"}]],[[{"type":"text","text":"Model registry"}],[{"type":"text","text":"Staging → production promotion, lineage, rollback"}],[{"type":"text","text":"MLflow Model Registry, SageMaker, Vertex AI"}]],[[{"type":"text","text":"Feature store"}],[{"type":"text","text":"Same feature definitions offline (training) and online (serving)"}],[{"type":"text","text":"Feast, Tecton"}]],[[{"type":"text","text":"CI/CD/CT"}],[{"type":"text","text":"Automated tests, builds, deployments — and continuous training"}],[{"type":"text","text":"GitHub Actions, Kubeflow, Airflow"}]],[[{"type":"text","text":"Data validation"}],[{"type":"text","text":"Catch schema and distribution problems before training/serving"}],[{"type":"text","text":"Great Expectations, TFDV, pandera"}]],[[{"type":"text","text":"Documentation"}],[{"type":"text","text":"Intended use, data, metrics by slice, limitations"}],[{"type":"text","text":"Model cards, datasheets for datasets"}]]]},"revision":1},{"id":"8e7e5c30-f7e2-7e0b-87bf-1dc8e4f001a6","type":"callout","position":"aH","content":{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Training–serving skew","marks":[{"type":"bold"}]},{"type":"text","text":" — a difference between how features are computed at training time and at serving time (different code, different data freshness, a timezone bug). The model sees inputs it was never trained on. Prevent with shared feature code or a feature store, and by logging production features to compare with training data."}]}]}},"revision":1},{"id":"31de8fa0-7f90-75c9-aa93-46a5dbeaab36","type":"question","position":"aI","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How do you detect and handle model drift in production?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Monitor input feature distributions (PSI/KS), prediction distributions and — as labels arrive — actual performance, plus data-quality checks. When alerts fire, first rule out pipeline bugs and training–serving skew, then diagnose the type of drift, retrain on recent data (or adjust thresholds for pure label shift), validate against the current model, and roll out gradually."}]}]}},"revision":1},{"id":"f731ca46-3e3d-75be-b98c-64e10727054d","type":"question","position":"aJ","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is the difference between covariate shift and concept drift?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Covariate shift: the input distribution P(X) changes but the relationship P(y|X) is the same — the model may still be right where it has data, but sees unfamiliar regions. Concept drift: P(y|X) itself changes, so the learned mapping is wrong and the model must be retrained with new labels."}]}]}},"revision":1},{"id":"fb95b763-0b17-7564-a6eb-7a624ee905ee","type":"question","position":"aK","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Shadow vs canary deployment?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Shadow: the new model receives a copy of live traffic but its predictions aren''t used — zero user impact, good for checking latency and skew. Canary: the new model actually serves a small fraction of users, which tests real impact with limited risk before a full rollout."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
