INSERT INTO "notes"."NoteVersion" ("id", "noteId", "number", "kind", "title", "cards", "createdById", "createdAt")
SELECT '6863c70c-d5f4-79c1-a3d1-baacd6307d75', '1d64a3ae-5fa6-7503-9d16-7649ebcf065c', 1, 'PUBLISHED', 'Data Types & EDA', '[{"id":"2602315b-28dc-717a-b395-0c80ddd08c94","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Exploratory data analysis (EDA) is how you learn what''s in the data before modelling: types, missing values, distributions, outliers, the target''s balance and suspicious features."}]}]}},"revision":1},{"id":"0f4acc71-2783-7f05-9f80-3b3e1320477f","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Kinds of data"}]},"revision":1},{"id":"01e333da-dd0a-76c9-bd78-a75122e1091f","type":"text","position":"a2","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Structured","marks":[{"type":"bold"}]},{"type":"text","text":" (tabular) data has rows and named columns — database tables, CSVs. "},{"type":"text","text":"Unstructured","marks":[{"type":"bold"}]},{"type":"text","text":" data — text, images, audio, video — has no predefined columns; classic ML needs features extracted from it, while deep learning learns them. Within a table, each column has a statistical type that decides how it is prepared:"}]}]}},"revision":1},{"id":"b3703d70-6848-7927-8ceb-603ee6ea9438","type":"table","position":"a3","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Type"}],[{"type":"text","text":"Examples"}],[{"type":"text","text":"Typical preparation"}]],[[{"type":"text","text":"Numerical — continuous"}],[{"type":"text","text":"Price, temperature, duration"}],[{"type":"text","text":"Scaling; log-transform if skewed"}]],[[{"type":"text","text":"Numerical — discrete (counts)"}],[{"type":"text","text":"Number of purchases, children"}],[{"type":"text","text":"As numbers; sometimes capped or log-transformed"}]],[[{"type":"text","text":"Categorical — nominal (no order)"}],[{"type":"text","text":"City, product id, colour"}],[{"type":"text","text":"One-hot, target or hash encoding"}]],[[{"type":"text","text":"Categorical — ordinal (ordered)"}],[{"type":"text","text":"Size S < M < L, education level, star rating"}],[{"type":"text","text":"Ordered integer codes"}]],[[{"type":"text","text":"Binary"}],[{"type":"text","text":"Is_premium, has_children"}],[{"type":"text","text":"0 / 1"}]],[[{"type":"text","text":"Date / time"}],[{"type":"text","text":"Signup timestamp"}],[{"type":"text","text":"Extract parts (hour, weekday), elapsed time, cyclical encoding"}]],[[{"type":"text","text":"Free text"}],[{"type":"text","text":"Reviews, titles"}],[{"type":"text","text":"Bag-of-words / TF-IDF, embeddings"}]],[[{"type":"text","text":"Identifiers"}],[{"type":"text","text":"User id, row number"}],[{"type":"text","text":"Usually "},{"type":"text","text":"not","marks":[{"type":"bold"}]},{"type":"text","text":" features — they let a model memorise rows"}]]]},"revision":1},{"id":"09ec1bd5-5f98-7d7a-98bf-d1a383a35fea","type":"heading","position":"a4","content":{"level":1,"content":[{"type":"text","text":"A first look with pandas"}]},"revision":1},{"id":"43952a39-24cf-77cc-aab9-e0d71fb5635d","type":"code","position":"a5","content":{"language":"python","code":"import numpy as np\nimport pandas as pd\n\ndf = pd.DataFrame({\n    \"age\":     [34, 45, np.nan, 23, 51, 38, 29, 62],\n    \"income\":  [52_000, 61_000, 48_000, 31_000, 250_000, 58_000, 40_000, 75_000],\n    \"city\":    [\"Pune\", \"Delhi\", \"Pune\", \"Mumbai\", \"Delhi\", \"Pune\", None, \"Mumbai\"],\n    \"plan\":    [\"basic\", \"pro\", \"basic\", \"basic\", \"premium\", \"pro\", \"basic\", \"pro\"],\n    \"churned\": [0, 0, 1, 1, 0, 0, 1, 0],\n})\nprint(df.shape)                                        # (8, 5)\nprint(df.isna().sum().to_dict())                       # {''age'': 1, ''income'': 0, ''city'': 1, ''plan'': 0, ''churned'': 0}\nprint(df[\"churned\"].mean())                            # 0.375 ← share of positives: check the balance\nprint(df[\"income\"].agg([\"mean\", \"median\"]).tolist())   # [76875.0, 55000.0] ← mean pulled up by one 250k value\nprint(round(df[\"income\"].skew(), 2))                   # 2.63 ← strongly right-skewed\nprint(df[\"city\"].value_counts().to_dict())             # {''Pune'': 3, ''Delhi'': 2, ''Mumbai'': 2}\nprint(df[[\"age\", \"income\", \"churned\"]].corr()[\"churned\"].drop(\"churned\").round(2).to_dict())   # {''age'': -0.73, ''income'': -0.43} ← only 8 rows: far too few to trust","filename":"Python"},"revision":1},{"id":"5f9b5504-5d32-7546-9ab4-5a22fcacee18","type":"heading","position":"a6","content":{"level":1,"content":[{"type":"text","text":"EDA checklist"}]},"revision":1},{"id":"31c135e5-35f7-7fd1-b344-95afd6db9249","type":"table","position":"a7","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Check"}],[{"type":"text","text":"How"}],[{"type":"text","text":"Why"}]],[[{"type":"text","text":"Shape, types, ids"}],[{"type":"text","text":"df.info()","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"df.dtypes","marks":[{"type":"code"}]}],[{"type":"text","text":"Numbers stored as strings, ids that must not be features"}]],[[{"type":"text","text":"Missing values"}],[{"type":"text","text":"df.isna().mean()","marks":[{"type":"code"}]}],[{"type":"text","text":"Choose imputation; missingness can be informative"}]],[[{"type":"text","text":"Duplicates"}],[{"type":"text","text":"df.duplicated().sum()","marks":[{"type":"code"}]}],[{"type":"text","text":"Duplicates across train/test inflate scores"}]],[[{"type":"text","text":"Target distribution"}],[{"type":"text","text":"value_counts(normalize=True)","marks":[{"type":"code"}]},{"type":"text","text":" / histogram"}],[{"type":"text","text":"Class imbalance, skewed regression targets"}]],[[{"type":"text","text":"Univariate distributions"}],[{"type":"text","text":"describe()","marks":[{"type":"code"}]},{"type":"text","text":", histograms, box plots"}],[{"type":"text","text":"Skew, impossible values (age = −1), outliers"}]],[[{"type":"text","text":"Relationships"}],[{"type":"text","text":"Scatter plots, "},{"type":"text","text":"corr()","marks":[{"type":"code"}]},{"type":"text","text":", grouped means by category"}],[{"type":"text","text":"Useful features, collinearity"}]],[[{"type":"text","text":"Too-good features"}],[{"type":"text","text":"A single feature almost perfectly predicting the target"}],[{"type":"text","text":"Usually "},{"type":"text","text":"target leakage","marks":[{"type":"bold"}]}]],[[{"type":"text","text":"Time"}],[{"type":"text","text":"Plot counts and target rate over time"}],[{"type":"text","text":"Drift, seasonality, logging changes"}]]]},"revision":1},{"id":"db258588-78f2-7eed-8dd7-a95a23ef324a","type":"callout","position":"a8","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Do the detailed EDA on the "},{"type":"text","text":"training split","marks":[{"type":"bold"}]},{"type":"text","text":". Looking closely at the test set and designing features around it leaks information about it into your choices."}]}]}},"revision":1},{"id":"e86c3144-9f79-7fae-aadc-5b87c074e190","type":"heading","position":"a9","content":{"level":1,"content":[{"type":"text","text":"Correlation, carefully"}]},"revision":1},{"id":"dbbe4e00-ed10-7f00-ac3f-f65154a6b46c","type":"code","position":"aA","content":{"language":"python","code":"import numpy as np\nfrom scipy.stats import pearsonr, spearmanr\n\nx = np.arange(1, 11, dtype=float)\ny_curve = x ** 3                               # perfectly monotonic, but not linear\nprint(round(pearsonr(x, y_curve)[0], 3))       # 0.928 ← Pearson: linear association\nprint(round(spearmanr(x, y_curve)[0], 3))      # 1.0 ← Spearman: rank (monotonic) association\n\nu = np.linspace(-1, 1, 21)\nprint(round(pearsonr(u, u ** 2)[0], 3))        # 0.0 ← y depends on u completely, yet correlation is 0","filename":"Python"},"revision":1},{"id":"62c31521-426a-7762-9e02-93c2772d88ef","type":"text","position":"aB","content":{"doc":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Pearson measures "},{"type":"text","text":"linear","marks":[{"type":"bold"}]},{"type":"text","text":" association only; zero correlation does not mean independence."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Spearman uses ranks — robust to outliers and captures any monotonic trend."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Correlation is not causation: ice-cream sales and drownings both rise in summer."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"For categorical–target relationships, compare target rates per category or use mutual information."}]}]}]}]}},"revision":1},{"id":"4a5e9e8c-e920-732e-94aa-8b5a61ae4a40","type":"question","position":"aC","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What do you look at first in a new dataset?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Size and column types, the target''s distribution, missing values and duplicates, obviously wrong values, then each feature''s distribution and its relationship with the target. I also check how the data was collected and over what time span, and flag any feature that predicts the target suspiciously well."}]}]}},"revision":1},{"id":"4d928ce1-c703-7a4e-9b3c-794addd565f5","type":"question","position":"aD","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why shouldn''t an ID column be used as a feature?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"It carries no generalisable information but is unique per row, so flexible models memorise it and look great on training data. Worse, if ids were assigned in time order, it can leak time or target information."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
