SELECT 'c24c3095-76de-7c86-b5c2-62c530d2ef02', 'd4539eee-f693-766e-af14-4314104c7af5', 1, 'PUBLISHED', 'Feature Scaling & Transforms', '[{"id":"168252ec-c35a-72ea-a40c-5f617fa2213d","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Scaling puts features on comparable ranges. It matters for models that use "},{"type":"text","text":"distances, dot products or gradient descent","marks":[{"type":"bold"}]},{"type":"text","text":", and not at all for tree-based models."}]}]}},"revision":1},{"id":"16985729-bea5-7e94-b222-6da42d547812","type":"table","position":"a1","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Scaler"}],[{"type":"text","text":"Formula"}],[{"type":"text","text":"Result"}],[{"type":"text","text":"Use when"}]],[[{"type":"text","text":"StandardScaler","marks":[{"type":"code"}]}],[{"type":"text","text":"z = (x − mean) / std","marks":[{"type":"code"}]}],[{"type":"text","text":"Mean 0, std 1 (unbounded)"}],[{"type":"text","text":"Default for linear models, SVM, PCA, k-NN, neural nets"}]],[[{"type":"text","text":"MinMaxScaler","marks":[{"type":"code"}]}],[{"type":"text","text":"(x − min) / (max − min)","marks":[{"type":"code"}]}],[{"type":"text","text":"Range [0, 1]"}],[{"type":"text","text":"Bounded inputs needed (pixel values); no big outliers"}]],[[{"type":"text","text":"RobustScaler","marks":[{"type":"code"}]}],[{"type":"text","text":"(x − median) / IQR","marks":[{"type":"code"}]}],[{"type":"text","text":"Median 0, IQR 1"}],[{"type":"text","text":"Outliers present"}]],[[{"type":"text","text":"MaxAbsScaler","marks":[{"type":"code"}]}],[{"type":"text","text":"x / max(|x|)","marks":[{"type":"code"}]}],[{"type":"text","text":"Range [−1, 1], keeps zeros"}],[{"type":"text","text":"Sparse data"}]],[[{"type":"text","text":"Normalizer","marks":[{"type":"code"}]}],[{"type":"text","text":"Each "},{"type":"text","text":"row","marks":[{"type":"bold"}]},{"type":"text","text":" divided by its norm"}],[{"type":"text","text":"Every row has length 1"}],[{"type":"text","text":"Text vectors / cosine similarity — not a per-feature scaler"}]]]},"revision":1},{"id":"f7acdb82-eceb-725c-94fa-d80e6acf6dd2","type":"code","position":"a2","content":{"language":"python","code":"import numpy as np\nfrom sklearn.preprocessing import MinMaxScaler, RobustScaler, StandardScaler\n\nx = np.array([[1.0], [2.0], [3.0], [4.0], [100.0]])      # one outlier\nprint(StandardScaler().fit_transform(x).ravel().round(2))  # [-0.54 -0.51 -0.49 -0.46  2.  ]\nprint(MinMaxScaler().fit_transform(x).ravel().round(2))    # [0.   0.01 0.02 0.03 1.  ] ← normal values squashed near 0\nprint(RobustScaler().fit_transform(x).ravel().round(2))    # [-1.  -0.5  0.   0.5 48.5] ← normal values keep their spread","filename":"Python"},"revision":1},{"id":"36c7f669-c80b-7d0b-9f91-b04c6caef88a","type":"heading","position":"a3","content":{"level":1,"content":[{"type":"text","text":"Why it matters: k-NN on the wine data"}]},"revision":1},{"id":"080f12ba-45ce-7233-b554-a742547d4498","type":"text","position":"a4","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Two of the 13 wine features (magnesium, proline) have far larger numbers than the rest, so they dominate Euclidean distance until everything is standardised:"}]}]}},"revision":1},{"id":"4a82cd03-ded2-7987-a73a-a504235aa599","type":"code","position":"a5","content":{"language":"python","code":"from sklearn.datasets import load_wine\nfrom sklearn.model_selection import cross_val_score\nfrom sklearn.neighbors import KNeighborsClassifier\nfrom sklearn.pipeline import make_pipeline\nfrom sklearn.preprocessing import StandardScaler\n\nX, y = load_wine(return_X_y=True)\nprint(X.std(axis=0)[[4, 7, 12]].round(1).tolist())   # [14.2, 0.1, 314.0] ← magnesium, nonflavanoid phenols, proline\n\nraw = cross_val_score(KNeighborsClassifier(), X, y, cv=5).mean()\nscaled = cross_val_score(make_pipeline(StandardScaler(), KNeighborsClassifier()), X, y, cv=5).mean()\nprint(round(raw, 3), round(scaled, 3))           # 0.691 0.949","filename":"Python"},"revision":1},{"id":"a4341715-6dd3-76ed-8b46-bc5a2ffe6a11","type":"table","position":"a6","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Needs scaling"}],[{"type":"text","text":"Doesn''t need scaling"}]],[[{"type":"text","text":"k-NN, k-means, SVM, PCA, linear/logistic regression "},{"type":"text","text":"with regularisation","marks":[{"type":"bold"}]},{"type":"text","text":", anything trained by gradient descent (including neural nets)"}],[{"type":"text","text":"Decision trees, random forests, gradient-boosted trees, Naive Bayes (each feature handled separately)"}]]]},"revision":1},{"id":"ba524000-bc5c-7f7e-b8e8-0f609de25b34","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"Fit on train, transform everything"}]},"revision":1},{"id":"e5270b2f-8c60-73ba-9417-56cd36e4f7fb","type":"code","position":"a8","content":{"language":"python","code":"import numpy as np\nfrom sklearn.preprocessing import StandardScaler\n\nX_train = np.array([[10.0], [20.0], [30.0]])\nX_test = np.array([[40.0]])\n\nscaler = StandardScaler().fit(X_train)            # learns mean 20 and std 8.165 from TRAIN\nprint(scaler.mean_, scaler.scale_.round(3))       # [20.] [8.165]\nprint(scaler.transform(X_test).round(3))          # [[2.449]] ← test uses the TRAIN statistics","filename":"Python"},"revision":1},{"id":"a67bb367-e9d9-73b7-9e68-78af05047d76","type":"callout","position":"a9","content":{"variant":"tip","title":"Do","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Fit the scaler on the training data (inside a "},{"type":"text","text":"Pipeline","marks":[{"type":"code"}]},{"type":"text","text":" for cross-validation) and use "},{"type":"text","text":"transform","marks":[{"type":"code"}]},{"type":"text","text":" on validation/test/production data."}]}]}},"revision":1},{"id":"da40cda2-3da1-7b30-b704-22892c66f37b","type":"callout","position":"aA","content":{"variant":"danger","title":"Avoid","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"fit_transform","marks":[{"type":"code"}]},{"type":"text","text":" on the whole dataset before splitting, or re-fitting on the test set — both leak or shift information."}]}]}},"revision":1},{"id":"cd55c682-73c4-73f4-ac79-85aed42c2b91","type":"heading","position":"aB","content":{"level":1,"content":[{"type":"text","text":"Transforming skewed features"}]},"revision":1},{"id":"53c3249b-eb8a-7ee4-8a8c-b31d6cc725f7","type":"code","position":"aC","content":{"language":"python","code":"import numpy as np\nfrom scipy.stats import skew\nfrom sklearn.preprocessing import PowerTransformer\n\nrng = np.random.default_rng(0)\nincome = rng.lognormal(mean=10, sigma=1, size=1000)       # right-skewed, like real incomes\nprint(round(skew(income), 2))                                             # 3.87\nprint(round(skew(np.log1p(income)), 2))                                   # -0.07 ← log: roughly symmetric\nprint(round(skew(PowerTransformer().fit_transform(income.reshape(-1, 1)).ravel()), 2))  # 0.0 ← Yeo-Johnson","filename":"Python"},"revision":1},{"id":"ad16049a-61b7-7d5b-8763-8b8771ec1df7","type":"callout","position":"aD","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Standardising changes the "},{"type":"text","text":"scale","marks":[{"type":"bold"}]},{"type":"text","text":", not the "},{"type":"text","text":"shape","marks":[{"type":"bold"}]},{"type":"text","text":": a skewed feature stays skewed with mean 0 and std 1. Use a log / Box-Cox / Yeo-Johnson transform (or "},{"type":"text","text":"QuantileTransformer","marks":[{"type":"code"}]},{"type":"text","text":") to change the shape."}]}]}},"revision":1},{"id":"562b9b72-6ee3-7421-9d11-9617231e2594","type":"question","position":"aE","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Normalization vs standardization?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Min-max normalization maps a feature to [0, 1] using its min and max — sensitive to outliers. Standardization subtracts the mean and divides by the standard deviation — unbounded, usually a safer default. Both are fitted on the training data. (Confusingly, sklearn''s "},{"type":"text","text":"Normalizer","marks":[{"type":"code"}]},{"type":"text","text":" does something else: it scales each "},{"type":"text","text":"row","marks":[{"type":"italic"}]},{"type":"text","text":" to unit length.)"}]}]}},"revision":1},{"id":"e3df6483-c3fe-7e56-8668-800da2241d26","type":"question","position":"aF","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Does a random forest need feature scaling?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"No. Trees split on thresholds of one feature at a time, and any monotonic rescaling leaves the ordering — and therefore the splits — unchanged."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
