SELECT 'f351cdca-9fea-7217-917f-7cd27977ca5b', 'e07a9c75-24fd-7f33-a70d-d5af4ac83746', 1, 'PUBLISHED', 'Hyperparameter Tuning', '[{"id":"3d4004a6-896b-7bc8-8930-33bcea684538","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Hyperparameters (tree depth, "},{"type":"text","text":"C","marks":[{"type":"code"}]},{"type":"text","text":", learning rate) aren''t learned by "},{"type":"text","text":"fit","marks":[{"type":"code"}]},{"type":"text","text":"; you choose them by comparing cross-validated scores. The search strategy decides how much compute that takes."}]}]}},"revision":1},{"id":"23b260d8-d4b0-7d86-bb8b-a7b46d74da33","type":"table","position":"a1","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Strategy"}],[{"type":"text","text":"How"}],[{"type":"text","text":"Pros / cons"}]],[[{"type":"text","text":"Manual"}],[{"type":"text","text":"Intuition + a few runs"}],[{"type":"text","text":"Quick for 1–2 knobs; not reproducible"}]],[[{"type":"text","text":"Grid search"}],[{"type":"text","text":"Every combination of listed values"}],[{"type":"text","text":"Exhaustive and simple; cost multiplies with each hyperparameter"}]],[[{"type":"text","text":"Random search"}],[{"type":"text","text":"Sample combinations from distributions"}],[{"type":"text","text":"Same budget explores more distinct values of each hyperparameter — usually better when only a few matter (Bergstra & Bengio, 2012)"}]],[[{"type":"text","text":"Successive halving / Hyperband"}],[{"type":"text","text":"Evaluate many configs on little data/iterations, keep the best fraction, give them more"}],[{"type":"text","text":"Much cheaper; early rounds can be noisy"}]],[[{"type":"text","text":"Bayesian optimisation"}],[{"type":"text","text":"A surrogate model (Gaussian process, TPE) predicts promising configs; an acquisition function balances exploring and exploiting"}],[{"type":"text","text":"Fewest evaluations for expensive models; sequential; tools: Optuna, scikit-optimize, Hyperopt"}]]]},"revision":1},{"id":"33d17bc8-c41c-7c06-b46d-a560161a1c09","type":"heading","position":"a2","content":{"level":1,"content":[{"type":"text","text":"Grid search"}]},"revision":1},{"id":"2e89eb14-07b3-7a51-8583-98431293dff9","type":"code","position":"a3","content":{"language":"python","code":"from sklearn.datasets import load_breast_cancer\nfrom sklearn.model_selection import GridSearchCV, train_test_split\nfrom sklearn.pipeline import Pipeline\nfrom sklearn.preprocessing import StandardScaler\nfrom sklearn.svm import SVC\n\nX, y = load_breast_cancer(return_X_y=True)\nX_tr, X_te, y_tr, y_te = train_test_split(X, y, stratify=y, random_state=0)\n\npipe = Pipeline([(\"scale\", StandardScaler()), (\"svc\", SVC())])\ngrid = {\"svc__C\": [0.1, 1, 10, 100], \"svc__gamma\": [0.001, 0.01, 0.1]}    # step__param names\nsearch = GridSearchCV(pipe, grid, cv=5, scoring=\"roc_auc\").fit(X_tr, y_tr)\n\nprint(search.best_params_)                      # {''svc__C'': 10, ''svc__gamma'': 0.001}\nprint(round(search.best_score_, 4))             # 0.9962 ← mean CV score of the winner (optimistic)\nprint(round(search.score(X_te, y_te), 4))       # 0.9937 ← refit on all training data, scored once on test","filename":"Python"},"revision":1},{"id":"11bcdf88-bd5f-7733-a73b-089af1fdf678","type":"heading","position":"a4","content":{"level":1,"content":[{"type":"text","text":"Random search"}]},"revision":1},{"id":"deb232d2-37d5-7bac-a3fe-adcbfcc8a69b","type":"code","position":"a5","content":{"language":"python","code":"from scipy.stats import loguniform, randint\nfrom sklearn.datasets import load_breast_cancer\nfrom sklearn.ensemble import HistGradientBoostingClassifier\nfrom sklearn.model_selection import RandomizedSearchCV\n\nX, y = load_breast_cancer(return_X_y=True)\ndists = {\n    \"learning_rate\": loguniform(0.01, 0.5),          # sample on a log scale\n    \"max_leaf_nodes\": randint(4, 64),\n    \"min_samples_leaf\": randint(5, 50),\n    \"l2_regularization\": loguniform(1e-4, 10),\n}\nsearch = RandomizedSearchCV(HistGradientBoostingClassifier(random_state=0), dists, n_iter=15,\n                            cv=3, scoring=\"roc_auc\", random_state=0).fit(X, y)\nprint(round(search.best_score_, 4))                                   # 0.9934\nprint(sorted(search.best_params_))                                    # [''l2_regularization'', ''learning_rate'', ''max_leaf_nodes'', ''min_samples_leaf'']","filename":"Python"},"revision":1},{"id":"194e127b-8a50-7497-867f-a9a0dfb82b50","type":"heading","position":"a6","content":{"level":1,"content":[{"type":"text","text":"Successive halving"}]},"revision":1},{"id":"1c9e3855-744b-7a9f-9bd5-f2a9a09637cd","type":"code","position":"a7","content":{"language":"python","code":"from sklearn.experimental import enable_halving_search_cv  # noqa: F401  (still experimental)\nfrom sklearn.model_selection import HalvingGridSearchCV\nfrom sklearn.datasets import load_digits\nfrom sklearn.ensemble import RandomForestClassifier\n\nX, y = load_digits(return_X_y=True)\ngrid = {\"max_depth\": [4, 8, None], \"min_samples_leaf\": [1, 5, 20], \"max_features\": [\"sqrt\", 0.5]}\nsearch = HalvingGridSearchCV(RandomForestClassifier(n_estimators=50, random_state=0), grid,\n                             resource=\"n_samples\", factor=3, cv=3, random_state=0).fit(X, y)\nprint(search.n_candidates_)              # [18, 6, 2] ← candidates per round: most are dropped early on little data\nprint(search.n_resources_)               # [199, 597, 1791] ← samples used per round","filename":"Python"},"revision":1},{"id":"d597ab0f-8dee-7a2e-b337-4c56a8306cf4","type":"heading","position":"a8","content":{"level":1,"content":[{"type":"text","text":"Tips"}]},"revision":1},{"id":"a1c96322-c924-76a9-9a22-b5c3221d6078","type":"text","position":"a9","content":{"doc":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Search learning rates and regularisation strengths on a "},{"type":"text","text":"log scale","marks":[{"type":"bold"}]},{"type":"text","text":" (0.001, 0.01, 0.1 …)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Go coarse → fine: a wide random search, then a narrow one around the best region."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Tune the hyperparameters that matter most (for GBMs: learning rate, number of trees via early stopping, depth/leaves, subsampling)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Put preprocessing in the "},{"type":"text","text":"Pipeline","marks":[{"type":"code"}]},{"type":"text","text":" so each CV fold fits its own scaler/encoder, and tune preprocessing choices too ("},{"type":"text","text":"\"scale\": [StandardScaler(), \"passthrough\"]","marks":[{"type":"code"}]},{"type":"text","text":")."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"best_score_","marks":[{"type":"code"}]},{"type":"text","text":" is optimistically biased (it''s the maximum of many noisy estimates) — report a held-out test score or nested CV."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Fix "},{"type":"text","text":"random_state","marks":[{"type":"code"}]},{"type":"text","text":"s and record every trial (MLflow, Weights & Biases) so results are reproducible."}]}]}]}]}},"revision":1},{"id":"2cc4f7ba-73c3-7173-b6ba-dd97fe78920e","type":"question","position":"aA","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why can random search beat grid search?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"With a fixed budget, a grid tests only a few distinct values of each hyperparameter, and many runs are wasted varying ones that don''t matter. Random search tries a new value of every hyperparameter in every run, so it explores the important dimensions much more finely."}]}]}},"revision":1},{"id":"4cbed386-e206-7c50-a628-0ad5e75140b6","type":"question","position":"aB","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How does Bayesian optimisation work?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"It fits a cheap surrogate model of score as a function of hyperparameters to the trials so far, then picks the next trial by maximising an acquisition function (e.g. expected improvement) that trades off exploring uncertain regions and exploiting good ones. It needs far fewer expensive training runs than grid or random search."}]}]}},"revision":1},{"id":"fa9bc705-0746-7ec0-8e0d-660621154595","type":"question","position":"aC","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Can you tune hyperparameters on the test set?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"No — the chosen hyperparameters would be fitted to the test set, and its score would no longer estimate performance on new data. Tune with a validation set or cross-validation on the training data; use the test set once at the end."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
