SELECT 'topic:ml-ai/imbalanced-data', '53171874-f178-712d-8696-a8d8b4cc2cdb', 'ce665a311f764f3ccee68fb1509fc166c1b4b4db5d50366236969c2e9c9805fc', 'fd3d3f57-5d69-7e54-9426-6f9d9f0e91e9', TIMESTAMPTZ '2026-10-07 03:23:53+00', TIMESTAMPTZ '2026-10-07 03:23:53+00'
