INSERT INTO "notes"."NoteVersion" ("id", "noteId", "number", "kind", "title", "cards", "createdById", "createdAt")
SELECT 'bdeacbb4-2033-7364-9cf8-a722500497a2', 'babfaa9a-771f-7149-9448-b0d7c8c4d4aa', 1, 'PUBLISHED', 'Interview Questions', '[{"id":"95a64c45-20f8-74d6-be01-4666bc5fc8cf","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Short, precise answers to the machine-learning questions asked most often — each points back to the topic that explains it in depth."}]}]}},"revision":1},{"id":"871cab0d-bdfc-7459-928c-f9a917666047","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Fundamentals"}]},"revision":1},{"id":"51082443-79c7-77fd-b119-5c715cb3f7d8","type":"question","position":"a2","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is the difference between supervised, unsupervised and reinforcement learning?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Supervised learns a mapping from inputs to known labels (classification, regression). Unsupervised finds structure without labels (clustering, dimensionality reduction). Reinforcement learning learns a policy from rewards received by acting in an environment. (See "},{"type":"text","text":"Types of Learning","marks":[{"type":"bold"}]},{"type":"text","text":".)"}]}]}},"revision":1},{"id":"84fc216c-b28f-7d48-b024-36e7c3018e3a","type":"question","position":"a3","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is overfitting and how do you prevent it?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The model learns noise in the training data, so training error is low but validation error is high. Prevent it with more data, simpler models, regularisation (L1/L2, pruning, early stopping), feature selection, bagging, and by validating properly with held-out data or cross-validation."}]}]}},"revision":1},{"id":"28492641-79e9-7242-abd4-0745edd6429a","type":"question","position":"a4","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Explain the bias–variance trade-off."}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Expected error = bias² + variance + irreducible noise. Simple models have high bias and low variance (underfit); flexible models the reverse (overfit). Model complexity is tuned to minimise the sum, using validation data. (See "},{"type":"text","text":"Bias–Variance & Overfitting","marks":[{"type":"bold"}]},{"type":"text","text":".)"}]}]}},"revision":1},{"id":"5b47c4a9-69dd-74fd-8caa-de9125a2f321","type":"question","position":"a5","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why do we split data into train, validation and test sets?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Train fits parameters, validation guides choices (hyperparameters, features, threshold), and the untouched test set gives an unbiased final estimate. Using the test set for choices makes its score optimistic."}]}]}},"revision":1},{"id":"ee34a35e-d74b-713b-afbe-82892c04e246","type":"question","position":"a6","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is cross-validation and when would you use GroupKFold or TimeSeriesSplit?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Rotating held-out folds to estimate performance more reliably. GroupKFold when several rows belong to the same entity (patient, user) so an entity never appears on both sides; TimeSeriesSplit when data is time-ordered so models are always validated on the future."}]}]}},"revision":1},{"id":"82384a66-7d29-731f-941b-96f47ef1dbbe","type":"question","position":"a7","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is data leakage? Give two examples."}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Information unavailable at prediction time influencing training or evaluation. Examples: scaling or selecting features on the full dataset before splitting; a feature derived from the target (e.g. "},{"type":"text","text":"refund_issued","marks":[{"type":"code"}]},{"type":"text","text":" for fraud); the same customer in train and test. (See "},{"type":"text","text":"Data Leakage","marks":[{"type":"bold"}]},{"type":"text","text":".)"}]}]}},"revision":1},{"id":"3d5c9228-fcbf-7138-9f43-732ba56dc8cc","type":"heading","position":"a8","content":{"level":1,"content":[{"type":"text","text":"Algorithms"}]},"revision":1},{"id":"0e9caf29-009b-7dfa-b6df-43baa1a200da","type":"question","position":"a9","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How does logistic regression work?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"It computes a linear score "},{"type":"text","text":"w·x + b","marks":[{"type":"code"}]},{"type":"text","text":" and passes it through the sigmoid to get P(y = 1). It''s trained by minimising log-loss (maximum likelihood), a convex problem. The decision boundary is linear; coefficients are changes in log-odds."}]}]}},"revision":1},{"id":"5f7db4aa-779a-7de8-89d8-2a4559d1a695","type":"question","position":"aA","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"L1 vs L2 regularisation?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"L1 (Lasso) adds "},{"type":"text","text":"α·Σ|w|","marks":[{"type":"code"}]},{"type":"text","text":" and drives many weights exactly to zero — built-in feature selection. L2 (Ridge) adds "},{"type":"text","text":"α·Σw²","marks":[{"type":"code"}]},{"type":"text","text":" and shrinks weights smoothly, handling correlated features well. Elastic Net combines them. Scale features first."}]}]}},"revision":1},{"id":"6d6611ad-ac2c-7809-adb1-b960f1eb2bc4","type":"question","position":"aB","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How does a decision tree choose splits, and why do trees overfit?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Greedily, by the largest impurity decrease (Gini/entropy for classification, squared error for regression). Grown without limits a tree isolates individual points; limit depth or leaf size, prune, or use ensembles."}]}]}},"revision":1},{"id":"ba7c3a21-9e2b-734e-a779-8429160fc36b","type":"question","position":"aC","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Random forest vs gradient boosting?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A random forest averages many deep trees trained independently on bootstrap samples with random feature subsets — it reduces variance, is robust and needs little tuning. Gradient boosting adds shallow trees sequentially, each fitting the gradient of the loss of the current ensemble — it reduces bias and is usually more accurate but needs a learning rate and early stopping to avoid overfitting."}]}]}},"revision":1},{"id":"7c01a9b3-9e58-7588-9c60-4776689f7532","type":"question","position":"aD","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How do SVMs work? What is the kernel trick?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"An SVM finds the hyperplane with the maximum margin; soft margins trade margin width against violations via "},{"type":"text","text":"C","marks":[{"type":"code"}]},{"type":"text","text":". The kernel trick replaces dot products with a kernel function, giving non-linear boundaries as if the data were mapped to a higher-dimensional space."}]}]}},"revision":1},{"id":"fdda5a7d-2ac4-7f6c-983f-4c09bb868a4d","type":"question","position":"aE","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How does k-NN work and what are its weaknesses?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"It predicts from the k nearest training points (vote or average). No training, but slow predictions, needs feature scaling, and suffers from irrelevant features and the curse of dimensionality."}]}]}},"revision":1},{"id":"ced3c298-4923-737e-a3a8-0a630065a471","type":"question","position":"aF","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why is Naive Bayes naive, and why does it still work?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"It assumes features are conditionally independent given the class. The probabilities it outputs are poorly calibrated, but the ranking of classes is often right, so classification works well — especially for text."}]}]}},"revision":1},{"id":"73f2dd50-b52c-7379-8181-05983cbd769f","type":"question","position":"aG","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How does k-means work and what are its assumptions?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Alternately assign points to the nearest centroid and recompute centroids, minimising within-cluster squared distances. Assumes roughly spherical, similarly sized clusters and meaningful Euclidean distances; needs k, scaling and several initialisations."}]}]}},"revision":1},{"id":"9edc2ea7-1443-726e-a34d-122a484ae1e8","type":"question","position":"aH","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is PCA and why scale before it?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"PCA projects data onto orthogonal directions of maximum variance (eigenvectors of the covariance matrix). Without scaling, features with large units dominate the variance and therefore the components."}]}]}},"revision":1},{"id":"9f8c90aa-f9d8-7909-9e35-39626d54d47e","type":"heading","position":"aI","content":{"level":1,"content":[{"type":"text","text":"Evaluation"}]},"revision":1},{"id":"7a1e49ab-8bee-75b9-8c5d-99d81f063a1b","type":"question","position":"aJ","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Precision vs recall — when do you favour each?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Precision = TP/(TP+FP): favour it when false alarms are costly (spam filtering). Recall = TP/(TP+FN): favour it when misses are costly (disease screening, fraud). The threshold moves you along the trade-off."}]}]}},"revision":1},{"id":"bf227058-90f8-7211-9b00-7ee8cc8cd572","type":"question","position":"aK","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"ROC-AUC vs PR-AUC?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"ROC plots TPR vs FPR; its AUC is the probability a random positive is ranked above a random negative (0.5 = random). PR plots precision vs recall; its baseline is the positive prevalence, so it''s more informative for rare positives."}]}]}},"revision":1},{"id":"3ebf459b-006b-7ce4-a375-8f4eaa15379d","type":"question","position":"aL","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Can R² be negative?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Yes — when predictions are worse than always predicting the mean of the true values, e.g. on test data after overfitting."}]}]}},"revision":1},{"id":"be8e7a46-977d-75cf-abf3-6b2cc666b36d","type":"question","position":"aM","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How do you handle imbalanced data?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Right metric (PR-AUC, recall at precision, cost), stratified splits, threshold tuning, class weights, resampling inside training folds only, more positive data; recalibrate probabilities afterwards. (See "},{"type":"text","text":"Imbalanced Data","marks":[{"type":"bold"}]},{"type":"text","text":".)"}]}]}},"revision":1},{"id":"35f5fe14-33a7-7602-971a-5f58eb07caca","type":"question","position":"aN","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is model calibration and how do you check it?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A model is calibrated if events predicted with probability p happen about p of the time. Check with a reliability diagram, Brier score or log-loss; fix with Platt scaling or isotonic regression via "},{"type":"text","text":"CalibratedClassifierCV","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"4a86ea60-fbed-76a7-b064-edfa40c56568","type":"question","position":"aO","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How would you compare two models statistically?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"On the same test rows: McNemar''s test on disagreements, or a bootstrap confidence interval of the metric difference; across CV folds a corrected paired t-test. Also ask whether the difference is practically meaningful."}]}]}},"revision":1},{"id":"23ba4607-c53d-7ebe-889c-5a81488a1ecb","type":"heading","position":"aP","content":{"level":1,"content":[{"type":"text","text":"Features & data"}]},"revision":1},{"id":"978597a7-6431-7869-9dd0-7ed9f07eef6c","type":"question","position":"aQ","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How do you handle missing values?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Understand why they''re missing (MCAR/MAR/MNAR). Options: drop, impute (median/most-frequent, KNN, iterative), add missing-indicator columns, or use models that handle NaN natively. Fit imputers on training data inside the pipeline."}]}]}},"revision":1},{"id":"c512d538-b8a9-7640-9614-3dfce33acf73","type":"question","position":"aR","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"One-hot vs label (ordinal) encoding?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"One-hot for nominal categories so no false order is implied; ordinal codes for truly ordered categories (and acceptable for tree models). High cardinality → target encoding with cross-fitting, hashing or embeddings."}]}]}},"revision":1},{"id":"4b851cb9-ca67-7f2b-9550-6a01ec05c715","type":"question","position":"aS","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Which models need feature scaling?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Distance- and gradient-based or regularised models: k-NN, k-means, SVM, PCA, regularised linear/logistic regression, neural networks. Tree-based models don''t."}]}]}},"revision":1},{"id":"b23a808d-6909-7985-a1b2-4fafc475bf6e","type":"question","position":"aT","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is the curse of dimensionality?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"As dimensions grow, data becomes sparse and distances concentrate, so neighbourhoods stop being local and much more data is needed. It hurts distance-based methods most; use feature selection, dimensionality reduction or more data."}]}]}},"revision":1},{"id":"2e0bab80-c355-764c-b8c9-f18a25ceeaac","type":"heading","position":"aU","content":{"level":1,"content":[{"type":"text","text":"Production & responsible AI"}]},"revision":1},{"id":"b9fb513f-4db9-7cac-8345-de436cedd3d3","type":"question","position":"aV","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is concept drift vs data drift?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Data (covariate) drift: P(X) changes. Label shift: P(y) changes. Concept drift: P(y|X) changes, so the learned relationship is outdated. Monitor inputs, predictions and delayed outcomes; retrain on recent data."}]}]}},"revision":1},{"id":"6d228a59-3487-7fc7-8753-a89ec0603582","type":"question","position":"aW","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is training–serving skew?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Features computed differently in training and in production (different code, freshness or bugs), so the model receives inputs unlike its training data. Prevent with shared pipelines or a feature store and by comparing logged production features with training data."}]}]}},"revision":1},{"id":"89af6854-6a05-7c37-9ea1-7fc1fbe230f2","type":"question","position":"aX","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How do you explain a black-box model''s predictions?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Globally with permutation importance and partial dependence; locally with SHAP (additive Shapley attributions) or LIME; counterfactuals for “what would change the decision”. Remember explanations describe the model, not causality."}]}]}},"revision":1},{"id":"9c6bdb00-f15d-70e6-a0bd-b61dd364c82d","type":"question","position":"aY","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How do you measure fairness?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Compute metrics per group: selection rate (demographic parity), TPR (equal opportunity), TPR and FPR (equalized odds), precision and calibration. Differing base rates make some criteria mutually incompatible, so choose based on the application and document the trade-off."}]}]}},"revision":1},{"id":"8d5db213-b9a6-77a7-9087-8b990d49dde7","type":"heading","position":"aZ","content":{"level":1,"content":[{"type":"text","text":"Beyond classic ML"}]},"revision":1},{"id":"917d6774-4b1f-797e-bfce-0e997cb80caf","type":"question","position":"aa","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"When would you use deep learning instead of classic ML?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"For unstructured data (images, audio, text), very large datasets, or when a pretrained model can be fine-tuned. For small or medium tabular data, gradient-boosted trees are usually as good or better with less effort. (See "},{"type":"text","text":"Deep Learning","marks":[{"type":"bold"}]},{"type":"text","text":".)"}]}]}},"revision":1},{"id":"adb770b6-596f-7a0b-97e2-dc6c9e0bc86c","type":"question","position":"ab","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is the relationship between logistic regression and a neural network?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Logistic regression is a single neuron with a sigmoid activation trained with log-loss. Neural networks stack many such units with non-linear activations, learning intermediate features, and are trained with backpropagation and gradient descent."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
WHERE EXISTS (SELECT 1 FROM "notes"."Note" n WHERE n.id = 'babfaa9a-771f-7149-9448-b0d7c8c4d4aa' AND n."ownerId" = '019a118c-f480-7000-8000-000000000001' AND n."publishedVersionId" IS NULL AND n.visibility = 'PRIVATE' AND n."deletedAt" IS NULL AND n."draftUpdatedAt" = TIMESTAMPTZ '2026-10-07 03:23:53+00')
