  SELECT 1 FROM "notes"."Note" n
  WHERE n.id = '4bc6ce8a-d5a1-71f2-86e8-a0fc6c059472' AND n.visibility = 'PUBLIC' AND n."publishedVersionId" = '2632f979-c2e2-7afa-83ec-b97ccdedd824' AND n."deletedAt" IS NULL
