INSERT INTO "notes"."NoteVersion" ("id", "noteId", "number", "kind", "title", "cards", "createdById", "createdAt")
SELECT 'e26d5a3d-0324-7792-93c7-385a775a73f9', 'b24b1621-c849-78ef-af71-2f8adcf3523d', 1, 'PUBLISHED', 'k-Means Clustering', '[{"id":"0d32d508-43a0-7797-8ce5-92395ddbd195","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"k-means splits the data into "},{"type":"text","text":"k","marks":[{"type":"code"}]},{"type":"text","text":" groups by placing "},{"type":"text","text":"k","marks":[{"type":"code"}]},{"type":"text","text":" centroids and assigning every point to the nearest one. It is fast and simple — and it quietly assumes round, similarly sized clusters."}]},{"type":"paragraph","content":[{"type":"text","text":"minimise inertia = Σₖ Σ_{x ∈ Cₖ} ‖x − μₖ‖² (within-cluster sum of squared distances)","marks":[{"type":"code"}]}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Initialise","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Pick k starting centroids — "},{"type":"text","text":"k-means++","marks":[{"type":"bold"}]},{"type":"text","text":" spreads them out (scikit-learn''s default)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Assign","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Put each point in the cluster of its nearest centroid."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Update","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Move each centroid to the mean of its points."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Repeat","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Until assignments stop changing. Each step lowers inertia, so it converges — but to a "},{"type":"text","text":"local","marks":[{"type":"bold"}]},{"type":"text","text":" minimum."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Because the result depends on the starting centroids, scikit-learn runs several initialisations ("},{"type":"text","text":"n_init","marks":[{"type":"code"}]},{"type":"text","text":") and keeps the one with the lowest inertia."}]}]}},"revision":1},{"id":"5c05f531-33ad-73da-a3bf-4311f40b901d","type":"code","position":"a1","content":{"language":"python","code":"import numpy as np\nfrom sklearn.cluster import KMeans\nfrom sklearn.datasets import make_blobs\n\nX, y_true = make_blobs(n_samples=300, centers=4, cluster_std=0.8, random_state=0)\nkm = KMeans(n_clusters=4, n_init=10, random_state=0).fit(X)\n\nprint(km.cluster_centers_.round(2).tolist())        # [[0.85, 4.44], [1.98, 0.83], [-1.44, 7.78], [-1.66, 2.76]]\nprint(round(km.inertia_, 1))                         # 369.5\nprint(np.bincount(km.labels_).tolist())              # [81, 74, 73, 72] ← cluster sizes\nprint(km.predict([[0, 4], [2, 1]]))                  # [0 1] ← new points go to the nearest centroid","filename":"Python"},"revision":1},{"id":"b54000d2-d85f-7b00-96b6-ffe3b93f3a44","type":"heading","position":"a2","content":{"level":1,"content":[{"type":"text","text":"Choosing k"}]},"revision":1},{"id":"a984fe71-82e1-7248-b310-e713f1aaecb6","type":"text","position":"a3","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Inertia always falls as "},{"type":"text","text":"k","marks":[{"type":"code"}]},{"type":"text","text":" grows (k = n gives 0), so you can''t just minimise it. Two common heuristics:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Elbow method","marks":[{"type":"bold"}]},{"type":"text","text":" — plot inertia against k and look for the bend after which gains flatten."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Silhouette score","marks":[{"type":"bold"}]},{"type":"text","text":" — for each point "},{"type":"text","text":"s = (b − a) / max(a, b)","marks":[{"type":"code"}]},{"type":"text","text":", where "},{"type":"text","text":"a","marks":[{"type":"code"}]},{"type":"text","text":" is its mean distance to its own cluster and "},{"type":"text","text":"b","marks":[{"type":"code"}]},{"type":"text","text":" to the nearest other cluster. Ranges from −1 to 1; pick the k with the highest average."}]}]}]}]}},"revision":1},{"id":"c0f9754d-02b1-715a-9734-9e923537bb97","type":"code","position":"a4","content":{"language":"python","code":"from sklearn.cluster import KMeans\nfrom sklearn.datasets import make_blobs\nfrom sklearn.metrics import silhouette_score\n\nX, _ = make_blobs(n_samples=300, centers=4, cluster_std=0.8, random_state=0)\ninertia, silhouette = {}, {}\nfor k in range(2, 8):\n    km = KMeans(n_clusters=k, n_init=10, random_state=0).fit(X)\n    inertia[k] = round(km.inertia_)\n    silhouette[k] = round(silhouette_score(X, km.labels_), 3)\nprint(inertia)       # {2: 1349, 3: 709, 4: 370, 5: 326, 6: 292, 7: 260} ← big drops up to k = 4, small after: the elbow\nprint(silhouette)    # {2: 0.496, 3: 0.515, 4: 0.58, 5: 0.503, 6: 0.43, 7: 0.396} ← highest at k = 4","filename":"Python"},"revision":1},{"id":"dc5e511c-2f81-7e60-a10d-f977ae77f30f","type":"callout","position":"a5","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Let the use case have the final say: five customer segments the marketing team can act on beat seven segments with a marginally better silhouette."}]}]}},"revision":1},{"id":"0ce1e90d-eefd-7aac-a545-862242727aaf","type":"heading","position":"a6","content":{"level":1,"content":[{"type":"text","text":"Assumptions and failure modes"}]},"revision":1},{"id":"1a894909-1ad5-75cf-9b65-d30972e00eb0","type":"table","position":"a7","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"k-means assumes…"}],[{"type":"text","text":"So it struggles with…"}],[{"type":"text","text":"Try instead"}]],[[{"type":"text","text":"Clusters are roughly spherical (isotropic)"}],[{"type":"text","text":"Elongated or curved clusters (moons, rings)"}],[{"type":"text","text":"Gaussian mixtures, DBSCAN, spectral clustering"}]],[[{"type":"text","text":"Clusters have similar size and density"}],[{"type":"text","text":"One big sparse cluster next to a small dense one"}],[{"type":"text","text":"Gaussian mixtures, HDBSCAN"}]],[[{"type":"text","text":"Euclidean distance is meaningful"}],[{"type":"text","text":"Unscaled features; categorical data"}],[{"type":"text","text":"Scale first; k-modes / k-prototypes for categories"}]],[[{"type":"text","text":"Every point belongs to a cluster"}],[{"type":"text","text":"Outliers dragging centroids"}],[{"type":"text","text":"DBSCAN (labels noise), k-medoids"}]],[[{"type":"text","text":"You know k"}],[{"type":"text","text":"Unknown number of groups"}],[{"type":"text","text":"DBSCAN/HDBSCAN, silhouette/BIC to choose"}]]]},"revision":1},{"id":"ac1b1154-dc23-752f-ae54-563814fd62a3","type":"code","position":"a8","content":{"language":"python","code":"from sklearn.cluster import KMeans\nfrom sklearn.datasets import make_moons\nfrom sklearn.metrics import adjusted_rand_score\n\nX, y = make_moons(n_samples=300, noise=0.05, random_state=0)      # two curved clusters\nlabels = KMeans(n_clusters=2, n_init=10, random_state=0).fit_predict(X)\nprint(round(adjusted_rand_score(y, labels), 2))    # 0.24 ← far from 1: straight boundary cuts both moons","filename":"Python"},"revision":1},{"id":"0ff9c88d-4751-7c2b-9335-5b34548c2a90","type":"text","position":"a9","content":{"doc":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Scale features","marks":[{"type":"bold"}]},{"type":"text","text":" first (k-means is distance-based)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"MiniBatchKMeans","marks":[{"type":"code"}]},{"type":"text","text":" handles very large datasets."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Evaluating without labels: silhouette, Davies–Bouldin (lower is better), Calinski–Harabasz (higher is better). With ground truth: adjusted Rand index (ARI), normalised mutual information."}]}]}]}]}},"revision":1},{"id":"d07e4e4b-a7e0-7505-8265-7e1c9edf2b25","type":"question","position":"aA","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How does k-means work and what does it optimise?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"It alternates between assigning each point to its nearest centroid and moving each centroid to the mean of its assigned points, which monotonically decreases the within-cluster sum of squares. It converges to a local optimum, so it''s restarted from several k-means++ initialisations."}]}]}},"revision":1},{"id":"65917e0e-7736-7c71-8998-651f89d5f4b1","type":"question","position":"aB","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How do you choose k?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Elbow in the inertia curve, the maximum average silhouette score, the gap statistic, or BIC with a Gaussian mixture — combined with whether the clusters are useful and stable for the business question."}]}]}},"revision":1},{"id":"6d88a287-e2cc-7392-924c-ccfd4ebcf783","type":"question","position":"aC","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"When does k-means fail?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Non-spherical or nested clusters, clusters of very different size or density, unscaled or categorical features, strong outliers, and high dimensions where distances concentrate."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
